-- ============================================================================
-- MJV Staging Schema Export
-- Generated: 2026-10-02
-- Source: Live production database (bqtsuzvuvqvgidipbsis.supabase.co)
-- Purpose: Schema-only export for staging branch validation (PR #77)
--
-- EXCLUSIONS:
--   - Application data (all row data excluded)
--   - Credentials and secrets (no API keys, tokens, or vault entries)
--   - Scheduled jobs (pg_cron job definitions excluded)
--   - Supabase auth schema internals (auth.users, auth.sessions, etc.)
--   - Supabase migration history (supabase_migrations.schema_migrations)
--
-- KNOWN GAPS (could not be captured via catalog queries):
--   1. Storage internal functions (14 functions in storage schema, not exported)
--   2. Supabase auth schema table structures (platform-managed)
--   3. pg_cron job definitions (cron.jobs table not accessible)
--   4. Supabase vault secrets (excluded by design)
--
-- VERIFIED ABSENT (confirmed no objects of these types exist):
--   - Foreign tables (pg_foreign_table: empty)
--   - Partition children (pg_inherits: empty)
--   - Composite types (pg_type typtype='c' with typrelid=0: empty)
--   - Custom collations (pg_collation in public: empty)
--   - Custom operators (pg_operator in public: empty)
--   - Materialized views (pg_class relkind='m': empty)
--
-- NOTE: This is NOT a pg_dump output. It was reconstructed from live database
-- catalog queries using pg_get_constraintdef, pg_get_functiondef, pg_get_indexdef,
-- pg_get_triggerdef, pg_get_viewdef, and pg_get_expr. All predicates were
-- verified untruncated (longest: 964 chars on messages_portal_public_only).
--
-- WARNING: Migration 20251104191142 has corrupted stored SQL in
-- supabase_migrations.schema_migrations (escaped \\n literals instead of
-- actual newlines). This does NOT affect the live schema (objects exist
-- correctly), but will cause Supabase branch replay to fail. Fix the
-- migration history on the staging branch before replaying.
-- ============================================================================

SET statement_timeout = 0;
SET lock_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;


-- ============================================================================
-- EXTENSIONS, ENUMS & DOMAINS
-- ============================================================================

-- pg_stat_statements v1.11 (schema: extensions)
CREATE EXTENSION IF NOT EXISTS "pg_stat_statements";
-- uuid-ossp v1.1 (schema: extensions)
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
-- pgcrypto v1.3 (schema: public)
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
-- supabase_vault v0.3.1 (schema: vault)
CREATE EXTENSION IF NOT EXISTS "supabase_vault";
-- pg_cron v1.6.4 (schema: pg_catalog)
CREATE EXTENSION IF NOT EXISTS "pg_cron";
-- http v1.6 (schema: public)
CREATE EXTENSION IF NOT EXISTS "http";
-- pg_net v0.19.5 (schema: public)
CREATE EXTENSION IF NOT EXISTS "pg_net";

-- Custom enum types
CREATE TYPE public.proposal_visibility_scope AS ENUM ('own', 'office', 'company');

-- Custom domain types
CREATE DOMAIN public.http_method AS text;
CREATE DOMAIN public.content_type AS text;
-- Note: content_type has CHECK constraint: CHECK ((VALUE ~ '^\S+\/\S+'::text))


-- ============================================================================
-- TABLES
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.appointments
(
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  company_id uuid NOT NULL,
  project_id uuid,
  contact_id uuid,
  title text NOT NULL,
  description text,
  appointment_date date NOT NULL,
  start_time time without time zone,
  end_time time without time zone,
  status text NOT NULL DEFAULT 'scheduled'::text,
  assigned_technician uuid,
  location text,
  notes text,
  created_by uuid NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  recurrence_rule jsonb,
  recurrence_parent_id uuid,
  is_recurring_parent boolean DEFAULT false,
  reminder_status text DEFAULT 'pending'::text,
  send_reminder boolean DEFAULT true,
  reminder_hours_before integer DEFAULT 24,
  recurring_subscription_id uuid,
  appointment_type text NOT NULL DEFAULT 'customer_meeting'::text,
  is_private boolean NOT NULL DEFAULT false,
  all_day boolean NOT NULL DEFAULT false,
  organization_id uuid NOT NULL DEFAULT get_user_org_id()
);

