  first_time_completion_rate numeric(5,2) DEFAULT 
CASE
    WHEN (completed_projects > 0) THEN (((first_time_completions)::numeric / (completed_projects)::numeric) * (100)::numeric)
    ELSE (0)::numeric
END,
  total_post_completion_hours numeric(10,2) DEFAULT 0,
  avg_post_completion_hours numeric(10,2) DEFAULT 0,
