CREATE OR REPLACE FUNCTION public.accept_punchlist_invitation(p_contact_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Update any pending access grants for this contact to active
UPDATE punchlist_access_grants
SET 
status = 'active',
granted_date = CURRENT_DATE,
notes = COALESCE(notes || ' | ', '') || 'Accepted by customer on ' || CURRENT_DATE::text,
updated_at = now()
WHERE contact_id = p_contact_id
AND status = 'pending'
AND (expiration_date IS NULL OR expiration_date >= CURRENT_DATE);

IF NOT FOUND THEN
RAISE EXCEPTION 'No pending invitation found for this contact';
END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.add_revision_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- If proposal is being renewed and has revision notes, add to history
IF NEW.renewal_count > OLD.renewal_count AND NEW.revision_notes IS NOT NULL AND NEW.revision_notes != '' THEN
NEW.revision_history := COALESCE(OLD.revision_history, '[]'::jsonb) || 
jsonb_build_object(
'revision_number', NEW.renewal_count,
'notes', NEW.revision_notes,
'resubmitted_at', NOW(),
'resubmitted_by', auth.uid()
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.advance_workflow_enrollment(p_enrollment_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_enrollment RECORD; v_current_step RECORD; v_next_step RECORD;
BEGIN
SELECT * INTO v_enrollment FROM email_workflow_enrollments WHERE id = p_enrollment_id;
IF NOT FOUND THEN RETURN FALSE; END IF;
SELECT * INTO v_current_step FROM email_workflow_steps WHERE id = v_enrollment.current_step_id;
SELECT * INTO v_next_step FROM email_workflow_steps WHERE workflow_id = v_enrollment.workflow_id AND step_order > v_current_step.step_order ORDER BY step_order ASC LIMIT 1;
IF FOUND THEN
UPDATE email_workflow_enrollments SET current_step_id = v_next_step.id, next_send_at = now() + (v_next_step.delay_days || ' days')::INTERVAL + (v_next_step.delay_hours || ' hours')::INTERVAL WHERE id = p_enrollment_id;
ELSE
UPDATE email_workflow_enrollments SET status = 'completed', completed_at = now(), next_send_at = NULL WHERE id = p_enrollment_id;
END IF;
RETURN TRUE;
END;
$function$


CREATE OR REPLACE FUNCTION public.aggregate_location_metrics()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
INSERT INTO location_quality_metrics (
technician_id,
device_model,
date,
total_points,
avg_accuracy,
min_accuracy,
max_accuracy,
points_high_accuracy,
points_medium_accuracy,
points_low_accuracy,
avg_battery_level
)
SELECT
technician_id,
device_model,
DATE(captured_at) as date,
COUNT(*) as total_points,
AVG(accuracy) as avg_accuracy,
MIN(accuracy) as min_accuracy,
MAX(accuracy) as max_accuracy,
COUNT(*) FILTER (WHERE accuracy < 10) as points_high_accuracy,
COUNT(*) FILTER (WHERE accuracy >= 10 AND accuracy <= 50) as points_medium_accuracy,
COUNT(*) FILTER (WHERE accuracy > 50) as points_low_accuracy,
AVG(battery_level) as avg_battery_level
FROM enhanced_gps_breadcrumbs
WHERE DATE(captured_at) = CURRENT_DATE - INTERVAL '1 day'
GROUP BY technician_id, device_model, DATE(captured_at)
ON CONFLICT (technician_id, device_model, date)
DO UPDATE SET
total_points = EXCLUDED.total_points,
avg_accuracy = EXCLUDED.avg_accuracy,
min_accuracy = EXCLUDED.min_accuracy,
max_accuracy = EXCLUDED.max_accuracy,
points_high_accuracy = EXCLUDED.points_high_accuracy,
points_medium_accuracy = EXCLUDED.points_medium_accuracy,
points_low_accuracy = EXCLUDED.points_low_accuracy,
avg_battery_level = EXCLUDED.avg_battery_level;
END;
$function$


CREATE OR REPLACE FUNCTION public.allocate_billing_amount(p_transaction_type text, p_transaction_id uuid, p_amount_to_bill numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_composition jsonb;
v_classifications jsonb;
v_total numeric;
v_allocated numeric[] := ARRAY[]::numeric[];
v_codes text[] := ARRAY[]::text[];
v_remaining numeric;
v_sum_allocated numeric := 0;
v_result jsonb[] := ARRAY[]::jsonb[];
v_class jsonb;
v_code text;
v_amount numeric;
v_pct numeric;
v_allocated_amount numeric;
v_count integer;
v_i integer;
BEGIN
-- Get the composition
v_composition := get_billing_classification_composition(p_transaction_type, p_transaction_id);
v_classifications := v_composition->'classifications';
v_total := (v_composition->>'total_classified_amount')::numeric;

-- Edge case: nothing to allocate
IF v_total = 0 OR p_amount_to_bill = 0 THEN
RETURN jsonb_build_object('allocations', '[]'::jsonb, 'total_allocated', 0);
END IF;

-- First pass: allocate proportionally, track for rounding
v_count := jsonb_array_length(v_classifications);
v_remaining := p_amount_to_bill;

FOR v_i IN 0..v_count - 1 LOOP
v_class := v_classifications->v_i;
v_code := v_class->>'classification_code';
v_pct := (v_class->>'percentage')::numeric;

IF v_i = v_count - 1 THEN
-- Last classification absorbs the rounding remainder
v_allocated_amount := round(v_remaining, 2);
ELSE
v_allocated_amount := round(p_amount_to_bill * v_pct, 2);
v_remaining := v_remaining - v_allocated_amount;
END IF;

v_result := array_append(v_result, jsonb_build_object(
'classification_code', v_code,
'allocated_amount', v_allocated_amount
));
v_sum_allocated := v_sum_allocated + v_allocated_amount;
END LOOP;

RETURN jsonb_build_object(
'allocations', to_jsonb(v_result),
'total_allocated', v_sum_allocated
);
END;
$function$


CREATE OR REPLACE FUNCTION public.analyze_proposal_pricing(p_proposal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_discontinued_items jsonb;
v_pricing_changed_items jsonb;
v_pricing_unchanged_items jsonb;
v_old_total numeric;
v_new_total numeric;
BEGIN
-- Get discontinued items (product not active)
SELECT jsonb_agg(jsonb_build_object(
'line_item_id', pli.id,
'product_id', pli.product_id,
'description', pli.description,
'quantity', pli.quantity,
'unit_price', pli.unit_price,
'cost', pli.cost,
'line_total', pli.line_total,
'product_name', p.name
))
INTO v_discontinued_items
FROM proposal_line_items pli
JOIN products p ON p.id = pli.product_id
WHERE pli.proposal_id = p_proposal_id
AND pli.product_id IS NOT NULL
AND pli.is_custom = false
AND p.is_active = false;

-- Get pricing changed items (current price differs from line item)
SELECT jsonb_agg(jsonb_build_object(
'line_item_id', pli.id,
'product_id', pli.product_id,
'description', pli.description,
'quantity', pli.quantity,
'old_unit_price', pli.unit_price,
'new_unit_price', p.unit_price,
'old_cost', pli.cost,
'new_cost', p.cost,
'old_line_total', pli.line_total,
'new_line_total', pli.quantity * p.unit_price,
'price_difference', p.unit_price - pli.unit_price,
'line_difference', (pli.quantity * p.unit_price) - pli.line_total,
'product_name', p.name
))
INTO v_pricing_changed_items
FROM proposal_line_items pli
JOIN products p ON p.id = pli.product_id
WHERE pli.proposal_id = p_proposal_id
AND pli.product_id IS NOT NULL
AND pli.is_custom = false
AND p.is_active = true
AND (p.unit_price != pli.unit_price OR p.cost != pli.cost);

-- Get pricing unchanged items
SELECT jsonb_agg(jsonb_build_object(
'line_item_id', pli.id,
'product_id', pli.product_id,
'description', pli.description,
'quantity', pli.quantity,
'unit_price', pli.unit_price,
'cost', pli.cost,
'line_total', pli.line_total,
'product_name', p.name
))
INTO v_pricing_unchanged_items
FROM proposal_line_items pli
JOIN products p ON p.id = pli.product_id
WHERE pli.proposal_id = p_proposal_id
AND pli.product_id IS NOT NULL
AND pli.is_custom = false
AND p.is_active = true
AND p.unit_price = pli.unit_price
AND p.cost = pli.cost;

-- Calculate old and new totals
SELECT
COALESCE(SUM(pli.line_total), 0),
COALESCE(SUM(
CASE
WHEN p.is_active = true THEN pli.quantity * p.unit_price
ELSE pli.line_total
END
), 0)
INTO v_old_total, v_new_total
FROM proposal_line_items pli
LEFT JOIN products p ON p.id = pli.product_id
WHERE pli.proposal_id = p_proposal_id
AND pli.product_id IS NOT NULL
AND pli.is_custom = false;

-- Build result
v_result := jsonb_build_object(
'discontinued_items', COALESCE(v_discontinued_items, '[]'::jsonb),
'pricing_changed_items', COALESCE(v_pricing_changed_items, '[]'::jsonb),
'pricing_unchanged_items', COALESCE(v_pricing_unchanged_items, '[]'::jsonb),
'summary', jsonb_build_object(
'old_total', v_old_total,
'new_total', v_new_total,
'difference', v_new_total - v_old_total,
'has_discontinued', v_discontinued_items IS NOT NULL AND jsonb_array_length(v_discontinued_items) > 0,
'has_pricing_changes', v_pricing_changed_items IS NOT NULL AND jsonb_array_length(v_pricing_changed_items) > 0
)
);

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.apply_bonus_override(p_sales_order_id uuid, p_employee_id uuid, p_override_amount numeric, p_reason text, p_admin_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_override_id uuid;
v_original_amount numeric;
v_bonus_calc_id uuid;
v_org_id uuid;
v_admin_role text;
BEGIN
-- Check if caller is admin
SELECT role, organization_id INTO v_admin_role, v_org_id
FROM profiles
WHERE id = auth.uid();

IF v_admin_role NOT IN ('admin', 'super_admin', 'sales_manager') THEN
RAISE EXCEPTION 'Only administrators can apply bonus overrides';
END IF;

-- Get current bonus amount
SELECT id, COALESCE(projected_bonus, 0), organization_id
INTO v_bonus_calc_id, v_original_amount, v_org_id
FROM test_tune_bonus_calculations
WHERE sales_order_id = p_sales_order_id
AND (lead_technician_id = p_employee_id OR project_manager_id = p_employee_id)
LIMIT 1;

IF v_bonus_calc_id IS NULL THEN
RAISE EXCEPTION 'No bonus calculation found for this sales order and employee';
END IF;

-- Create override record
INSERT INTO test_tune_bonus_overrides (
organization_id,
sales_order_id,
bonus_calculation_id,
employee_id,
original_amount,
override_amount,
reason,
admin_notes,
status,
created_by,
approved_by,
approved_at
) VALUES (
v_org_id,
p_sales_order_id,
v_bonus_calc_id,
p_employee_id,
v_original_amount,
p_override_amount,
p_reason,
p_admin_notes,
'approved',
auth.uid(),
auth.uid(),
now()
)
RETURNING id INTO v_override_id;

-- Update bonus calculation
UPDATE test_tune_bonus_calculations
SET
is_overridden = true,
override_amount = p_override_amount,
override_reason = p_reason,
overridden_by = auth.uid(),
overridden_at = now(),
updated_at = now()
WHERE id = v_bonus_calc_id;

RETURN v_override_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.apply_change_order(p_change_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_co          change_orders%ROWTYPE;
v_item        change_order_line_items%ROWTYPE;
v_proposal_id uuid;
BEGIN
-- Load the change order
SELECT * INTO v_co
FROM change_orders
WHERE id = p_change_order_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Change order % not found', p_change_order_id;
END IF;

IF v_co.status <> 'approved' THEN
RAISE EXCEPTION 'Change order % must be in approved status to apply (current: %)',
p_change_order_id, v_co.status;
END IF;

-- Resolve the parent proposal from the sales order
SELECT proposal_id INTO v_proposal_id
FROM sales_orders
WHERE id = v_co.sales_order_id;

-- Process each line item action
FOR v_item IN
SELECT *
FROM change_order_line_items
WHERE change_order_id = p_change_order_id
ORDER BY sort_order NULLS LAST, created_at
LOOP

IF v_item.action_type = 'remove' THEN
-- Permanently hide the removed line item
UPDATE proposal_line_items
SET    is_hidden  = true,
updated_at = now()
WHERE  id = v_item.proposal_line_item_id;

ELSIF v_item.action_type = 'add' THEN
-- Insert a new line item on the proposal (skip if somehow already there)
IF v_proposal_id IS NOT NULL AND NOT EXISTS (
SELECT 1 FROM proposal_line_items
WHERE proposal_id   = v_proposal_id
AND product_id    IS NOT DISTINCT FROM v_item.product_id
AND description   = COALESCE(v_item.product_description, v_item.product_name)
AND unit_price    = v_item.new_unit_price
AND quantity      = v_item.new_quantity
) THEN
INSERT INTO proposal_line_items (
proposal_id,
product_id,
description,
quantity,
unit_price,
line_total,
is_taxable,
item_type,
labor_phase_id,
sort_order,
organization_id,
created_at,
updated_at
) VALUES (
v_proposal_id,
v_item.product_id,
COALESCE(v_item.product_description, v_item.product_name),
v_item.new_quantity,
v_item.new_unit_price,
ROUND(v_item.new_quantity * v_item.new_unit_price, 2),
COALESCE(v_item.is_taxable, true),
v_item.item_type,
v_item.labor_phase_id,
v_item.sort_order,
v_co.organization_id,
now(),
now()
);
END IF;

ELSIF v_item.action_type IN ('modify_quantity', 'modify_price') THEN
UPDATE proposal_line_items
SET
quantity   = CASE WHEN v_item.action_type = 'modify_quantity'
THEN v_item.new_quantity ELSE quantity END,
unit_price = CASE WHEN v_item.action_type = 'modify_price'
THEN v_item.new_unit_price ELSE unit_price END,
line_total = ROUND(
CASE WHEN v_item.action_type = 'modify_quantity'
THEN v_item.new_quantity ELSE quantity END
*
CASE WHEN v_item.action_type = 'modify_price'
THEN v_item.new_unit_price ELSE unit_price END
, 2),
updated_at = now()
WHERE id = v_item.proposal_line_item_id;

ELSIF v_item.action_type = 'modify_labor' THEN
UPDATE proposal_line_items
SET
labor_hours = v_item.labor_hours,
labor_rate  = v_item.labor_rate,
labor_total = v_item.new_labor_total,
updated_at  = now()
WHERE id = v_item.proposal_line_item_id;

-- modify_modifiers: no per-line-item change needed
END IF;

END LOOP;

-- Lock the CO: mark is_active = false so it becomes historical
UPDATE change_orders
SET    is_active  = false,
updated_at = now()
WHERE  id = p_change_order_id;

-- Recalculate proposal totals if helper function exists
IF v_proposal_id IS NOT NULL THEN
BEGIN
PERFORM calculate_proposal_totals(v_proposal_id);
EXCEPTION WHEN undefined_function THEN
NULL;
END;
END IF;

END;
$function$


CREATE OR REPLACE FUNCTION public.apply_time_adjustment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_new_total_hours numeric;
BEGIN
-- Only process when status changes to 'approved'
IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
-- Calculate new total hours
IF NEW.requested_clock_out IS NOT NULL THEN
v_new_total_hours := EXTRACT(EPOCH FROM (NEW.requested_clock_out - NEW.requested_clock_in)) / 3600.0;
v_new_total_hours := v_new_total_hours - (NEW.requested_break_minutes / 60.0);
ELSE
v_new_total_hours := 0;
END IF;

-- Update the daily_clock_entries entry
UPDATE daily_clock_entries
SET
clock_in = NEW.requested_clock_in,
clock_out = NEW.requested_clock_out,
break_minutes = NEW.requested_break_minutes,
total_hours = v_new_total_hours,
admin_adjusted = true,
adjustment_reason = NEW.reason || ' (Via adjustment request)',
admin_notes = NEW.review_notes,
updated_at = now()
WHERE id = NEW.time_entry_id;

-- Create notification for technician
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id
) VALUES (
NEW.technician_id,
'time_adjustment_approved',
'Time Adjustment Approved',
'Your time adjustment request has been approved by ' || 
COALESCE((SELECT full_name FROM profiles WHERE id = NEW.reviewed_by), 'an administrator'),
NEW.id::text
);
END IF;

-- Notify technician of denial
IF NEW.status = 'denied' AND (OLD.status IS NULL OR OLD.status != 'denied') THEN
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id
) VALUES (
NEW.technician_id,
'time_adjustment_denied',
'Time Adjustment Denied',
'Your time adjustment request has been denied. Reason: ' || COALESCE(NEW.review_notes, 'No reason provided'),
NEW.id::text
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.approve_payroll_period(p_pay_period_id uuid, p_approved_by uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org_id uuid; v_status text; v_caller_org_id uuid; v_readiness json; v_approved_count int := 0;
BEGIN
IF p_approved_by IS NULL OR p_approved_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Unauthorized approval actor'; END IF;
SELECT organization_id, status INTO v_org_id, v_status FROM pay_periods WHERE id=p_pay_period_id;
IF NOT FOUND THEN RETURN json_build_object('error','pay period not found'); END IF;
SELECT organization_id INTO v_caller_org_id FROM profiles WHERE id=auth.uid();
IF NOT FOUND OR v_caller_org_id IS DISTINCT FROM v_org_id THEN RAISE EXCEPTION 'Unauthorized: caller does not belong to this organization'; END IF;
IF NOT EXISTS (SELECT 1 FROM profiles WHERE id=auth.uid() AND organization_id=v_org_id AND role IN ('admin','manager','office_manager','production_manager','service_manager')) THEN RAISE EXCEPTION 'Unauthorized: caller is not authorized to approve payroll'; END IF;
IF v_status NOT IN ('needs_review') THEN RETURN json_build_object('error','Pay period must be in needs_review status to approve'); END IF;
SELECT check_payroll_readiness(p_pay_period_id) INTO v_readiness;
IF (v_readiness->>'ready_for_submission')::boolean IS NOT TRUE THEN RAISE EXCEPTION 'Cannot approve payroll: readiness check failed. Unassigned jurisdiction: %, GPS mismatches: %, Pending approvals: %, Pending adjustments: %, Unreviewed configs: %, Unresolved payroll flags: %', v_readiness->>'unassigned_jurisdiction', v_readiness->>'gps_mismatches', v_readiness->>'pending_count', v_readiness->>'pending_adjustments', v_readiness->>'unreviewed_timekeeping_configs', v_readiness->>'unresolved_payroll_flags'; END IF;
UPDATE pay_periods SET status='payroll_approved', payroll_approved_at=now(), payroll_approved_by=auth.uid(), updated_at=now() WHERE id=p_pay_period_id;
UPDATE payroll_time_segments SET is_locked=true, locked_at=now(), payroll_approval_status='approved', payroll_approved_by=auth.uid(), payroll_approved_at=now() WHERE pay_period_id=p_pay_period_id AND organization_id=v_org_id;
GET DIAGNOSTICS v_approved_count=ROW_COUNT;
RETURN json_build_object('success',true,'segments_locked',v_approved_count,'message','Pay period approved and segments locked');
END;
$function$


CREATE OR REPLACE FUNCTION public.archive_work_order(p_work_order_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE work_orders
SET
is_archived = true,
archived_at = now(),
archived_by = p_user_id
WHERE id = p_work_order_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.assign_invoice_number_on_submit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- When transitioning from draft to a non-draft status, assign a number if missing
IF NEW.status <> 'draft' AND COALESCE(OLD.status, 'draft') = 'draft'
AND (NEW.invoice_number IS NULL OR NEW.invoice_number = '') THEN
NEW.invoice_number := generate_invoice_number();
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.assign_segments_to_pay_period(p_pay_period_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_org_id uuid;
v_start date;
v_end date;
v_count int;
BEGIN
SELECT organization_id, period_start_date, period_end_date
INTO v_org_id, v_start, v_end
FROM pay_periods
WHERE id = p_pay_period_id;

IF NOT FOUND THEN
RETURN json_build_object('error', 'pay period not found');
END IF;

UPDATE payroll_time_segments
SET pay_period_id = p_pay_period_id
WHERE organization_id = v_org_id
AND segment_date >= v_start
AND segment_date <= v_end
AND is_locked = false;

GET DIAGNOSTICS v_count = ROW_COUNT;

RETURN json_build_object('assigned', v_count);
END;
$function$


CREATE OR REPLACE FUNCTION public.auth_role()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT role FROM profiles WHERE id = auth.uid();
$function$


CREATE OR REPLACE FUNCTION public.auth_uid()
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT auth.uid();
$function$


CREATE OR REPLACE FUNCTION public.auto_archive_declined_proposals()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_days_threshold integer;
v_enabled boolean;
v_cutoff_date timestamptz;
v_proposal_ids uuid[];
v_archived_count integer := 0;
v_result jsonb;
BEGIN
-- Get company settings
SELECT
COALESCE(auto_archive_declined_proposals_enabled, true),
COALESCE(auto_archive_declined_after_days, 90)
INTO v_enabled, v_days_threshold
FROM company_settings
LIMIT 1;

-- Exit if auto-archive is disabled
IF NOT v_enabled THEN
RETURN jsonb_build_object(
'success', true,
'archived_count', 0,
'message', 'Auto-archive is disabled'
);
END IF;

-- Calculate cutoff date
v_cutoff_date := now() - (v_days_threshold || ' days')::interval;

-- Get proposals to archive
SELECT array_agg(id)
INTO v_proposal_ids
FROM proposals
WHERE status = 'declined'
AND updated_at < v_cutoff_date;

-- Archive proposals
IF v_proposal_ids IS NOT NULL THEN
UPDATE proposals
SET
status = 'archived',
archived_at = now(),
auto_archived = true,
updated_at = now()
WHERE id = ANY(v_proposal_ids);

GET DIAGNOSTICS v_archived_count = ROW_COUNT;
END IF;

-- Log execution
INSERT INTO proposal_archive_log (
executed_at,
proposals_archived,
proposal_ids,
success
) VALUES (
now(),
v_archived_count,
COALESCE(v_proposal_ids, '{}'),
true
);

-- Build result
v_result := jsonb_build_object(
'success', true,
'archived_count', v_archived_count,
'proposal_ids', COALESCE(v_proposal_ids, '[]'::uuid[]),
'cutoff_date', v_cutoff_date
);

RETURN v_result;
EXCEPTION
WHEN OTHERS THEN
-- Log error
INSERT INTO proposal_archive_log (
executed_at,
proposals_archived,
success,
error_message
) VALUES (
now(),
0,
false,
SQLERRM
);

RAISE;
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_clock_out_forgotten_entries()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_settings                record;
v_cutoff_time             time;
v_default_clock_out_time  time;
v_cutoff_timestamp        timestamptz;
v_penalty_points          integer;
v_affected_count          integer := 0;
v_job_entries_count       integer := 0;
v_execution_start         timestamptz := clock_timestamp();
v_execution_log_id        uuid;
v_entry_ids               uuid[]  := '{}';
v_tech_ids                uuid[]  := '{}';
v_tech_names              text[]  := '{}';
v_total_points            integer := 0;
v_admin_ids               uuid[]  := '{}';
v_notification_ids        uuid[]  := '{}';
v_notification_id         uuid;
v_admin_id                uuid;
v_execution_duration      integer;
v_timezone                text;
v_org_id                  uuid;
v_cutoff_date             date;
BEGIN
-- Get company settings including timezone
SELECT
organization_id,
auto_clock_out_enabled,
auto_clock_out_cutoff_time,
auto_clock_out_time,
forgot_clock_out_penalty_points,
home_clock_notification_roles,
COALESCE(timezone, 'America/Chicago') AS tz
INTO v_settings
FROM company_settings
LIMIT 1;

IF v_settings IS NULL THEN
RETURN jsonb_build_object(
'success',           false,
'message',           'No company settings found',
'entries_processed', 0
);
END IF;

v_org_id   := COALESCE(v_settings.organization_id, (SELECT id FROM organizations LIMIT 1));
v_timezone := v_settings.tz;

IF NOT v_settings.auto_clock_out_enabled THEN
RETURN jsonb_build_object(
'success',           false,
'message',           'Auto clock-out is not enabled',
'entries_processed', 0
);
END IF;

v_cutoff_time            := COALESCE(v_settings.auto_clock_out_cutoff_time, '22:00:00'::time);
v_default_clock_out_time := COALESCE(v_settings.auto_clock_out_time,        '16:00:00'::time);
v_penalty_points         := COALESCE(v_settings.forgot_clock_out_penalty_points, -15);

-- Determine the cutoff date in the org's local timezone.
-- FIX: cast the date arithmetic result back to ::date — subtracting an interval
--      from a date returns `timestamp without time zone` in Postgres, not date,
--      so ::text would produce "YYYY-MM-DD 00:00:00" instead of "YYYY-MM-DD".
IF (now() AT TIME ZONE v_timezone)::time >= v_cutoff_time THEN
v_cutoff_date := (now() AT TIME ZONE v_timezone)::date;
ELSE
v_cutoff_date := ((now() AT TIME ZONE v_timezone)::date - interval '1 day')::date;
END IF;

-- Build the cutoff timestamptz from clean date + time strings
v_cutoff_timestamp := (v_cutoff_date::text || ' ' || v_cutoff_time::text)::timestamp
AT TIME ZONE v_timezone;

-- -------------------------------------------------------
-- STEP A: Process daily_clock_entries (home / office clock)
-- -------------------------------------------------------
WITH entries_to_process AS (
SELECT
dce.id,
dce.technician_id,
dce.clock_in,
dce.entry_date,
p.full_name,
p.requires_daily_clock,
p.standard_end_time,
-- FIX: cast (entry_date + interval '1 day') back to ::date before ::text
CASE
WHEN p.standard_end_time IS NOT NULL THEN
CASE
WHEN (dce.entry_date::text || ' ' || p.standard_end_time::text)::timestamp
AT TIME ZONE v_timezone > dce.clock_in
THEN (dce.entry_date::text || ' ' || p.standard_end_time::text)::timestamp
AT TIME ZONE v_timezone
ELSE ((dce.entry_date + interval '1 day')::date::text || ' ' || p.standard_end_time::text)::timestamp
AT TIME ZONE v_timezone
END
ELSE
CASE
WHEN (dce.entry_date::text || ' ' || v_default_clock_out_time::text)::timestamp
AT TIME ZONE v_timezone > dce.clock_in
THEN (dce.entry_date::text || ' ' || v_default_clock_out_time::text)::timestamp
AT TIME ZONE v_timezone
ELSE ((dce.entry_date + interval '1 day')::date::text || ' ' || v_default_clock_out_time::text)::timestamp
AT TIME ZONE v_timezone
END
END AS calculated_clock_out
FROM daily_clock_entries dce
JOIN profiles p ON p.id = dce.technician_id
WHERE dce.status = 'clocked_in'
AND dce.clock_in < v_cutoff_timestamp
AND p.requires_daily_clock = true
AND dce.auto_clocked_out = false
),
updated_entries AS (
UPDATE daily_clock_entries dce
SET
clock_out               = etp.calculated_clock_out,
status                  = 'clocked_out',
total_hours             = GREATEST(
0,
EXTRACT(EPOCH FROM (etp.calculated_clock_out - dce.clock_in)) / 3600
),
deduct_points           = true,
points_deducted         = v_penalty_points,
auto_clocked_out        = true,
auto_clocked_out_at     = now(),
auto_clock_out_approved = false,
notes = COALESCE(notes || E'\
', '') ||
'Auto-clocked out at ' ||
to_char(etp.calculated_clock_out AT TIME ZONE v_timezone, 'YYYY-MM-DD HH12:MI:SS AM TZ') ||
' (cutoff was ' || to_char(v_cutoff_timestamp AT TIME ZONE v_timezone, 'HH12:MI:SS AM') ||
'). Penalty: ' || v_penalty_points || ' points.'
FROM entries_to_process etp
WHERE dce.id = etp.id
AND etp.calculated_clock_out > dce.clock_in
RETURNING dce.id, dce.technician_id, dce.points_deducted, etp.full_name
)
SELECT
COALESCE(array_agg(id),                     '{}'),
COALESCE(array_agg(DISTINCT technician_id), '{}'),
COALESCE(array_agg(DISTINCT full_name),     '{}'),
COALESCE(SUM(ABS(points_deducted))::integer, 0)
INTO v_entry_ids, v_tech_ids, v_tech_names, v_total_points
FROM updated_entries;

v_affected_count := COALESCE(array_length(v_entry_ids, 1), 0);

-- -------------------------------------------------------
-- STEP B: Process open job time_entries (work-order clock)
-- -------------------------------------------------------
WITH job_entries_to_close AS (
SELECT
te.id,
te.technician_id,
te.clock_in,
te.entry_date,
-- FIX: same ::date cast on the +1 day branch
CASE
WHEN (te.entry_date::text || ' ' || v_default_clock_out_time::text)::timestamp
AT TIME ZONE v_timezone > te.clock_in
THEN (te.entry_date::text || ' ' || v_default_clock_out_time::text)::timestamp
AT TIME ZONE v_timezone
ELSE ((te.entry_date + interval '1 day')::date::text || ' ' || v_default_clock_out_time::text)::timestamp
AT TIME ZONE v_timezone
END AS calculated_clock_out
FROM time_entries te
WHERE te.status = 'clocked_in'
AND te.clock_in < v_cutoff_timestamp
AND te.clock_out IS NULL
),
updated_job_entries AS (
UPDATE time_entries te
SET
clock_out   = jec.calculated_clock_out,
status      = 'draft',
total_hours = GREATEST(
0,
EXTRACT(EPOCH FROM (jec.calculated_clock_out - te.clock_in)) / 3600
),
notes = COALESCE(notes || E'\
', '') ||
'Auto-clocked out at ' ||
to_char(jec.calculated_clock_out AT TIME ZONE v_timezone, 'YYYY-MM-DD HH12:MI:SS AM TZ') ||
' (cutoff was ' || to_char(v_cutoff_timestamp AT TIME ZONE v_timezone, 'HH12:MI:SS AM') || ').'
FROM job_entries_to_close jec
WHERE te.id = jec.id
AND jec.calculated_clock_out > te.clock_in
RETURNING te.id
)
SELECT COUNT(*)::integer INTO v_job_entries_count FROM updated_job_entries;

-- -------------------------------------------------------
-- Award penalty points and notify admins
-- -------------------------------------------------------
IF v_affected_count > 0 THEN
FOR i IN 1..array_length(v_tech_ids, 1) LOOP
PERFORM award_points(
v_tech_ids[i],
v_penalty_points,
'Automatic clock-out penalty for forgotten clock-out on ' ||
to_char((now() AT TIME ZONE v_timezone)::date, 'YYYY-MM-DD')
);
END LOOP;

IF v_settings.home_clock_notification_roles IS NOT NULL
AND array_length(v_settings.home_clock_notification_roles, 1) > 0
THEN
SELECT COALESCE(array_agg(DISTINCT id), '{}')
INTO   v_admin_ids
FROM   profiles
WHERE  role = ANY(v_settings.home_clock_notification_roles);
ELSE
SELECT COALESCE(array_agg(DISTINCT id), '{}')
INTO   v_admin_ids
FROM   profiles
WHERE  role IN ('admin', 'owner');
END IF;

IF v_admin_ids IS NOT NULL AND array_length(v_admin_ids, 1) > 0 THEN
FOREACH v_admin_id IN ARRAY v_admin_ids LOOP
INSERT INTO notifications (
user_id, organization_id, type, title, body, related_id
) VALUES (
v_admin_id,
v_org_id,
'auto_clock_out',
'Auto Clock-Out: Needs Approval',
v_affected_count ||
' technician(s) were automatically clocked out and need approval before payroll. Click to review.',
NULL
)
RETURNING id INTO v_notification_id;

v_notification_ids := array_append(v_notification_ids, v_notification_id);
END LOOP;
END IF;
END IF;

-- -------------------------------------------------------
-- Log execution
-- -------------------------------------------------------
v_execution_duration := EXTRACT(EPOCH FROM (clock_timestamp() - v_execution_start)) * 1000;

INSERT INTO auto_clock_out_execution_log (
organization_id,
executed_at,
entries_processed,
entry_ids,
technician_ids,
technician_names,
total_points_deducted,
admin_notified,
admin_notification_ids,
success,
execution_duration_ms
) VALUES (
v_org_id,
v_execution_start,
v_affected_count,
COALESCE(v_entry_ids,        '{}'),
COALESCE(v_tech_ids,         '{}'),
COALESCE(v_tech_names,       '{}'),
COALESCE(v_total_points,     0),
COALESCE(array_length(v_admin_ids, 1), 0) > 0,
COALESCE(v_notification_ids, '{}'),
true,
v_execution_duration
)
RETURNING id INTO v_execution_log_id;

UPDATE company_settings SET last_auto_clock_out_run = v_execution_start;

RETURN jsonb_build_object(
'success',               true,
'execution_log_id',      v_execution_log_id,
'entries_processed',     v_affected_count,
'job_entries_closed',    v_job_entries_count,
'technician_ids',        v_tech_ids,
'technician_names',      v_tech_names,
'total_points_deducted', v_total_points,
'admin_notified',        COALESCE(array_length(v_admin_ids, 1), 0) > 0,
'notification_count',    COALESCE(array_length(v_notification_ids, 1), 0),
'executed_at',           v_execution_start,
'execution_duration_ms', v_execution_duration,
'cutoff_time',           v_cutoff_time::text,
'default_clock_out_time', v_default_clock_out_time::text,
'timezone',              v_timezone
);

EXCEPTION WHEN OTHERS THEN
BEGIN
INSERT INTO auto_clock_out_execution_log (
organization_id,
executed_at,
entries_processed,
entry_ids,
technician_ids,
technician_names,
success,
error_message
) VALUES (
COALESCE(v_org_id, (SELECT id FROM organizations LIMIT 1)),
v_execution_start,
0, '{}', '{}', '{}',
false,
SQLERRM
);
EXCEPTION WHEN OTHERS THEN
NULL;
END;

RETURN jsonb_build_object(
'success',           false,
'message',           'Error: ' || SQLERRM,
'entries_processed', 0
);
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_compute_line_item_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- If customer-supplied, force only material pricing to zero; labor stays editable
IF NEW.is_customer_supplied = true THEN
NEW.unit_price  := 0;
NEW.line_total  := 0;
NEW.cost        := 0;
-- Still compute labor_total if labor fields are set
IF NEW.labor_hours IS NOT NULL AND NEW.labor_hours > 0
AND NEW.labor_rate IS NOT NULL AND NEW.labor_rate > 0
THEN
NEW.labor_total := NEW.labor_hours * COALESCE(NEW.quantity, 1) * NEW.labor_rate;
END IF;
RETURN NEW;
END IF;

-- Auto-compute line_total if unit_price is set but line_total is missing/zero
IF NEW.unit_price IS NOT NULL AND NEW.unit_price > 0
AND NEW.quantity IS NOT NULL AND NEW.quantity > 0
AND (NEW.line_total IS NULL OR NEW.line_total = 0)
THEN
NEW.line_total := NEW.quantity * NEW.unit_price;
END IF;

-- Auto-compute labor_total if labor_hours and labor_rate are set but labor_total is missing/zero
IF NEW.labor_hours IS NOT NULL AND NEW.labor_hours > 0
AND NEW.labor_rate IS NOT NULL AND NEW.labor_rate > 0
AND (NEW.labor_total IS NULL OR NEW.labor_total = 0)
THEN
NEW.labor_total := NEW.labor_hours * COALESCE(NEW.quantity, 1) * NEW.labor_rate;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_lock_change_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.status IN ('approved', 'pending_approval', 'rejected', 'completed')
AND OLD.status IS DISTINCT FROM NEW.status THEN
NEW.is_locked := true;
NEW.is_active := false;
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_lock_live_proposals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- If proposal becomes visible on portal with active status, lock it
IF NEW.is_portal_visible = true
AND NEW.is_active_revision = true
AND NEW.status IN ('sent', 'viewed', 'approved', 'approved_pending_action')
AND (OLD.is_portal_visible = false OR OLD.is_active_revision = false OR OLD.status NOT IN ('sent', 'viewed', 'approved', 'approved_pending_action'))
THEN
NEW.is_locked := true;
NEW.locked_at := now();
NEW.locked_by := auth.uid();
END IF;

-- If proposal is no longer live on portal, unlock it
IF NEW.is_portal_visible = false OR NEW.is_active_revision = false
THEN
NEW.is_locked := false;
NEW.locked_at := NULL;
NEW.locked_by := NULL;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_set_invoice_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Only assign a number for non-draft invoices that don't have one
IF NEW.status <> 'draft' AND (NEW.invoice_number IS NULL OR NEW.invoice_number = '') THEN
NEW.invoice_number := generate_invoice_number();
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_update_billable_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- If type changed to service, set is_billable to true
IF NEW.type = 'service' AND (OLD.type IS NULL OR OLD.type != 'service') THEN
NEW.is_billable := true;
END IF;

-- If type changed from service to something else, set is_billable to false
-- (unless manually overridden by user in the same update)
IF NEW.type != 'service' AND OLD.type = 'service' THEN
-- Only auto-set to false if is_billable wasn't explicitly changed in this update
IF NEW.is_billable = OLD.is_billable THEN
NEW.is_billable := false;
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_watch_assigned_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.assigned_to IS NOT NULL AND (OLD.assigned_to IS NULL OR NEW.assigned_to != OLD.assigned_to) THEN
INSERT INTO task_watchers (task_id, user_id)
VALUES (NEW.id, NEW.assigned_to)
ON CONFLICT (task_id, user_id) DO NOTHING;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_watch_commented_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
INSERT INTO task_watchers (task_id, user_id)
VALUES (NEW.task_id, NEW.user_id)
ON CONFLICT (task_id, user_id) DO NOTHING;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.auto_watch_created_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Add task creator as watcher
INSERT INTO task_watchers (task_id, user_id)
VALUES (NEW.id, NEW.user_id)
ON CONFLICT (task_id, user_id) DO NOTHING;

-- If task is assigned, add assignee as watcher
IF NEW.assigned_to IS NOT NULL THEN
INSERT INTO task_watchers (task_id, user_id)
VALUES (NEW.id, NEW.assigned_to)
ON CONFLICT (task_id, user_id) DO NOTHING;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.award_points(p_user_id uuid, p_points integer, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Update the user's total points using correct column name
UPDATE profiles
SET 
points_earned = COALESCE(points_earned, 0) + p_points,
updated_at = now()
WHERE id = p_user_id;

-- Log the points award in the points log table if it exists
IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'points_log') THEN
INSERT INTO points_log (
user_id,
points,
reason,
created_at
) VALUES (
p_user_id,
p_points,
p_reason,
now()
);
END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.award_points_for_connection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
points_config RECORD;
contact_name_text text;
BEGIN
-- Get points configuration
SELECT connection_logged_points INTO points_config
FROM points_configuration
LIMIT 1;

-- If no config exists or points are 0, skip
IF points_config IS NULL OR points_config.connection_logged_points = 0 THEN
RETURN NEW;
END IF;

-- Get contact name for description
SELECT COALESCE(first_name || ' ' || last_name, company_name) INTO contact_name_text
FROM contacts
WHERE id = NEW.contact_id;

-- Award points using user_id instead of created_by
INSERT INTO points_transactions (user_id, points_amount, transaction_type, reference_id, description)
VALUES (
NEW.user_id,
points_config.connection_logged_points,
'admin_adjustment',
NEW.id,
'Connection logged with ' || COALESCE(contact_name_text, 'contact')
);

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.award_points_for_contact()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
points_config RECORD;
BEGIN
-- Skip if contact was created anonymously (no created_by user)
IF NEW.created_by IS NULL THEN
RETURN NEW;
END IF;

-- Get points configuration
SELECT contact_created_points INTO points_config
FROM points_configuration
LIMIT 1;

-- If no config exists or points are 0, skip
IF points_config IS NULL OR points_config.contact_created_points = 0 THEN
RETURN NEW;
END IF;

-- Award points
INSERT INTO points_transactions (user_id, points_amount, transaction_type, reference_id, description)
VALUES (
NEW.created_by,
points_config.contact_created_points,
'admin_adjustment',
NEW.id,
'Contact created: ' || COALESCE(NEW.contact_name, 'New Contact')
);

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.award_points_for_fishbowl_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
points_config RECORD;
BEGIN
-- Get points configuration
SELECT fishbowl_post_points INTO points_config
FROM points_configuration
LIMIT 1;

-- If no config exists or points are 0, skip
IF points_config IS NULL OR points_config.fishbowl_post_points = 0 THEN
RETURN NEW;
END IF;

-- Only award points for public posts (not private)
IF NEW.is_private = false THEN
-- Award points
INSERT INTO points_transactions (user_id, points_amount, transaction_type, reference_id, description)
VALUES (
NEW.author_id,
points_config.fishbowl_post_points,
'admin_adjustment',
NEW.id,
'Fishbowl post created'
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.award_points_for_lead_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
points_config RECORD;
BEGIN
-- Skip if this is an anonymous lead (created_by is NULL)
IF NEW.created_by IS NULL THEN
RETURN NEW;
END IF;

-- Get points configuration
SELECT lead_created_points INTO points_config
FROM points_configuration
LIMIT 1;

-- If no config exists or points are 0, skip
IF points_config IS NULL OR points_config.lead_created_points = 0 THEN
RETURN NEW;
END IF;

-- Award points
INSERT INTO points_transactions (user_id, points_amount, transaction_type, reference_id, description)
VALUES (
NEW.created_by,
points_config.lead_created_points,
'admin_adjustment',
NEW.id,
'Lead created: ' || COALESCE(NEW.company_name, 'New Lead')
);

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.award_points_for_lead_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
points_config RECORD;
points_to_award integer;
award_description text;
BEGIN
-- Get points configuration
SELECT lead_claimed_points, lead_converted_points INTO points_config
FROM points_configuration
LIMIT 1;

-- If no config exists, skip
IF points_config IS NULL THEN
RETURN NEW;
END IF;

-- Check for lead claimed (status changed from unclaimed to claimed)
IF OLD.status = 'unclaimed' AND NEW.status = 'claimed' AND NEW.assigned_to IS NOT NULL THEN
IF points_config.lead_claimed_points > 0 THEN
INSERT INTO points_transactions (user_id, points_amount, transaction_type, reference_id, description)
VALUES (
NEW.assigned_to,
points_config.lead_claimed_points,
'admin_adjustment',
NEW.id,
'Lead claimed: ' || COALESCE(NEW.company_name, 'Lead')
);
END IF;
END IF;

-- Check for lead converted (status changed to converted/won)
IF OLD.status != 'converted' AND NEW.status = 'converted' AND NEW.assigned_to IS NOT NULL THEN
IF points_config.lead_converted_points > 0 THEN
INSERT INTO points_transactions (user_id, points_amount, transaction_type, reference_id, description)
VALUES (
NEW.assigned_to,
points_config.lead_converted_points,
'admin_adjustment',
NEW.id,
'Lead converted: ' || COALESCE(NEW.company_name, 'Lead')
);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.award_task_points()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
target_user_id uuid;
task_points integer;
BEGIN
-- Only award points when task is newly marked as completed
IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
-- Determine who completed the task
IF NEW.claimed_by IS NOT NULL THEN
target_user_id := NEW.claimed_by;
ELSIF NEW.assigned_to IS NOT NULL THEN
target_user_id := NEW.assigned_to;
ELSE
target_user_id := NEW.user_id;
END IF;

task_points := COALESCE(NEW.points, 10);

-- Create or update user_points record
INSERT INTO user_points (user_id, total_points)
VALUES (target_user_id, task_points)
ON CONFLICT (user_id)
DO UPDATE SET
total_points = user_points.total_points + task_points,
updated_at = now();

-- Add to points history
INSERT INTO points_history (user_id, task_id, points, reason)
VALUES (
target_user_id,
NEW.id,
task_points,
'Completed task: ' || NEW.title
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.batch_determine_jurisdiction(p_entry_ids uuid[])
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_total int := 0;
v_high int := 0;
v_medium int := 0;
v_low int := 0;
v_unassigned int := 0;
v_needs_review int := 0;
v_result json;
v_entry_id uuid;
BEGIN
FOREACH v_entry_id IN ARRAY p_entry_ids LOOP
v_result := determine_work_jurisdiction(v_entry_id);
v_total := v_total + 1;

IF (v_result->>'confidence') = 'high' THEN
v_high := v_high + 1;
ELSIF (v_result->>'confidence') = 'medium' THEN
v_medium := v_medium + 1;
ELSIF (v_result->>'confidence') = 'low' THEN
v_low := v_low + 1;
ELSIF (v_result->>'confidence') = 'unassigned' THEN
v_unassigned := v_unassigned + 1;
END IF;

IF (v_result->>'needs_review') = 'true' THEN
v_needs_review := v_needs_review + 1;
END IF;
END LOOP;

RETURN json_build_object(
'total', v_total,
'high_confidence', v_high,
'medium_confidence', v_medium,
'low_confidence', v_low,
'unassigned', v_unassigned,
'needs_review', v_needs_review
);
END;
$function$


CREATE OR REPLACE FUNCTION public.bytea_to_text(data bytea)
 RETURNS text
 LANGUAGE c
 IMMUTABLE STRICT
AS '$libdir/http', $function$bytea_to_text$function$


CREATE OR REPLACE FUNCTION public.calculate_break_duration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.break_end IS NOT NULL AND (OLD.break_end IS NULL OR NEW.break_end != OLD.break_end) THEN
NEW.break_duration_minutes = EXTRACT(EPOCH FROM (NEW.break_end - NEW.break_start)) / 60.0;

-- Update the daily clock entry's total break minutes
UPDATE daily_clock_entries
SET break_minutes = (
SELECT COALESCE(SUM(break_duration_minutes), 0)
FROM daily_clock_breaks
WHERE daily_clock_entry_id = NEW.daily_clock_entry_id
)
WHERE id = NEW.daily_clock_entry_id;
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_change_order_totals(p_change_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_net_change        numeric(10,2) := 0;
v_running_total     numeric(10,2) := 0;
v_tax_rate          numeric(5,4)  := 0;
v_tax_environment   text;
v_tax_project_type  text;
v_tax_state         text;
v_parts_taxable     boolean;
v_labor_taxable     boolean;
v_tax_amount        numeric(10,2) := 0;
v_change_amount     numeric(10,2) := 0;
v_co_record         record;
v_org_id            uuid;
v_review_required   boolean := false;
v_material_result   jsonb;
v_labor_result      jsonb;

-- Modifier amounts
v_discount_amount        numeric(10,2) := 0;
v_project_mgmt_amount    numeric(10,2) := 0;
v_project_design_amount  numeric(10,2) := 0;
v_system_design_amount   numeric(10,2) := 0;
v_credit_card_fee_amount numeric(10,2) := 0;
v_misc_parts_amount      numeric(10,2) := 0;
v_custom_mod_1_amount    numeric(10,2) := 0;
v_custom_mod_2_amount    numeric(10,2) := 0;
BEGIN
SELECT * INTO v_co_record
FROM change_orders
WHERE id = p_change_order_id;

IF NOT FOUND THEN
RETURN;
END IF;

-- Sum the signed change_amount from each line item (the true delta per item).
-- Exclude modify_modifiers rows as those are handled via modifier fields.
SELECT COALESCE(SUM(change_amount), 0)
INTO v_net_change
FROM change_order_line_items
WHERE change_order_id = p_change_order_id
AND action_type <> 'modify_modifiers';

v_running_total := v_net_change;

-- Apply modifiers (percentages applied to the pre-modifier net change)
IF v_co_record.apply_discount AND v_co_record.discount_percent > 0 THEN
v_discount_amount := v_net_change * (v_co_record.discount_percent / 100);
v_running_total := v_running_total - v_discount_amount;
END IF;

IF v_co_record.apply_project_management AND v_co_record.project_management_percent > 0 THEN
v_project_mgmt_amount := v_net_change * (v_co_record.project_management_percent / 100);
v_running_total := v_running_total + v_project_mgmt_amount;
END IF;

IF v_co_record.apply_project_design AND v_co_record.project_design_percent > 0 THEN
v_project_design_amount := v_net_change * (v_co_record.project_design_percent / 100);
v_running_total := v_running_total + v_project_design_amount;
END IF;

IF v_co_record.apply_system_design AND v_co_record.system_design_percent > 0 THEN
v_system_design_amount := v_net_change * (v_co_record.system_design_percent / 100);
v_running_total := v_running_total + v_system_design_amount;
END IF;

-- Credit card fee is still calculated and stored on the change order record
-- but is NO LONGER added to the change order total (payment-method fee, not project pricing)
IF v_co_record.apply_credit_card_fee AND v_co_record.credit_card_fee_percent > 0 THEN
v_credit_card_fee_amount := v_net_change * (v_co_record.credit_card_fee_percent / 100);
END IF;

IF v_co_record.apply_misc_parts AND v_co_record.misc_parts_percent > 0 THEN
v_misc_parts_amount := v_net_change * (v_co_record.misc_parts_percent / 100);
v_running_total := v_running_total + v_misc_parts_amount;
END IF;

IF v_co_record.apply_custom_modifier_1 AND v_co_record.custom_modifier_1_percent > 0 THEN
v_custom_mod_1_amount := v_net_change * (v_co_record.custom_modifier_1_percent / 100);
v_running_total := v_running_total + v_custom_mod_1_amount;
END IF;

IF v_co_record.apply_custom_modifier_2 AND v_co_record.custom_modifier_2_percent > 0 THEN
v_custom_mod_2_amount := v_net_change * (v_co_record.custom_modifier_2_percent / 100);
v_running_total := v_running_total + v_custom_mod_2_amount;
END IF;

-- Tax configuration
v_tax_rate         := COALESCE(v_co_record.tax_rate, 0);
v_tax_environment  := COALESCE(v_co_record.tax_environment, 'residential');
v_tax_project_type := COALESCE(v_co_record.tax_project_type, 'general_installation_repair');

-- Resolve state and org from the parent proposal
SELECT p.jobsite_state, p.organization_id
INTO v_tax_state, v_org_id
FROM proposals p
WHERE p.id = v_co_record.proposal_id;

v_tax_state := COALESCE(v_tax_state, '');

-- Resolve taxability via resolve_tax_rule
v_material_result := resolve_tax_rule(v_tax_state, v_org_id, v_tax_environment, v_tax_project_type, 'material');
v_labor_result := resolve_tax_rule(v_tax_state, v_org_id, v_tax_environment, v_tax_project_type, 'labor');

v_parts_taxable := (v_material_result->>'taxability_status' = 'taxable');
v_labor_taxable := (v_labor_result->>'taxability_status' = 'taxable');

IF v_material_result->>'taxability_status' = 'needs_review'
OR v_labor_result->>'taxability_status' = 'needs_review' THEN
v_review_required := true;
END IF;

-- Apply tax only when taxable (use full running total since we no longer split parts/labor)
IF v_parts_taxable OR v_labor_taxable THEN
v_tax_amount := v_running_total * v_tax_rate;
END IF;

v_change_amount := v_running_total + v_tax_amount;

UPDATE change_orders
SET
subtotal_after_modifiers     = v_running_total,
discount_amount              = v_discount_amount,
project_management_amount    = v_project_mgmt_amount,
project_design_amount        = v_project_design_amount,
system_design_amount         = v_system_design_amount,
credit_card_fee_amount       = v_credit_card_fee_amount,
misc_parts_amount            = v_misc_parts_amount,
custom_modifier_1_amount     = v_custom_mod_1_amount,
custom_modifier_2_amount     = v_custom_mod_2_amount,
tax_amount                   = v_tax_amount,
change_amount                = v_change_amount,
new_contract_total           = COALESCE(original_contract_amount, 0) + v_change_amount,
tax_review_required          = v_review_required,
updated_at                   = now()
WHERE id = p_change_order_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_claim_duration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF OLD.status IN ('unclaimed', 'fishbowl') AND NEW.status NOT IN ('unclaimed', 'fishbowl') AND NEW.claimed_at IS NOT NULL THEN
IF OLD.time_to_claim_seconds IS NULL THEN
NEW.time_to_claim_seconds = EXTRACT(EPOCH FROM (NEW.claimed_at - NEW.created_at))::integer;
END IF;

IF OLD.claimed_at IS NULL OR OLD.claimed_at <> NEW.claimed_at THEN
NEW.unclaimed_duration_seconds = COALESCE(OLD.unclaimed_duration_seconds, 0) + 
EXTRACT(EPOCH FROM (NEW.claimed_at - COALESCE(OLD.claimed_at, NEW.created_at)))::integer;
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_convenience_fee(p_amount numeric, p_payment_type text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_payment_type = 'card' THEN
    RETURN ROUND(p_amount * 0.03, 2);
  ELSE
    RETURN 0;
  END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_customer_completeness(p_company_name text, p_given_name text, p_family_name text, p_email text, p_phone text, p_address jsonb)
 RETURNS TABLE(completeness_status text, missing_fields text[], completeness_score integer)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
v_missing_fields text[] := ARRAY[]::text[];
v_score integer := 0;
v_status text;
BEGIN
-- Check required fields
IF p_company_name IS NOT NULL AND p_company_name != '' THEN
v_score := v_score + 20;
ELSE
v_missing_fields := array_append(v_missing_fields, 'company_name');
END IF;

IF (p_given_name IS NOT NULL AND p_given_name != '') OR (p_family_name IS NOT NULL AND p_family_name != '') THEN
v_score := v_score + 20;
ELSE
v_missing_fields := array_append(v_missing_fields, 'contact_name');
END IF;

IF p_email IS NOT NULL AND p_email != '' THEN
v_score := v_score + 20;
ELSE
v_missing_fields := array_append(v_missing_fields, 'email');
END IF;

IF p_phone IS NOT NULL AND p_phone != '' THEN
v_score := v_score + 20;
ELSE
v_missing_fields := array_append(v_missing_fields, 'phone');
END IF;

IF p_address IS NOT NULL AND
p_address->>'Line1' IS NOT NULL AND
p_address->>'City' IS NOT NULL AND
p_address->>'PostalCode' IS NOT NULL THEN
v_score := v_score + 20;
ELSE
v_missing_fields := array_append(v_missing_fields, 'address');
END IF;

-- Determine status based on score
IF v_score >= 80 THEN
v_status := 'complete';
ELSIF v_score >= 40 THEN
v_status := 'partial';
ELSE
v_status := 'minimal';
END IF;

RETURN QUERY SELECT v_status, v_missing_fields, v_score;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_daily_clock_hours()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.clock_out IS NOT NULL AND (OLD.clock_out IS NULL OR NEW.clock_out != OLD.clock_out) THEN
NEW.total_hours = EXTRACT(EPOCH FROM (NEW.clock_out - NEW.clock_in)) / 3600.0 - (NEW.break_minutes / 60.0);
IF NEW.status = 'clocked_in' THEN
NEW.status = 'clocked_out';
END IF;
END IF;
NEW.updated_at = now();
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_distance_meters(lat1 numeric, lng1 numeric, lat2 numeric, lng2 numeric)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
earth_radius_km constant numeric := 6371.0;
d_lat numeric;
d_lng numeric;
a numeric;
c numeric;
distance_km numeric;
BEGIN
d_lat := radians(lat2 - lat1);
d_lng := radians(lng2 - lng1);

a := sin(d_lat / 2) * sin(d_lat / 2) +
cos(radians(lat1)) * cos(radians(lat2)) *
sin(d_lng / 2) * sin(d_lng / 2);

c := 2 * atan2(sqrt(a), sqrt(1 - a));
distance_km := earth_radius_km * c;

RETURN CAST(distance_km * 1000 AS integer);
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_distance_miles(lat1 numeric, lon1 numeric, lat2 numeric, lon2 numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
earth_radius decimal := 3958.8; -- Earth's radius in miles
dlat decimal;
dlon decimal;
a decimal;
c decimal;
BEGIN
dlat := radians(lat2 - lat1);
dlon := radians(lon2 - lon1);

a := sin(dlat/2) * sin(dlat/2) + 
cos(radians(lat1)) * cos(radians(lat2)) * 
sin(dlon/2) * sin(dlon/2);

c := 2 * atan2(sqrt(a), sqrt(1-a));

RETURN earth_radius * c;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_eta(tech_id uuid, dest_lat numeric, dest_lng numeric)
 RETURNS TABLE(distance_meters integer, travel_time_seconds integer, estimated_arrival timestamp with time zone, tech_lat numeric, tech_lng numeric, location_age_seconds integer)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
tech_location record;
calc_distance integer;
calc_time integer;
BEGIN
-- Get tech's most recent location
SELECT * INTO tech_location 
FROM get_tech_current_location(tech_id);

IF tech_location IS NULL THEN
RETURN;
END IF;

-- Calculate distance
calc_distance := calculate_distance_meters(
tech_location.latitude,
tech_location.longitude,
dest_lat,
dest_lng
);

-- Estimate travel time
calc_time := estimate_travel_time(calc_distance);

-- Return all calculated values
RETURN QUERY SELECT
calc_distance,
calc_time,
now() + (calc_time || ' seconds')::interval,
tech_location.latitude,
tech_location.longitude,
EXTRACT(epoch FROM (now() - tech_location.recorded_at))::integer;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_gps_quality_score(p_accuracy real, p_method text, p_duration_ms integer, p_refined boolean, p_original_accuracy real)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
v_score integer := 0;
v_accuracy_score integer := 0;
v_method_bonus integer := 0;
v_duration_penalty integer := 0;
v_refinement_bonus integer := 0;
BEGIN
-- Handle NULL or failed captures
IF p_accuracy IS NULL OR p_method = 'failed' OR p_method = 'none' THEN
RETURN 0;
END IF;

-- Calculate accuracy score (0-100)
-- Excellent: <10m = 100, Good: <50m = 90+, Fair: <200m = 70+, Poor: <500m = 40+, Very Poor: >500m = 0-40
IF p_accuracy < 10 THEN
v_accuracy_score := 100;
ELSIF p_accuracy < 50 THEN
v_accuracy_score := 90 + ROUND((50 - p_accuracy) / 4)::integer;
ELSIF p_accuracy < 200 THEN
v_accuracy_score := 70 + ROUND((200 - p_accuracy) / 7.5)::integer;
ELSIF p_accuracy < 500 THEN
v_accuracy_score := 40 + ROUND((500 - p_accuracy) / 10)::integer;
ELSIF p_accuracy < 1000 THEN
v_accuracy_score := GREATEST(0, ROUND(40 - (p_accuracy - 500) / 12.5)::integer);
ELSE
v_accuracy_score := 0;
END IF;

-- Method bonus
CASE p_method
WHEN 'high_accuracy' THEN v_method_bonus := 10;
WHEN 'network' THEN v_method_bonus := 5;
WHEN 'cached' THEN v_method_bonus := 0;
WHEN 'emergency' THEN v_method_bonus := -10;
ELSE v_method_bonus := 0;
END CASE;

-- Duration penalty (penalize slow captures)
IF p_duration_ms > 5000 THEN
v_duration_penalty := -1 * LEAST(20, ((p_duration_ms - 5000) / 1000)::integer);
END IF;

-- Refinement bonus
IF p_refined = true AND p_original_accuracy IS NOT NULL AND p_original_accuracy > p_accuracy * 1.5 THEN
v_refinement_bonus := 15;
END IF;

-- Calculate total score
v_score := v_accuracy_score + v_method_bonus + v_duration_penalty + v_refinement_bonus;

-- Clamp to 0-100 range
RETURN GREATEST(0, LEAST(100, v_score));
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_line_item_tax(p_environment text, p_project_type text, p_item_type text, p_amount numeric, p_tax_rate numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
-- Exempt project - no tax
IF p_project_type = 'exempt_project' THEN
RETURN 0;
END IF;

-- Design services - no tax (should be separate invoice)
IF p_project_type = 'design_services' THEN
RETURN 0;
END IF;

-- Security monitoring - only non-taxable on recurring (handle in application)
-- Maintenance/Memberships - always taxable
IF p_project_type IN ('maintenance_agreement', 'membership') THEN
RETURN p_amount * p_tax_rate;
END IF;

-- Residential original construction
IF p_environment = 'residential' AND p_project_type = 'original_construction' THEN
IF p_item_type = 'labor' THEN
RETURN 0; -- Labor not taxed
ELSE
RETURN p_amount * p_tax_rate; -- Materials taxed
END IF;
END IF;

-- Residential remodel
IF p_environment = 'residential' AND p_project_type = 'remodel' THEN
IF p_item_type = 'labor' THEN
RETURN 0; -- Labor not taxed
ELSE
RETURN p_amount * p_tax_rate; -- Materials taxed
END IF;
END IF;

-- Commercial original construction
IF p_environment = 'commercial' AND p_project_type = 'original_construction' THEN
IF p_item_type = 'labor' THEN
RETURN 0; -- Labor not taxed
ELSE
RETURN p_amount * p_tax_rate; -- Materials taxed
END IF;
END IF;

-- Commercial remodel
IF p_environment = 'commercial' AND p_project_type = 'remodel' THEN
RETURN p_amount * p_tax_rate; -- Both labor and materials taxed
END IF;

-- General installation/repair (both residential and commercial)
IF p_project_type = 'general_installation_repair' THEN
RETURN p_amount * p_tax_rate; -- Both labor and materials taxed
END IF;

-- Default: apply tax
RETURN p_amount * p_tax_rate;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_next_billing_date(p_date date, p_frequency text, p_billing_day integer DEFAULT NULL::integer)
 RETURNS date
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
CASE p_frequency
WHEN 'daily' THEN
RETURN p_date + INTERVAL '1 day';
WHEN 'weekly' THEN
RETURN p_date + INTERVAL '1 week';
WHEN 'monthly' THEN
IF p_billing_day IS NOT NULL THEN
-- Bill on specific day of month
RETURN (date_trunc('month', p_date) + INTERVAL '1 month' + (p_billing_day - 1 || ' days')::interval)::date;
ELSE
RETURN p_date + INTERVAL '1 month';
END IF;
WHEN 'quarterly' THEN
RETURN p_date + INTERVAL '3 months';
WHEN 'yearly' THEN
RETURN p_date + INTERVAL '1 year';
ELSE
RETURN p_date + INTERVAL '1 month';
END CASE;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_next_occurrence_date(p_current_date date, p_pattern text, p_interval integer, p_day_rule text)
 RETURNS date
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_next_date date;
v_day_of_week integer;
v_target_day integer;
BEGIN
CASE p_pattern
WHEN 'weekly' THEN
IF p_day_rule IS NULL THEN
v_next_date := p_current_date + (7 * p_interval);
ELSE
-- Get target day (0=Sunday, 6=Saturday)
v_target_day := CASE p_day_rule
WHEN 'sunday' THEN 0
WHEN 'monday' THEN 1
WHEN 'tuesday' THEN 2
WHEN 'wednesday' THEN 3
WHEN 'thursday' THEN 4
WHEN 'friday' THEN 5
WHEN 'saturday' THEN 6
ELSE EXTRACT(DOW FROM p_current_date)::integer
END;

v_next_date := p_current_date + (7 * p_interval);
v_day_of_week := EXTRACT(DOW FROM v_next_date)::integer;

-- Adjust to target day
IF v_day_of_week != v_target_day THEN
v_next_date := v_next_date + (v_target_day - v_day_of_week + 7) % 7;
END IF;
END IF;

WHEN 'biweekly' THEN
v_next_date := p_current_date + 14;

WHEN 'monthly' THEN
IF p_day_rule IS NULL OR p_day_rule = '' THEN
-- Same day next month
v_next_date := p_current_date + INTERVAL '1 month' * p_interval;
ELSIF p_day_rule ~ '^\\d+$' THEN
-- Specific day of month (e.g., '15th')
v_next_date := (DATE_TRUNC('month', p_current_date) + INTERVAL '1 month' * p_interval)::date + (p_day_rule::integer - 1);
ELSIF p_day_rule = 'first_monday' THEN
v_next_date := DATE_TRUNC('month', p_current_date + INTERVAL '1 month' * p_interval)::date;
v_day_of_week := EXTRACT(DOW FROM v_next_date)::integer;
v_next_date := v_next_date + ((1 - v_day_of_week + 7) % 7);
ELSIF p_day_rule = 'first_tuesday' THEN
v_next_date := DATE_TRUNC('month', p_current_date + INTERVAL '1 month' * p_interval)::date;
v_day_of_week := EXTRACT(DOW FROM v_next_date)::integer;
v_next_date := v_next_date + ((2 - v_day_of_week + 7) % 7);
ELSIF p_day_rule = 'first_friday' THEN
v_next_date := DATE_TRUNC('month', p_current_date + INTERVAL '1 month' * p_interval)::date;
v_day_of_week := EXTRACT(DOW FROM v_next_date)::integer;
v_next_date := v_next_date + ((5 - v_day_of_week + 7) % 7);
ELSE
v_next_date := p_current_date + INTERVAL '1 month' * p_interval;
END IF;

WHEN 'quarterly' THEN
v_next_date := p_current_date + INTERVAL '3 months';

WHEN 'semi_annually' THEN
v_next_date := p_current_date + INTERVAL '6 months';

WHEN 'annually' THEN
v_next_date := p_current_date + INTERVAL '1 year';

WHEN 'custom' THEN
-- Custom interval in months
v_next_date := p_current_date + (INTERVAL '1 month' * p_interval);

ELSE
v_next_date := p_current_date + 1;
END CASE;

RETURN v_next_date;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_pm_aggregate_metrics(p_pm_id uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date)
 RETURNS TABLE(total_projects integer, completed_projects integer, first_time_completions integer, first_time_completion_rate numeric, total_post_completion_hours numeric, avg_post_completion_hours numeric, total_labor_drag_cost numeric, total_labor_savings numeric, projects_on_track integer, projects_at_risk integer, projects_over_budget integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_start_date date := COALESCE(p_start_date, CURRENT_DATE - INTERVAL '90 days');
v_end_date date := COALESCE(p_end_date, CURRENT_DATE);
v_labor_rate numeric := 75.00;
BEGIN
RETURN QUERY
WITH project_stats AS (
SELECT
so.id,
p.project_manager_id,
so.test_tune_start_date,
so.test_tune_end_date,
so.completion_attempts,
so.first_completion_hours,
so.field_labor_target_hours,
COALESCE(labor.field_hours, 0) as current_field_hours,
COALESCE(labor.post_completion_hours, 0) as post_completion_hours,
CASE
WHEN COALESCE(labor.field_hours, 0) <= (so.field_labor_target_hours * 0.75) THEN 'on_track'
WHEN COALESCE(labor.field_hours, 0) <= so.field_labor_target_hours THEN 'at_risk'
ELSE 'over_budget'
END as status,
CASE
WHEN COALESCE(labor.field_hours, 0) > so.field_labor_target_hours
THEN (COALESCE(labor.field_hours, 0) - so.field_labor_target_hours) * v_labor_rate
ELSE 0
END as labor_drag_cost,
CASE
WHEN COALESCE(labor.field_hours, 0) < so.field_labor_target_hours
THEN (so.field_labor_target_hours - COALESCE(labor.field_hours, 0)) * v_labor_rate
ELSE 0
END as labor_savings
FROM sales_orders so
INNER JOIN projects p ON p.sales_order_id = so.id
LEFT JOIN LATERAL (
SELECT
SUM(CASE WHEN lp.labor_phase = 'Field Labor' THEN COALESCE(wo.actual_hours, 0) ELSE 0 END) as field_hours,
SUM(CASE
WHEN so.first_completion_date IS NOT NULL
AND wo.completed_at > so.first_completion_date
AND lp.labor_phase = 'Field Labor'
THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as post_completion_hours
FROM work_orders wo
LEFT JOIN labor_phases lp ON lp.id = wo.labor_phase_id
WHERE wo.sales_order_id = so.id AND wo.status = 'completed'
) labor ON true
WHERE p.project_manager_id = p_pm_id
AND so.test_tune_status = 'active'
AND so.test_tune_start_date >= v_start_date
AND so.test_tune_end_date <= v_end_date
)
SELECT
COUNT(*)::integer as total_projects,
COUNT(CASE WHEN completion_attempts > 0 THEN 1 END)::integer as completed_projects,
COUNT(CASE WHEN completion_attempts = 1 THEN 1 END)::integer as first_time_completions,
CASE
WHEN COUNT(CASE WHEN completion_attempts > 0 THEN 1 END) > 0
THEN (COUNT(CASE WHEN completion_attempts = 1 THEN 1 END)::numeric /
COUNT(CASE WHEN completion_attempts > 0 THEN 1 END)::numeric * 100)
ELSE 0
END as first_time_completion_rate,
COALESCE(SUM(post_completion_hours), 0)::numeric as total_post_completion_hours,
CASE
WHEN COUNT(*) > 0
THEN (COALESCE(SUM(post_completion_hours), 0) / COUNT(*))::numeric
ELSE 0
END as avg_post_completion_hours,
COALESCE(SUM(labor_drag_cost), 0)::numeric as total_labor_drag_cost,
COALESCE(SUM(labor_savings), 0)::numeric as total_labor_savings,
COUNT(CASE WHEN status = 'on_track' THEN 1 END)::integer as projects_on_track,
COUNT(CASE WHEN status = 'at_risk' THEN 1 END)::integer as projects_at_risk,
COUNT(CASE WHEN status = 'over_budget' THEN 1 END)::integer as projects_over_budget
FROM project_stats;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_product_price()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.margin_percent IS NOT NULL AND NEW.cost IS NOT NULL AND NEW.cost > 0 THEN
NEW.our_price := NEW.cost / (1 - (NEW.margin_percent / 100));
ELSIF NEW.our_price IS NOT NULL AND NEW.cost IS NOT NULL AND NEW.our_price > 0 THEN
NEW.margin_percent := ((NEW.our_price - NEW.cost) / NEW.our_price) * 100;
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_proposal_items_hash(p_proposal_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
items_data text;
BEGIN
SELECT string_agg(
concat_ws('|',
pli.id,
pli.description,
pli.quantity,
pli.unit_price,
pli.labor_hours,
pli.updated_at
),
','
ORDER BY pli.created_at, pli.id
) INTO items_data
FROM proposal_line_items pli
WHERE pli.proposal_id = p_proposal_id;

-- Return MD5 hash of the concatenated items data
RETURN md5(COALESCE(items_data, ''));
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_proposal_line_item_labor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Compute labor normally regardless of is_customer_supplied
IF NEW.labor_hours IS NOT NULL AND NEW.labor_rate IS NOT NULL THEN
NEW.labor_total := NEW.labor_hours * COALESCE(NEW.quantity, 1) * NEW.labor_rate;
ELSE
NEW.labor_total := 0;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_proposal_readiness(proposal_id_input uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal proposals%ROWTYPE;
v_settings proposal_settings%ROWTYPE;
v_has_line_items boolean;
v_is_ready boolean := false;
BEGIN
-- Get proposal and settings
SELECT * INTO v_proposal FROM proposals WHERE id = proposal_id_input;
SELECT * INTO v_settings FROM proposal_settings WHERE proposal_id = proposal_id_input;

IF v_proposal IS NULL THEN
RETURN false;
END IF;

-- Check if proposal has line items
SELECT EXISTS(
SELECT 1 FROM proposal_line_items WHERE proposal_id = proposal_id_input
) INTO v_has_line_items;

-- Calculate readiness based on required criteria
v_is_ready := (
-- Details validation: Has title and contact
v_proposal.title IS NOT NULL AND
v_proposal.title != '' AND
v_proposal.contact_id IS NOT NULL AND

-- Must have line items
v_has_line_items AND

-- Settings must exist
v_settings IS NOT NULL AND

-- Contract validation: Has contract selected
v_settings.contract_id IS NOT NULL AND

-- Billing validation: Has deposit configuration
v_settings.require_deposit IS NOT NULL AND
v_settings.deposit_type IS NOT NULL AND

-- Tax validation: Has tax environment
v_proposal.tax_environment IS NOT NULL AND
v_proposal.tax_project_type IS NOT NULL AND

-- All sections have been reviewed at least once
v_settings.details_reviewed_at IS NOT NULL AND
v_settings.scope_reviewed_at IS NOT NULL AND
v_settings.contract_reviewed_at IS NOT NULL AND
v_settings.billing_reviewed_at IS NOT NULL AND
v_settings.tax_reviewed_at IS NOT NULL AND
v_settings.fees_reviewed_at IS NOT NULL
);

RETURN v_is_ready;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_proposal_totals(p_proposal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_parts_total numeric(10,2);
v_labor_total numeric(10,2);
v_subtotal numeric(10,2);
v_running_total numeric(10,2);
v_tax_rate numeric(5,4);
v_tax_environment text;
v_tax_project_type text;
v_tax_state text;
v_parts_taxable boolean;
v_labor_taxable boolean;
v_parts_tax numeric(10,2);
v_labor_tax numeric(10,2);
v_tax_amount numeric(10,2);
v_total numeric(10,2);
v_deposit_amount numeric(10,2);
v_deposit_type text;
v_deposit_percent numeric;
v_discount_percent numeric;
v_discount_amount numeric(10,2);
v_project_mgmt_percent numeric;
v_project_mgmt_amount numeric(10,2);
v_project_design_percent numeric;
v_project_design_amount numeric(10,2);
v_system_design_percent numeric;
v_system_design_amount numeric(10,2);
v_credit_card_fee_percent numeric;
v_credit_card_fee_amount numeric(10,2);
v_misc_parts_percent numeric;
v_misc_parts_amount numeric(10,2);
v_custom_mod_1_percent numeric;
v_custom_mod_1_amount numeric(10,2);
v_custom_mod_2_percent numeric;
v_custom_mod_2_amount numeric(10,2);
v_proposal_record record;
v_material_result jsonb;
v_labor_result jsonb;
v_org_id uuid;
v_review_required boolean := false;
BEGIN
SELECT * INTO v_proposal_record
FROM proposals
WHERE id = p_proposal_id;

IF NOT FOUND THEN
RETURN;
END IF;

-- Parts total: exclude customer-supplied items (material cost is zero)
SELECT COALESCE(SUM(line_total), 0)
INTO v_parts_total
FROM proposal_line_items
WHERE proposal_id = p_proposal_id
AND COALESCE(item_type, 'part') != 'labor'
AND COALESCE(is_customer_supplied, false) = false;

-- Labor total: INCLUDE customer-supplied items' labor
SELECT
COALESCE(SUM(
CASE
WHEN item_type = 'labor' THEN COALESCE(labor_total, line_total)
ELSE COALESCE(labor_total, 0)
END
), 0)
INTO v_labor_total
FROM proposal_line_items
WHERE proposal_id = p_proposal_id;

v_subtotal := v_parts_total + v_labor_total;
v_running_total := v_subtotal;

SELECT
COALESCE(ps.discount_percent, 0),
COALESCE(ps.project_management_percent, 0),
COALESCE(ps.project_design_percent, 0),
COALESCE(ps.system_design_percent, 0),
COALESCE(ps.credit_card_fee_percent, 0),
COALESCE(ps.misc_parts_percent, 0),
COALESCE(ps.custom_modifier_1_percent, 0),
COALESCE(ps.custom_modifier_2_percent, 0),
COALESCE(ps.deposit_type, 'percentage'),
COALESCE(ps.deposit_percent, 50)
INTO
v_discount_percent,
v_project_mgmt_percent,
v_project_design_percent,
v_system_design_percent,
v_credit_card_fee_percent,
v_misc_parts_percent,
v_custom_mod_1_percent,
v_custom_mod_2_percent,
v_deposit_type,
v_deposit_percent
FROM proposal_settings ps
WHERE ps.proposal_id = p_proposal_id;

IF v_proposal_record.discount_percent IS NOT NULL AND v_proposal_record.discount_percent > 0 THEN
v_discount_percent := v_proposal_record.discount_percent;
END IF;
IF v_proposal_record.project_management_percent IS NOT NULL AND v_proposal_record.project_management_percent > 0 THEN
v_project_mgmt_percent := v_proposal_record.project_management_percent;
END IF;
IF v_proposal_record.project_design_percent IS NOT NULL AND v_proposal_record.project_design_percent > 0 THEN
v_project_design_percent := v_proposal_record.project_design_percent;
END IF;

v_discount_amount := v_subtotal * (v_discount_percent / 100);
v_project_mgmt_amount := v_subtotal * (v_project_mgmt_percent / 100);
v_project_design_amount := v_subtotal * (v_project_design_percent / 100);
v_system_design_amount := v_subtotal * (v_system_design_percent / 100);
-- Credit card fee is still calculated and stored on the proposal record
-- but is NO LONGER added to the project total (it is a payment-method fee, not project pricing)
v_credit_card_fee_amount := v_subtotal * (v_credit_card_fee_percent / 100);
v_misc_parts_amount := v_subtotal * (v_misc_parts_percent / 100);
v_custom_mod_1_amount := v_subtotal * (v_custom_mod_1_percent / 100);
v_custom_mod_2_amount := v_subtotal * (v_custom_mod_2_percent / 100);

v_running_total := v_running_total
- v_discount_amount
+ v_project_mgmt_amount
+ v_project_design_amount
+ v_system_design_amount
+ v_misc_parts_amount
+ v_custom_mod_1_amount
+ v_custom_mod_2_amount;

v_tax_rate := COALESCE(v_proposal_record.tax_rate, 0);
v_tax_environment := COALESCE(v_proposal_record.tax_environment, 'residential');
v_tax_project_type := COALESCE(v_proposal_record.tax_project_type, 'general_installation_repair');
v_tax_state := COALESCE(v_proposal_record.jobsite_state, '');
v_org_id := v_proposal_record.organization_id;

-- Resolve taxability via resolve_tax_rule
v_material_result := resolve_tax_rule(v_tax_state, v_org_id, v_tax_environment, v_tax_project_type, 'material');
v_labor_result := resolve_tax_rule(v_tax_state, v_org_id, v_tax_environment, v_tax_project_type, 'labor');

v_parts_taxable := (v_material_result->>'taxability_status' = 'taxable');
v_labor_taxable := (v_labor_result->>'taxability_status' = 'taxable');

IF v_material_result->>'taxability_status' = 'needs_review'
OR v_labor_result->>'taxability_status' = 'needs_review' THEN
v_review_required := true;
END IF;

IF v_parts_taxable THEN
v_parts_tax := v_parts_total * v_tax_rate;
ELSE
v_parts_tax := 0;
END IF;

IF v_labor_taxable THEN
v_labor_tax := v_labor_total * v_tax_rate;
ELSE
v_labor_tax := 0;
END IF;

v_tax_amount := v_parts_tax + v_labor_tax;
v_total := v_running_total + v_tax_amount;

IF v_deposit_type = 'percentage' THEN
v_deposit_amount := v_total * (v_deposit_percent / 100);
ELSIF v_deposit_type = 'parts_total' THEN
v_deposit_amount := v_parts_total;
ELSIF v_deposit_type = 'custom' THEN
SELECT COALESCE(deposit_amount, 0)
INTO v_deposit_amount
FROM proposal_settings
WHERE proposal_id = p_proposal_id;
ELSE
v_deposit_amount := 0;
END IF;

UPDATE proposals
SET
parts_total = v_parts_total,
labor_total = v_labor_total,
subtotal = v_subtotal,
discount_amount = v_discount_amount,
project_management_amount = v_project_mgmt_amount,
project_design_amount = v_project_design_amount,
system_design_amount = v_system_design_amount,
credit_card_fee_amount = v_credit_card_fee_amount,
misc_parts_amount = v_misc_parts_amount,
custom_modifier_1_amount = v_custom_mod_1_amount,
custom_modifier_2_amount = v_custom_mod_2_amount,
tax_amount = v_tax_amount,
total = v_total,
deposit_amount_due = v_deposit_amount,
tax_review_required = v_review_required,
updated_at = now()
WHERE id = p_proposal_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_sales_quota(p_user_id uuid, p_as_of_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_profile record;
v_org record;
v_base_quota numeric;
v_escalation numeric;
v_start_date date;
v_years_elapsed integer;
v_current_year integer;
v_year_quota numeric;
v_breakdown jsonb := '[]'::jsonb;
v_year_actual numeric;
v_anniversary_start date;
v_anniversary_end date;
v_calendar_year integer;
i integer;
BEGIN
SELECT p.id, p.sales_rep_start_date, p.quota_mode, p.custom_base_quota,
p.custom_escalation_percentage, p.created_at, p.organization_id
INTO v_profile
FROM profiles p
WHERE p.id = p_user_id;

IF NOT FOUND THEN
RETURN jsonb_build_object('error', 'profile_not_found');
END IF;

SELECT o.default_base_annual_quota, o.default_quota_escalation_percentage,
o.default_quota_rolling_average_years
INTO v_org
FROM organizations o
WHERE o.id = v_profile.organization_id;

IF NOT FOUND THEN
v_org.default_base_annual_quota := 500000;
v_org.default_quota_escalation_percentage := 5.000;
v_org.default_quota_rolling_average_years := 3;
END IF;

v_start_date := COALESCE(v_profile.sales_rep_start_date, v_profile.created_at::date, p_as_of_date);

IF v_profile.quota_mode = 'custom_plus_escalation' AND v_profile.custom_base_quota IS NOT NULL THEN
v_base_quota := v_profile.custom_base_quota;
ELSE
v_base_quota := v_org.default_base_annual_quota;
END IF;

v_escalation := COALESCE(v_profile.custom_escalation_percentage, v_org.default_quota_escalation_percentage);

v_years_elapsed := GREATEST(0, EXTRACT(YEAR FROM AGE(p_as_of_date, v_start_date))::integer);
v_current_year := v_years_elapsed + 1;

FOR i IN 1..v_current_year LOOP
v_anniversary_start := (v_start_date + ((i - 1) || ' years')::interval)::date;
v_anniversary_end   := (v_start_date + (i || ' years')::interval - interval '1 day')::date;
v_calendar_year     := EXTRACT(YEAR FROM v_anniversary_start)::integer;

v_year_quota := ROUND(v_base_quota * POWER(1.0 + v_escalation / 100.0, i - 1), 2);

SELECT total_revenue INTO v_year_actual
FROM yearly_sales_performance
WHERE user_id = p_user_id AND year = v_calendar_year
LIMIT 1;

v_breakdown := v_breakdown || jsonb_build_object(
'year_number',    i,
'calendar_year',  v_calendar_year,
'window_start',   v_anniversary_start,
'window_end',     v_anniversary_end,
'quota',          v_year_quota,
'actual_revenue', COALESCE(v_year_actual, 0),
'rule',           CASE WHEN i = 1 THEN 'base' ELSE 'compound_growth' END
);
END LOOP;

RETURN jsonb_build_object(
'user_id',               p_user_id,
'start_date',            v_start_date,
'as_of_date',            p_as_of_date,
'current_year_number',   v_current_year,
'current_annual_quota',  v_year_quota,
'current_monthly_quota', ROUND(v_year_quota / 12.0, 2),
'quota_mode',            v_profile.quota_mode,
'base_quota_used',       v_base_quota,
'escalation_percentage', v_escalation,
'rolling_average_years', COALESCE(v_org.default_quota_rolling_average_years, 3),
'breakdown',             v_breakdown
);
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_tax(p_transaction_type text, p_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_org_id uuid;
v_txn_org_id uuid;
v_context jsonb;
v_status text;
v_tax_amount numeric;
BEGIN
-- ── 1. Caller authorization ───────────────────────────────────────────
-- When called by an authenticated user (not the service role), verify
-- the user belongs to the transaction's organization.
v_caller_org_id := auth.uid();
IF v_caller_org_id IS NOT NULL THEN
IF p_transaction_type = 'proposal' THEN
SELECT organization_id INTO v_txn_org_id FROM proposals WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'change_order' THEN
SELECT organization_id INTO v_txn_org_id FROM change_orders WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'invoice' THEN
SELECT organization_id INTO v_txn_org_id FROM invoices WHERE id = p_transaction_id;
ELSE
RETURN jsonb_build_object('error', 'Unknown transaction type: ' || p_transaction_type);
END IF;

IF v_txn_org_id IS NULL THEN
RETURN jsonb_build_object('error', 'Transaction not found');
END IF;

SELECT p.organization_id INTO v_caller_org_id
FROM profiles p WHERE p.id = v_caller_org_id;

IF v_caller_org_id IS NULL OR v_caller_org_id <> v_txn_org_id THEN
RETURN jsonb_build_object('error', 'You do not have access to this transaction');
END IF;
END IF;

-- ── 2. Call the single authoritative calculation engine ──────────────
v_context := calculate_tax_context(p_transaction_type, p_transaction_id);

-- If the engine returned an error, pass it through
IF v_context ? 'error' THEN
RETURN v_context;
END IF;

-- ── 3. Persist the status to the transaction row ─────────────────────
v_status := v_context->>'tax_calculation_status';
v_tax_amount := COALESCE((v_context->>'tax_amount')::numeric, 0);

IF p_transaction_type = 'proposal' THEN
UPDATE proposals SET
tax_review_required = (v_status = 'review_required'),
tax_calculation_status = v_status,
tax_amount = v_tax_amount
WHERE id = p_transaction_id;

ELSIF p_transaction_type = 'change_order' THEN
UPDATE change_orders SET
tax_review_required = (v_status = 'review_required'),
tax_calculation_status = v_status,
tax_amount = v_tax_amount
WHERE id = p_transaction_id;

ELSIF p_transaction_type = 'invoice' THEN
UPDATE invoices SET
tax_review_required = (v_status = 'review_required'),
tax_calculation_status = v_status,
tax_amount = v_tax_amount
WHERE id = p_transaction_id;
END IF;

-- ── 4. Return the result ──────────────────────────────────────────────
RETURN v_context;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_tax_context(p_transaction_type text, p_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_office_id uuid;
v_contact_id uuid;
v_state text;
v_environment text;
v_project_type text;
v_tax_rate numeric;
v_jobsite_street text;
v_jobsite_city text;
v_jobsite_state text;
v_jobsite_zip text;

v_material_taxability jsonb;
v_labor_taxability jsonb;
v_freight_taxability jsonb;
v_design_fee_taxability jsonb;
v_pm_taxability jsonb;
v_ccf_taxability jsonb;
v_taxability_results jsonb;
v_origin_result jsonb;
v_collection_status text;
v_nexus_status text;
v_destination_result jsonb;
v_is_exempt boolean := false;
v_exemption_ref text;

v_tax_calculation_status text;
v_review_reasons jsonb[] := ARRAY[]::jsonb[];

v_material_amount numeric := 0;
v_labor_amount numeric := 0;
v_freight_amount numeric := 0;
v_design_fee_amount numeric := 0;
v_pm_amount numeric := 0;
v_ccf_amount numeric := 0;
v_taxable_subtotal numeric := 0;
v_tax_amount numeric := 0;

v_freight_sc_id uuid;
v_cm1_sc_id uuid;
v_cm2_sc_id uuid;
v_cm1_amount numeric;
v_cm2_amount numeric;
v_cm1_apply boolean;
v_cm2_apply boolean;

v_classification_id uuid;
v_classification_code text;
v_line_amount numeric;
BEGIN
-- 1. Load the transaction record
IF p_transaction_type = 'proposal' THEN
SELECT organization_id, office_id, contact_id, tax_environment, tax_project_type,
tax_rate, jobsite_address, jobsite_city, jobsite_state, jobsite_zip
INTO v_org_id, v_office_id, v_contact_id, v_environment, v_project_type,
v_tax_rate, v_jobsite_street, v_jobsite_city, v_jobsite_state, v_jobsite_zip
FROM proposals WHERE id = p_transaction_id;

IF v_org_id IS NULL THEN
RETURN jsonb_build_object('error', 'Proposal not found');
END IF;

-- Material: sum parts_total (covers all material-classified line items)
SELECT parts_total, labor_total INTO v_material_amount, v_labor_amount
FROM proposals WHERE id = p_transaction_id;

-- Design fee, PM, freight from proposal-level fields
SELECT COALESCE(project_design_amount, 0), COALESCE(project_management_amount, 0), 0
INTO v_design_fee_amount, v_pm_amount, v_freight_amount
FROM proposals WHERE id = p_transaction_id;

-- CCF from proposal-level field
SELECT COALESCE(credit_card_fee_amount, 0) INTO v_ccf_amount
FROM proposals WHERE id = p_transaction_id;

ELSIF p_transaction_type = 'change_order' THEN
SELECT organization_id, office_id, contact_id, tax_environment, tax_project_type,
tax_rate
INTO v_org_id, v_office_id, v_contact_id, v_environment, v_project_type,
v_tax_rate
FROM change_orders WHERE id = p_transaction_id;

IF v_org_id IS NULL THEN
RETURN jsonb_build_object('error', 'Change order not found');
END IF;

-- Get jobsite address from parent proposal
SELECT p.jobsite_address, p.jobsite_city, p.jobsite_state, p.jobsite_zip
INTO v_jobsite_street, v_jobsite_city, v_jobsite_state, v_jobsite_zip
FROM proposals p
JOIN change_orders co ON co.proposal_id = p.id
WHERE co.id = p_transaction_id;

-- Amounts from change order line items grouped by classification
SELECT COALESCE(SUM(
CASE WHEN COALESCE(tc.code,
CASE WHEN COALESCE(coli.item_type, 'material') = 'labor' THEN 'labor'
ELSE 'material' END) = 'material'
THEN coli.amount ELSE 0 END
), 0)
INTO v_material_amount
FROM change_order_line_items coli
LEFT JOIN tax_classifications tc ON tc.id = coli.tax_classification_id
WHERE coli.change_order_id = p_transaction_id;

SELECT COALESCE(SUM(
CASE WHEN COALESCE(tc.code,
CASE WHEN COALESCE(coli.item_type, 'material') = 'labor' THEN 'labor'
ELSE 'material' END) = 'labor'
THEN coli.amount ELSE 0 END
), 0)
INTO v_labor_amount
FROM change_order_line_items coli
LEFT JOIN tax_classifications tc ON tc.id = coli.tax_classification_id
WHERE coli.change_order_id = p_transaction_id;

SELECT COALESCE(SUM(CASE WHEN tc.code = 'design_fee' THEN coli.amount ELSE 0 END), 0)
INTO v_design_fee_amount
FROM change_order_line_items coli
LEFT JOIN tax_classifications tc ON tc.id = coli.tax_classification_id
WHERE coli.change_order_id = p_transaction_id;

SELECT COALESCE(SUM(CASE WHEN tc.code = 'project_management' THEN coli.amount ELSE 0 END), 0)
INTO v_pm_amount
FROM change_order_line_items coli
LEFT JOIN tax_classifications tc ON tc.id = coli.tax_classification_id
WHERE coli.change_order_id = p_transaction_id;

SELECT COALESCE(SUM(CASE WHEN tc.code = 'freight_delivery' THEN coli.amount ELSE 0 END), 0)
INTO v_freight_amount
FROM change_order_line_items coli
LEFT JOIN tax_classifications tc ON tc.id = coli.tax_classification_id
WHERE coli.change_order_id = p_transaction_id;

SELECT COALESCE(SUM(CASE WHEN tc.code = 'credit_card_fee' THEN coli.amount ELSE 0 END), 0)
INTO v_ccf_amount
FROM change_order_line_items coli
LEFT JOIN tax_classifications tc ON tc.id = coli.tax_classification_id
WHERE coli.change_order_id = p_transaction_id;

ELSIF p_transaction_type = 'invoice' THEN
-- Load tax context from the invoices table directly
SELECT organization_id, office_id, contact_id, tax_environment, tax_project_type,
tax_rate, jobsite_address, jobsite_city, jobsite_state, jobsite_zip
INTO v_org_id, v_office_id, v_contact_id, v_environment, v_project_type,
v_tax_rate, v_jobsite_street, v_jobsite_city, v_jobsite_state, v_jobsite_zip
FROM invoices WHERE id = p_transaction_id;

IF v_org_id IS NULL THEN
RETURN jsonb_build_object('error', 'Invoice not found');
END IF;

-- If invoice's own tax fields are NULL, fall back to proposal JOIN (backward compat)
IF v_environment IS NULL AND v_jobsite_state IS NULL THEN
SELECT p.tax_environment, p.tax_project_type, p.tax_rate,
p.jobsite_address, p.jobsite_city, p.jobsite_state, p.jobsite_zip
INTO v_environment, v_project_type, v_tax_rate,
v_jobsite_street, v_jobsite_city, v_jobsite_state, v_jobsite_zip
FROM proposals p
JOIN invoices inv ON inv.proposal_id = p.id
WHERE inv.id = p_transaction_id
LIMIT 1;
END IF;

-- Group invoice line items by tax_classification_id, fall back to item_type
SELECT COALESCE(SUM(
CASE WHEN COALESCE(tc.code,
CASE WHEN COALESCE(ili.item_type, 'material') = 'labor' THEN 'labor'
ELSE 'material' END) = 'material'
THEN ili.amount ELSE 0 END
), 0)
INTO v_material_amount
FROM invoice_line_items ili
LEFT JOIN tax_classifications tc ON tc.id = ili.tax_classification_id
WHERE ili.invoice_id = p_transaction_id;

SELECT COALESCE(SUM(
CASE WHEN COALESCE(tc.code,
CASE WHEN COALESCE(ili.item_type, 'material') = 'labor' THEN 'labor'
ELSE 'material' END) = 'labor'
THEN ili.amount ELSE 0 END
), 0)
INTO v_labor_amount
FROM invoice_line_items ili
LEFT JOIN tax_classifications tc ON tc.id = ili.tax_classification_id
WHERE ili.invoice_id = p_transaction_id;

SELECT COALESCE(SUM(CASE WHEN tc.code = 'design_fee' THEN ili.amount ELSE 0 END), 0)
INTO v_design_fee_amount
FROM invoice_line_items ili
LEFT JOIN tax_classifications tc ON tc.id = ili.tax_classification_id
WHERE ili.invoice_id = p_transaction_id;

SELECT COALESCE(SUM(CASE WHEN tc.code = 'project_management' THEN ili.amount ELSE 0 END), 0)
INTO v_pm_amount
FROM invoice_line_items ili
LEFT JOIN tax_classifications tc ON tc.id = ili.tax_classification_id
WHERE ili.invoice_id = p_transaction_id;

SELECT COALESCE(SUM(CASE WHEN tc.code = 'freight_delivery' THEN ili.amount ELSE 0 END), 0)
INTO v_freight_amount
FROM invoice_line_items ili
LEFT JOIN tax_classifications tc ON tc.id = ili.tax_classification_id
WHERE ili.invoice_id = p_transaction_id;

-- Invoice branch: CCF amount IS read from line items (payment events may create CCF lines)
SELECT COALESCE(SUM(CASE WHEN tc.code = 'credit_card_fee' THEN ili.amount ELSE 0 END), 0)
INTO v_ccf_amount
FROM invoice_line_items ili
LEFT JOIN tax_classifications tc ON tc.id = ili.tax_classification_id
WHERE ili.invoice_id = p_transaction_id;

ELSE
RETURN jsonb_build_object('error', 'Unknown transaction type: ' || p_transaction_type);
END IF;

v_state := COALESCE(v_jobsite_state, '');
v_tax_rate := COALESCE(v_tax_rate, 0);
v_environment := COALESCE(v_environment, 'residential');
v_project_type := COALESCE(v_project_type, 'general_installation_repair');

-- 2. Resolve origin address
v_origin_result := resolve_tax_origin_address(v_org_id, v_office_id);
IF (v_origin_result->>'review_required')::boolean THEN
v_review_reasons := array_append(v_review_reasons,
jsonb_build_object('layer', 'origin', 'reason', v_origin_result->>'review_reason'));
END IF;

-- 3. Resolve taxability for all 6 classifications (CCF remains a valid classification)
v_material_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'material');
v_labor_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'labor');
v_freight_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'freight_delivery');
v_design_fee_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'design_fee');
v_pm_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'project_management');
v_ccf_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'credit_card_fee');

v_taxability_results := jsonb_build_object(
'material', v_material_taxability,
'labor', v_labor_taxability,
'freight_delivery', v_freight_taxability,
'design_fee', v_design_fee_taxability,
'project_management', v_pm_taxability,
'credit_card_fee', v_ccf_taxability
);

-- Flag needs_review only for classifications with non-zero amount ($0 rule)
IF v_material_amount > 0 AND v_material_taxability->>'taxability_status' = 'needs_review' THEN
v_review_reasons := array_append(v_review_reasons,
jsonb_build_object('layer', 'taxability', 'classification', 'material', 'reason', v_material_taxability->>'explanation'));
END IF;
IF v_labor_amount > 0 AND v_labor_taxability->>'taxability_status' = 'needs_review' THEN
v_review_reasons := array_append(v_review_reasons,
jsonb_build_object('layer', 'taxability', 'classification', 'labor', 'reason', v_labor_taxability->>'explanation'));
END IF;
IF v_freight_amount > 0 AND v_freight_taxability->>'taxability_status' = 'needs_review' THEN
v_review_reasons := array_append(v_review_reasons,
jsonb_build_object('layer', 'taxability', 'classification', 'freight_delivery', 'reason', v_freight_taxability->>'explanation'));
END IF;
IF v_design_fee_amount > 0 AND v_design_fee_taxability->>'taxability_status' = 'needs_review' THEN
v_review_reasons := array_append(v_review_reasons,
jsonb_build_object('layer', 'taxability', 'classification', 'design_fee', 'reason', v_design_fee_taxability->>'explanation'));
END IF;
IF v_pm_amount > 0 AND v_pm_taxability->>'taxability_status' = 'needs_review' THEN
v_review_reasons := array_append(v_review_reasons,
jsonb_build_object('layer', 'taxability', 'classification', 'project_management', 'reason', v_pm_taxability->>'explanation'));
END IF;
IF v_ccf_amount > 0 AND v_ccf_taxability->>'taxability_status' = 'needs_review' THEN
v_review_reasons := array_append(v_review_reasons,
jsonb_build_object('layer', 'taxability', 'classification', 'credit_card_fee', 'reason', v_ccf_taxability->>'explanation'));
END IF;

-- 4. Resolve destination / nexus
v_destination_result := resolve_tax_destination(v_state, v_org_id, v_contact_id);
IF (v_destination_result->>'review_required')::boolean THEN
v_review_reasons := array_append(v_review_reasons,
jsonb_build_object('layer', 'destination', 'reason', v_destination_result->>'review_reason'));
END IF;

v_collection_status := v_destination_result->>'collection_status';
v_nexus_status := v_destination_result->>'nexus_status';

-- 5. Resolve exemption
v_is_exempt := false;
v_exemption_ref := null;
IF v_contact_id IS NOT NULL THEN
SELECT exemption_reference INTO v_exemption_ref
FROM resolve_tax_exemption(v_contact_id, v_state, v_environment, v_project_type);
IF v_exemption_ref IS NOT NULL THEN
v_is_exempt := true;
END IF;
END IF;

-- 6. Compute tax amount
v_taxable_subtotal := v_material_amount + v_labor_amount + v_freight_amount
+ v_design_fee_amount + v_pm_amount + v_ccf_amount;

IF v_is_exempt THEN
v_tax_amount := 0;
ELSIF v_collection_status = 'collecting' THEN
v_tax_amount := round(v_taxable_subtotal * v_tax_rate / 100, 2);
ELSE
v_tax_amount := 0;
END IF;

-- 7. Determine calculation status
IF array_length(v_review_reasons, 1) IS NOT NULL THEN
v_tax_calculation_status := 'review_required';
ELSIF v_is_exempt THEN
v_tax_calculation_status := 'exempt';
ELSIF v_collection_status = 'not_collecting' THEN
v_tax_calculation_status := 'not_collecting';
ELSE
v_tax_calculation_status := 'ready';
END IF;

RETURN jsonb_build_object(
'organization_id', v_org_id,
'office_id', v_office_id,
'contact_id', v_contact_id,
'state', v_state,
'environment', v_environment,
'project_type', v_project_type,
'tax_rate', v_tax_rate,
'jobsite_address', v_jobsite_street,
'jobsite_city', v_jobsite_city,
'jobsite_state', v_jobsite_state,
'jobsite_zip', v_jobsite_zip,
'material_amount', v_material_amount,
'labor_amount', v_labor_amount,
'freight_amount', v_freight_amount,
'design_fee_amount', v_design_fee_amount,
'pm_amount', v_pm_amount,
'ccf_amount', v_ccf_amount,
'taxable_subtotal', v_taxable_subtotal,
'tax_amount', v_tax_amount,
'taxability_results', v_taxability_results,
'origin_result', v_origin_result,
'destination_result', v_destination_result,
'collection_status', v_collection_status,
'nexus_status', v_nexus_status,
'is_exempt', v_is_exempt,
'exemption_reference', v_exemption_ref,
'tax_calculation_status', v_tax_calculation_status,
'review_reasons', to_jsonb(v_review_reasons)
);
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_tax_readonly(p_transaction_type text, p_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN calculate_tax_context(p_transaction_type, p_transaction_id);
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_technician_mileage(p_clock_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_total_distance REAL := 0;
v_total_points INTEGER := 0;
v_avg_speed REAL := 0;
v_max_speed REAL := 0;
v_duration_hours REAL := 0;
v_start_time TIMESTAMPTZ;
v_end_time TIMESTAMPTZ;
BEGIN
-- Get total distance using the existing function
v_total_distance := calculate_trip_distance(p_clock_entry_id);

-- Get additional metrics
SELECT
COUNT(*),
AVG(speed),
MAX(speed),
MIN(captured_at),
MAX(captured_at)
INTO
v_total_points,
v_avg_speed,
v_max_speed,
v_start_time,
v_end_time
FROM enhanced_gps_breadcrumbs
WHERE daily_clock_entry_id = p_clock_entry_id;

-- Calculate duration in hours
IF v_start_time IS NOT NULL AND v_end_time IS NOT NULL THEN
v_duration_hours := EXTRACT(EPOCH FROM (v_end_time - v_start_time)) / 3600.0;
END IF;

RETURN jsonb_build_object(
'total_distance_meters', v_total_distance,
'total_distance_miles', v_total_distance * 0.000621371,
'total_points', v_total_points,
'avg_speed_mph', COALESCE(v_avg_speed * 2.237, 0),
'max_speed_mph', COALESCE(v_max_speed * 2.237, 0),
'duration_hours', v_duration_hours,
'start_time', v_start_time,
'end_time', v_end_time
);
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_test_tune_bonus(p_sales_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_settings RECORD;
v_sales_order RECORD;
v_total_estimated_labor numeric := 0;
v_field_labor_target numeric := 0;
v_total_field_hours numeric := 0;
v_labor_savings_hours numeric := 0;
v_labor_savings_pct numeric := 0;
v_total_savings_amount numeric := 0;
v_bonus_tier text := 'over_target';
v_bonus_percentage numeric := 0;
v_total_bonus_amount numeric := 0;
v_tech_bonus_amount numeric := 0;
v_pm_bonus_amount numeric := 0;
v_lead_tech_id uuid;
v_pm_id uuid;
v_existing_calc_id uuid;
v_total_labor_revenue numeric := 0;
v_effective_labor_rate numeric := 0;
v_sales_rep_eligible boolean := true;
v_org_id uuid;
v_tier_record jsonb;
v_tier_min numeric;
v_tier_max numeric;
v_tier_pct numeric;
v_effective_threshold numeric;
v_tier_type text;
v_comparison_value numeric;
BEGIN
-- Load settings
SELECT * INTO v_settings
FROM test_tune_settings
LIMIT 1;

IF NOT FOUND THEN
RAISE EXCEPTION 'Test & Tune settings not found';
END IF;

v_tier_type := COALESCE(v_settings.bonus_tier_type, 'flat_hours');

-- Load sales order (with per-job ELR override)
SELECT
so.*,
p.total_price AS contract_total
INTO v_sales_order
FROM sales_orders so
LEFT JOIN proposals p ON p.sales_order_id = so.id
WHERE so.id = p_sales_order_id
LIMIT 1;

IF NOT FOUND THEN
RAISE EXCEPTION 'Sales order not found: %', p_sales_order_id;
END IF;

v_org_id := v_sales_order.organization_id;

-- Determine effective ELR threshold (per-job override takes precedence)
v_effective_threshold := COALESCE(
v_sales_order.min_effective_labor_rate_override,
v_settings.min_effective_labor_rate
);

-- Get lead tech and PM assignments
v_lead_tech_id := v_sales_order.lead_technician_id;

SELECT project_manager_id INTO v_pm_id
FROM projects
WHERE sales_order_id = p_sales_order_id
LIMIT 1;

-- Calculate estimated labor from proposal line items
SELECT COALESCE(SUM(labor_hours), 0) INTO v_total_estimated_labor
FROM proposal_line_items pli
JOIN proposals pr ON pr.id = pli.proposal_id
WHERE pr.sales_order_id = p_sales_order_id;

-- Calculate total labor revenue for effective rate check
SELECT COALESCE(SUM(
CASE
WHEN pli.item_type = 'labor' OR pli.labor_hours > 0
THEN pli.total_price
ELSE 0
END
), 0) INTO v_total_labor_revenue
FROM proposal_line_items pli
JOIN proposals pr ON pr.id = pli.proposal_id
WHERE pr.sales_order_id = p_sales_order_id;

-- Compute effective labor rate (revenue / estimated hours)
IF v_total_estimated_labor > 0 THEN
v_effective_labor_rate := v_total_labor_revenue / v_total_estimated_labor;
ELSE
v_effective_labor_rate := 0;
END IF;

-- Determine sales rep eligibility using effective threshold
IF v_effective_labor_rate < v_effective_threshold THEN
v_sales_rep_eligible := false;
END IF;

-- Field Labor Target = Total Estimated Labor × 95%
v_field_labor_target := v_total_estimated_labor * 0.95;

-- Get field performance hours from linked work orders (using labor phase mapping)
SELECT COALESCE(SUM(wo.actual_hours), 0) INTO v_total_field_hours
FROM work_orders wo
LEFT JOIN labor_phase_performance_mapping lppm ON lppm.labor_phase_id = wo.labor_phase_id
WHERE wo.sales_order_id = p_sales_order_id
AND wo.status = 'completed'
AND COALESCE(lppm.counts_against_target, true) = true;

-- Calculate savings (positive = under target = good)
v_labor_savings_hours := v_field_labor_target - v_total_field_hours;

-- Calculate savings as a percentage of total estimated labor (for display and pct mode)
IF v_total_estimated_labor > 0 THEN
v_labor_savings_pct := ROUND((v_labor_savings_hours / v_total_estimated_labor * 100)::numeric, 2);
ELSE
v_labor_savings_pct := 0;
END IF;

-- Determine tier and bonus
IF v_labor_savings_hours <= 0 THEN
v_bonus_tier := CASE WHEN v_labor_savings_hours = 0 THEN 'on_target' ELSE 'over_target' END;
v_bonus_percentage := 0;
v_total_bonus_amount := 0;
ELSE
v_total_savings_amount := v_labor_savings_hours * v_settings.default_labor_burden_rate;
v_bonus_tier := 'no_tier';
v_bonus_percentage := 0;

-- The value we compare against tier thresholds depends on the tier type
-- pct_of_estimated: compare savings % against min_pct / max_pct
-- flat_hours: compare raw hours saved against min_hours / max_hours
IF v_tier_type = 'pct_of_estimated' THEN
v_comparison_value := GREATEST(0, v_labor_savings_pct);
ELSE
v_comparison_value := v_labor_savings_hours;
END IF;

-- Use bonus_tiers_jsonb if present (supports unlimited tiers)
IF v_settings.bonus_tiers_jsonb IS NOT NULL AND jsonb_array_length(v_settings.bonus_tiers_jsonb) > 0 THEN
FOR v_tier_record IN
SELECT * FROM jsonb_array_elements(v_settings.bonus_tiers_jsonb)
LOOP
IF v_tier_type = 'pct_of_estimated' THEN
-- Read min_pct / max_pct fields for percentage mode
v_tier_min := COALESCE((v_tier_record->>'min_pct')::numeric, 0);
v_tier_max := CASE
WHEN v_tier_record->>'max_pct' IS NULL OR v_tier_record->>'max_pct' = 'null' THEN NULL
ELSE (v_tier_record->>'max_pct')::numeric
END;
ELSE
-- Read min_hours / max_hours fields for flat mode
v_tier_min := COALESCE((v_tier_record->>'min_hours')::numeric, 0);
v_tier_max := CASE
WHEN v_tier_record->>'max_hours' IS NULL OR v_tier_record->>'max_hours' = 'null' THEN NULL
ELSE (v_tier_record->>'max_hours')::numeric
END;
END IF;

v_tier_pct := COALESCE((v_tier_record->>'percentage')::numeric, 0);

IF v_comparison_value >= v_tier_min AND (v_tier_max IS NULL OR v_comparison_value <= v_tier_max) THEN
v_bonus_tier := 'tier_jsonb';
v_bonus_percentage := v_tier_pct;
END IF;
END LOOP;
ELSE
-- Fallback to legacy 3-tier columns (flat hours only)
IF v_labor_savings_hours >= v_settings.tier_3_min_hours THEN
v_bonus_tier := 'tier_3';
v_bonus_percentage := v_settings.tier_3_percentage;
ELSIF v_labor_savings_hours >= v_settings.tier_2_min_hours THEN
v_bonus_tier := 'tier_2';
v_bonus_percentage := v_settings.tier_2_percentage;
ELSIF v_labor_savings_hours >= v_settings.tier_1_min_hours THEN
v_bonus_tier := 'tier_1';
v_bonus_percentage := v_settings.tier_1_percentage;
END IF;
END IF;

v_total_bonus_amount := v_total_savings_amount * (v_bonus_percentage / 100.0);

-- Apply optional per-project cap
IF v_settings.max_bonus_pool_per_project IS NOT NULL AND v_total_bonus_amount > v_settings.max_bonus_pool_per_project THEN
v_total_bonus_amount := v_settings.max_bonus_pool_per_project;
END IF;
END IF;

-- Split bonus between tech and PM
v_tech_bonus_amount := v_total_bonus_amount * (v_settings.tech_bonus_percentage / 100.0);
v_pm_bonus_amount := v_total_bonus_amount * (v_settings.pm_bonus_percentage / 100.0);

-- Upsert bonus calculation record
SELECT id INTO v_existing_calc_id
FROM test_tune_bonus_calculations
WHERE sales_order_id = p_sales_order_id
LIMIT 1;

IF v_existing_calc_id IS NOT NULL THEN
UPDATE test_tune_bonus_calculations SET
evaluation_date = now(),
total_estimated_labor = v_total_estimated_labor,
field_labor_target = v_field_labor_target,
total_field_hours = v_total_field_hours,
labor_savings_hours = GREATEST(0, v_labor_savings_hours),
labor_savings_pct = GREATEST(0, v_labor_savings_pct),
labor_burden_rate = v_settings.default_labor_burden_rate,
total_savings_amount = GREATEST(0, v_total_savings_amount),
bonus_tier = v_bonus_tier,
bonus_percentage = v_bonus_percentage,
total_bonus_amount = v_total_bonus_amount,
tech_bonus_amount = v_tech_bonus_amount,
pm_bonus_amount = v_pm_bonus_amount,
lead_technician_id = v_lead_tech_id,
project_manager_id = v_pm_id,
status = 'provisional',
effective_labor_rate = v_effective_labor_rate,
sales_rep_eligible = v_sales_rep_eligible,
effective_rate_threshold_used = v_effective_threshold,
updated_at = now()
WHERE id = v_existing_calc_id;
ELSE
INSERT INTO test_tune_bonus_calculations (
organization_id,
sales_order_id,
evaluation_date,
total_estimated_labor,
field_labor_target,
total_field_hours,
labor_savings_hours,
labor_savings_pct,
labor_burden_rate,
total_savings_amount,
bonus_tier,
bonus_percentage,
total_bonus_amount,
tech_bonus_amount,
pm_bonus_amount,
lead_technician_id,
project_manager_id,
status,
effective_labor_rate,
sales_rep_eligible,
effective_rate_threshold_used
) VALUES (
v_org_id,
p_sales_order_id,
now(),
v_total_estimated_labor,
v_field_labor_target,
v_total_field_hours,
GREATEST(0, v_labor_savings_hours),
GREATEST(0, v_labor_savings_pct),
v_settings.default_labor_burden_rate,
GREATEST(0, v_total_savings_amount),
v_bonus_tier,
v_bonus_percentage,
v_total_bonus_amount,
v_tech_bonus_amount,
v_pm_bonus_amount,
v_lead_tech_id,
v_pm_id,
'provisional',
v_effective_labor_rate,
v_sales_rep_eligible,
v_effective_threshold
);
END IF;

EXCEPTION WHEN OTHERS THEN
RAISE NOTICE 'Error in calculate_test_tune_bonus for order %: %', p_sales_order_id, SQLERRM;
RAISE;
END;
$function$


CREATE OR REPLACE FUNCTION public.calculate_trip_distance(p_daily_clock_entry_id uuid)
 RETURNS real
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_total_distance REAL := 0;
v_prev_lat REAL;
v_prev_lon REAL;
v_curr_lat REAL;
v_curr_lon REAL;
v_segment_distance REAL;
BEGIN
-- Calculate total distance using Haversine formula
FOR v_curr_lat, v_curr_lon IN
SELECT latitude, longitude
FROM enhanced_gps_breadcrumbs
WHERE daily_clock_entry_id = p_daily_clock_entry_id
ORDER BY captured_at
LOOP
IF v_prev_lat IS NOT NULL THEN
-- Haversine formula
v_segment_distance := 6371000 * 2 * ASIN(
SQRT(
POW(SIN(RADIANS(v_curr_lat - v_prev_lat) / 2), 2) +
COS(RADIANS(v_prev_lat)) * COS(RADIANS(v_curr_lat)) *
POW(SIN(RADIANS(v_curr_lon - v_prev_lon) / 2), 2)
)
);

-- Only add if reasonable (< 1km between points to filter anomalies)
IF v_segment_distance < 1000 THEN
v_total_distance := v_total_distance + v_segment_distance;
END IF;
END IF;

v_prev_lat := v_curr_lat;
v_prev_lon := v_curr_lon;
END LOOP;

RETURN v_total_distance;
END;
$function$


CREATE OR REPLACE FUNCTION public.caller_is_admin_profile()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
SELECT EXISTS (
SELECT 1 FROM public.profiles p
WHERE p.id = auth.uid()
AND (p.is_global_admin = true OR p.role IN ('admin', 'manager'))
);
$function$


CREATE OR REPLACE FUNCTION public.can_convert_to_work_order(p_service_request_id uuid)
 RETURNS TABLE(ready boolean, missing_fields text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sr RECORD;
v_missing text[] := ARRAY[]::text[];
BEGIN
SELECT * INTO v_sr
FROM service_requests
WHERE id = p_service_request_id;

IF NOT FOUND THEN
RETURN QUERY SELECT false, ARRAY['Service request not found']::text[];
RETURN;
END IF;

-- Check required fields
IF v_sr.contact_id IS NULL THEN
v_missing := array_append(v_missing, 'Contact');
END IF;

IF v_sr.description IS NULL OR trim(v_sr.description) = '' THEN
v_missing := array_append(v_missing, 'Description');
END IF;

IF v_sr.type IS NULL THEN
v_missing := array_append(v_missing, 'Service Type');
END IF;

-- Return results
RETURN QUERY SELECT
(array_length(v_missing, 1) IS NULL OR array_length(v_missing, 1) = 0),
v_missing;
END;
$function$


CREATE OR REPLACE FUNCTION public.can_view_all_org_invoices()
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM profiles
WHERE id = auth.uid()
AND role IN ('admin', 'manager', 'service_manager', 'finance')
);
$function$


CREATE OR REPLACE FUNCTION public.can_view_message_thread(user_id uuid, thread_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
thread_proposal_id uuid;
thread_contact_id uuid;
thread_context text;
user_visibility_scope text;
user_office_id uuid;
proposal_created_by uuid;
proposal_office_id uuid;
contact_assigned_to uuid;
BEGIN
-- Get thread details
SELECT proposal_id, contact_id, context_type
INTO thread_proposal_id, thread_contact_id, thread_context
FROM message_threads
WHERE id = thread_id;

-- If no proposal context, use general messaging visibility
IF thread_proposal_id IS NULL THEN
RETURN true; -- General messages visible to all staff for now
END IF;

-- Get user's visibility scope and office
SELECT get_user_proposal_visibility_scope(user_id), office_id
INTO user_visibility_scope, user_office_id
FROM profiles
WHERE id = user_id;

-- Company-wide visibility
IF user_visibility_scope = 'company' THEN
RETURN true;
END IF;

-- Get proposal details
SELECT created_by, office_id
INTO proposal_created_by, proposal_office_id
FROM proposals
WHERE id = thread_proposal_id;

-- Check if proposal was created by this user
IF proposal_created_by = user_id THEN
RETURN true;
END IF;

-- Get contact assignment
IF thread_contact_id IS NOT NULL THEN
SELECT assigned_to
INTO contact_assigned_to
FROM contacts
WHERE id = thread_contact_id;

-- Check if contact is assigned to this user
IF contact_assigned_to = user_id THEN
RETURN true;
END IF;
END IF;

-- Office-level visibility
IF user_visibility_scope = 'office' THEN
IF proposal_office_id = user_office_id THEN
RETURN true;
END IF;
END IF;

-- Default deny
RETURN false;
END;
$function$


CREATE OR REPLACE FUNCTION public.capture_proposal_snapshot(p_proposal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_rooms jsonb;
v_result jsonb;
BEGIN
-- Build rooms array with their line items
SELECT jsonb_agg(
jsonb_build_object(
'id', r.id,
'name', r.name,
'description', r.description,
'sort_order', r.sort_order,
'line_items', COALESCE((
SELECT jsonb_agg(
jsonb_build_object(
'id', li.id,
'product_id', li.product_id,
'description', li.description,
'quantity', li.quantity,
'unit', li.unit,
'unit_price', li.unit_price,
'cost', li.cost,
'line_total', li.line_total,
'item_type', li.item_type,
'labor_hours', li.labor_hours,
'labor_rate', li.labor_rate,
'labor_total', li.labor_total,
'is_taxable', li.is_taxable,
'is_hidden', li.is_hidden,
'sort_order', li.sort_order,
'parent_item_id', li.parent_item_id,
'labor_phase_id', li.labor_phase_id,
'class_id', li.class_id,
'display_mode', li.display_mode,
'show_task_notes', li.show_task_notes,
'task_notes', li.task_notes
)
ORDER BY li.sort_order
)
FROM proposal_line_items li
WHERE li.room_id = r.id
AND li.proposal_id = p_proposal_id
), '[]'::jsonb)
)
ORDER BY r.sort_order
)
INTO v_rooms
FROM proposal_rooms r
WHERE r.proposal_id = p_proposal_id;

v_result := jsonb_build_object(
'captured_at', now(),
'proposal_id', p_proposal_id,
'rooms', COALESCE(v_rooms, '[]'::jsonb)
);

RETURN v_result;
END;
$function$


