CREATE OR REPLACE FUNCTION public.check_home_clock_and_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
v_settings record;
v_profile record;
v_org_id uuid;
v_distance_in integer;
v_distance_out integer;
v_is_home_clock_in boolean := false;
v_is_home_clock_out boolean := false;
v_recipient record;
BEGIN
-- Get technician profile with home coordinates and org id
SELECT 
id,
full_name,
home_latitude,
home_longitude,
home_address,
organization_id
INTO v_profile
FROM profiles
WHERE id = NEW.technician_id;

v_org_id := v_profile.organization_id;

-- Get company settings for this org
SELECT 
home_clock_notification_enabled,
home_location_radius_meters,
home_clock_notification_roles
INTO v_settings
FROM company_settings
WHERE organization_id = v_org_id
LIMIT 1;

-- If no org-specific settings, fall back to any row
IF v_settings IS NULL THEN
SELECT 
home_clock_notification_enabled,
home_location_radius_meters,
home_clock_notification_roles
INTO v_settings
FROM company_settings
LIMIT 1;
END IF;

-- Exit early if notifications are disabled
IF NOT COALESCE(v_settings.home_clock_notification_enabled, false) THEN
RETURN NEW;
END IF;

-- Check clock IN from home (only on INSERT or when clock_in changes)
IF (TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.clock_in IS DISTINCT FROM NEW.clock_in))
AND NEW.clock_in IS NOT NULL
AND NEW.clock_in_latitude IS NOT NULL
AND NEW.clock_in_longitude IS NOT NULL
AND v_profile.home_latitude IS NOT NULL
AND v_profile.home_longitude IS NOT NULL THEN

v_distance_in := calculate_distance_meters(
NEW.clock_in_latitude,
NEW.clock_in_longitude,
v_profile.home_latitude,
v_profile.home_longitude
);

IF v_distance_in IS NOT NULL AND v_distance_in <= COALESCE(v_settings.home_location_radius_meters, 150) THEN
v_is_home_clock_in := true;
NEW.clocked_in_from_home := true;
END IF;
END IF;

-- Check clock OUT from home (only when clock_out changes)
IF TG_OP = 'UPDATE'
AND OLD.clock_out IS DISTINCT FROM NEW.clock_out
AND NEW.clock_out IS NOT NULL
AND NEW.clock_out_latitude IS NOT NULL
AND NEW.clock_out_longitude IS NOT NULL
AND v_profile.home_latitude IS NOT NULL
AND v_profile.home_longitude IS NOT NULL THEN

v_distance_out := calculate_distance_meters(
NEW.clock_out_latitude,
NEW.clock_out_longitude,
v_profile.home_latitude,
v_profile.home_longitude
);

IF v_distance_out IS NOT NULL AND v_distance_out <= COALESCE(v_settings.home_location_radius_meters, 150) THEN
v_is_home_clock_out := true;
NEW.clocked_out_from_home := true;
END IF;
END IF;

-- Send notifications for clock-in from home
IF v_is_home_clock_in THEN
FOR v_recipient IN
SELECT id
FROM profiles
WHERE organization_id = v_org_id
AND role = ANY(COALESCE(
v_settings.home_clock_notification_roles,
ARRAY['admin', 'office_manager', 'production_manager', 'service_manager']
))
LOOP
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id,
organization_id
) VALUES (
v_recipient.id,
'home_clock',
'Clock In From Home',
v_profile.full_name || ' clocked in from home at ' ||
TO_CHAR(NEW.clock_in AT TIME ZONE 'America/Chicago', 'HH12:MI AM') ||
CASE
WHEN v_distance_in IS NOT NULL THEN ' (' || v_distance_in || 'm from home)'
ELSE ''
END,
NEW.id,
v_org_id
);
END LOOP;
END IF;

-- Send notifications for clock-out from home
IF v_is_home_clock_out THEN
FOR v_recipient IN
SELECT id
FROM profiles
WHERE organization_id = v_org_id
AND role = ANY(COALESCE(
v_settings.home_clock_notification_roles,
ARRAY['admin', 'office_manager', 'production_manager', 'service_manager']
))
LOOP
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id,
organization_id
) VALUES (
v_recipient.id,
'home_clock',
'Clock Out From Home',
v_profile.full_name || ' clocked out from home at ' ||
TO_CHAR(NEW.clock_out AT TIME ZONE 'America/Chicago', 'HH12:MI AM') ||
CASE
WHEN v_distance_out IS NOT NULL THEN ' (' || v_distance_out || 'm from home)'
ELSE ''
END,
NEW.id,
v_org_id
);
END LOOP;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.check_late_clock_in()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
tech_start_time time;
minutes_diff integer;
alert_exists boolean;
org_timezone text;
local_clock_in_time time;
BEGIN
-- Get technician scheduled start time
SELECT standard_start_time INTO tech_start_time
FROM profiles
WHERE id = NEW.technician_id;

-- If no standard start time, skip
IF tech_start_time IS NULL THEN
RETURN NEW;
END IF;

-- Get organization timezone
SELECT COALESCE(timezone, 'America/Chicago') INTO org_timezone
FROM organizations
LIMIT 1;

-- Convert UTC clock_in to the org's local time, then extract the time portion
local_clock_in_time := (NEW.clock_in AT TIME ZONE org_timezone)::time;

-- Calculate minutes late using local time
minutes_diff := EXTRACT(EPOCH FROM (local_clock_in_time - tech_start_time)) / 60;

-- If more than 15 minutes late, create alert
IF minutes_diff > 15 THEN
-- Check if alert already exists for this date
SELECT EXISTS(
SELECT 1 FROM time_clock_alerts
WHERE technician_id = NEW.technician_id
AND alert_date = NEW.entry_date
AND alert_type = 'really_late'
) INTO alert_exists;

-- Only create if it does not exist
IF NOT alert_exists THEN
INSERT INTO time_clock_alerts (
technician_id,
alert_date,
alert_type,
scheduled_start_time,
actual_clock_in_time,
minutes_late
) VALUES (
NEW.technician_id,
NEW.entry_date,
'really_late',
tech_start_time,
local_clock_in_time,
minutes_diff::integer
);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.check_max_starred_modules()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF (SELECT COUNT(*) FROM user_starred_modules WHERE user_id = NEW.user_id) >= 6 THEN
RAISE EXCEPTION 'Cannot star more than 6 modules. Please unstar a module first.';
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.check_payroll_readiness(p_pay_period_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_start date;
v_end date;
v_total_employees int;
v_approved_count int;
v_pending_count int;
v_excluded_count int;
v_unassigned_jurisdiction int;
v_gps_mismatches int;
v_pending_adjustments int;
v_total_segments int;
v_unreviewed_configs int;
v_unresolved_payroll_flags int;
v_pay_schedule_id uuid;
v_emp_id uuid;
v_config record;
BEGIN
SELECT organization_id, period_start_date, period_end_date, pay_schedule_id
INTO v_org_id, v_start, v_end, v_pay_schedule_id
FROM pay_periods
WHERE id = p_pay_period_id;

IF NOT FOUND THEN
RETURN json_build_object('error', 'pay period not found');
END IF;

-- Count distinct employees (profiles.id) with segments in this period
SELECT COUNT(DISTINCT employee_id) INTO v_total_employees
FROM payroll_time_segments
WHERE pay_period_id = p_pay_period_id
AND organization_id = v_org_id;

-- Count approvals by status
SELECT
COUNT(*) FILTER (WHERE approval_status = 'approved'),
COUNT(*) FILTER (WHERE approval_status = 'pending'),
COUNT(*) FILTER (WHERE approval_status = 'excluded')
INTO v_approved_count, v_pending_count, v_excluded_count
FROM payroll_approvals
WHERE pay_period_id = p_pay_period_id;

-- Segments with unassigned jurisdiction
SELECT COUNT(*) INTO v_unassigned_jurisdiction
FROM payroll_time_segments
WHERE pay_period_id = p_pay_period_id
AND organization_id = v_org_id
AND (work_jurisdiction_state IS NULL OR work_jurisdiction_confidence = 'unassigned');

-- Segments with GPS/job mismatches
SELECT COUNT(*) INTO v_gps_mismatches
FROM payroll_time_segments
WHERE pay_period_id = p_pay_period_id
AND organization_id = v_org_id
AND work_jurisdiction_confidence = 'low';

-- Pending time adjustments for employees in this period
-- employee_id in payroll_time_segments is profiles.id, which is the same as technician_id
SELECT COUNT(*) INTO v_pending_adjustments
FROM time_adjustment_requests tar
WHERE tar.organization_id = v_org_id
AND tar.status = 'pending'
AND tar.technician_id IN (
SELECT DISTINCT pts.employee_id
FROM payroll_time_segments pts
WHERE pts.pay_period_id = p_pay_period_id
);

-- Total segments
SELECT COUNT(*) INTO v_total_segments
FROM payroll_time_segments
WHERE pay_period_id = p_pay_period_id
AND organization_id = v_org_id;

-- Check for unreviewed employee_payroll_configs
-- Need to map segment employee_id (profiles.id) to employees.id
v_unreviewed_configs := 0;
FOR v_emp_id IN
SELECT DISTINCT e.id
FROM payroll_time_segments pts
JOIN employees e ON e.user_id = pts.employee_id
WHERE pts.pay_period_id = p_pay_period_id
AND pts.organization_id = v_org_id
LOOP
SELECT * INTO v_config
FROM employee_payroll_configs
WHERE employee_id = v_emp_id
AND effective_from <= v_end
AND (effective_to IS NULL OR effective_to >= v_start)
ORDER BY effective_from DESC
LIMIT 1;

IF v_config IS NULL OR v_config.reviewed_at IS NULL THEN
v_unreviewed_configs := v_unreviewed_configs + 1;
END IF;
END LOOP;

-- Count unresolved payroll reconciliation flags (type = 'payroll' only)
SELECT COUNT(*) INTO v_unresolved_payroll_flags
FROM payroll_reconciliation_flags
WHERE pay_period_id = p_pay_period_id
AND reconciliation_type = 'payroll'
AND needs_review = true
AND resolution_status = 'unresolved';

RETURN json_build_object(
'total_employees', v_total_employees,
'approved_count', v_approved_count,
'pending_count', v_pending_count,
'excluded_count', v_excluded_count,
'total_segments', v_total_segments,
'unassigned_jurisdiction', v_unassigned_jurisdiction,
'gps_mismatches', v_gps_mismatches,
'pending_adjustments', v_pending_adjustments,
'unreviewed_timekeeping_configs', v_unreviewed_configs,
'unresolved_payroll_flags', v_unresolved_payroll_flags,
'ready_for_submission',
v_unassigned_jurisdiction = 0
AND v_gps_mismatches = 0
AND v_pending_count = 0
AND v_pending_adjustments = 0
AND v_unreviewed_configs = 0
AND v_unresolved_payroll_flags = 0
);
END;
$function$


CREATE OR REPLACE FUNCTION public.check_po_billing_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
-- If accepts_po is being set to true, validate billing information is complete
IF NEW.accepts_po = true THEN
-- Check required fields for PO acceptance
IF NEW.company_name IS NULL OR NEW.company_name = '' THEN
RAISE EXCEPTION 'Cannot enable PO acceptance: Company name is required';
END IF;

IF NEW.street_address IS NULL OR NEW.street_address = '' THEN
RAISE EXCEPTION 'Cannot enable PO acceptance: Street address is required';
END IF;

IF NEW.city IS NULL OR NEW.city = '' THEN
RAISE EXCEPTION 'Cannot enable PO acceptance: City is required';
END IF;

IF NEW.state IS NULL OR NEW.state = '' THEN
RAISE EXCEPTION 'Cannot enable PO acceptance: State is required';
END IF;

IF NEW.zip_code IS NULL OR NEW.zip_code = '' THEN
RAISE EXCEPTION 'Cannot enable PO acceptance: ZIP code is required';
END IF;

IF NEW.default_payment_terms IS NULL OR NEW.default_payment_terms = '' THEN
RAISE EXCEPTION 'Cannot enable PO acceptance: Payment terms are required';
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.check_project_task_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_project_task_id uuid;
v_auto_completion_enabled boolean;
v_requires_approval boolean;
BEGIN
-- Get the project_task_id (either from NEW or from work_order_tasks)
v_project_task_id := NEW.project_task_id;

-- If not directly set, try to get from work_order_tasks
IF v_project_task_id IS NULL AND NEW.work_order_task_id IS NOT NULL THEN
SELECT project_task_id INTO v_project_task_id
FROM work_order_tasks
WHERE id = NEW.work_order_task_id;
END IF;

-- Exit if no project task is linked
IF v_project_task_id IS NULL THEN
RETURN NEW;
END IF;

-- Check company settings
SELECT 
COALESCE(auto_completion_enabled, true),
COALESCE(auto_completion_requires_approval, false)
INTO v_auto_completion_enabled, v_requires_approval
FROM company_settings
LIMIT 1;

-- If auto-completion is disabled or requires approval, don't auto-complete
IF NOT v_auto_completion_enabled OR v_requires_approval THEN
RETURN NEW;
END IF;

-- Auto-complete the project task if not already completed
UPDATE project_tasks
SET 
status = 'completed',
completed_at = NEW.completed_at,
is_auto_completed = true,
auto_completed_by = NEW.id
WHERE 
id = v_project_task_id 
AND status != 'completed';

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.check_proposal_acceptance_requirements(p_proposal_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_require_deposit boolean;
v_deposit_paid boolean;
v_acceptance_methods text[];
v_purchase_order_number text;
v_accepted_via_method text;
v_deposit_request_sent boolean;
BEGIN
-- Get proposal details, prioritizing proposal-level settings over template settings
SELECT
COALESCE(p.require_deposit, ps.require_deposit, true),
COALESCE(p.deposit_paid, false),
COALESCE(p.acceptance_methods, ps.acceptance_methods, ARRAY['payment']::text[]),
p.purchase_order_number,
p.accepted_via_method,
COALESCE(p.deposit_request_sent, false)
INTO
v_require_deposit,
v_deposit_paid,
v_acceptance_methods,
v_purchase_order_number,
v_accepted_via_method,
v_deposit_request_sent
FROM proposals p
LEFT JOIN proposal_settings ps ON ps.id = p.proposal_settings_id
WHERE p.id = p_proposal_id;

-- Purchase Order: Only allowed when deposit is NOT required
IF v_accepted_via_method = 'purchase_order' THEN
-- Check if PO is in allowed methods
IF NOT ('purchase_order' = ANY(v_acceptance_methods)) THEN
RETURN false;
END IF;

-- Check if deposit is required - PO not allowed with deposits
IF v_require_deposit THEN
RETURN false;
END IF;

-- Check if PO number is provided
RETURN v_purchase_order_number IS NOT NULL;
END IF;

-- Payment Received method: Deposit must be marked as paid
IF v_accepted_via_method = 'payment' THEN
RETURN v_deposit_paid;
END IF;

-- Verbal/In-Person approval: If deposit required, must have deposit_request_sent OR deposit_paid
-- This allows the flow where we create the invoice and let customer pay OR manually apply payment
IF v_accepted_via_method = 'verbal' THEN
IF v_require_deposit THEN
RETURN (v_deposit_request_sent OR v_deposit_paid);
END IF;
-- No deposit required, approval is valid
RETURN true;
END IF;

-- No deposit required: any acceptance method is valid
IF NOT v_require_deposit THEN
RETURN true;
END IF;

-- Default: require deposit to be handled
RETURN (v_deposit_paid OR v_deposit_request_sent);
END;
$function$


CREATE OR REPLACE FUNCTION public.classify_as_employee(p_user_id uuid, p_hire_date date, p_employee_number text DEFAULT NULL::text, p_employment_status text DEFAULT 'active'::text, p_compensation_type text DEFAULT 'hourly'::text, p_requires_daily_clock boolean DEFAULT true, p_requires_time_allocation boolean DEFAULT false, p_payroll_time_basis text DEFAULT 'daily_clock'::text, p_expected_weekly_hours numeric DEFAULT 40, p_standard_start_time text DEFAULT '08:00'::text, p_standard_end_time text DEFAULT '17:00'::text, p_work_days text[] DEFAULT ARRAY['monday'::text, 'tuesday'::text, 'wednesday'::text, 'thursday'::text, 'friday'::text], p_overtime_eligible boolean DEFAULT false, p_pto_eligible boolean DEFAULT false, p_pay_schedule_id uuid DEFAULT NULL::uuid, p_reviewed_by uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org_id uuid; v_existing_emp uuid; v_new_emp_id uuid;
BEGIN
IF p_reviewed_by IS NULL OR p_reviewed_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Unauthorized classification actor'; END IF;
SELECT organization_id INTO v_org_id FROM profiles WHERE id = p_user_id;
IF NOT FOUND THEN RAISE EXCEPTION 'User profile not found'; END IF;
IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND organization_id = v_org_id AND role IN ('admin','manager','office_manager','production_manager','service_manager')) THEN RAISE EXCEPTION 'Unauthorized: caller cannot classify users'; END IF;
SELECT id INTO v_existing_emp FROM employees WHERE user_id = p_user_id AND organization_id = v_org_id;
IF v_existing_emp IS NOT NULL THEN
UPDATE profiles SET employment_classification = 'employee', employment_classification_reviewed_at = now(), employment_classification_reviewed_by = auth.uid() WHERE id = p_user_id;
RETURN json_build_object('success', true, 'employee_id', v_existing_emp, 'message', 'Employee classification confirmed');
END IF;
INSERT INTO employees (organization_id, user_id, employment_status, hire_date, termination_date, employee_number) VALUES (v_org_id, p_user_id, p_employment_status, p_hire_date, NULL, p_employee_number) RETURNING id INTO v_new_emp_id;
INSERT INTO employee_payroll_configs (organization_id, employee_id, effective_from, effective_to, compensation_type, requires_daily_clock, requires_time_allocation, payroll_time_basis, expected_weekly_hours, standard_start_time, standard_end_time, work_days, overtime_eligible, pto_eligible, pay_schedule_id, reviewed_at, reviewed_by)
VALUES (v_org_id, v_new_emp_id, p_hire_date, NULL, p_compensation_type, p_requires_daily_clock, p_requires_time_allocation, p_payroll_time_basis, p_expected_weekly_hours, CASE WHEN p_requires_daily_clock THEN p_standard_start_time::time ELSE NULL END, CASE WHEN p_requires_daily_clock THEN p_standard_end_time::time ELSE NULL END, CASE WHEN array_length(p_work_days, 1) > 0 THEN p_work_days ELSE NULL END, p_overtime_eligible, p_pto_eligible, p_pay_schedule_id, now(), auth.uid());
UPDATE profiles SET employment_classification = 'employee', employment_classification_reviewed_at = now(), employment_classification_reviewed_by = auth.uid() WHERE id = p_user_id;
RETURN json_build_object('success', true, 'employee_id', v_new_emp_id, 'message', 'Employee classification created');
END;
$function$


CREATE OR REPLACE FUNCTION public.classify_as_non_employee(p_user_id uuid, p_reviewed_by uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_existing_emp uuid;
BEGIN
IF p_reviewed_by IS NULL OR p_reviewed_by IS DISTINCT FROM auth.uid() THEN
RAISE EXCEPTION 'Unauthorized classification actor';
END IF;

SELECT organization_id INTO v_org_id FROM profiles WHERE id = p_user_id;
IF NOT FOUND THEN RAISE EXCEPTION 'User profile not found'; END IF;

IF NOT EXISTS (
SELECT 1 FROM profiles
WHERE id = auth.uid() AND organization_id = v_org_id
AND role IN ('admin','manager','office_manager','production_manager','service_manager')
) THEN
RAISE EXCEPTION 'Unauthorized: caller cannot classify users';
END IF;

SELECT id INTO v_existing_emp FROM employees WHERE user_id = p_user_id AND organization_id = v_org_id;
IF v_existing_emp IS NOT NULL THEN
RAISE EXCEPTION 'Employee records cannot be confirmed as non-employee users';
END IF;

UPDATE profiles SET
employment_classification = 'non_employee',
employment_classification_reviewed_at = now(),
employment_classification_reviewed_by = auth.uid()
WHERE id = p_user_id;

RETURN json_build_object('success', true, 'message', 'Non-Employee classification recorded');
END;
$function$


CREATE OR REPLACE FUNCTION public.classify_deposit_invoice(p_invoice_id uuid, p_proposal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_deposit_amount numeric;
v_org_id uuid;
v_tax_rate numeric;
v_environment text;
v_project_type text;
v_state text;
v_allocation jsonb;
v_allocations jsonb;
v_alloc jsonb;
v_class_code text;
v_alloc_amount numeric;
v_class_id uuid;
v_taxable boolean;
v_taxable_subtotal numeric := 0;
v_tax_amount numeric := 0;
v_sort_order integer := 0;
v_material_taxability jsonb;
v_labor_taxability jsonb;
v_freight_taxability jsonb;
v_design_fee_taxability jsonb;
v_pm_taxability jsonb;
v_item_type text;
BEGIN
-- Get deposit amount from existing line items
SELECT COALESCE(SUM(amount), 0) INTO v_deposit_amount
FROM invoice_line_items WHERE invoice_id = p_invoice_id;

IF v_deposit_amount = 0 THEN
RETURN;
END IF;

-- Get proposal info
SELECT organization_id, tax_rate, tax_environment, tax_project_type, jobsite_state
INTO v_org_id, v_tax_rate, v_environment, v_project_type, v_state
FROM proposals WHERE id = p_proposal_id;

v_tax_rate := COALESCE(v_tax_rate, 0);
v_environment := COALESCE(v_environment, 'residential');
v_project_type := COALESCE(v_project_type, 'general_installation_repair');
v_state := COALESCE(v_state, '');

-- Delete existing unclassified line items
DELETE FROM invoice_line_items WHERE invoice_id = p_invoice_id;

-- Get classified allocation (5 project classifications only, no CCF)
v_allocation := allocate_billing_amount('proposal', p_proposal_id, v_deposit_amount);
v_allocations := v_allocation->'allocations';

IF jsonb_array_length(v_allocations) = 0 THEN
-- Fallback: single unclassified line
INSERT INTO invoice_line_items (
invoice_id, organization_id,
description, quantity, unit_price, amount, is_taxable, sort_order
) VALUES (
p_invoice_id, v_org_id,
'Deposit', 1, v_deposit_amount, v_deposit_amount, false, 0
);
RETURN;
END IF;

-- Resolve taxability for 5 project classifications (no CCF in deposits)
v_material_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'material');
v_labor_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'labor');
v_freight_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'freight_delivery');
v_design_fee_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'design_fee');
v_pm_taxability := resolve_tax_rule(v_state, v_org_id, v_environment, v_project_type, 'project_management');

v_taxable_subtotal := 0;

FOR v_alloc IN SELECT * FROM jsonb_array_elements(v_allocations) LOOP
v_class_code := v_alloc->>'classification_code';
v_alloc_amount := (v_alloc->>'allocated_amount')::numeric;

SELECT tc.id INTO v_class_id
FROM tax_classifications tc
WHERE tc.code = v_class_code AND tc.organization_id = v_org_id
LIMIT 1;

v_taxable := false;
v_item_type := 'service';
IF v_class_code = 'material' THEN
v_taxable := (v_material_taxability->>'taxability_status') = 'taxable';
v_item_type := 'material';
ELSIF v_class_code = 'labor' THEN
v_taxable := (v_labor_taxability->>'taxability_status') = 'taxable';
v_item_type := 'labor';
ELSIF v_class_code = 'freight_delivery' THEN
v_taxable := (v_freight_taxability->>'taxability_status') = 'taxable';
ELSIF v_class_code = 'design_fee' THEN
v_taxable := (v_design_fee_taxability->>'taxability_status') = 'taxable';
ELSIF v_class_code = 'project_management' THEN
v_taxable := (v_pm_taxability->>'taxability_status') = 'taxable';
END IF;

IF v_taxable THEN
v_taxable_subtotal := v_taxable_subtotal + v_alloc_amount;
END IF;

INSERT INTO invoice_line_items (
invoice_id, organization_id,
description, quantity, unit_price, amount,
item_type, is_taxable, tax_amount,
tax_classification_id, sort_order
) VALUES (
p_invoice_id, v_org_id,
'Deposit — ' || v_class_code,
1, v_alloc_amount, v_alloc_amount,
v_item_type, v_taxable,
CASE WHEN v_taxable THEN round(v_alloc_amount * v_tax_rate, 2) ELSE 0 END,
v_class_id, v_sort_order
);
v_sort_order := v_sort_order + 1;
END LOOP;

v_tax_amount := round(v_taxable_subtotal * v_tax_rate, 2);

-- Update invoice totals
UPDATE invoices SET
tax_amount = v_tax_amount,
total = v_deposit_amount + v_tax_amount
WHERE id = p_invoice_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.classify_deposit_on_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
IF NEW.source_type = 'deposit' AND NEW.proposal_id IS NOT NULL THEN
-- Only classify if the line items are unclassified (single line, no tax_classification_id)
PERFORM classify_deposit_invoice(NEW.id, NEW.proposal_id);
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.cleanup_old_gps_capture_attempts()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
DELETE FROM gps_capture_attempts
WHERE created_at < now() - interval '90 days';
END;
$function$


CREATE OR REPLACE FUNCTION public.cleanup_old_tech_locations()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
-- Delete locations older than 7 days
DELETE FROM tech_locations
WHERE recorded_at < now() - interval '7 days';

-- Delete expired cache entries
DELETE FROM distance_matrix_cache
WHERE expires_at < now();
END;
$function$


CREATE OR REPLACE FUNCTION public.cleanup_stale_sessions()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE user_sessions
SET
is_active = false,
session_end = last_activity + INTERVAL '30 minutes'
WHERE is_active = true
AND last_activity < now() - INTERVAL '30 minutes';
END;
$function$


CREATE OR REPLACE FUNCTION public.combine_service_requests_to_work_order(p_service_request_ids uuid[], p_tech_ids uuid[], p_scheduled_date date, p_scheduled_time text, p_estimated_hours numeric, p_description text, p_internal_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_contact_id        uuid;
v_company_id        uuid;
v_priority          text;
v_billable_type     text;
v_address           text;
v_city              text;
v_state             text;
v_zip               text;
v_project_id        uuid;
v_work_order_id     uuid;
v_work_order_number text;
v_tech_id           uuid;
v_sr                record;
v_distinct_contacts int;
BEGIN
-- Validate we got at least one service request and one tech
IF array_length(p_service_request_ids, 1) IS NULL OR array_length(p_service_request_ids, 1) < 1 THEN
RAISE EXCEPTION 'At least one service request is required';
END IF;

IF array_length(p_tech_ids, 1) IS NULL OR array_length(p_tech_ids, 1) < 1 THEN
RAISE EXCEPTION 'At least one technician is required';
END IF;

-- Ensure all provided service requests belong to the same contact
SELECT COUNT(DISTINCT contact_id)
INTO v_distinct_contacts
FROM service_requests
WHERE id = ANY(p_service_request_ids);

IF v_distinct_contacts > 1 THEN
RAISE EXCEPTION 'All service requests must belong to the same customer';
END IF;

-- Load the common attributes from the first service request
SELECT
contact_id,
company_id,
priority,
billable_type,
job_location_address,
job_location_city,
job_location_state,
job_location_zip
INTO
v_contact_id,
v_company_id,
v_priority,
v_billable_type,
v_address,
v_city,
v_state,
v_zip
FROM service_requests
WHERE id = p_service_request_ids[1];

-- Find or create a "Service Work" project for the contact
SELECT id INTO v_project_id
FROM projects
WHERE contact_id = v_contact_id
AND project_name = 'Service Work'
LIMIT 1;

IF v_project_id IS NULL THEN
INSERT INTO projects (company_id, contact_id, project_name, status)
VALUES (v_company_id, v_contact_id, 'Service Work', 'active')
RETURNING id INTO v_project_id;
END IF;

-- Generate a work order number
v_work_order_number := 'WO-' || LPAD(EXTRACT(EPOCH FROM now())::bigint::text, 10, '0') || '-' || UPPER(SUBSTR(MD5(RANDOM()::text), 1, 4));

-- Create one work order (one per tech — we create only the first one here and
-- loop below for additional techs, but all SRs point to the first WO)
v_tech_id := p_tech_ids[1];

INSERT INTO work_orders (
company_id,
project_id,
work_order_number,
title,
description,
type,
status,
priority,
assigned_to,
start_date,
estimated_hours,
internal_notes,
created_by,
contact_id,
billable_type,
address,
service_location_address,
service_location_city,
service_location_state,
service_location_zip
)
VALUES (
v_company_id,
v_project_id,
v_work_order_number,
'Service: ' || LEFT(p_description, 60),
p_description,
'service',
'scheduled',
v_priority,
v_tech_id,
p_scheduled_date,
p_estimated_hours,
p_internal_notes,
auth.uid(),
v_contact_id,
v_billable_type,
v_address,
v_address,
v_city,
v_state,
v_zip
)
RETURNING id INTO v_work_order_id;

-- For additional techs, create additional work orders (linked to same SRs)
IF array_length(p_tech_ids, 1) > 1 THEN
FOR i IN 2 .. array_length(p_tech_ids, 1) LOOP
INSERT INTO work_orders (
company_id,
project_id,
work_order_number,
title,
description,
type,
status,
priority,
assigned_to,
start_date,
estimated_hours,
internal_notes,
created_by,
contact_id,
billable_type,
address,
service_location_address,
service_location_city,
service_location_state,
service_location_zip
)
VALUES (
v_company_id,
v_project_id,
'WO-' || LPAD(EXTRACT(EPOCH FROM now())::bigint::text, 10, '0') || '-' || UPPER(SUBSTR(MD5(RANDOM()::text), 1, 4)),
'Service: ' || LEFT(p_description, 60),
p_description,
'service',
'scheduled',
v_priority,
p_tech_ids[i],
p_scheduled_date,
p_estimated_hours,
p_internal_notes,
auth.uid(),
v_contact_id,
v_billable_type,
v_address,
v_address,
v_city,
v_state,
v_zip
);
END LOOP;
END IF;

-- Mark all service requests as scheduled and link them to the primary work order
UPDATE service_requests
SET status         = 'scheduled',
work_order_id  = v_work_order_id,
updated_at     = NOW()
WHERE id = ANY(p_service_request_ids);

RETURN v_work_order_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.complete_lost_review_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE d lost_review_details;
BEGIN
 SELECT * INTO STRICT d FROM lost_review_details WHERE request_id=NEW.request_id;
 UPDATE lost_review_details SET responded_at=NEW.created_at WHERE request_id=NEW.request_id;
 UPDATE review_requests SET review_completed=true WHERE id=NEW.request_id;
 INSERT INTO notifications(user_id,organization_id,type,title,body,related_id)
 SELECT p.user_id,d.organization_id,'review_request','Lost opportunity feedback received',
 'A customer has sent private feedback. Open Reviews → Lost Opportunities to review it.',NEW.request_id
 FROM lost_review_notification_recipients(d.organization_id) p;
 RETURN NEW;
END $function$


CREATE OR REPLACE FUNCTION public.complete_po_pending_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sales_order_id uuid;
v_order_number   text;
v_customer_name  text;
v_project_id     uuid;
v_project_number text;
BEGIN
IF NEW.purchase_order_number IS NOT NULL
AND NEW.purchase_order_number != ''
AND OLD.po_pending = true
AND NEW.po_pending = true
AND NEW.sales_order_id IS NULL
THEN
NEW.po_pending := false;
NEW.billing_action_type := 'purchase_order';

SELECT COALESCE(full_name, contact_name, email, 'Customer')
INTO v_customer_name
FROM contacts
WHERE id = NEW.contact_id;

v_order_number := generate_sales_order_number(NEW.proposal_number);

INSERT INTO sales_orders (
organization_id,
proposal_id,
contact_id,
order_number,
status,
contract_total,
payment_terms,
notes,
created_by,
portal_template_override_id
) VALUES (
NEW.organization_id,
NEW.id,
NEW.contact_id,
v_order_number,
'planning',
NEW.total,
COALESCE(NEW.payment_terms, 'Net 30'),
'Converted from proposal ' || NEW.proposal_number || ' - PO: ' || NEW.purchase_order_number,
auth.uid(),
NEW.report_template_id
) RETURNING id INTO v_sales_order_id;

NEW.sales_order_id := v_sales_order_id;
NEW.billing_action_taken := true;
NEW.billing_action_at := now();
NEW.billing_action_by := auth.uid();

-- Create Project
BEGIN
v_project_number := get_next_project_number();

INSERT INTO projects (
organization_id,
sales_order_id, contact_id,
project_number, name,
status, assigned_pm,
job_site_address, notes, created_by,
salesperson_id
) VALUES (
NEW.organization_id,
v_sales_order_id, NEW.contact_id,
v_project_number,
COALESCE(NEW.title, 'Project for ' || v_customer_name),
'planning',
NEW.created_by,
NEW.jobsite_location,
'Project created from approved proposal ' || NEW.proposal_number || ' - PO: ' || NEW.purchase_order_number,
auth.uid(),
NEW.created_by
) RETURNING id INTO v_project_id;

UPDATE sales_orders SET project_id = v_project_id WHERE id = v_sales_order_id;

EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Failed to create project for PO approval %: %', NEW.proposal_number, SQLERRM;
END;

BEGIN
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id
) VALUES (
NEW.created_by,
'proposal_approved',
'PO Number Received',
'PO #' || NEW.purchase_order_number || ' received for proposal ' || NEW.proposal_number || '. Sales order ' || v_order_number || ' created and ready for scheduling.',
NEW.id
);
EXCEPTION
WHEN OTHERS THEN
RAISE WARNING 'Failed to create PO received notification: %', SQLERRM;
END;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.contact_has_active_vip_subscription(p_contact_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN EXISTS (
SELECT 1 
FROM recurring_subscriptions rs
JOIN recurring_plans rp ON rp.id = rs.plan_id
WHERE rs.contact_id = p_contact_id
AND rp.plan_type = 'vip_plan'
AND (
-- Active subscription with valid end date (or no end date)
(rs.status = 'active' AND (rs.end_date IS NULL OR rs.end_date >= CURRENT_DATE))
OR
-- Trial subscription with valid trial end date
(rs.status = 'trial' AND rs.trial_end_date >= CURRENT_DATE)
)
);
END;
$function$


CREATE OR REPLACE FUNCTION public.contact_has_punchlist_access(p_contact_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN EXISTS (
SELECT 1 FROM punchlist_access_grants
WHERE contact_id = p_contact_id
AND status = 'active'
AND (expiration_date IS NULL OR expiration_date >= CURRENT_DATE)
);
END;
$function$


CREATE OR REPLACE FUNCTION public.convert_lead_to_prospect(p_lead_id uuid, p_competitor_id uuid DEFAULT NULL::uuid, p_relationship_type text DEFAULT NULL::text, p_relationship_strength text DEFAULT NULL::text, p_follow_up_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_follow_up_type text DEFAULT 'call'::text, p_follow_up_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_lead record;
v_contact_id uuid;
v_existing_contact record;
v_user_id uuid;
v_can_view_prospects boolean;
v_company_id uuid;
v_office_id uuid;
v_lead_converted_points integer := 25;
v_contact_name text;
BEGIN
-- Get current user ID
v_user_id := auth.uid();

IF v_user_id IS NULL THEN
RETURN json_build_object(
'success', false,
'message', 'User not authenticated'
);
END IF;

-- Check if user has prospect permission
SELECT can_view_prospects, company_id, office_id
INTO v_can_view_prospects, v_company_id, v_office_id
FROM profiles
WHERE id = v_user_id;

IF NOT v_can_view_prospects THEN
RETURN json_build_object(
'success', false,
'message', 'You do not have permission to manage prospects'
);
END IF;

-- Get the lead data
SELECT * INTO v_lead FROM leads WHERE id = p_lead_id;

IF NOT FOUND THEN
RETURN json_build_object(
'success', false,
'message', 'Lead not found'
);
END IF;

-- Check for existing contact by email or phone (case-insensitive)
SELECT * INTO v_existing_contact
FROM contacts
WHERE (
(v_lead.email IS NOT NULL AND LOWER(email) = LOWER(v_lead.email))
OR
(v_lead.phone IS NOT NULL AND phone = v_lead.phone)
)
LIMIT 1;

-- Determine contact name
v_contact_name := COALESCE(v_lead.contact_name, v_lead.company_name, 'Unnamed Prospect');

IF FOUND THEN
-- Update existing contact to be a prospect
v_contact_id := v_existing_contact.id;

UPDATE contacts
SET
is_prospect = true,
contact_type = 'prospect',
temperature = NULL,  -- Prospects don't have temperature tracking
-- Merge data, preferring non-null lead values
full_name = COALESCE(v_lead.contact_name, full_name, v_contact_name),
company = COALESCE(v_lead.company_name, company),
email = COALESCE(v_lead.email, email),
phone = COALESCE(v_lead.phone, phone),
notes = CASE
WHEN notes IS NOT NULL AND v_lead.opportunity_description IS NOT NULL
THEN notes || E'\
\
--- Merged from Lead ---\
' || v_lead.opportunity_description
WHEN v_lead.opportunity_description IS NOT NULL
THEN v_lead.opportunity_description
ELSE notes
END,
assigned_to = COALESCE(v_lead.assigned_to, assigned_to),
updated_at = now()
WHERE id = v_contact_id;
ELSE
-- Create new contact as prospect
INSERT INTO contacts (
full_name,
company,
email,
phone,
notes,
contact_type,
is_prospect,
temperature,
assigned_to,
office_id,
created_by
) VALUES (
v_contact_name,
v_lead.company_name,
v_lead.email,
v_lead.phone,
v_lead.opportunity_description,
'prospect',
true,
NULL,  -- Prospects don't have temperature tracking
v_lead.assigned_to,
COALESCE(v_lead.office_id, v_office_id),
v_user_id
)
RETURNING id INTO v_contact_id;
END IF;

-- Create connection record documenting the conversion
INSERT INTO connections (
user_id,
contact_id,
connection_type,
connection_date,
notes,
follow_up_needed,
lead_created,
lead_id
) VALUES (
v_user_id,
v_contact_id,
'other',
now(),
'Downgraded from lead to prospect for future follow-up',
false,
false,
p_lead_id
);

-- Create scheduled follow-up if date is provided
IF p_follow_up_date IS NOT NULL THEN
INSERT INTO scheduled_connections (
user_id,
contact_id,
scheduled_date,
connection_type,
notes,
status
) VALUES (
v_user_id,
v_contact_id,
p_follow_up_date,
COALESCE(p_follow_up_type, 'call'),
COALESCE(p_follow_up_notes, 'Follow-up from lead-to-prospect downgrade'),
'pending'
);
END IF;

-- Update any tasks linked to the lead to also reference the contact
UPDATE tasks
SET contact_id = v_contact_id
WHERE lead_id = p_lead_id AND contact_id IS NULL;

-- Create competitor relationship if specified
IF p_competitor_id IS NOT NULL THEN
INSERT INTO prospect_competitor_relationships (
prospect_id,
competitor_id,
relationship_type,
relationship_strength,
notes,
created_by
) VALUES (
v_contact_id,
p_competitor_id,
COALESCE(p_relationship_type, 'evaluating'),
COALESCE(p_relationship_strength, 'moderate'),
'Added during lead-to-prospect downgrade',
v_user_id
)
ON CONFLICT (prospect_id, competitor_id)
DO UPDATE SET
relationship_type = COALESCE(p_relationship_type, prospect_competitor_relationships.relationship_type),
relationship_strength = COALESCE(p_relationship_strength, prospect_competitor_relationships.relationship_strength),
updated_at = now();
END IF;

-- Award points to the user for converting the lead
PERFORM award_points(
v_user_id,
v_lead_converted_points,
'Downgraded lead to prospect: ' || v_contact_name
);

-- Create feed event for the conversion
INSERT INTO feed_events (
event_type,
user_id,
lead_id,
title,
description
) VALUES (
'lead_converted',
v_user_id,
p_lead_id,
'Lead Downgraded to Prospect',
v_contact_name || ' was downgraded to a prospect for future follow-up'
);

-- Delete the lead (CASCADE will clean up lead_messages and lead_tags)
DELETE FROM leads WHERE id = p_lead_id;

-- Return success with contact ID and follow-up info
RETURN json_build_object(
'success', true,
'contact_id', v_contact_id,
'message', 'Lead successfully downgraded to prospect',
'was_merged', (v_existing_contact.id IS NOT NULL),
'follow_up_scheduled', (p_follow_up_date IS NOT NULL)
);

EXCEPTION
WHEN OTHERS THEN
-- Log error and return failure
RAISE LOG 'Error converting lead to prospect: %', SQLERRM;
RETURN json_build_object(
'success', false,
'message', 'Error converting lead: ' || SQLERRM
);
END;
$function$


CREATE OR REPLACE FUNCTION public.convert_prospect_to_customer(p_contact_id uuid, p_proposal_id uuid, p_proposal_number text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_was_prospect boolean;
v_contact_name text;
v_contact_type text;
BEGIN
-- Get current prospect status and name
SELECT is_prospect, full_name, contact_type
INTO v_was_prospect, v_contact_name, v_contact_type
FROM contacts
WHERE id = p_contact_id;

-- If not found, return false
IF NOT FOUND THEN
RETURN false;
END IF;

-- Only proceed if they were actually a prospect
IF v_was_prospect THEN
-- Update contact to customer status
UPDATE contacts
SET
is_prospect = false,
contact_type = CASE
WHEN contact_type = 'lead' THEN 'person'
ELSE contact_type
END,
updated_at = now()
WHERE id = p_contact_id;

-- Log the conversion as a connection
INSERT INTO connections (
company_id,
contact_id,
connected_by,
connection_type,
description,
follow_up_date,
status
)
SELECT
'00000000-0000-0000-0000-000000000001'::uuid,
p_contact_id,
auth.uid(),
'conversion',
'Converted from prospect to customer - Proposal ' || p_proposal_number || ' approved',
NULL,
'completed'
WHERE NOT EXISTS (
-- Avoid duplicate conversion logs
SELECT 1 FROM connections
WHERE contact_id = p_contact_id
AND connection_type = 'conversion'
AND description LIKE '%Proposal ' || p_proposal_number || '%'
);

RETURN true;
END IF;

-- Was already a customer
RETURN false;
END;
$function$


CREATE OR REPLACE FUNCTION public.convert_punchlist_tasks_to_service_request(p_task_ids uuid[], p_contact_id uuid, p_billable_type text DEFAULT 'warranty'::text, p_billable_by text DEFAULT 'company'::text, p_billable_by_user_id uuid DEFAULT NULL::uuid, p_priority text DEFAULT 'medium'::text, p_requested_tech_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_service_request_id uuid;
v_task record;
v_combined_description text := '';
v_contact record;
v_organization_id uuid;
BEGIN
-- Get organization_id from auth
SELECT organization_id INTO v_organization_id
FROM profiles
WHERE id = auth.uid();

IF v_organization_id IS NULL THEN
RAISE EXCEPTION 'User must belong to an organization';
END IF;

-- Get contact details
SELECT * INTO v_contact
FROM contacts
WHERE id = p_contact_id AND organization_id = v_organization_id;

IF v_contact IS NULL THEN
RAISE EXCEPTION 'Contact not found';
END IF;

-- Combine all task descriptions
FOR v_task IN 
SELECT title, details
FROM punchlist_tasks
WHERE id = ANY(p_task_ids)
AND contact_id = p_contact_id
ORDER BY priority_order
LOOP
v_combined_description := v_combined_description || '• ' || v_task.title;
IF v_task.details IS NOT NULL AND v_task.details != '' THEN
v_combined_description := v_combined_description || E'\
  ' || v_task.details;
END IF;
v_combined_description := v_combined_description || E'\
\
';
END LOOP;

-- Create service request with source_type set to 'punchlist'
INSERT INTO service_requests (
contact_id,
customer_name,
customer_phone,
customer_email,
job_location_address,
job_location_city,
job_location_state,
job_location_zip,
job_description,
billable_type,
billable_by,
billable_by_user_id,
priority,
requested_tech_ids,
status,
notes,
created_by,
created_by_name,
organization_id,
source_type
) VALUES (
p_contact_id,
v_contact.full_name,
v_contact.phone,
v_contact.email,
COALESCE(v_contact.address, 'No address on file'),
v_contact.city,
v_contact.state,
v_contact.zip,
'Punchlist items submitted by customer',
p_billable_type,
p_billable_by,
p_billable_by_user_id,
p_priority,
p_requested_tech_ids,
'pending',
v_combined_description,
auth.uid(),
(SELECT full_name FROM profiles WHERE id = auth.uid()),
v_organization_id,
'punchlist'
) RETURNING id INTO v_service_request_id;

-- Update punchlist tasks with service request ID and set status to submitted
UPDATE punchlist_tasks
SET 
service_request_id = v_service_request_id,
status = 'submitted',
updated_at = now()
WHERE id = ANY(p_task_ids);

RETURN v_service_request_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.convert_punchlist_tasks_to_service_request(p_task_ids uuid[], p_description text, p_urgency text DEFAULT 'medium'::text, p_scheduled_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_service_request_id uuid;
v_contact_id uuid;
v_contact_name text;
v_combined_description text;
v_company_id uuid;
v_task record;
BEGIN
-- Validate we have tasks
IF array_length(p_task_ids, 1) IS NULL OR array_length(p_task_ids, 1) = 0 THEN
RAISE EXCEPTION 'No tasks provided';
END IF;

-- Get company_id (single-tenant)
SELECT id INTO v_company_id FROM company_settings LIMIT 1;

-- Verify all tasks are from the same contact and are draft status
SELECT DISTINCT contact_id INTO v_contact_id
FROM punchlist_tasks
WHERE id = ANY(p_task_ids);

IF NOT FOUND THEN
RAISE EXCEPTION 'Tasks not found';
END IF;

-- Check if we got more than one distinct contact
IF (SELECT COUNT(DISTINCT contact_id) FROM punchlist_tasks WHERE id = ANY(p_task_ids)) > 1 THEN
RAISE EXCEPTION 'All tasks must belong to the same contact';
END IF;

-- Verify all tasks are draft status
IF EXISTS (SELECT 1 FROM punchlist_tasks WHERE id = ANY(p_task_ids) AND status != 'draft') THEN
RAISE EXCEPTION 'All tasks must be in draft status';
END IF;

-- Get contact name
SELECT full_name INTO v_contact_name FROM contacts WHERE id = v_contact_id;

-- Generate combined description
v_combined_description := generate_combined_task_description(p_task_ids);

-- Create service request
INSERT INTO service_requests (
company_id,
contact_id,
description,
status,
urgency,
scheduled_date,
notes,
created_by
) VALUES (
v_company_id,
v_contact_id,
COALESCE(p_description, 'Punchlist Items - ' || v_contact_name),
CASE WHEN p_scheduled_date IS NOT NULL THEN 'scheduled' ELSE 'new' END,
p_urgency,
p_scheduled_date,
v_combined_description,
auth.uid()
)
RETURNING id INTO v_service_request_id;

-- Update all tasks to link to service request and change status
UPDATE punchlist_tasks
SET
service_request_id = v_service_request_id,
status = 'scheduled',
combined_description = v_combined_description,
updated_at = now()
WHERE id = ANY(p_task_ids);

RETURN v_service_request_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.convert_punchlist_tasks_to_service_request(p_task_ids uuid[], p_contact_id uuid, p_priority text DEFAULT 'normal'::text, p_billable_type text DEFAULT 'billable'::text, p_billable_by text DEFAULT 'dispatch'::text, p_billable_by_user_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_service_request_id uuid;
v_combined_description text;
v_contact_record record;
v_task_id uuid;
BEGIN
-- Validate we have at least one task
IF array_length(p_task_ids, 1) IS NULL OR array_length(p_task_ids, 1) = 0 THEN
RAISE EXCEPTION 'At least one task ID is required';
END IF;

-- Validate all tasks belong to the same contact
IF EXISTS (
SELECT 1 FROM punchlist_tasks
WHERE id = ANY(p_task_ids)
AND contact_id != p_contact_id
) THEN
RAISE EXCEPTION 'All tasks must belong to the same contact';
END IF;

-- Validate tasks are not already converted
IF EXISTS (
SELECT 1 FROM punchlist_tasks
WHERE id = ANY(p_task_ids)
AND (service_request_id IS NOT NULL OR work_order_id IS NOT NULL)
) THEN
RAISE EXCEPTION 'One or more tasks have already been converted';
END IF;

-- Get contact information
SELECT
full_name,
phone,
email,
street_address,
city,
state,
zip_code
INTO v_contact_record
FROM contacts
WHERE id = p_contact_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Contact not found';
END IF;

-- Generate combined description
v_combined_description := generate_combined_task_description(p_task_ids);

-- Create service request
INSERT INTO service_requests (
created_by,
contact_id,
customer_name,
customer_phone,
customer_email,
job_location_address,
job_location_city,
job_location_state,
job_location_zip,
job_description,
billable_type,
billable_by,
billable_by_user_id,
priority,
notes,
status
) VALUES (
auth.uid(),
p_contact_id,
v_contact_record.full_name,
v_contact_record.phone,
v_contact_record.email,
v_contact_record.street_address,
v_contact_record.city,
v_contact_record.state,
v_contact_record.zip_code,
v_combined_description,
p_billable_type,
p_billable_by,
p_billable_by_user_id,
p_priority,
p_notes,
'pending'
)
RETURNING id INTO v_service_request_id;

-- Update all punchlist tasks
FOREACH v_task_id IN ARRAY p_task_ids
LOOP
UPDATE punchlist_tasks
SET
service_request_id = v_service_request_id,
status = 'requested',
combined_description = v_combined_description,
updated_at = now()
WHERE id = v_task_id;
END LOOP;

RETURN v_service_request_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.convert_punchlist_tasks_to_work_order(p_task_ids uuid[], p_contact_id uuid, p_project_id uuid DEFAULT NULL::uuid, p_work_order_type text DEFAULT 'service'::text, p_billable_type text DEFAULT 'billable'::text, p_priority text DEFAULT 'medium'::text, p_title text DEFAULT NULL::text, p_description_override text DEFAULT NULL::text, p_assigned_technician_ids uuid[] DEFAULT NULL::uuid[], p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_estimated_hours numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_internal_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_work_order_id uuid;
v_combined_description text;
v_contact_record record;
v_task_id uuid;
v_work_order_title text;
v_work_order_description text;
v_task_count int;
BEGIN
-- Validate we have at least one task
IF array_length(p_task_ids, 1) IS NULL OR array_length(p_task_ids, 1) = 0 THEN
RAISE EXCEPTION 'At least one task ID is required';
END IF;

-- Validate all tasks belong to the same contact
IF EXISTS (
SELECT 1 FROM punchlist_tasks
WHERE id = ANY(p_task_ids)
AND contact_id != p_contact_id
) THEN
RAISE EXCEPTION 'All tasks must belong to the same contact';
END IF;

-- Validate tasks are not already converted
IF EXISTS (
SELECT 1 FROM punchlist_tasks
WHERE id = ANY(p_task_ids)
AND (service_request_id IS NOT NULL OR work_order_id IS NOT NULL)
) THEN
RAISE EXCEPTION 'One or more tasks have already been converted';
END IF;

-- Get contact information
SELECT
full_name,
street_address,
city,
state,
zip_code
INTO v_contact_record
FROM contacts
WHERE id = p_contact_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Contact not found';
END IF;

-- Generate combined description
v_combined_description := generate_combined_task_description(p_task_ids);

-- Determine title
v_task_count := array_length(p_task_ids, 1);
IF p_title IS NOT NULL THEN
v_work_order_title := p_title;
ELSIF v_task_count = 1 THEN
SELECT title INTO v_work_order_title FROM punchlist_tasks WHERE id = p_task_ids[1];
ELSE
v_work_order_title := 'Punchlist Service - ' || v_contact_record.full_name || ' (' || v_task_count || ' tasks)';
END IF;

-- Determine description
v_work_order_description := COALESCE(p_description_override, v_combined_description);

-- Create work order
INSERT INTO work_orders (
contact_id,
project_id,
type,
billable_type,
title,
description,
priority,
status,
service_location_address,
service_location_city,
service_location_state,
service_location_zip,
start_date,
estimated_hours,
notes,
internal_notes,
created_by
) VALUES (
p_contact_id,
p_project_id,
p_work_order_type,
p_billable_type,
v_work_order_title,
v_work_order_description,
p_priority,
CASE
WHEN p_assigned_technician_ids IS NOT NULL AND array_length(p_assigned_technician_ids, 1) > 0
THEN 'scheduled'
ELSE 'unscheduled'
END,
v_contact_record.street_address,
v_contact_record.city,
v_contact_record.state,
v_contact_record.zip_code,
p_start_date,
p_estimated_hours,
p_notes,
p_internal_notes,
auth.uid()
)
RETURNING id INTO v_work_order_id;

-- Assign technicians if provided
IF p_assigned_technician_ids IS NOT NULL AND array_length(p_assigned_technician_ids, 1) > 0 THEN
INSERT INTO work_order_assignments (work_order_id, user_id)
SELECT v_work_order_id, unnest(p_assigned_technician_ids);
END IF;

-- Update all punchlist tasks
FOREACH v_task_id IN ARRAY p_task_ids
LOOP
UPDATE punchlist_tasks
SET
work_order_id = v_work_order_id,
status = CASE
WHEN p_start_date IS NOT NULL THEN 'scheduled'
ELSE 'in_work_order'
END,
combined_description = v_combined_description,
updated_at = now()
WHERE id = v_task_id;
END LOOP;

-- Create activity feed entry
INSERT INTO activity_feed (type, user_id, metadata)
VALUES (
'work_order_created',
auth.uid(),
jsonb_build_object(
'work_order_id', v_work_order_id,
'source', 'punchlist',
'task_count', v_task_count,
'contact_id', p_contact_id
)
);

RETURN v_work_order_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.convert_punchlist_tasks_to_work_order(p_task_ids uuid[], p_description text, p_assigned_to uuid[], p_scheduled_date date, p_scheduled_time time without time zone DEFAULT NULL::time without time zone, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_work_order_id uuid;
v_contact_id uuid;
v_contact_name text;
v_combined_description text;
v_company_id uuid;
v_tech_id uuid;
BEGIN
-- Validate we have tasks
IF array_length(p_task_ids, 1) IS NULL OR array_length(p_task_ids, 1) = 0 THEN
RAISE EXCEPTION 'No tasks provided';
END IF;

-- Get company_id (single-tenant)
SELECT id INTO v_company_id FROM company_settings LIMIT 1;

-- Verify all tasks are from the same contact and are draft status
SELECT DISTINCT contact_id INTO v_contact_id
FROM punchlist_tasks
WHERE id = ANY(p_task_ids);

IF NOT FOUND THEN
RAISE EXCEPTION 'Tasks not found';
END IF;

-- Check if we got more than one distinct contact
IF (SELECT COUNT(DISTINCT contact_id) FROM punchlist_tasks WHERE id = ANY(p_task_ids)) > 1 THEN
RAISE EXCEPTION 'All tasks must belong to the same contact';
END IF;

-- Verify all tasks are draft status
IF EXISTS (SELECT 1 FROM punchlist_tasks WHERE id = ANY(p_task_ids) AND status != 'draft') THEN
RAISE EXCEPTION 'All tasks must be in draft status';
END IF;

-- Get contact name
SELECT full_name INTO v_contact_name FROM contacts WHERE id = v_contact_id;

-- Generate combined description
v_combined_description := generate_combined_task_description(p_task_ids);

-- Create work order
INSERT INTO work_orders (
company_id,
contact_id,
type,
description,
status,
scheduled_date,
scheduled_time,
notes,
created_by
) VALUES (
v_company_id,
v_contact_id,
'punchlist',
COALESCE(p_description, 'Punchlist Items - ' || v_contact_name),
'scheduled',
p_scheduled_date,
p_scheduled_time,
COALESCE(p_notes, '') || E'\
\
Punchlist Tasks:\
' || v_combined_description,
auth.uid()
)
RETURNING id INTO v_work_order_id;

-- Assign technicians
IF p_assigned_to IS NOT NULL AND array_length(p_assigned_to, 1) > 0 THEN
FOREACH v_tech_id IN ARRAY p_assigned_to
LOOP
INSERT INTO work_order_assignments (
work_order_id,
user_id,
role,
assigned_at,
assigned_by
) VALUES (
v_work_order_id,
v_tech_id,
'technician',
now(),
auth.uid()
);
END LOOP;
END IF;

-- Update all tasks to link to work order and change status
UPDATE punchlist_tasks
SET
work_order_id = v_work_order_id,
status = 'in_work_order',
combined_description = v_combined_description,
updated_at = now()
WHERE id = ANY(p_task_ids);

RETURN v_work_order_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.convert_service_request_to_work_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
new_work_order_id uuid;
v_work_order_type text;
BEGIN
IF NEW.status = 'pending' AND NEW.work_order_id IS NULL THEN

IF NEW.notes LIKE '%punchlist%' OR 
EXISTS (
SELECT 1 FROM punchlist_tasks 
WHERE service_request_id = NEW.id
) THEN
v_work_order_type := 'punchlist';
ELSE
v_work_order_type := 'service';
END IF;

INSERT INTO work_orders (
company_id,
contact_id,
title,
description,
type,
status,
priority,
service_location_address,
service_location_city,
service_location_state,
service_location_zip,
billable_type,
created_by
) VALUES (
(SELECT company_id FROM profiles WHERE id = NEW.created_by LIMIT 1),
NEW.contact_id,
CASE 
WHEN v_work_order_type = 'punchlist' THEN 'Punchlist Service'
ELSE 'Service Request'
END,
NEW.job_description,
v_work_order_type,
'unscheduled',
NEW.priority,
NEW.job_location_address,
NEW.job_location_city,
NEW.job_location_state,
NEW.job_location_zip,
NEW.billable_type,
NEW.created_by
)
RETURNING id INTO new_work_order_id;

NEW.work_order_id = new_work_order_id;
NEW.status = 'converted_to_work_order';

END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.cool_down_inactive_contacts()
 RETURNS TABLE(contact_id uuid, contact_name text, previous_temperature text, days_inactive integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
three_months_ago timestamptz := now() - interval '90 days';
cooled_count integer := 0;
BEGIN
-- Find and cool down inactive prospects and leads
RETURN QUERY
WITH inactive_contacts AS (
SELECT 
c.id,
c.full_name,
c.temperature,
COALESCE(
GREATEST(
-- Last proposal created for this contact
(SELECT MAX(created_at) FROM proposals WHERE contact_id = c.id),
-- Last connection logged
(SELECT MAX(connection_date) FROM connections WHERE contact_id = c.id),
-- Last task created for this contact
(SELECT MAX(created_at) FROM tasks WHERE contact_id = c.id),
-- Last time contact was updated
c.updated_at,
c.created_at
),
c.created_at
) as last_activity_date,
EXTRACT(days FROM now() - COALESCE(
GREATEST(
(SELECT MAX(created_at) FROM proposals WHERE contact_id = c.id),
(SELECT MAX(connection_date) FROM connections WHERE contact_id = c.id),
(SELECT MAX(created_at) FROM tasks WHERE contact_id = c.id),
c.updated_at,
c.created_at
),
c.created_at
))::integer as days_since_activity
FROM contacts c
WHERE 
-- Only prospects and leads
(c.is_prospect = true OR c.contact_type = 'lead')
-- Not already cold
AND c.temperature != 'cold'
-- Has a temperature set
AND c.temperature IS NOT NULL
-- Last activity was more than 90 days ago
AND COALESCE(
GREATEST(
(SELECT MAX(created_at) FROM proposals WHERE contact_id = c.id),
(SELECT MAX(connection_date) FROM connections WHERE contact_id = c.id),
(SELECT MAX(created_at) FROM tasks WHERE contact_id = c.id),
c.updated_at,
c.created_at
),
c.created_at
) < three_months_ago
)
UPDATE contacts c
SET 
temperature = 'cold',
updated_at = now()
FROM inactive_contacts ic
WHERE c.id = ic.id
RETURNING 
c.id as contact_id,
ic.full_name as contact_name,
ic.temperature as previous_temperature,
ic.days_since_activity as days_inactive;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_commission_records_for_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_project record;
v_sales_order record;
v_settings record;
v_sales_rep_id uuid;
v_pm_id uuid;
v_sales_rate numeric;
v_pm_rate numeric;
v_basis_amount numeric;
v_basis_type text;
BEGIN
-- Only process if invoice has a project_id
IF NEW.project_id IS NULL THEN
RETURN NEW;
END IF;

-- Get project details
SELECT * INTO v_project FROM projects WHERE id = NEW.project_id;

-- Get sales order to find sales rep
IF v_project.sales_order_id IS NOT NULL THEN
SELECT * INTO v_sales_order FROM sales_orders WHERE id = v_project.sales_order_id;
v_sales_rep_id := v_sales_order.created_by;
END IF;

-- Get project manager
v_pm_id := v_project.assigned_pm;

-- Get company settings for basis type
SELECT * INTO v_settings FROM company_commission_settings LIMIT 1;
v_basis_type := v_settings.commission_basis;

-- Use invoice total as basis (in future, could use subtotal for profit basis)
v_basis_amount := NEW.total;

-- Create Sales Rep Commission Record
IF v_sales_rep_id IS NOT NULL THEN
-- Check if employee is eligible
IF EXISTS (
SELECT 1 FROM employee_commission_config 
WHERE employee_id = v_sales_rep_id 
AND eligible_for_commissions = true
) OR NOT EXISTS (
SELECT 1 FROM employee_commission_config 
WHERE employee_id = v_sales_rep_id
) THEN
v_sales_rate := get_effective_commission_rate(v_sales_rep_id, 'sales_projects');

INSERT INTO commission_records (
employee_id,
project_id,
invoice_id,
role_type,
basis_type,
basis_amount,
commission_rate,
total_potential_commission,
amount_collected,
amount_earned,
amount_paid,
status
) VALUES (
v_sales_rep_id,
NEW.project_id,
NEW.id,
'sales_projects',
v_basis_type,
v_basis_amount,
v_sales_rate,
v_basis_amount * v_sales_rate / 100,
0,
0,
0,
'pending'
);
END IF;
END IF;

-- Create Project Manager Commission Record
IF v_pm_id IS NOT NULL AND v_pm_id != v_sales_rep_id THEN
-- Check if employee is eligible
IF EXISTS (
SELECT 1 FROM employee_commission_config 
WHERE employee_id = v_pm_id 
AND eligible_for_commissions = true
) OR NOT EXISTS (
SELECT 1 FROM employee_commission_config 
WHERE employee_id = v_pm_id
) THEN
v_pm_rate := get_effective_commission_rate(v_pm_id, 'pm');

INSERT INTO commission_records (
employee_id,
project_id,
invoice_id,
role_type,
basis_type,
basis_amount,
commission_rate,
total_potential_commission,
amount_collected,
amount_earned,
amount_paid,
status
) VALUES (
v_pm_id,
NEW.project_id,
NEW.id,
'pm',
v_basis_type,
v_basis_amount,
v_pm_rate,
v_basis_amount * v_pm_rate / 100,
0,
0,
0,
'pending'
);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_contact_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF TG_OP = 'INSERT' THEN
-- Skip feed event for anonymous / kiosk inserts (no authenticated user)
IF NEW.created_by IS NULL THEN
RETURN NEW;
END IF;

INSERT INTO feed_events (
event_type,
user_id,
contact_id,
metadata
) VALUES (
'contact_created',
NEW.created_by,
NEW.id,
jsonb_build_object(
'name', NEW.contact_name,
'company', NEW.company_name
)
);

ELSIF TG_OP = 'UPDATE' THEN
-- Only create update event if meaningful fields changed and user is authenticated
IF auth.uid() IS NOT NULL AND (
OLD.contact_name IS DISTINCT FROM NEW.contact_name OR
OLD.company_name IS DISTINCT FROM NEW.company_name OR
OLD.email IS DISTINCT FROM NEW.email OR
OLD.phone IS DISTINCT FROM NEW.phone OR
OLD.assigned_to IS DISTINCT FROM NEW.assigned_to) THEN
INSERT INTO feed_events (
event_type,
user_id,
contact_id,
metadata
) VALUES (
'contact_updated',
auth.uid(),
NEW.id,
jsonb_build_object(
'name', NEW.contact_name,
'company', NEW.company_name
)
);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_default_proposal_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
default_contract_id uuid;
company_defaults record;
customer_defaults record;
default_acceptance_methods text[];
default_progress_terms text;
default_balance_terms text;
BEGIN
SELECT id INTO default_contract_id
FROM contracts
WHERE contract_type = 'proposal'
AND is_default = true
LIMIT 1;

SELECT
job_module_settings->>'deposit_default_percent' as default_deposit_percent,
job_module_settings->>'project_mgmt_default_percent' as default_project_mgmt_percent,
job_module_settings->>'system_design_default_percent' as default_system_design_percent,
job_module_settings->>'cc_fee_default_percent' as default_cc_fee_percent,
job_module_settings->>'misc_parts_default_percent' as default_misc_parts_percent
INTO company_defaults
FROM company_settings
LIMIT 1;

SELECT
default_payment_terms,
accepts_po
INTO customer_defaults
FROM contacts
WHERE id = NEW.contact_id;

IF customer_defaults.accepts_po = true THEN
default_acceptance_methods := ARRAY['payment', 'purchase_order'];
default_progress_terms := 'net_30';
ELSE
default_acceptance_methods := ARRAY['payment'];
default_progress_terms := 'net_10';
END IF;

IF customer_defaults.default_payment_terms IS NOT NULL THEN
default_balance_terms := customer_defaults.default_payment_terms;
ELSE
default_balance_terms := 'Net 10';
END IF;

INSERT INTO proposal_settings (
proposal_id,
organization_id,
contract_id,
deposit_percent,
project_management_percent,
system_design_percent,
credit_card_fee_percent,
misc_parts_percent,
acceptance_methods,
progress_invoice_terms,
balance_payment_terms
) VALUES (
NEW.id,
NEW.organization_id,
default_contract_id,
COALESCE(company_defaults.default_deposit_percent::numeric, 50),
COALESCE(company_defaults.default_project_mgmt_percent::numeric, 0),
COALESCE(company_defaults.default_system_design_percent::numeric, 0),
COALESCE(company_defaults.default_cc_fee_percent::numeric, 3),
COALESCE(company_defaults.default_misc_parts_percent::numeric, 0),
default_acceptance_methods,
default_progress_terms,
default_balance_terms
);

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_deposit_invoice_from_proposal(p_proposal_id uuid, p_invoice_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invoice_id uuid;
v_invoice_number text;
v_proposal record;
v_deposit_amount numeric(10,2);
v_deposit_description text;
v_payment_id uuid;
BEGIN
SELECT
p.id, p.company_id, p.contact_id, p.proposal_number, p.deposit_amount_due, p.created_by,
p.deposit_payment_date, p.tax_rate, c.full_name as contact_name
INTO v_proposal
FROM proposals p
LEFT JOIN contacts c ON c.id = p.contact_id
WHERE p.id = p_proposal_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Proposal not found';
END IF;

v_deposit_amount := COALESCE(v_proposal.deposit_amount_due, 0);

IF v_deposit_amount <= 0 THEN
RAISE EXCEPTION 'No deposit amount to invoice';
END IF;

v_invoice_number := generate_invoice_number();
v_deposit_description := 'Deposit for Proposal ' || v_proposal.proposal_number;

INSERT INTO invoices (
company_id, proposal_id, contact_id, invoice_number, invoice_type,
invoice_date, due_date, subtotal, tax_amount, tax_rate, total, amount_due, status,
payment_terms, notes, created_by, created_at, updated_at
) VALUES (
v_proposal.company_id, v_proposal.id, v_proposal.contact_id, v_invoice_number, 'deposit',
CURRENT_DATE, CURRENT_DATE, v_deposit_amount, 0, COALESCE(v_proposal.tax_rate, 0),
v_deposit_amount,
CASE WHEN p_invoice_status = 'paid' THEN 0 ELSE v_deposit_amount END,
CASE WHEN p_invoice_status = 'paid' THEN 'paid' ELSE 'submitted' END,
CASE WHEN p_invoice_status = 'paid' THEN 'Paid' ELSE 'Due upon receipt' END,
CASE WHEN p_invoice_status = 'paid' THEN 'Deposit payment received for ' || v_proposal.contact_name
ELSE 'Deposit invoice for ' || v_proposal.contact_name END,
v_proposal.created_by, now(), now()
) RETURNING id INTO v_invoice_id;

INSERT INTO invoice_line_items (
invoice_id, description, quantity, unit_price, amount, sort_order, taxable
) VALUES (
v_invoice_id, v_deposit_description, 1, v_deposit_amount, v_deposit_amount, 1, false
);

IF p_invoice_status = 'paid' THEN
INSERT INTO invoice_payments (
company_id, invoice_id, proposal_id, payment_date, amount, payment_method,
reference_number, notes, created_by, created_at
) VALUES (
v_proposal.company_id, v_invoice_id, v_proposal.id,
COALESCE(v_proposal.deposit_payment_date, CURRENT_DATE), v_deposit_amount, 'other',
'Deposit - Proposal ' || v_proposal.proposal_number,
'Deposit payment recorded at proposal approval',
v_proposal.created_by, now()
) RETURNING id INTO v_payment_id;
END IF;

UPDATE proposals SET deposit_invoice_id = v_invoice_id WHERE id = p_proposal_id;

RETURN v_invoice_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_deposit_invoice_from_proposal(p_proposal_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invoice_id uuid;
v_invoice_number text;
v_proposal record;
v_deposit_amount numeric(10,2);
v_deposit_description text;
BEGIN
SELECT
p.id, p.company_id, p.contact_id, p.proposal_number, p.deposit_amount_due, p.created_by,
c.full_name as contact_name
INTO v_proposal
FROM proposals p
LEFT JOIN contacts c ON c.id = p.contact_id
WHERE p.id = p_proposal_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Proposal not found';
END IF;

v_deposit_amount := COALESCE(v_proposal.deposit_amount_due, 0);

IF v_deposit_amount <= 0 THEN
RAISE EXCEPTION 'No deposit amount to invoice';
END IF;

v_invoice_number := generate_invoice_number();
v_deposit_description := 'Deposit for Proposal ' || v_proposal.proposal_number;

INSERT INTO invoices (
company_id, proposal_id, contact_id, invoice_number, invoice_type,
invoice_date, due_date, subtotal, tax_amount, total, amount_due, status,
payment_terms, notes, created_by, created_at, updated_at
) VALUES (
v_proposal.company_id, v_proposal.id, v_proposal.contact_id, v_invoice_number, 'deposit',
CURRENT_DATE, CURRENT_DATE, v_deposit_amount, 0, v_deposit_amount, v_deposit_amount,
'submitted',
'Due upon receipt',
'Deposit invoice for ' || v_proposal.contact_name,
v_proposal.created_by, now(), now()
) RETURNING id INTO v_invoice_id;

INSERT INTO invoice_line_items (
invoice_id, description, quantity, unit_price, amount, sort_order
) VALUES (
v_invoice_id, v_deposit_description, 1, v_deposit_amount, v_deposit_amount, 1
);

UPDATE proposals SET deposit_invoice_id = v_invoice_id WHERE id = p_proposal_id;

RETURN v_invoice_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_discussion_post_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Only create event for top-level posts (not replies)
IF NEW.parent_id IS NULL THEN
INSERT INTO feed_events (
event_type,
user_id,
discussion_post_id,
metadata
) VALUES (
'discussion_created',
NEW.user_id,
NEW.id,
jsonb_build_object(
'post_type', NEW.post_type,
'content_preview', substring(NEW.content, 1, 100)
)
);
ELSE
-- Create reply event
INSERT INTO feed_events (
event_type,
user_id,
discussion_post_id,
metadata
) VALUES (
'discussion_replied',
NEW.user_id,
NEW.parent_id,
jsonb_build_object(
'reply_id', NEW.id,
'content_preview', substring(NEW.content, 1, 100)
)
);
END IF;

RETURN NEW;
END;
$function$


