CREATE OR REPLACE FUNCTION public.create_leave_time_entry_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_policy_type text;
v_company_id uuid;
v_entry_id uuid;
v_current_date date;
BEGIN
-- Only fire when transitioning from pending to approved
IF NEW.status = 'approved' AND OLD.status = 'pending' THEN
-- Get the PTO type
SELECT pto_type INTO v_policy_type
FROM pto_policies
WHERE id = NEW.policy_id;

-- Get company_id from the employee's profile
SELECT company_id INTO v_company_id
FROM profiles
WHERE id = NEW.employee_id;

IF v_company_id IS NULL THEN
-- Fallback: try to get from organization
SELECT id INTO v_company_id FROM organizations LIMIT 1;
END IF;

v_current_date := NEW.start_date;

-- Create a time_entries row for each day in the range
-- For simplicity, create one entry per day with 8 hours
-- (the existing PTO system calculates total_hours already)
INSERT INTO time_entries (
company_id,
technician_id,
entry_date,
clock_in,
clock_out,
total_hours,
status,
entry_type,
notes,
approved_by,
approved_at
)
VALUES (
v_company_id,
NEW.employee_id,
v_current_date,
now(),
now(),
NEW.total_hours,
'approved',
v_policy_type,
COALESCE(NEW.reason, 'PTO - ' || v_policy_type),
NEW.reviewed_by,
NEW.reviewed_at
)
RETURNING id INTO v_entry_id;

-- Link the time entry back to the PTO request
UPDATE pto_requests
SET time_entry_id = v_entry_id
WHERE id = NEW.id;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_manual_punchlist_invite(p_contact_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invite_id uuid;
v_contact_name text;
BEGIN
-- Get contact name for notes
SELECT full_name INTO v_contact_name
FROM contacts
WHERE id = p_contact_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Contact not found';
END IF;

-- Check if contact already has pending invite
IF EXISTS (
SELECT 1 FROM pending_punchlist_invites 
WHERE contact_id = p_contact_id 
AND status = 'pending'
) THEN
RAISE EXCEPTION 'Contact already has a pending punchlist invite';
END IF;

-- Check if contact already has active access
IF EXISTS (
SELECT 1 FROM punchlist_access_grants
WHERE contact_id = p_contact_id
AND status = 'active'
AND (expiration_date IS NULL OR expiration_date >= CURRENT_DATE)
) THEN
RAISE EXCEPTION 'Contact already has active punchlist access';
END IF;

-- Create the pending invite
INSERT INTO pending_punchlist_invites (
contact_id,
project_id,
status,
notes
) VALUES (
p_contact_id,
NULL,  -- No project association for manual invites
'pending',
COALESCE(
p_notes, 
'Manual invite created for ' || v_contact_name || ' by staff on ' || CURRENT_DATE::text
)
)
RETURNING id INTO v_invite_id;

RETURN v_invite_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_next_mileage_reminder(p_user_id uuid, p_vehicle_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_last_entry_date date;
v_next_due_date date;
BEGIN
-- Get the last mileage entry date
SELECT MAX(entry_date) INTO v_last_entry_date
FROM mileage_entries
WHERE user_id = p_user_id
AND vehicle_id = p_vehicle_id;

-- If no entry exists, use assignment date
IF v_last_entry_date IS NULL THEN
SELECT assigned_date INTO v_last_entry_date
FROM vehicle_assignments
WHERE user_id = p_user_id
AND vehicle_id = p_vehicle_id
AND is_active = true
LIMIT 1;
END IF;

-- Calculate next due date (3 months from last entry)
v_next_due_date := v_last_entry_date + INTERVAL '3 months';

-- Create reminder if it doesn't exist
INSERT INTO mileage_reminders (user_id, vehicle_id, due_date, status)
VALUES (p_user_id, p_vehicle_id, v_next_due_date, 'pending')
ON CONFLICT DO NOTHING;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_promotional_access_grant(p_contact_id uuid, p_project_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 90, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_access_grant_id uuid;
v_expiration_date date;
v_final_notes text;
BEGIN
-- Calculate expiration date
v_expiration_date := CURRENT_DATE + (p_days || ' days')::interval;

-- Check if contact already has active promotional access
IF EXISTS (
SELECT 1 FROM punchlist_access_grants
WHERE contact_id = p_contact_id
AND access_type = 'promotional'
AND status = 'active'
AND (expiration_date IS NULL OR expiration_date >= CURRENT_DATE)
) THEN
RAISE EXCEPTION 'Contact already has active promotional punchlist access';
END IF;

-- Build notes with timestamp and user info
v_final_notes := COALESCE(p_notes, 'Promotional access granted');
v_final_notes := v_final_notes || ' on ' || CURRENT_DATE::text;

-- Add user info if available from auth context
IF auth.uid() IS NOT NULL THEN
v_final_notes := v_final_notes || ' by user ' || auth.uid()::text;
END IF;

-- Create the promotional access grant
INSERT INTO punchlist_access_grants (
contact_id,
access_type,
project_id,
granted_date,
expiration_date,
status,
notes
) VALUES (
p_contact_id,
'promotional',
p_project_id,
CURRENT_DATE,
v_expiration_date,
'active',
v_final_notes
)
RETURNING id INTO v_access_grant_id;

RETURN v_access_grant_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_proposal_revision(p_proposal_id uuid, p_revision_name text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_new_proposal_id    uuid;
v_root_proposal_id   uuid;
v_root_proposal_number text;
v_next_revision_number integer;
v_new_proposal_number text;
v_room_mapping       jsonb := '{}'::jsonb;
v_line_item_mapping  jsonb := '{}'::jsonb;
v_old_room           record;
v_new_room_id        uuid;
v_line_item          record;
v_new_line_item_id   uuid;
v_old_labor_phase    record;
v_old_task           record;
BEGIN
v_root_proposal_id := get_root_proposal_id(p_proposal_id);

SELECT
CASE
WHEN proposal_number ~ '-[0-9]+$' AND is_revision = true
THEN regexp_replace(proposal_number, '-[0-9]+$', '')
ELSE proposal_number
END
INTO v_root_proposal_number
FROM proposals
WHERE id = v_root_proposal_id;

SELECT COALESCE(MAX(revision_number), 0) + 1
INTO v_next_revision_number
FROM proposals
WHERE (id = v_root_proposal_id OR parent_proposal_id = v_root_proposal_id);

v_new_proposal_number := v_root_proposal_number || '-' || v_next_revision_number::text;

UPDATE proposals
SET is_active_revision = false
WHERE (id = v_root_proposal_id OR parent_proposal_id = v_root_proposal_id);

INSERT INTO proposals (
company_id, contact_id, lead_id, proposal_number, title, status,
valid_until, notes, customer_notes, subtotal, tax_rate, tax_amount, total,
deposit_percent, deposit_amount, created_by, is_revision, parent_proposal_id,
revision_name, is_active_revision, is_portal_visible, revision_number
)
SELECT
company_id, contact_id, lead_id, v_new_proposal_number, title, 'designing',
valid_until, notes, customer_notes, subtotal, tax_rate, tax_amount, total,
deposit_percent, deposit_amount, p_created_by, true, v_root_proposal_id,
p_revision_name, true, false, v_next_revision_number
FROM proposals
WHERE id = p_proposal_id
RETURNING id INTO v_new_proposal_id;

-- Copy rooms and track ID mapping
FOR v_old_room IN
SELECT * FROM proposal_rooms WHERE proposal_id = p_proposal_id ORDER BY sort_order
LOOP
INSERT INTO proposal_rooms (proposal_id, name, description, sort_order)
VALUES (v_new_proposal_id, v_old_room.name, v_old_room.description, v_old_room.sort_order)
RETURNING id INTO v_new_room_id;

v_room_mapping := jsonb_set(v_room_mapping, ARRAY[v_old_room.id::text], to_jsonb(v_new_room_id));
END LOOP;

-- Copy line items with ALL columns, track ID mapping
FOR v_line_item IN
SELECT * FROM proposal_line_items WHERE proposal_id = p_proposal_id ORDER BY sort_order
LOOP
INSERT INTO proposal_line_items (
proposal_id, room_id, product_id, description, quantity, unit, unit_price,
cost, line_total, sort_order, is_custom, created_at, updated_at,
labor_hours, labor_rate, labor_total, item_type, is_taxable, tax_amount,
item_class, labor_phase, task_notes, is_hidden, show_task_notes,
labor_phase_id, class_id, parent_item_id, display_mode, organization_id,
programming_labor_hours, programming_notes, show_programming_notes,
task_completed, is_customer_supplied, tax_classification_id, tasks_seeded_at
)
VALUES (
v_new_proposal_id,
CASE WHEN v_line_item.room_id IS NOT NULL
THEN (v_room_mapping->>v_line_item.room_id::text)::uuid
ELSE NULL
END,
v_line_item.product_id,
v_line_item.description,
v_line_item.quantity,
v_line_item.unit,
v_line_item.unit_price,
v_line_item.cost,
v_line_item.line_total,
v_line_item.sort_order,
v_line_item.is_custom,
v_line_item.created_at,
v_line_item.updated_at,
v_line_item.labor_hours,
v_line_item.labor_rate,
v_line_item.labor_total,
v_line_item.item_type,
v_line_item.is_taxable,
v_line_item.tax_amount,
v_line_item.item_class,
v_line_item.labor_phase,
v_line_item.task_notes,
v_line_item.is_hidden,
v_line_item.show_task_notes,
v_line_item.labor_phase_id,
v_line_item.class_id,
-- Map parent_item_id to new revision's parent item
CASE WHEN v_line_item.parent_item_id IS NOT NULL
THEN (v_line_item_mapping->>v_line_item.parent_item_id::text)::uuid
ELSE NULL
END,
v_line_item.display_mode,
v_line_item.organization_id,
v_line_item.programming_labor_hours,
v_line_item.programming_notes,
v_line_item.show_programming_notes,
v_line_item.task_completed,
v_line_item.is_customer_supplied,
v_line_item.tax_classification_id,
v_line_item.tasks_seeded_at
)
RETURNING id INTO v_new_line_item_id;

v_line_item_mapping := jsonb_set(v_line_item_mapping, ARRAY[v_line_item.id::text], to_jsonb(v_new_line_item_id));
END LOOP;

-- Copy labor phases with mapped line_item_id (pre-existing gap fixed)
FOR v_old_labor_phase IN
SELECT * FROM proposal_line_item_labor_phases
WHERE line_item_id IN (SELECT id FROM proposal_line_items WHERE proposal_id = p_proposal_id)
ORDER BY line_item_id, sort_order
LOOP
INSERT INTO proposal_line_item_labor_phases (
line_item_id, labor_phase_id, hours, tech_notes, sort_order, organization_id
)
VALUES (
(v_line_item_mapping->>v_old_labor_phase.line_item_id::text)::uuid,
v_old_labor_phase.labor_phase_id,
v_old_labor_phase.hours,
v_old_labor_phase.tech_notes,
v_old_labor_phase.sort_order,
v_old_labor_phase.organization_id
);
END LOOP;

-- Copy proposal_tasks with mapped line_item_id (snapshot, not regenerated)
FOR v_old_task IN
SELECT * FROM proposal_tasks
WHERE proposal_id = p_proposal_id
ORDER BY sort_order
LOOP
INSERT INTO proposal_tasks (
proposal_id, line_item_id, source_default_task_id,
title, description, labor_phase_id, sort_order,
organization_id, created_by, created_at, updated_at
)
VALUES (
v_new_proposal_id,
CASE WHEN v_old_task.line_item_id IS NOT NULL
THEN (v_line_item_mapping->>v_old_task.line_item_id::text)::uuid
ELSE NULL
END,
v_old_task.source_default_task_id,
v_old_task.title,
v_old_task.description,
v_old_task.labor_phase_id,
v_old_task.sort_order,
v_old_task.organization_id,
v_old_task.created_by,
v_old_task.created_at,
v_old_task.updated_at
);
END LOOP;

-- Copy proposal settings
INSERT INTO proposal_settings (
proposal_id, contract_id, payment_terms_type, deposit_percent, deposit_amount,
deposit_type, payment_schedule, project_management_percent, project_design_percent,
system_design_percent, credit_card_fee_percent, misc_parts_percent, discount_percent,
custom_modifier_1_label, custom_modifier_1_percent, custom_modifier_2_label,
custom_modifier_2_percent, selected_areas, acceptance_methods, require_deposit,
scope_of_work, show_scope_in_pdf, show_contract_in_pdf, show_deposit_in_pdf,
show_classes_in_builder, show_classes_in_pdf, class_display_mode, show_class_summary_page
)
SELECT
v_new_proposal_id, contract_id, payment_terms_type, deposit_percent, deposit_amount,
deposit_type, payment_schedule, project_management_percent, project_design_percent,
system_design_percent, credit_card_fee_percent, misc_parts_percent, discount_percent,
custom_modifier_1_label, custom_modifier_1_percent, custom_modifier_2_label,
custom_modifier_2_percent, selected_areas, acceptance_methods, require_deposit,
scope_of_work, show_scope_in_pdf, show_contract_in_pdf, show_deposit_in_pdf,
show_classes_in_builder, show_classes_in_pdf, class_display_mode, show_class_summary_page
FROM proposal_settings
WHERE proposal_id = p_proposal_id;

RETURN v_new_proposal_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_proposal_version(p_proposal_id uuid, p_changed_by uuid, p_change_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_version_number integer;
v_snapshot jsonb;
v_version_id uuid;
BEGIN
-- Get next version number
SELECT COALESCE(MAX(version_number), 0) + 1
INTO v_version_number
FROM proposal_versions
WHERE proposal_id = p_proposal_id;

-- Build snapshot (complete proposal data)
SELECT jsonb_build_object(
'proposal', row_to_json(p.*),
'rooms', (
SELECT jsonb_agg(
jsonb_build_object(
'room', row_to_json(r.*),
'line_items', (
SELECT jsonb_agg(row_to_json(li.*) ORDER BY li.sort_order)
FROM proposal_line_items li
WHERE li.room_id = r.id
)
) ORDER BY r.sort_order
)
FROM proposal_rooms r
WHERE r.proposal_id = p.id
)
)
INTO v_snapshot
FROM proposals p
WHERE p.id = p_proposal_id;

-- Insert version
INSERT INTO proposal_versions (
proposal_id,
version_number,
snapshot_data,
changed_by,
change_description
)
VALUES (
p_proposal_id,
v_version_number,
v_snapshot,
p_changed_by,
p_change_description
)
RETURNING id INTO v_version_id;

RETURN v_version_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_sales_order_from_proposal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sales_order_id uuid;
v_order_number text;
v_sales_order_status text;
v_require_deposit boolean;
v_acceptance_methods text[];
BEGIN
-- Only process if status changed to 'approved' and no sales order exists yet
IF NEW.status = 'approved' AND OLD.status != 'approved' AND NEW.sales_order_id IS NULL THEN

-- Get proposal-level acceptance requirements from proposal settings
SELECT
COALESCE(NEW.require_deposit, ps.require_deposit, true),
COALESCE(NEW.acceptance_methods, ps.acceptance_methods, ARRAY['payment']::text[])
INTO v_require_deposit, v_acceptance_methods
FROM proposal_settings ps
WHERE ps.proposal_id = NEW.id
LIMIT 1;

-- If no proposal_settings found, use values from proposal or defaults
IF v_require_deposit IS NULL THEN
v_require_deposit := COALESCE(NEW.require_deposit, true);
v_acceptance_methods := COALESCE(NEW.acceptance_methods, ARRAY['payment']::text[]);
END IF;

-- Determine sales order status based on deposit requirements and payment status
IF v_require_deposit AND NOT COALESCE(NEW.deposit_paid, false) THEN
-- Deposit required but not paid yet
v_sales_order_status := 'pending_deposit';

-- Set deposit_request_sent flag if not already set
IF NOT COALESCE(NEW.deposit_request_sent, false) THEN
NEW.deposit_request_sent := true;
NEW.deposit_request_sent_at := now();
END IF;
ELSE
-- No deposit required, or deposit already paid
v_sales_order_status := 'planning';
END IF;

-- Generate sales order number from proposal number
v_order_number := generate_sales_order_number(NEW.proposal_number);

-- Set approval timestamp if not already set
IF NEW.approval_completed_at IS NULL THEN
NEW.approval_completed_at := now();
END IF;

-- Create the sales order
INSERT INTO sales_orders (
company_id,
proposal_id,
contact_id,
order_number,
status,
contract_total,
payment_terms,
notes,
created_by,
created_at,
updated_at
) VALUES (
NEW.company_id,
NEW.id,
NEW.contact_id,
v_order_number,
v_sales_order_status,
NEW.total,
'Net 30',
CASE
WHEN v_sales_order_status = 'pending_deposit' THEN
'Converted from proposal ' || NEW.proposal_number || ' - Awaiting deposit payment'
ELSE
'Converted from proposal ' || NEW.proposal_number
END,
NEW.approved_by,
now(),
now()
)
RETURNING id INTO v_sales_order_id;

-- Link sales order back to proposal
NEW.sales_order_id := v_sales_order_id;

-- Create notification for sales rep (the proposal creator)
IF NEW.approved_by IS DISTINCT FROM NEW.created_by THEN
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id,
created_at
) VALUES (
NEW.created_by,
'proposal_approved',
CASE
WHEN v_sales_order_status = 'pending_deposit' THEN 'Proposal Approved - Deposit Pending'
ELSE 'Proposal Approved'
END,
'Proposal ' || NEW.proposal_number || ' has been approved and converted to Sales Order ' || v_order_number ||
CASE
WHEN v_sales_order_status = 'pending_deposit' THEN ' (awaiting deposit payment)'
ELSE ''
END,
NEW.id,
now()
);
END IF;

END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_subscription_from_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
template_record RECORD;
contact_record RECORD;
new_subscription_id uuid;
BEGIN
-- Only run when status changes to 'active' and subscription doesn't exist
IF NEW.status = 'active' AND OLD.status != 'active' AND NEW.subscription_id IS NULL THEN

-- Get template details
SELECT * INTO template_record
FROM security_contract_templates
WHERE id = NEW.template_id;

-- Only proceed if auto-create is enabled and plan is set
IF template_record.auto_create_subscription AND template_record.default_billing_plan_id IS NOT NULL THEN

-- Get contact details
SELECT * INTO contact_record
FROM contacts
WHERE id = NEW.contact_id;

-- Create the subscription
INSERT INTO recurring_subscriptions (
contact_id,
plan_id,
status,
start_date,
next_billing_date,
billing_cycle,
created_by_user_id,
notes
)
SELECT
NEW.contact_id,
template_record.default_billing_plan_id,
'active',
CURRENT_DATE,
CURRENT_DATE + (rp.billing_frequency || ' ' || rp.billing_period)::interval,
rp.billing_frequency || ' ' || rp.billing_period,
NEW.approved_by_user_id,
'Auto-created from Security Contract: ' || NEW.contract_number
FROM recurring_plans rp
WHERE rp.id = template_record.default_billing_plan_id
RETURNING id INTO new_subscription_id;

-- Link subscription to contract
NEW.subscription_id := new_subscription_id;
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_task_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF TG_OP = 'INSERT' THEN
INSERT INTO feed_events (
event_type,
user_id,
task_id,
lead_id,
metadata
) VALUES (
'task_created',
NEW.user_id,  -- Fixed: was NEW.created_by
NEW.id,
NEW.lead_id,
jsonb_build_object(
'title', NEW.title,
'status', NEW.status
)
);
ELSIF TG_OP = 'UPDATE' THEN
-- Track completion
IF OLD.status != 'completed' AND NEW.status = 'completed' THEN
INSERT INTO feed_events (
event_type,
user_id,
task_id,
lead_id,
metadata
) VALUES (
'task_completed',
auth.uid(),
NEW.id,
NEW.lead_id,
jsonb_build_object(
'title', NEW.title
)
);
-- Track other updates
ELSIF (OLD.title IS DISTINCT FROM NEW.title OR
OLD.description IS DISTINCT FROM NEW.description OR
OLD.due_date IS DISTINCT FROM NEW.due_date OR
OLD.status IS DISTINCT FROM NEW.status) THEN
INSERT INTO feed_events (
event_type,
user_id,
task_id,
lead_id,
metadata
) VALUES (
'task_updated',
auth.uid(),
NEW.id,
NEW.lead_id,
jsonb_build_object(
'title', NEW.title,
'old_status', OLD.status,
'new_status', NEW.status
)
);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_travel_bonus_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_tech_record          RECORD;
v_office_settings      RECORD;
v_office_location      RECORD;
v_work_order           RECORD;
v_prior_job            RECORD;
v_from_lat             decimal;
v_from_lon             decimal;
v_from_address         text;
v_from_type            text;
v_distance_miles       decimal;
v_eligible_miles       decimal;
v_bonus_amount         decimal;
v_rate                 decimal;
v_method               text;
v_daily_clock_id       uuid;
v_window_hours         numeric;
BEGIN
-- Only process when a work order time entry is created (clock-in)
-- NEW.clock_out will be NULL on insert (just clocked in)
-- Must have a work_order_id to calculate travel
IF NEW.work_order_id IS NULL THEN
RETURN NEW;
END IF;

-- Only fire on INSERT (fresh clock-in)
-- Skip if this is somehow an update
IF TG_OP != 'INSERT' THEN
RETURN NEW;
END IF;

-- Get tech record with travel bonus settings
SELECT * INTO v_tech_record
FROM profiles
WHERE id = NEW.technician_id
AND travel_bonus_enabled = true;

IF NOT FOUND THEN
RETURN NEW;
END IF;

-- Get work order details (need GPS coordinates of the destination)
SELECT * INTO v_work_order
FROM work_orders
WHERE id = NEW.work_order_id;

IF NOT FOUND THEN
RETURN NEW;
END IF;

-- Skip if work order has no GPS coordinates (can't calculate distance)
IF v_work_order.latitude IS NULL OR v_work_order.longitude IS NULL
OR v_work_order.latitude = 0 OR v_work_order.longitude = 0 THEN
RETURN NEW;
END IF;

-- Get the tech's home office location
SELECT
co.id,
COALESCE(co.latitude, 0)  AS latitude,
COALESCE(co.longitude, 0) AS longitude,
co.office_name,
co.city,
co.state
INTO v_office_location
FROM company_offices co
WHERE co.id = COALESCE(v_tech_record.primary_office_id, v_work_order.office_id);

IF NOT FOUND OR v_office_location.latitude = 0 OR v_office_location.longitude = 0 THEN
RETURN NEW;
END IF;

-- Get (or create) office travel settings
SELECT * INTO v_office_settings
FROM office_travel_settings
WHERE office_id = v_office_location.id;

IF NOT FOUND THEN
INSERT INTO office_travel_settings (office_id)
VALUES (v_office_location.id)
RETURNING * INTO v_office_settings;
END IF;

v_rate         := COALESCE(v_tech_record.travel_bonus_rate, v_office_settings.default_rate_per_mile, 0.50);
v_method       := COALESCE(v_tech_record.travel_bonus_method, v_office_settings.calculation_method, 'round_trip');
v_window_hours := COALESCE(v_office_settings.same_day_job_window_hours, 4.0);

-- ----------------------------------------------------------------
-- Determine trip origin: previous job vs. home office
-- Look for the most recent clock-out on a DIFFERENT work order
-- for this tech on the same calendar day, within the window.
-- ----------------------------------------------------------------
SELECT
te.id,
wo.latitude   AS lat,
wo.longitude  AS lon,
wo.address    AS addr
INTO v_prior_job
FROM time_entries te
JOIN work_orders wo ON wo.id = te.work_order_id
WHERE te.technician_id  = NEW.technician_id
AND te.work_order_id != NEW.work_order_id
AND te.clock_out IS NOT NULL
-- same calendar day as the new clock-in
AND DATE(te.clock_out AT TIME ZONE 'UTC') = DATE(NEW.clock_in AT TIME ZONE 'UTC')
-- clock-out must be within the window before this clock-in
AND te.clock_out >= (NEW.clock_in - (v_window_hours || ' hours')::interval)
AND te.clock_out <= NEW.clock_in
-- prior job must also have GPS coordinates
AND wo.latitude  IS NOT NULL
AND wo.longitude IS NOT NULL
AND wo.latitude  != 0
AND wo.longitude != 0
ORDER BY te.clock_out DESC
LIMIT 1;

IF FOUND AND v_prior_job.lat IS NOT NULL AND v_prior_job.lon IS NOT NULL THEN
-- Tech is coming from a prior job site — point-to-point, no radius deduction
v_from_lat     := v_prior_job.lat;
v_from_lon     := v_prior_job.lon;
v_from_address := COALESCE(v_prior_job.addr, 'Previous Job Site');
v_from_type    := 'previous_job';
-- Job-to-job is always one-way (we don't know the return yet)
v_method       := 'one_way';
ELSE
-- Tech is coming from the home office
v_from_lat     := v_office_location.latitude;
v_from_lon     := v_office_location.longitude;
v_from_address := TRIM(
COALESCE(v_office_location.office_name, '') || ' - ' ||
COALESCE(v_office_location.city, '') || ', ' ||
COALESCE(v_office_location.state, '')
);
v_from_type    := 'office';
END IF;

-- ----------------------------------------------------------------
-- Calculate distance from origin to job site
-- ----------------------------------------------------------------
v_distance_miles := calculate_distance_miles(
v_from_lat,
v_from_lon,
v_work_order.latitude,
v_work_order.longitude
);

IF v_distance_miles = 0 THEN
RETURN NEW;
END IF;

-- Apply round-trip multiplier only when departing from office
IF v_from_type = 'office' AND v_method = 'round_trip' THEN
v_distance_miles := v_distance_miles * 2;
END IF;

-- Calculate eligible miles
-- Radius bubble only applies when departing from office
IF v_from_type = 'office' THEN
IF v_method = 'round_trip' THEN
v_eligible_miles := GREATEST(0, v_distance_miles - (v_office_settings.radius_miles * 2));
ELSE
v_eligible_miles := GREATEST(0, v_distance_miles - v_office_settings.radius_miles);
END IF;
ELSE
-- Job-to-job: full distance is eligible (no radius deduction)
v_eligible_miles := v_distance_miles;
END IF;

v_bonus_amount := v_eligible_miles * v_rate;

IF v_eligible_miles <= 0 OR v_bonus_amount <= 0 THEN
RETURN NEW;
END IF;

-- Get today's daily clock entry
SELECT id INTO v_daily_clock_id
FROM daily_clock_entries
WHERE technician_id = NEW.technician_id
AND entry_date = DATE(NEW.clock_in AT TIME ZONE 'UTC')
LIMIT 1;

-- Insert the bonus request; skip silently if duplicate (same tech + work order)
INSERT INTO travel_bonus_requests (
technician_id,
work_order_id,
daily_clock_entry_id,
office_id,
from_type,
from_address,
from_latitude,
from_longitude,
job_address,
job_latitude,
job_longitude,
office_latitude,
office_longitude,
total_distance_miles,
eligible_miles,
rate_per_mile,
bonus_amount,
calculation_method,
status
) VALUES (
NEW.technician_id,
NEW.work_order_id,
v_daily_clock_id,
v_office_location.id,
v_from_type,
v_from_address,
v_from_lat,
v_from_lon,
COALESCE(v_work_order.address, 'Unknown'),
v_work_order.latitude,
v_work_order.longitude,
v_from_lat,           -- keep office_lat/lon pointing at the actual origin
v_from_lon,
v_distance_miles,
v_eligible_miles,
v_rate,
v_bonus_amount,
v_method,
CASE
WHEN v_office_settings.auto_approve_under_amount IS NOT NULL
AND v_bonus_amount <= v_office_settings.auto_approve_under_amount
THEN 'approved'
ELSE 'pending'
END
)
ON CONFLICT (technician_id, work_order_id) DO NOTHING;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_vip_work_order_from_appointment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_subscription RECORD;
v_plan RECORD;
v_work_order_id uuid;
v_scheduled_datetime timestamptz;
BEGIN
-- Only proceed if appointment has a subscription
IF NEW.recurring_subscription_id IS NULL THEN
RETURN NEW;
END IF;

-- Get subscription and plan details
SELECT s.*, p.plan_type
INTO v_subscription
FROM recurring_subscriptions s
JOIN recurring_plans p ON p.id = s.plan_id
WHERE s.id = NEW.recurring_subscription_id;

-- Only create work order if subscription exists and is for VIP program
IF NOT FOUND OR v_subscription.plan_type != 'vip_program' THEN
RETURN NEW;
END IF;

-- Check if subscription is active
IF v_subscription.status NOT IN ('active') THEN
RETURN NEW;
END IF;

-- Check if work order already exists for this appointment
IF EXISTS (
SELECT 1 FROM work_orders
WHERE appointment_id = NEW.id
) THEN
RETURN NEW;
END IF;

-- Combine appointment date and start time to create scheduled datetime
v_scheduled_datetime := (NEW.appointment_date || ' ' || NEW.start_time)::timestamptz;

-- Create the work order
INSERT INTO work_orders (
company_id,
work_order_number,
type,
contact_id,
description,
scheduled_date,
priority,
status,
assigned_to,
recurring_subscription_id,
appointment_id,
billable_type,
send_appointment_reminder,
reminder_email,
created_by
) VALUES (
NEW.company_id,
'WO-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LPAD(FLOOR(RANDOM() * 10000)::TEXT, 4, '0'),
'vip_program',
NEW.contact_id,
COALESCE(NEW.description, NEW.title || ' - VIP Program Visit'),
v_scheduled_datetime,
'medium',
'scheduled',
NEW.assigned_technician,
NEW.recurring_subscription_id,
NEW.id,
'billable',
NEW.send_appointment_reminder,
NEW.reminder_email,
NEW.created_by
) RETURNING id INTO v_work_order_id;

-- Log the creation
RAISE NOTICE 'Created VIP work order % for appointment %', v_work_order_id, NEW.id;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.create_work_order_from_vip_appointment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_subscription RECORD;
v_plan RECORD;
v_work_order_id uuid;
v_work_order_number text;
BEGIN
-- Only process if appointment has a recurring_subscription_id
IF NEW.recurring_subscription_id IS NULL THEN
RETURN NEW;
END IF;

-- Get subscription details
SELECT * INTO v_subscription
FROM recurring_subscriptions
WHERE id = NEW.recurring_subscription_id;

-- If subscription not found, return
IF NOT FOUND THEN
RETURN NEW;
END IF;

-- Get plan details
SELECT * INTO v_plan
FROM recurring_plans
WHERE id = v_subscription.plan_id;

-- Only create work orders for VIP plans
IF NOT FOUND OR v_plan.plan_type != 'vip' THEN
RETURN NEW;
END IF;

-- Generate work order number
v_work_order_number := 'WO-' || to_char(NEW.appointment_date, 'YYYYMMDD') || '-' || 
substring(gen_random_uuid()::text, 1, 8);

-- Create the work order
INSERT INTO work_orders (
company_id,
contact_id,
type,
status,
priority,
work_order_number,
description,
scheduled_date,
scheduled_start_time,
scheduled_end_time,
location_address,
billable_type,
recurring_subscription_id,
appointment_id,
send_appointment_reminder,
reminder_email,
reminder_sms,
created_at
) VALUES (
NEW.company_id,
NEW.contact_id,
'vip_program',
'scheduled',
'medium',
v_work_order_number,
COALESCE(
v_plan.name || ' - ' || COALESCE(v_plan.description, ''),
NEW.title || ' - VIP Service'
),
NEW.appointment_date,
NEW.start_time,
NEW.end_time,
NEW.location,
'billable',
NEW.recurring_subscription_id,
NEW.id,
NEW.send_reminder,
true,
NEW.send_reminder,
now()
)
RETURNING id INTO v_work_order_id;

RAISE NOTICE 'Created VIP work order % for appointment %', v_work_order_number, NEW.id;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.current_user_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT auth.uid();
$function$


CREATE OR REPLACE FUNCTION public.decline_punchlist_invite(p_invite_id uuid, p_decline_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE pending_punchlist_invites
SET 
status = 'declined',
reviewed_by = auth.uid(),
reviewed_at = now(),
decline_reason = p_decline_reason
WHERE id = p_invite_id
AND status = 'pending';

IF NOT FOUND THEN
RAISE EXCEPTION 'Invite not found or already processed';
END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.deduct_manual_entry_points()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_points_to_deduct integer;
BEGIN
-- Only process if this is a manual entry that should deduct points
IF NEW.admin_adjusted = true AND NEW.deduct_points = true AND NEW.points_deducted = 0 THEN
-- Get the configured points loss amount
SELECT manual_entry_points_loss INTO v_points_to_deduct
FROM points_configuration
LIMIT 1;

-- Default to 10 if no configuration exists
IF v_points_to_deduct IS NULL THEN
v_points_to_deduct := 10;
END IF;

-- Record the points deducted
NEW.points_deducted := v_points_to_deduct;

-- Deduct points from the technician's profile
UPDATE profiles
SET points_earned = GREATEST(0, points_earned - v_points_to_deduct)
WHERE id = NEW.technician_id;

-- Create a points transaction record
INSERT INTO points_transactions (
user_id,
points_amount,
transaction_type,
reference_id,
description
) VALUES (
NEW.technician_id,
-v_points_to_deduct,
'admin_adjustment',
NEW.id,
'Points deducted for manual time entry: ' || COALESCE(NEW.adjustment_reason, 'No reason provided')
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.deduct_same_day_callin_points()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_cutoff_time time;
v_points_loss integer;
v_current_time time;
v_policy_type text;
v_is_same_day boolean := false;
BEGIN
-- Only process new pending requests
IF NEW.status <> 'pending' THEN
RETURN NEW;
END IF;

-- Get the PTO policy type
SELECT pto_type INTO v_policy_type
FROM pto_policies
WHERE id = NEW.policy_id;

-- Bereavement and jury duty are exempt from same-day penalties
IF v_policy_type IN ('bereavement', 'jury_duty', 'unpaid') THEN
RETURN NEW;
END IF;

-- Check if this is a same-day call-in
IF NEW.start_date = CURRENT_DATE THEN
v_is_same_day := true;
NEW.is_same_day_callin := true;

-- Get cutoff time and points loss from company settings
SELECT
pto_same_day_callin_cutoff_time,
pto_same_day_callin_points_loss
INTO v_cutoff_time, v_points_loss
FROM company_settings
LIMIT 1;

-- Defaults if no settings row
IF v_cutoff_time IS NULL THEN
v_cutoff_time := '07:00:00';
END IF;
IF v_points_loss IS NULL THEN
v_points_loss := 10;
END IF;

-- Get current time (timezone-aware)
v_current_time := (now() AT TIME ZONE 'America/Chicago')::time;

-- Only deduct points if submitted after the cutoff time
IF v_current_time > v_cutoff_time THEN
NEW.points_deducted := v_points_loss;

-- Deduct from the employee's rewards balance
UPDATE profiles
SET points_earned = GREATEST(0, COALESCE(points_earned, 0) - v_points_loss)
WHERE id = NEW.employee_id;

-- Record the transaction
INSERT INTO points_transactions (
user_id,
points_amount,
transaction_type,
reference_id,
description
) VALUES (
NEW.employee_id,
-v_points_loss,
'admin_adjustment',
NEW.id,
'Points deducted for same-day ' || v_policy_type || ' call-in'
);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.determine_segment_jurisdiction(p_segment_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_seg record;
v_job_state text;
v_phys_state text;
v_result json;
v_org_id uuid;
v_default_state text;
v_office_state text;
BEGIN
SELECT pts.* INTO v_seg
FROM payroll_time_segments pts
WHERE pts.id = p_segment_id;

IF NOT FOUND THEN
RETURN json_build_object('error', 'segment not found');
END IF;

v_org_id := v_seg.organization_id;
v_phys_state := v_seg.physical_work_location_state;

-- 1. Manual override takes precedence
IF v_seg.work_jurisdiction_source = 'manual_override' AND v_seg.work_jurisdiction_state IS NOT NULL THEN
RETURN json_build_object(
'jurisdiction_state', v_seg.work_jurisdiction_state,
'jurisdiction_source', 'manual_override',
'confidence', 'high',
'gps_validated', v_seg.gps_validated,
'physical_work_location_state', v_phys_state
);
END IF;

-- Determine job state
IF v_seg.work_order_id IS NOT NULL THEN
SELECT wo.job_state INTO v_job_state
FROM work_orders wo
WHERE wo.id = v_seg.work_order_id;
ELSIF v_seg.project_id IS NOT NULL THEN
SELECT p.job_state INTO v_job_state
FROM projects p
WHERE p.id = v_seg.project_id;
END IF;

-- Get tenant default jurisdiction state
SELECT cs.default_jurisdiction_state INTO v_default_state
FROM company_settings cs
WHERE cs.organization_id = v_org_id;

-- 2. GPS/job mismatch (Revision 2)
IF v_phys_state IS NOT NULL AND v_job_state IS NOT NULL AND UPPER(v_phys_state) != UPPER(v_job_state) THEN
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', 'gps_job_mismatch',
'confidence', 'low',
'gps_validated', false,
'physical_work_location_state', v_phys_state,
'job_state', v_job_state,
'needs_review', true
);
END IF;

-- 3. GPS-validated match
IF v_phys_state IS NOT NULL AND v_job_state IS NOT NULL AND UPPER(v_phys_state) = UPPER(v_job_state) THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_job_state),
'jurisdiction_source', 'gps_validated',
'confidence', 'high',
'gps_validated', true,
'physical_work_location_state', v_phys_state
);
END IF;

-- Non-job time types
IF v_seg.time_type IN ('training', 'shop_admin', 'pto', 'travel') THEN
-- Check for linked company office
IF v_seg.daily_clock_entry_id IS NOT NULL THEN
SELECT co.state INTO v_office_state
FROM daily_clock_entries dce
LEFT JOIN company_offices co ON co.id = dce.office_id
WHERE dce.id = v_seg.daily_clock_entry_id
AND co.state IS NOT NULL;
END IF;

IF v_office_state IS NOT NULL AND v_seg.time_type IN ('training', 'shop_admin') THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_office_state),
'jurisdiction_source', 'exception_rule',
'confidence', 'high',
'gps_validated', null,
'physical_work_location_state', v_phys_state
);
END IF;

-- Remote admin/training: use physical location if known
IF v_phys_state IS NOT NULL AND v_seg.time_type IN ('training', 'shop_admin') THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_phys_state),
'jurisdiction_source', 'exception_rule',
'confidence', 'medium',
'gps_validated', null,
'physical_work_location_state', v_phys_state
);
END IF;

-- PTO: never use GPS (Revision 1)
-- Travel: extensible, mark for review (Revision 1)
-- All others that can't be reliably determined
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', 'exception_rule',
'confidence', 'unassigned',
'gps_validated', null,
'physical_work_location_state', CASE WHEN v_seg.time_type = 'pto' THEN null ELSE v_phys_state END,
'needs_review', true
);
END IF;

-- 5. Job default (no GPS) — medium confidence, flagged for review
IF v_job_state IS NOT NULL THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_job_state),
'jurisdiction_source', 'job_default',
'confidence', 'medium',
'gps_validated', null,
'physical_work_location_state', v_phys_state,
'needs_review', true
);
END IF;

-- 6. No job, no GPS — unassigned
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', null,
'confidence', 'unassigned',
'gps_validated', null,
'physical_work_location_state', v_phys_state,
'needs_review', true
);
END;
$function$


CREATE OR REPLACE FUNCTION public.determine_work_jurisdiction(p_time_entry_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_entry record;
v_job_state text;
v_phys_state text;
v_result json;
v_org_id uuid;
v_session_type text;
v_office_state text;
v_default_state text;
v_entry_type text;
BEGIN
-- Load the time entry
SELECT te.* INTO v_entry
FROM time_entries te
WHERE te.id = p_time_entry_id;

IF NOT FOUND THEN
RETURN json_build_object('error', 'time entry not found');
END IF;

v_org_id := v_entry.organization_id;
v_phys_state := v_entry.physical_work_location_state;
v_entry_type := v_entry.entry_type;

-- 1. Manual override takes precedence
IF v_entry.work_jurisdiction_source = 'manual_override' AND v_entry.work_jurisdiction_state IS NOT NULL THEN
RETURN json_build_object(
'jurisdiction_state', v_entry.work_jurisdiction_state,
'jurisdiction_source', 'manual_override',
'confidence', 'high',
'gps_validated', v_entry.gps_validated,
'physical_work_location_state', v_phys_state
);
END IF;

-- Determine job state from linked work_order or project
IF v_entry.work_order_id IS NOT NULL THEN
SELECT wo.job_state INTO v_job_state
FROM work_orders wo
WHERE wo.id = v_entry.work_order_id;
ELSIF v_entry.project_id IS NOT NULL THEN
SELECT p.job_state INTO v_job_state
FROM projects p
WHERE p.id = v_entry.project_id;
END IF;

-- Check if this is a non-job time type (training, shop/admin via internal_session_id)
IF v_entry.internal_session_id IS NOT NULL THEN
SELECT session_type INTO v_session_type
FROM internal_time_sessions
WHERE id = v_entry.internal_session_id;
END IF;

-- Get tenant default jurisdiction state
SELECT cs.default_jurisdiction_state INTO v_default_state
FROM company_settings cs
WHERE cs.organization_id = v_org_id;

-- 2. GPS/job mismatch (Revision 2: preserve both, require review)
IF v_phys_state IS NOT NULL AND v_job_state IS NOT NULL AND UPPER(v_phys_state) != UPPER(v_job_state) THEN
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', 'gps_job_mismatch',
'confidence', 'low',
'gps_validated', false,
'physical_work_location_state', v_phys_state,
'job_state', v_job_state,
'needs_review', true
);
END IF;

-- 3. GPS-validated match
IF v_phys_state IS NOT NULL AND v_job_state IS NOT NULL AND UPPER(v_phys_state) = UPPER(v_job_state) THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_job_state),
'jurisdiction_source', 'gps_validated',
'confidence', 'high',
'gps_validated', true,
'physical_work_location_state', v_phys_state
);
END IF;

-- 4. Non-job time types (Revision 1)
-- Training: use configured location if known (from internal_time_sessions)
IF v_entry_type = 'training' OR v_session_type = 'training' THEN
-- Check if linked to a company office with a state
IF v_entry.internal_session_id IS NOT NULL THEN
SELECT co.state INTO v_office_state
FROM internal_time_sessions its
LEFT JOIN company_offices co ON co.id = its.office_id
WHERE its.id = v_entry.internal_session_id
AND co.state IS NOT NULL;
END IF;

IF v_office_state IS NOT NULL THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_office_state),
'jurisdiction_source', 'exception_rule',
'confidence', 'high',
'gps_validated', null,
'physical_work_location_state', v_phys_state
);
END IF;

-- If employee's physical location is known (remote training), use it
IF v_phys_state IS NOT NULL THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_phys_state),
'jurisdiction_source', 'exception_rule',
'confidence', 'medium',
'gps_validated', null,
'physical_work_location_state', v_phys_state
);
END IF;

-- Cannot reliably determine — mark for review
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', 'exception_rule',
'confidence', 'unassigned',
'gps_validated', null,
'physical_work_location_state', null,
'needs_review', true
);
END IF;

-- Shop/admin time
IF v_session_type = 'shop_time' OR v_entry_type = 'shop_admin' THEN
-- Check if linked to a company office with a state
IF v_entry.internal_session_id IS NOT NULL THEN
SELECT co.state INTO v_office_state
FROM internal_time_sessions its
LEFT JOIN company_offices co ON co.id = its.office_id
WHERE its.id = v_entry.internal_session_id
AND co.state IS NOT NULL;
END IF;

IF v_office_state IS NOT NULL THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_office_state),
'jurisdiction_source', 'exception_rule',
'confidence', 'high',
'gps_validated', null,
'physical_work_location_state', v_phys_state
);
END IF;

-- Remote admin: use employee's physical location if known
IF v_phys_state IS NOT NULL THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_phys_state),
'jurisdiction_source', 'exception_rule',
'confidence', 'medium',
'gps_validated', null,
'physical_work_location_state', v_phys_state
);
END IF;

-- Cannot reliably determine — mark for review
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', 'exception_rule',
'confidence', 'unassigned',
'gps_validated', null,
'physical_work_location_state', null,
'needs_review', true
);
END IF;

-- PTO: do NOT use GPS to establish physical work location (Revision 1)
IF v_entry_type = 'pto' OR v_session_type = 'pto' THEN
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', 'exception_rule',
'confidence', 'unassigned',
'gps_validated', null,
'physical_work_location_state', null,
'needs_review', true,
'note', 'PTO is paid leave — jurisdiction requires tenant configuration or admin decision'
);
END IF;

-- Travel: extensible, may cross jurisdictions — mark for review (Revision 1)
IF v_entry_type = 'travel' OR v_session_type = 'travel' THEN
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', 'exception_rule',
'confidence', 'unassigned',
'gps_validated', null,
'physical_work_location_state', v_phys_state,
'needs_review', true,
'note', 'Travel may cross jurisdictions — requires tenant-configured rules or admin decision'
);
END IF;

-- 5. Job default (no GPS) — medium confidence, flagged for review
IF v_job_state IS NOT NULL THEN
RETURN json_build_object(
'jurisdiction_state', UPPER(v_job_state),
'jurisdiction_source', 'job_default',
'confidence', 'medium',
'gps_validated', null,
'physical_work_location_state', v_phys_state,
'needs_review', true
);
END IF;

-- 6. No job, no GPS, no location info — unassigned (blocks payroll)
RETURN json_build_object(
'jurisdiction_state', null,
'jurisdiction_source', null,
'confidence', 'unassigned',
'gps_validated', null,
'physical_work_location_state', v_phys_state,
'needs_review', true
);
END;
$function$


CREATE OR REPLACE FUNCTION public.duplicate_work_order_to_technician(p_source_work_order_id uuid, p_target_technician_id uuid, p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_source_wo work_orders%ROWTYPE;
v_new_wo_id uuid;
v_group_id uuid;
BEGIN
-- Get the source work order
SELECT * INTO v_source_wo
FROM work_orders
WHERE id = p_source_work_order_id;

IF v_source_wo IS NULL THEN
RAISE EXCEPTION 'Source work order not found';
END IF;

-- Generate new ID
v_new_wo_id := gen_random_uuid();

-- Determine group_id for linking
IF v_source_wo.work_order_group_id IS NOT NULL THEN
-- Use existing group_id
v_group_id := v_source_wo.work_order_group_id;
ELSE
-- Create a new group_id and update source work order
v_group_id := gen_random_uuid();
UPDATE work_orders
SET work_order_group_id = v_group_id
WHERE id = p_source_work_order_id;
END IF;

-- Create the duplicate work order
INSERT INTO work_orders (
id,
company_id,
contact_id,
project_id,
work_order_group_id,
title,
description,
type,
is_billable,
billable_type,
warranty_reference_type,
warranty_reference_id,
priority,
status,
assigned_to,
start_date,
target_completion_date,
estimated_hours,
notes,
internal_notes,
send_appointment_reminder,
reminder_email,
reminder_sms,
created_by,
office_id
) VALUES (
v_new_wo_id,
v_source_wo.company_id,
v_source_wo.contact_id,
v_source_wo.project_id,
v_group_id, -- Link to group
v_source_wo.title,
v_source_wo.description,
v_source_wo.type,
v_source_wo.is_billable,
v_source_wo.billable_type,
v_source_wo.warranty_reference_type,
v_source_wo.warranty_reference_id,
v_source_wo.priority,
'assigned', -- New work order is assigned
p_target_technician_id, -- Assign to target technician
v_source_wo.start_date,
v_source_wo.target_completion_date,
v_source_wo.estimated_hours,
v_source_wo.notes,
v_source_wo.internal_notes,
v_source_wo.send_appointment_reminder,
v_source_wo.reminder_email,
v_source_wo.reminder_sms,
p_user_id,
v_source_wo.office_id
);

RETURN v_new_wo_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.end_user_session(p_user_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF p_session_id IS NOT NULL THEN
-- Only close this specific session
UPDATE user_sessions
SET
is_active = false,
session_end = now()
WHERE id = p_session_id
AND is_active = true;
END IF;
-- If only p_user_id is provided with no session_id, do nothing
-- (prevents accidental bulk-close of all sessions)
END;
$function$


CREATE OR REPLACE FUNCTION public.enforce_appointment_scheduling_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
caller_role TEXT;
bypass_guard TEXT;
BEGIN
bypass_guard := current_setting('app.bypass_scheduling_guard', true);
IF bypass_guard = 'true' THEN
RETURN NEW;
END IF;

IF (NEW.appointment_date IS DISTINCT FROM OLD.appointment_date)
OR (NEW.start_time IS DISTINCT FROM OLD.start_time)
OR (NEW.end_time IS DISTINCT FROM OLD.end_time)
OR (NEW.assigned_technician IS DISTINCT FROM OLD.assigned_technician) THEN

SELECT role INTO caller_role
FROM profiles
WHERE id = auth.uid();

IF caller_role IS NULL THEN
RAISE EXCEPTION 'Permission denied: unable to verify user role for scheduling changes';
END IF;

IF caller_role NOT IN ('admin', 'manager', 'service_manager') THEN
RAISE EXCEPTION 'Permission denied: only admin, manager, or service_manager can modify scheduling fields';
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.enforce_customer_location_default()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.is_default = true and new.is_active = true then
    update customer_locations set is_default = false where customer_contact_id = new.customer_contact_id and id <> new.id and is_default = true;
  end if;
  return new;
end;
$function$


CREATE OR REPLACE FUNCTION public.enforce_single_default_calendar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.is_default = true THEN
-- Unset all other default calendars for this user
UPDATE calendar_members
SET is_default = false
WHERE user_id = NEW.user_id
AND calendar_id != NEW.calendar_id
AND is_default = true;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.enforce_work_order_scheduling_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
caller_role TEXT;
bypass_guard TEXT;
BEGIN
-- Check if bypass is set (used by SECURITY DEFINER functions)
bypass_guard := current_setting('app.bypass_scheduling_guard', true);
IF bypass_guard = 'true' THEN
RETURN NEW;
END IF;

-- Only check if scheduling columns are actually being changed
IF (NEW.scheduled_date IS DISTINCT FROM OLD.scheduled_date)
OR (NEW.scheduled_start_time IS DISTINCT FROM OLD.scheduled_start_time)
OR (NEW.scheduled_end_time IS DISTINCT FROM OLD.scheduled_end_time)
OR (NEW.assigned_to IS DISTINCT FROM OLD.assigned_to) THEN

-- Get caller's role
SELECT role INTO caller_role
FROM profiles
WHERE id = auth.uid();

IF caller_role IS NULL THEN
RAISE EXCEPTION 'Permission denied: unable to verify user role for scheduling changes';
END IF;

IF caller_role NOT IN ('admin', 'manager', 'service_manager') THEN
RAISE EXCEPTION 'Permission denied: only admin, manager, or service_manager can modify scheduling fields';
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.enroll_in_workflow(p_workflow_id uuid, p_contact_id uuid DEFAULT NULL::uuid, p_lead_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_enrollment_id UUID; v_first_step RECORD;
BEGIN
SELECT * INTO v_first_step FROM email_workflow_steps WHERE workflow_id = p_workflow_id ORDER BY step_order ASC LIMIT 1;
IF NOT FOUND THEN RAISE EXCEPTION 'Workflow has no steps'; END IF;
INSERT INTO email_workflow_enrollments (workflow_id, contact_id, lead_id, current_step_id, next_send_at, metadata, status)
VALUES (p_workflow_id, p_contact_id, p_lead_id, v_first_step.id, now() + (v_first_step.delay_days || ' days')::INTERVAL + (v_first_step.delay_hours || ' hours')::INTERVAL, p_metadata, 'active')
RETURNING id INTO v_enrollment_id;
RETURN v_enrollment_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.ensure_single_default_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.is_default = true THEN
UPDATE contracts
SET is_default = false
WHERE company_id = NEW.company_id
AND id != NEW.id
AND is_default = true;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.ensure_single_default_payment_method()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_default = true THEN
    UPDATE payment_methods
    SET is_default = false, updated_at = now()
    WHERE contact_id = NEW.contact_id
    AND id != NEW.id
    AND is_default = true;
  END IF;
  RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.estimate_travel_time(distance_meters integer, average_speed_mph numeric DEFAULT 35.0)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
distance_miles numeric;
time_hours numeric;
time_seconds integer;
BEGIN
distance_miles := distance_meters / 1609.34;
time_hours := distance_miles / average_speed_mph;
time_seconds := CAST(time_hours * 3600 AS integer);

-- Minimum 5 minutes
RETURN GREATEST(time_seconds, 300);
END;
$function$


CREATE OR REPLACE FUNCTION public.execute_auto_archive_declined_proposals()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
BEGIN
-- Call the auto-archive function
SELECT auto_archive_declined_proposals() INTO v_result;

-- The function already logs to proposal_archive_log internally
-- This wrapper just provides a consistent interface for cron

EXCEPTION WHEN OTHERS THEN
-- Log any unexpected errors
INSERT INTO proposal_archive_log (
executed_at,
proposals_archived,
success,
error_message
) VALUES (
now(),
0,
false,
SQLERRM
);

RAISE;
END;
$function$


CREATE OR REPLACE FUNCTION public.execute_midnight_session_cleanup()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_sessions_closed integer;
BEGIN
-- Call the cleanup function
SELECT midnight_session_cleanup() INTO v_result;

-- Extract sessions closed count
v_sessions_closed := (v_result->>'sessions_closed')::integer;

-- Log successful execution
INSERT INTO session_cleanup_log (sessions_closed, success)
VALUES (v_sessions_closed, true);

EXCEPTION WHEN OTHERS THEN
-- Log any errors
INSERT INTO session_cleanup_log (sessions_closed, success, error_message)
VALUES (0, false, SQLERRM);

RAISE;
END;
$function$


CREATE OR REPLACE FUNCTION public.execute_scheduled_logout()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
v_schedule RECORD;
v_configured_utc timestamptz;
v_now_minute timestamptz;
v_sessions_closed integer := 0;
v_tokens_revoked integer := 0;
v_org_id uuid;
BEGIN
-- Resolve organization_id for logging (pg_cron has no authenticated user)
SELECT id INTO v_org_id FROM public.organizations LIMIT 1;

-- Load the schedule configuration
SELECT * INTO v_schedule
FROM public.session_logout_schedule
LIMIT 1;

-- If no schedule row or not enabled, skip
IF v_schedule IS NULL OR NOT v_schedule.enabled THEN
RETURN jsonb_build_object('skipped', true, 'reason', 'Schedule disabled or not configured');
END IF;

-- Convert the configured logout_time + timezone to a UTC timestamp for today
v_configured_utc := (
(current_date::text || ' ' || v_schedule.logout_time::text)::timestamp AT TIME ZONE v_schedule.timezone
);

-- Truncate both times to the minute for comparison
v_now_minute := date_trunc('minute', now() AT TIME ZONE 'UTC');

-- Only run when the current UTC minute matches the configured logout time
IF date_trunc('minute', v_configured_utc AT TIME ZONE 'UTC') <> v_now_minute THEN
RETURN jsonb_build_object(
'skipped', true,
'reason', 'Not the scheduled time',
'configured_utc', v_configured_utc,
'current_utc', now()
);
END IF;

-- Revoke all active auth refresh tokens (invalidates sessions app-wide)
DELETE FROM auth.refresh_tokens
WHERE revoked = false OR revoked IS NULL;
GET DIAGNOSTICS v_tokens_revoked = ROW_COUNT;

-- Delete all active auth sessions
DELETE FROM auth.sessions;

-- Close all active user_sessions tracking records
UPDATE public.user_sessions
SET is_active = false, session_end = now()
WHERE is_active = true;
GET DIAGNOSTICS v_sessions_closed = ROW_COUNT;

-- Record the run in the schedule table
UPDATE public.session_logout_schedule
SET
last_run_at = now(),
last_run_count = v_sessions_closed,
updated_at = now()
WHERE id = v_schedule.id;

-- Log to session_cleanup_log with explicit org_id (not get_user_org_id() which is NULL in cron)
INSERT INTO public.session_cleanup_log (sessions_closed, success, organization_id)
VALUES (v_sessions_closed, true, v_org_id);

RETURN jsonb_build_object(
'success', true,
'sessions_closed', v_sessions_closed,
'tokens_revoked', v_tokens_revoked,
'executed_at', now()
);

EXCEPTION WHEN OTHERS THEN
-- Log the error with explicit org_id so this INSERT doesn't fail too
BEGIN
INSERT INTO public.session_cleanup_log (sessions_closed, success, error_message, organization_id)
VALUES (0, false, SQLERRM, v_org_id);
EXCEPTION WHEN OTHERS THEN NULL;
END;

RAISE WARNING 'execute_scheduled_logout error: %', SQLERRM;
RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$


CREATE OR REPLACE FUNCTION public.expire_old_proposals()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE proposals
SET status = 'expired'
WHERE status IN ('sent', 'portal')
AND expires_at IS NOT NULL
AND expires_at < NOW();
END;
$function$


CREATE OR REPLACE FUNCTION public.flow_can_view_thread(p_thread uuid, p_user uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT EXISTS (
  SELECT 1 FROM public.message_threads t
  JOIN public.profiles me ON me.id=p_user AND me.organization_id=t.organization_id AND me.contact_id IS NULL
  WHERE t.id=p_thread AND (
   me.role='admin' OR me.can_view_all_messages
   OR (me.role='service_manager' AND t.context_type IN ('work_order','service_request'))
   OR t.created_by=p_user OR t.assigned_sales_rep_id=p_user
   OR EXISTS (SELECT 1 FROM public.contacts c WHERE c.id=t.contact_id AND c.organization_id=t.organization_id AND c.assigned_to=p_user)
   OR EXISTS (SELECT 1 FROM public.proposals p WHERE p.id=t.proposal_id AND p.organization_id=t.organization_id AND p.created_by=p_user)
   OR EXISTS (SELECT 1 FROM public.projects p WHERE p.organization_id=t.organization_id
       AND (t.context_type='project' AND p.id=t.context_id OR t.context_type NOT IN ('project','work_order') AND p.contact_id=t.contact_id)
       AND p_user IN (p.assigned_pm,p.salesperson_id,p.designer_id))
   OR EXISTS (SELECT 1 FROM public.work_orders w WHERE w.organization_id=t.organization_id
       AND (t.context_type='work_order' AND w.id=t.context_id OR t.context_type NOT IN ('project','work_order') AND w.contact_id=t.contact_id)
       AND p_user IN (w.assigned_to,w.customer_sales_rep_id))
  )
 );
$function$


CREATE OR REPLACE FUNCTION public.flow_has_module_access(p_module text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 SELECT NOT EXISTS (
   SELECT 1 FROM public.user_permission_overrides o JOIN public.department_modules m ON m.id=o.module_id
   WHERE o.user_id=(SELECT auth.uid()) AND m.module_key=p_module AND m.is_active AND o.override_type='revoke'
 ) AND EXISTS (
   SELECT 1 FROM public.profiles p
   JOIN public.department_modules m ON m.module_key=p_module AND m.is_active
   LEFT JOIN public.user_permission_overrides o ON o.user_id=p.id AND o.module_id=m.id
   LEFT JOIN public.role_module_access r ON r.role_id=p.role_id AND r.module_id=m.id
   WHERE p.id=(SELECT auth.uid()) AND p.organization_id IS NOT NULL
   AND CASE WHEN o.override_type='revoke' THEN false WHEN o.override_type='grant' THEN true
       WHEN p.role='admin' THEN true ELSE coalesce(r.has_access,false) END
 );
$function$


CREATE OR REPLACE FUNCTION public.generate_adjustment_number()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
next_num integer;
adj_num text;
BEGIN
SELECT COALESCE(MAX(CAST(SUBSTRING(adjustment_number FROM 5) AS integer)), 0) + 1
INTO next_num
FROM stock_adjustments
WHERE adjustment_number ~ '^ADJ-[0-9]+$';

adj_num := 'ADJ-' || LPAD(next_num::text, 6, '0');
RETURN adj_num;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_batch_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
next_num integer;
date_prefix text;
BEGIN
date_prefix := TO_CHAR(CURRENT_DATE, 'YYYYMMDD');

SELECT COALESCE(MAX(
CASE 
WHEN batch_number ~ ('^BATCH-' || date_prefix || '-[0-9]+$')
THEN CAST(SUBSTRING(batch_number FROM '[0-9]+$') AS integer)
ELSE 0
END
), 0) + 1
INTO next_num
FROM commission_payment_batches
WHERE batch_number LIKE 'BATCH-' || date_prefix || '-%';

RETURN 'BATCH-' || date_prefix || '-' || LPAD(next_num::text, 3, '0');
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_change_order_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.change_order_number IS NULL OR NEW.change_order_number = '' THEN
NEW.change_order_number := 'CO-' || TO_CHAR(NOW(), 'YYYY') || '-' || 
LPAD(NEXTVAL('change_order_number_seq')::TEXT, 5, '0');
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_co_number_per_so()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_next_num integer;
BEGIN
IF NEW.change_order_number IS NULL OR NEW.change_order_number = '' THEN
SELECT COALESCE(MAX(
CASE
WHEN change_order_number ~ '^CO[0-9]+$'
THEN (regexp_replace(change_order_number, '^CO', ''))::integer
ELSE 0
END
), 0) + 1
INTO v_next_num
FROM change_orders
WHERE sales_order_id = NEW.sales_order_id;

NEW.change_order_number := 'CO' || v_next_num::text;
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_combined_task_description(task_ids uuid[])
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_description text := '';
v_task record;
v_count int := 0;
BEGIN
-- Build combined description from all tasks
FOR v_task IN
SELECT title, details, installer_notes
FROM punchlist_tasks
WHERE id = ANY(task_ids)
ORDER BY priority_order, created_at
LOOP
v_count := v_count + 1;
v_description := v_description || 'Task ' || v_count || ': ' || v_task.title || E'\
';

IF v_task.details IS NOT NULL THEN
v_description := v_description || v_task.details || E'\
';
END IF;

IF v_task.installer_notes IS NOT NULL THEN
v_description := v_description || 'Notes: ' || v_task.installer_notes || E'\
';
END IF;

v_description := v_description || E'\
';
END LOOP;

RETURN TRIM(v_description);
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_device_signature(p_device_type text, p_browser_name text, p_os_name text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN COALESCE(p_device_type, 'unknown') || '|' || 
COALESCE(p_browser_name, 'unknown') || '|' || 
COALESCE(p_os_name, 'unknown');
