CREATE OR REPLACE FUNCTION public.generate_project_tasks_on_project_creation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal_id   uuid;
v_task          record;
v_sort_order    integer := 0;
BEGIN
-- Only process if this project came from a sales order
IF NEW.sales_order_id IS NULL THEN
RETURN NEW;
END IF;

-- Get the proposal from the sales order
SELECT so.proposal_id INTO v_proposal_id
FROM sales_orders so
WHERE so.id = NEW.sales_order_id
LIMIT 1;

IF v_proposal_id IS NULL THEN
RETURN NEW;
END IF;

-- Copy surviving proposal tasks to project tasks
FOR v_task IN
SELECT
pt.id             AS proposal_task_id,
pt.title,
pt.description,
pt.labor_phase_id,
pt.line_item_id,
pt.sort_order
FROM proposal_tasks pt
WHERE pt.proposal_id = v_proposal_id
ORDER BY pt.sort_order
LOOP
-- Check if this proposal task was already copied (idempotency)
IF NOT EXISTS (
SELECT 1 FROM project_tasks
WHERE project_id = NEW.id
AND source_proposal_task_id = v_task.proposal_task_id
) THEN
INSERT INTO project_tasks (
project_id, organization_id,
title, description, labor_phase_id,
status, sort_order,
source_line_item_id, source_proposal_task_id,
source, visibility,
created_by, created_at, updated_at
) VALUES (
NEW.id, NEW.organization_id,
v_task.title, v_task.description, v_task.labor_phase_id,
'open', v_task.sort_order,
v_task.line_item_id, v_task.proposal_task_id,
'proposal', 'internal',
NEW.created_by, now(), now()
);
v_sort_order := v_sort_order + 1;
END IF;
END LOOP;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_proposal_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
office_num text;
next_number integer;
new_proposal_number text;
lock_key bigint;
user_office_id uuid;
BEGIN
-- Only generate if proposal_number is not provided
IF NEW.proposal_number IS NULL OR NEW.proposal_number = '' THEN
-- Get the user's office ID from profiles (using primary_office_id)
SELECT primary_office_id INTO user_office_id
FROM profiles
WHERE id = NEW.created_by;

-- Determine office number based on office_id
-- Default to '01' if no office found
IF user_office_id IS NULL THEN
office_num := '01';
ELSE
-- Get office number from company_offices table
-- Offices should have a sequence number or we'll derive from creation order
SELECT LPAD(
COALESCE(
(SELECT COUNT(*) + 1
FROM company_offices co2
WHERE co2.company_id = co.company_id
AND co2.created_at <= co.created_at),
1
)::text,
2,
'0'
)
INTO office_num
FROM company_offices co
WHERE co.id = user_office_id;

-- If still null, default to '01'
IF office_num IS NULL THEN
office_num := '01';
END IF;
END IF;

-- Create a lock key from company_id and office_num hash
lock_key := ('x' || substr(md5(NEW.company_id::text || office_num), 1, 15))::bit(60)::bigint;

-- Acquire advisory lock (automatically released at transaction end)
PERFORM pg_advisory_xact_lock(lock_key);

-- Find the highest number for this office
SELECT COALESCE(MAX(
CASE
WHEN proposal_number ~ ('^PRO-' || office_num || '-[0-9]+$')
THEN (regexp_match(proposal_number, '^PRO-' || office_num || '-([0-9]+)$'))[1]::integer
ELSE 0
END
), 24999) + 1
INTO next_number
FROM proposals
WHERE company_id = NEW.company_id
AND proposal_number LIKE 'PRO-' || office_num || '-%';

-- Ensure we start at 25000 minimum
IF next_number < 25000 THEN
next_number := 25000;
END IF;

-- Generate the new proposal number: PRO-##-#####
new_proposal_number := 'PRO-' || office_num || '-' || next_number::text;

NEW.proposal_number := new_proposal_number;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_recurring_appointments(parent_appointment_id uuid, generate_until date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
parent_apt RECORD;
rule JSONB;
frequency TEXT;
interval_val INTEGER;
end_date DATE;
max_occurrences INTEGER;
next_date DATE;
instance_count INTEGER := 0;
new_date DATE;
days_of_week INTEGER[];
day_of_month INTEGER;
i INTEGER;
BEGIN
-- Get parent appointment
SELECT * INTO parent_apt
FROM appointments
WHERE id = parent_appointment_id
AND is_recurring_parent = true;

IF NOT FOUND THEN
RAISE EXCEPTION 'Parent appointment not found or not marked as recurring';
END IF;

rule := parent_apt.recurrence_rule;
frequency := rule->>'frequency';
interval_val := COALESCE((rule->>'interval')::INTEGER, 1);

-- Determine end date
IF rule->>'end_date' IS NOT NULL THEN
end_date := (rule->>'end_date')::DATE;
ELSIF generate_until IS NOT NULL THEN
end_date := generate_until;
ELSE
-- Default to 1 year from parent appointment
end_date := parent_apt.appointment_date + INTERVAL '1 year';
END IF;

max_occurrences := (rule->>'occurrences')::INTEGER;
next_date := parent_apt.appointment_date +
CASE frequency
WHEN 'daily' THEN (interval_val || ' days')::INTERVAL
WHEN 'weekly' THEN (interval_val || ' weeks')::INTERVAL
WHEN 'monthly' THEN (interval_val || ' months')::INTERVAL
WHEN 'yearly' THEN (interval_val || ' years')::INTERVAL
END;

-- For weekly recurrence, get days of week
IF frequency = 'weekly' AND rule->'days_of_week' IS NOT NULL THEN
SELECT ARRAY_AGG((value::TEXT)::INTEGER)
INTO days_of_week
FROM jsonb_array_elements(rule->'days_of_week');
END IF;

-- For monthly recurrence, get day of month
IF frequency = 'monthly' THEN
day_of_month := COALESCE((rule->>'day_of_month')::INTEGER, EXTRACT(DAY FROM parent_apt.appointment_date)::INTEGER);
END IF;

-- Generate instances
WHILE next_date <= end_date LOOP
-- Check max occurrences
IF max_occurrences IS NOT NULL AND instance_count >= max_occurrences THEN
EXIT;
END IF;

-- For weekly recurrence, check if current day is in allowed days
IF frequency = 'weekly' AND days_of_week IS NOT NULL THEN
IF EXTRACT(DOW FROM next_date)::INTEGER = ANY(days_of_week) THEN
new_date := next_date;
ELSE
-- Skip to next interval
next_date := next_date + (interval_val || ' weeks')::INTERVAL;
CONTINUE;
END IF;
ELSIF frequency = 'monthly' THEN
-- Set to specific day of month
new_date := DATE_TRUNC('month', next_date) + (day_of_month - 1 || ' days')::INTERVAL;
IF new_date > end_date THEN
EXIT;
END IF;
ELSE
new_date := next_date;
END IF;

-- Check if appointment already exists for this date
IF NOT EXISTS (
SELECT 1 FROM appointments
WHERE recurrence_parent_id = parent_appointment_id
AND appointment_date = new_date
) THEN
-- Create new appointment instance
INSERT INTO appointments (
company_id,
title,
description,
appointment_date,
start_time,
end_time,
contact_id,
project_id,
technician_id,
status,
recurrence_parent_id,
is_recurring_parent
) VALUES (
parent_apt.company_id,
parent_apt.title,
parent_apt.description,
new_date,
parent_apt.start_time,
parent_apt.end_time,
parent_apt.contact_id,
parent_apt.project_id,
parent_apt.technician_id,
'scheduled',
parent_appointment_id,
false
);

instance_count := instance_count + 1;
END IF;

-- Move to next occurrence
next_date := next_date +
CASE frequency
WHEN 'daily' THEN (interval_val || ' days')::INTERVAL
WHEN 'weekly' THEN (interval_val || ' weeks')::INTERVAL
WHEN 'monthly' THEN (interval_val || ' months')::INTERVAL
WHEN 'yearly' THEN (interval_val || ' years')::INTERVAL
END;
END LOOP;

RETURN instance_count;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_recurring_invoices()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_generated integer := 0;
v_failed integer := 0;
v_errors text[] := ARRAY[]::text[];
v_contact RECORD;
v_sub RECORD;
v_invoice_id uuid;
v_invoice_number text;
v_billing_amount numeric;
v_tax_rate numeric;
v_tax_amount numeric;
v_total numeric;
v_subtotal numeric;
v_discount numeric := 0;
v_period_start date;
v_period_end date;
v_next_date date;
v_ri_id uuid;
v_pref text;
v_annual_enabled boolean;
v_disc_type text;
v_disc_pct numeric;
v_disc_flat numeric;
v_line_sort integer := 1;
v_line_amount numeric;
v_is_annual boolean;
v_org_id uuid;
v_office_id uuid;
v_contact_name text;
v_contact_email text;
v_contact_tax_rate numeric;
v_is_tax_exempt boolean;
v_tax_environment text;
v_tax_jurisdiction_id uuid;
v_grace_days integer;
BEGIN
SELECT
annual_billing_enabled, annual_discount_type, annual_discount_percentage,
annual_discount_flat_amount, grace_period_days
INTO
v_annual_enabled, v_disc_type, v_disc_pct, v_disc_flat, v_grace_days
FROM company_settings LIMIT 1;

v_disc_type := COALESCE(v_disc_type, 'none');
v_disc_pct := COALESCE(v_disc_pct, 0);
v_disc_flat := COALESCE(v_disc_flat, 0);
v_grace_days := COALESCE(v_grace_days, 0);

FOR v_contact IN
SELECT DISTINCT rs.contact_id
FROM recurring_subscriptions rs
WHERE rs.status = 'active'
AND rs.auto_invoice = true
AND rs.next_billing_date <= CURRENT_DATE
AND rs.contact_id IS NOT NULL
LOOP
BEGIN
v_pref := get_customer_billing_preference(v_contact.contact_id);
v_is_annual := (v_pref = 'annual' AND v_annual_enabled = true);

FOR v_sub IN
SELECT rs.*, c.full_name as contact_name, c.email as contact_email,
c.tax_rate as contact_tax_rate, c.is_tax_exempt,
c.tax_environment, c.tax_jurisdiction_id, c.organization_id, c.office_id
FROM recurring_subscriptions rs
JOIN contacts c ON c.id = rs.contact_id
WHERE rs.contact_id = v_contact.contact_id
AND rs.status = 'active'
AND rs.auto_invoice = true
AND rs.next_billing_date <= CURRENT_DATE
LOOP
BEGIN
v_billing_amount := v_sub.billing_amount;
v_tax_rate := COALESCE(v_sub.tax_rate, v_sub.contact_tax_rate, 0);
v_tax_environment := COALESCE(v_sub.tax_environment, 'residential');
v_tax_jurisdiction_id := v_sub.tax_jurisdiction_id;
v_org_id := v_sub.organization_id;
v_office_id := v_sub.office_id;
v_contact_name := v_sub.contact_name;
v_contact_email := v_sub.contact_email;
v_is_tax_exempt := COALESCE(v_sub.is_tax_exempt, false);

IF v_is_annual THEN
IF v_disc_type = 'percentage' THEN
v_discount := v_billing_amount * (v_disc_pct / 100);
ELSIF v_disc_type = 'flat' THEN
v_discount := v_disc_flat;
ELSE
v_discount := 0;
END IF;
ELSE
v_discount := 0;
END IF;

v_subtotal := v_billing_amount - v_discount;
v_tax_amount := CASE WHEN v_is_tax_exempt THEN 0 ELSE round(v_subtotal * v_tax_rate / 100, 2) END;
v_total := v_subtotal + v_tax_amount;

v_period_start := v_sub.next_billing_date;
v_period_end := v_period_start + (v_sub.billing_interval_days || ' days')::interval - 1;
v_next_date := v_period_end + 1;

v_invoice_number := generate_invoice_number();

INSERT INTO invoices (
company_id, contact_id, invoice_number, invoice_type,
invoice_date, due_date, subtotal, tax_amount, total,
amount_paid, amount_due, status, tax_rate,
tax_environment, tax_jurisdiction_id, tax_project_type,
source_type, office_id, organization_id,
notes, created_by, created_at, updated_at
) VALUES (
v_org_id, v_sub.contact_id, v_invoice_number, 'recurring',
CURRENT_DATE, CURRENT_DATE + 10, v_subtotal, v_tax_amount, v_total,
0, v_total, 'submitted', v_tax_rate,
v_tax_environment, v_tax_jurisdiction_id, 'general_installation_repair',
'recurring', v_office_id, v_org_id,
'Recurring Billing System', null, now(), now()
) RETURNING id INTO v_invoice_id;

v_line_sort := 1;
INSERT INTO invoice_line_items (
invoice_id, description, quantity, unit_price, amount, sort_order, taxable, organization_id
) VALUES (
v_invoice_id, v_sub.description || ' (' || v_period_start || ' to ' || v_period_end || ')',
1, v_subtotal, v_subtotal, v_line_sort, NOT v_is_tax_exempt, v_org_id
);

IF v_discount > 0 THEN
v_line_sort := v_line_sort + 1;
INSERT INTO invoice_line_items (
invoice_id, description, quantity, unit_price, amount, sort_order, taxable, organization_id
) VALUES (
v_invoice_id, 'Annual Billing Discount', 1, -v_discount, -v_discount, v_line_sort, false, v_org_id
);
END IF;

UPDATE recurring_subscriptions
SET next_billing_date = v_next_date, updated_at = now()
WHERE id = v_sub.id;

v_generated := v_generated + 1;
EXCEPTION WHEN OTHERS THEN
v_failed := v_failed + 1;
v_errors := array_append(v_errors, SQLERRM);
END;
END LOOP;
EXCEPTION WHEN OTHERS THEN
v_failed := v_failed + 1;
v_errors := array_append(v_errors, SQLERRM);
END;
END LOOP;

RETURN jsonb_build_object(
'generated', v_generated,
'failed', v_failed,
'errors', to_jsonb(v_errors)
);
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_recurring_work_orders(parent_work_order_id uuid, generate_until date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
parent_wo   RECORD;
rule        JSONB;
frequency   TEXT;
interval_val INTEGER;
end_date    DATE;
max_occurrences INTEGER;
next_date   DATE;
instance_count INTEGER := 0;
new_date    DATE;
days_of_week INTEGER[];
day_of_month INTEGER;
BEGIN
SELECT * INTO parent_wo
FROM work_orders
WHERE id = parent_work_order_id
AND is_recurring_parent = true;

IF NOT FOUND THEN
RAISE EXCEPTION 'Parent work order not found or not marked as recurring';
END IF;

rule         := parent_wo.recurrence_rule;
frequency    := rule->>'frequency';
interval_val := COALESCE((rule->>'interval')::INTEGER, 1);

-- Determine end date
IF rule->>'end_date' IS NOT NULL THEN
end_date := (rule->>'end_date')::DATE;
ELSIF generate_until IS NOT NULL THEN
end_date := generate_until;
ELSE
end_date := parent_wo.start_date + INTERVAL '1 year';
END IF;

max_occurrences := (rule->>'occurrences')::INTEGER;

-- First instance date is one interval after the parent
next_date := parent_wo.start_date +
CASE frequency
WHEN 'daily'   THEN (interval_val || ' days')::INTERVAL
WHEN 'weekly'  THEN (interval_val || ' weeks')::INTERVAL
WHEN 'monthly' THEN (interval_val || ' months')::INTERVAL
WHEN 'yearly'  THEN (interval_val || ' years')::INTERVAL
END;

IF frequency = 'weekly' AND rule->'days_of_week' IS NOT NULL THEN
SELECT ARRAY_AGG((value::TEXT)::INTEGER)
INTO days_of_week
FROM jsonb_array_elements(rule->'days_of_week');
END IF;

IF frequency = 'monthly' THEN
day_of_month := COALESCE(
(rule->>'day_of_month')::INTEGER,
EXTRACT(DAY FROM parent_wo.start_date)::INTEGER
);
END IF;

WHILE next_date <= end_date LOOP
IF max_occurrences IS NOT NULL AND instance_count >= max_occurrences THEN
EXIT;
END IF;

IF frequency = 'weekly' AND days_of_week IS NOT NULL THEN
IF EXTRACT(DOW FROM next_date)::INTEGER = ANY(days_of_week) THEN
new_date := next_date;
ELSE
next_date := next_date + (interval_val || ' weeks')::INTERVAL;
CONTINUE;
END IF;
ELSIF frequency = 'monthly' THEN
new_date := DATE_TRUNC('month', next_date) + (day_of_month - 1 || ' days')::INTERVAL;
IF new_date > end_date THEN EXIT; END IF;
ELSE
new_date := next_date;
END IF;

IF NOT EXISTS (
SELECT 1 FROM work_orders
WHERE recurrence_parent_id = parent_work_order_id
AND start_date = new_date
) THEN
INSERT INTO work_orders (
company_id,
organization_id,
contact_id,
project_id,
labor_phase_id,
labor_category_id,
title,
description,
type,
is_billable,
billable_type,
priority,
status,
assigned_to,
start_date,
start_time,
end_time,
target_completion_date,
estimated_hours,
notes,
internal_notes,
office_id,
recurrence_parent_id,
is_recurring_parent
) VALUES (
parent_wo.company_id,
parent_wo.organization_id,
parent_wo.contact_id,
parent_wo.project_id,
parent_wo.labor_phase_id,
parent_wo.labor_category_id,
parent_wo.title,
parent_wo.description,
parent_wo.type,
parent_wo.is_billable,
parent_wo.billable_type,
parent_wo.priority,
'pending',
parent_wo.assigned_to,
new_date,
parent_wo.start_time,
parent_wo.end_time,
NULL, -- target_completion_date computed fresh per instance
parent_wo.estimated_hours,
parent_wo.notes,
parent_wo.internal_notes,
parent_wo.office_id,
parent_work_order_id,
false
);

instance_count := instance_count + 1;
END IF;

next_date := next_date +
CASE frequency
WHEN 'daily'   THEN (interval_val || ' days')::INTERVAL
WHEN 'weekly'  THEN (interval_val || ' weeks')::INTERVAL
WHEN 'monthly' THEN (interval_val || ' months')::INTERVAL
WHEN 'yearly'  THEN (interval_val || ' years')::INTERVAL
END;
END LOOP;

RETURN instance_count;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_sales_order_number(p_proposal_number text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Convert PRO-##-##### to SO-##-#####
RETURN REPLACE(p_proposal_number, 'PRO-', 'SO-');
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_scheduled_occurrences()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_schedule RECORD;
v_next_date date;
v_end_date date;
v_count integer;
BEGIN
v_end_date := CURRENT_DATE + 90; -- Generate 90 days in advance

FOR v_schedule IN
SELECT * FROM scheduled_connections
WHERE is_active = true
AND (schedule_end_date IS NULL OR schedule_end_date >= CURRENT_DATE)
LOOP
-- Start from next_occurrence_date or last_occurrence_date
v_next_date := COALESCE(
v_schedule.next_occurrence_date,
v_schedule.last_occurrence_date,
v_schedule.schedule_start_date
);

-- If we already have occurrences, start from the next one
IF v_schedule.last_occurrence_date IS NOT NULL THEN
v_next_date := calculate_next_occurrence_date(
v_next_date,
v_schedule.recurrence_pattern,
v_schedule.recurrence_interval,
v_schedule.recurrence_day_rule
);
END IF;

v_count := 0;

-- Generate occurrences up to end_date
WHILE v_next_date <= v_end_date
AND (v_schedule.schedule_end_date IS NULL OR v_next_date <= v_schedule.schedule_end_date)
AND v_count < 100 -- Safety limit
LOOP
-- Check if occurrence already exists
IF NOT EXISTS (
SELECT 1 FROM scheduled_connection_occurrences
WHERE scheduled_connection_id = v_schedule.id
AND scheduled_date = v_next_date
) THEN
-- Create the occurrence
INSERT INTO scheduled_connection_occurrences (
scheduled_connection_id,
prospect_id,
scheduled_date,
scheduled_time,
original_scheduled_date
) VALUES (
v_schedule.id,
v_schedule.prospect_id,
v_next_date,
v_schedule.preferred_time,
v_next_date
);

-- Update schedule's next occurrence date
UPDATE scheduled_connections
SET
next_occurrence_date = v_next_date,
last_occurrence_date = v_next_date,
updated_at = now()
WHERE id = v_schedule.id;
END IF;

-- Calculate next date
v_next_date := calculate_next_occurrence_date(
v_next_date,
v_schedule.recurrence_pattern,
v_schedule.recurrence_interval,
v_schedule.recurrence_day_rule
);

v_count := v_count + 1;
END LOOP;
END LOOP;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_security_contract_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
year_part text;
next_num integer;
new_contract_number text;
lock_key bigint;
BEGIN
-- Only generate if contract_number is not already set
IF NEW.contract_number IS NOT NULL THEN
RETURN NEW;
END IF;

-- Get current year
year_part := TO_CHAR(NOW(), 'YYYY');

-- Create a unique lock key based on the year (hash of 'security_contract_' + year)
lock_key := hashtext('security_contract_' || year_part);

-- Acquire advisory lock to prevent concurrent number generation
PERFORM pg_advisory_xact_lock(lock_key);

-- Get the next number for this year (use [0-9] instead of \\d for regex)
SELECT COALESCE(MAX(
CAST(
SUBSTRING(contract_number FROM 'SC-' || year_part || '-([0-9]+)')
AS INTEGER
)
), 0) + 1
INTO next_num
FROM security_contracts
WHERE contract_number ~ ('^SC-' || year_part || '-[0-9]+$');

-- Generate the new contract number
new_contract_number := 'SC-' || year_part || '-' || LPAD(next_num::text, 5, '0');

-- Set the contract number
NEW.contract_number := new_contract_number;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_statement_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
next_num integer;
year_prefix text;
BEGIN
year_prefix := TO_CHAR(CURRENT_DATE, 'YYYY');

SELECT COALESCE(MAX(
CASE 
WHEN statement_number ~ ('^' || year_prefix || '-[0-9]+$')
THEN CAST(SUBSTRING(statement_number FROM '[0-9]+$') AS integer)
ELSE 0
END
), 0) + 1
INTO next_num
FROM commission_statements
WHERE statement_number LIKE year_prefix || '-%';

RETURN year_prefix || '-' || LPAD(next_num::text, 4, '0');
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_transfer_number()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
next_num integer;
trans_num text;
BEGIN
SELECT COALESCE(MAX(CAST(SUBSTRING(transfer_number FROM 4) AS integer)), 0) + 1
INTO next_num
FROM stock_transfers
WHERE transfer_number ~ '^TR-[0-9]+$';

trans_num := 'TR-' || LPAD(next_num::text, 6, '0');
RETURN trans_num;
END;
$function$


CREATE OR REPLACE FUNCTION public.generate_work_order_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.work_order_number IS NULL OR NEW.work_order_number = '' THEN
NEW.work_order_number := 'WO-' || TO_CHAR(NOW(), 'YYYY') || '-' || 
LPAD(NEXTVAL('work_order_number_seq')::TEXT, 5, '0');
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_active_sessions_with_cleanup()
 RETURNS TABLE(id uuid, user_id uuid, session_start timestamp with time zone, session_end timestamp with time zone, last_activity timestamp with time zone, ip_address text, user_agent text, is_active boolean, duration_seconds integer, device_type text, browser_name text, browser_version text, os_name text, os_version text, device_model text, device_vendor text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- First, cleanup stale sessions
PERFORM cleanup_stale_sessions();

-- Then return active sessions
RETURN QUERY
SELECT 
us.id,
us.user_id,
us.session_start,
us.session_end,
us.last_activity,
us.ip_address,
us.user_agent,
us.is_active,
us.duration_seconds,
us.device_type,
us.browser_name,
us.browser_version,
us.os_name,
us.os_version,
us.device_model,
us.device_vendor
FROM user_sessions us
WHERE us.is_active = true
ORDER BY us.last_activity DESC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_all_punchlist_customers()
 RETURNS TABLE(contact_id uuid, contact_name text, contact_email text, contact_phone text, access_type text, status text, days_remaining integer, project_name text, subscription_plan_name text, expiration_date timestamp with time zone, granted_date timestamp with time zone, grant_id uuid)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH vip_access AS (
SELECT DISTINCT
c.id                           AS contact_id,
c.full_name                    AS contact_name,
c.email                        AS contact_email,
c.phone                        AS contact_phone,
CASE WHEN s.status='trial' THEN 'vip_trial' ELSE 'vip_membership' END::text AS access_type,
s.status::text                 AS status,
NULL::int                      AS days_remaining,
NULL::text                     AS project_name,
rp.plan_name                   AS subscription_plan_name,
NULL::timestamptz              AS expiration_date,
s.start_date::timestamptz      AS granted_date,
NULL::uuid                     AS grant_id
FROM contacts c
INNER JOIN recurring_subscriptions s ON s.contact_id = c.id
INNER JOIN recurring_plans rp        ON rp.id = s.plan_id
WHERE rp.plan_type='vip_plan' AND (s.status='active' OR (s.status='trial' AND s.trial_source='vip_trial' AND s.trial_end_date>=CURRENT_DATE))
),
grant_access AS (
SELECT
c.id                       AS contact_id,
c.full_name                AS contact_name,
c.email                    AS contact_email,
c.phone                    AS contact_phone,
pag.access_type,
CASE
WHEN pag.access_type='vip_trial' AND NOT EXISTS(SELECT 1 FROM recurring_subscriptions trial WHERE trial.id=pag.subscription_id AND trial.status IN ('trial','active') AND trial.trial_end_date>=CURRENT_DATE) THEN 'expired'
WHEN pag.status = 'suspended' THEN 'suspended'
WHEN pag.expiration_date IS NULL THEN 'active'
WHEN pag.expiration_date > NOW() THEN 'active'
ELSE 'expired'
END::text                  AS status,
CASE
WHEN pag.expiration_date IS NULL THEN NULL
WHEN pag.expiration_date <= NOW() THEN 0
ELSE GREATEST(0, CEIL(EXTRACT(EPOCH FROM (pag.expiration_date - NOW())) / 86400))::int
END                        AS days_remaining,
p.name                     AS project_name,
NULL::text                 AS subscription_plan_name,
pag.expiration_date::timestamptz,
pag.granted_date::timestamptz,
pag.id                     AS grant_id
FROM contacts c
INNER JOIN punchlist_access_grants pag ON pag.contact_id = c.id
LEFT  JOIN projects p ON p.id = pag.project_id
WHERE pag.access_type IN ('test_and_tune', 'promotional', 'vip_signup', 'vip_trial')
),
all_access AS (
SELECT * FROM vip_access
UNION ALL
SELECT * FROM grant_access
)
SELECT DISTINCT ON (a.contact_id)
a.contact_id,
a.contact_name,
a.contact_email,
a.contact_phone,
a.access_type,
a.status,
a.days_remaining,
a.project_name,
a.subscription_plan_name,
a.expiration_date,
a.granted_date,
a.grant_id
FROM all_access a
ORDER BY
a.contact_id,
CASE a.access_type
WHEN 'vip_membership' THEN 1
WHEN 'vip_trial'      THEN 2
WHEN 'vip_signup'     THEN 5
WHEN 'test_and_tune'  THEN 3
WHEN 'promotional'    THEN 4
ELSE 5
END,
CASE a.status
WHEN 'active'     THEN 1
WHEN 'trial'      THEN 1
WHEN 'suspended'  THEN 2
WHEN 'expired'    THEN 3
ELSE 4
END,
a.granted_date DESC NULLS LAST;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_applicable_tax_rate(p_contact_id uuid, p_zip_code text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_is_exempt boolean;
v_tax_rate decimal;
BEGIN
-- Check if contact is tax exempt with valid certificate
SELECT c.is_tax_exempt INTO v_is_exempt
FROM contacts c
WHERE c.id = p_contact_id;

IF v_is_exempt THEN
-- Verify valid certificate exists
IF EXISTS (
SELECT 1 FROM tax_exemption_certificates
WHERE contact_id = p_contact_id
AND is_active = true
AND (expiration_date IS NULL OR expiration_date > CURRENT_DATE)
) THEN
RETURN 0;
END IF;
END IF;

-- Look up tax rate by zip code
IF p_zip_code IS NOT NULL THEN
SELECT combined_rate INTO v_tax_rate
FROM tax_jurisdictions
WHERE zip_code = p_zip_code
AND is_active = true
AND (end_date IS NULL OR end_date > CURRENT_DATE)
ORDER BY effective_date DESC
LIMIT 1;

IF v_tax_rate IS NOT NULL THEN
RETURN v_tax_rate;
END IF;
END IF;

-- Fall back to default company rate
SELECT combined_rate INTO v_tax_rate
FROM tax_jurisdictions
WHERE is_default = true
AND is_active = true
LIMIT 1;

RETURN COALESCE(v_tax_rate, 0);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_appointments_needing_reminders()
 RETURNS TABLE(appointment_id uuid, contact_name text, contact_phone text, appointment_datetime timestamp with time zone, title text, hours_before integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT a.id, CONCAT(c.first_name, ' ', c.last_name), c.mobile_phone, (a.appointment_date + a.start_time::TIME)::TIMESTAMPTZ, a.title, a.reminder_hours_before
FROM appointments a INNER JOIN contacts c ON a.contact_id = c.id
WHERE a.send_reminder = true AND a.reminder_status = 'pending' AND a.status = 'scheduled'
AND c.mobile_phone IS NOT NULL AND c.sms_opt_in = true
AND (a.appointment_date + a.start_time::TIME)::TIMESTAMPTZ > now()
AND (a.appointment_date + a.start_time::TIME)::TIMESTAMPTZ <= (now() + (a.reminder_hours_before || ' hours')::INTERVAL)
ORDER BY a.appointment_date, a.start_time;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_appointments_with_privacy(p_user_id uuid, p_company_id uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date)
 RETURNS TABLE(id uuid, company_id uuid, project_id uuid, contact_id uuid, title text, description text, appointment_date date, start_time time without time zone, end_time time without time zone, status text, assigned_technician uuid, location text, notes text, created_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone, appointment_type text, is_private boolean, all_day boolean, is_blocked boolean, can_view_details boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_role text;
v_is_admin boolean;
BEGIN
-- Get user role
SELECT role INTO v_user_role
FROM profiles
WHERE profiles.id = p_user_id;

-- Check if user is admin
v_is_admin := v_user_role IN ('admin', 'owner');

RETURN QUERY
SELECT 
a.id,
a.company_id,
a.project_id,
CASE 
WHEN a.is_private AND NOT (a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin)
THEN NULL
ELSE a.contact_id
END as contact_id,
CASE 
WHEN a.is_private AND NOT (a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin)
THEN 'Busy'
ELSE a.title
END as title,
CASE 
WHEN a.is_private AND NOT (a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin)
THEN NULL
ELSE a.description
END as description,
a.appointment_date,
a.start_time,
a.end_time,
a.status,
CASE 
WHEN a.is_private AND NOT (a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin)
THEN NULL
ELSE a.assigned_technician
END as assigned_technician,
CASE 
WHEN a.is_private AND NOT (a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin)
THEN NULL
ELSE a.location
END as location,
CASE 
WHEN a.is_private AND NOT (a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin)
THEN NULL
ELSE a.notes
END as notes,
a.created_by,
a.created_at,
a.updated_at,
CASE 
WHEN a.is_private AND NOT (a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin)
THEN 'personal'::text
ELSE a.appointment_type
END as appointment_type,
a.is_private,
a.all_day,
-- is_blocked: true if user can't see details
(a.is_private AND NOT (a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin)) as is_blocked,
-- can_view_details: true if user can see full details
(NOT a.is_private OR a.created_by = p_user_id OR a.assigned_technician = p_user_id OR v_is_admin) as can_view_details
FROM appointments a
WHERE 
a.company_id = p_company_id
AND (p_start_date IS NULL OR a.appointment_date >= p_start_date)
AND (p_end_date IS NULL OR a.appointment_date <= p_end_date)
ORDER BY a.appointment_date, a.start_time;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_billing_classification_composition(p_transaction_type text, p_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_material_amount numeric := 0;
v_labor_amount numeric := 0;
v_design_fee_amount numeric := 0;
v_pm_amount numeric := 0;
v_freight_amount numeric := 0;
v_total numeric := 0;
v_result jsonb[] := ARRAY[]::jsonb[];
v_freight_sc_id uuid;
v_cm1_sc_id uuid;
v_cm2_sc_id uuid;
v_cm1_amount numeric;
v_cm2_amount numeric;
v_cm1_apply boolean;
v_cm2_apply boolean;
BEGIN
IF p_transaction_type = 'proposal' THEN
SELECT COALESCE(SUM(
CASE WHEN COALESCE(item_type, 'part') != 'labor' AND COALESCE(is_customer_supplied, false) = false
THEN line_total ELSE 0 END
), 0)
INTO v_material_amount
FROM proposal_line_items WHERE proposal_id = p_transaction_id;

SELECT COALESCE(SUM(
CASE WHEN item_type = 'labor' THEN COALESCE(labor_total, line_total)
ELSE COALESCE(labor_total, 0) END
), 0)
INTO v_labor_amount
FROM proposal_line_items WHERE proposal_id = p_transaction_id;

SELECT COALESCE(project_design_amount, 0) + COALESCE(system_design_amount, 0)
INTO v_design_fee_amount
FROM proposals WHERE id = p_transaction_id;

SELECT COALESCE(project_management_amount, 0)
INTO v_pm_amount
FROM proposals WHERE id = p_transaction_id;

-- Credit Card Fee: NOT part of project billing composition (payment-method fee)
-- v_ccf_amount remains 0

-- Freight from custom modifiers
SELECT scc.id INTO v_freight_sc_id
FROM special_charge_classifications scc WHERE scc.code = 'freight_delivery';

SELECT ps.custom_modifier_1_special_charge_id, ps.custom_modifier_2_special_charge_id
INTO v_cm1_sc_id, v_cm2_sc_id
FROM proposal_settings ps WHERE ps.proposal_id = p_transaction_id;

SELECT p.custom_modifier_1_amount, p.custom_modifier_2_amount
INTO v_cm1_amount, v_cm2_amount
FROM proposals p WHERE p.id = p_transaction_id;

IF v_cm1_sc_id = v_freight_sc_id AND v_cm1_amount IS NOT NULL THEN
v_freight_amount := v_freight_amount + v_cm1_amount;
END IF;
IF v_cm2_sc_id = v_freight_sc_id AND v_cm2_amount IS NOT NULL THEN
v_freight_amount := v_freight_amount + v_cm2_amount;
END IF;

ELSIF p_transaction_type = 'change_order' THEN
SELECT COALESCE(SUM(change_amount), 0)
INTO v_material_amount
FROM change_order_line_items
WHERE change_order_id = p_transaction_id
AND action_type <> 'modify_modifiers'
AND COALESCE(item_type, 'material') <> 'labor';

SELECT COALESCE(SUM(COALESCE(labor_total, change_amount)), 0)
INTO v_labor_amount
FROM change_order_line_items
WHERE change_order_id = p_transaction_id
AND action_type <> 'modify_modifiers'
AND item_type = 'labor';

SELECT COALESCE(project_design_amount, 0) + COALESCE(system_design_amount, 0)
INTO v_design_fee_amount
FROM change_orders WHERE id = p_transaction_id;

SELECT COALESCE(project_management_amount, 0)
INTO v_pm_amount
FROM change_orders WHERE id = p_transaction_id;

-- Credit Card Fee: NOT part of project billing composition (payment-method fee)
-- v_ccf_amount remains 0

-- Freight from CO modifiers
SELECT scc.id INTO v_freight_sc_id
FROM special_charge_classifications scc WHERE scc.code = 'freight_delivery';

SELECT co.custom_modifier_1_special_charge_id, co.custom_modifier_2_special_charge_id,
co.custom_modifier_1_amount, co.custom_modifier_2_amount,
co.apply_custom_modifier_1, co.apply_custom_modifier_2
INTO v_cm1_sc_id, v_cm2_sc_id, v_cm1_amount, v_cm2_amount, v_cm1_apply, v_cm2_apply
FROM change_orders co WHERE co.id = p_transaction_id;

IF v_cm1_sc_id = v_freight_sc_id AND COALESCE(v_cm1_apply, true) AND v_cm1_amount IS NOT NULL THEN
v_freight_amount := v_freight_amount + v_cm1_amount;
END IF;
IF v_cm2_sc_id = v_freight_sc_id AND COALESCE(v_cm2_apply, true) AND v_cm2_amount IS NOT NULL THEN
v_freight_amount := v_freight_amount + v_cm2_amount;
END IF;

ELSE
RETURN jsonb_build_object('error', 'Unknown transaction type: ' || p_transaction_type);
END IF;

v_total := v_material_amount + v_labor_amount + v_design_fee_amount
+ v_pm_amount + v_freight_amount;

-- Build array of non-zero classifications (5 project classifications only)
IF v_material_amount > 0 THEN
v_result := array_append(v_result, jsonb_build_object(
'classification_code', 'material',
'amount', v_material_amount,
'percentage', CASE WHEN v_total > 0 THEN v_material_amount / v_total ELSE 0 END
));
END IF;
IF v_labor_amount > 0 THEN
v_result := array_append(v_result, jsonb_build_object(
'classification_code', 'labor',
'amount', v_labor_amount,
'percentage', CASE WHEN v_total > 0 THEN v_labor_amount / v_total ELSE 0 END
));
END IF;
IF v_design_fee_amount > 0 THEN
v_result := array_append(v_result, jsonb_build_object(
'classification_code', 'design_fee',
'amount', v_design_fee_amount,
'percentage', CASE WHEN v_total > 0 THEN v_design_fee_amount / v_total ELSE 0 END
));
END IF;
IF v_pm_amount > 0 THEN
v_result := array_append(v_result, jsonb_build_object(
'classification_code', 'project_management',
'amount', v_pm_amount,
'percentage', CASE WHEN v_total > 0 THEN v_pm_amount / v_total ELSE 0 END
));
END IF;
IF v_freight_amount > 0 THEN
v_result := array_append(v_result, jsonb_build_object(
'classification_code', 'freight_delivery',
'amount', v_freight_amount,
'percentage', CASE WHEN v_total > 0 THEN v_freight_amount / v_total ELSE 0 END
));
END IF;

RETURN jsonb_build_object(
'classifications', to_jsonb(v_result),
'total_classified_amount', v_total
);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_billing_summary(p_sales_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_summary jsonb;
v_proposal_total numeric := 0;
v_change_orders jsonb;
v_invoices jsonb;
v_billed_total numeric := 0;
BEGIN
-- Get proposal total
SELECT COALESCE(p.total, 0)
INTO v_proposal_total
FROM sales_orders so
LEFT JOIN proposals p ON so.proposal_id = p.id
WHERE so.id = p_sales_order_id;

-- Get change orders summary
SELECT COALESCE(
jsonb_agg(
jsonb_build_object(
'id', co.id,
'change_order_number', co.change_order_number,
'description', co.description,
'change_amount', co.change_amount,
'tax_amount', co.tax_amount,
'total_impact', co.new_contract_total - co.original_contract_amount,
'amount_billed', COALESCE(co.amount_billed, 0),
'billing_status', co.billing_status,
'status', co.status,
'approval_date', co.approval_date
)
ORDER BY co.created_at DESC
),
'[]'::jsonb
)
INTO v_change_orders
FROM change_orders co
WHERE co.sales_order_id = p_sales_order_id;

-- Get invoices summary
SELECT COALESCE(
jsonb_agg(
jsonb_build_object(
'id', i.id,
'invoice_number', i.invoice_number,
'invoice_title', i.invoice_title,
'source_type', i.source_type,
'invoice_date', i.invoice_date,
'due_date', i.due_date,
'total', i.total,
'amount_paid', i.amount_paid,
'amount_due', i.amount_due,
'status', i.status,
'billed_from_proposal', i.billed_from_proposal,
'includes_change_orders', i.includes_change_orders
)
ORDER BY i.invoice_date DESC
),
'[]'::jsonb
)
INTO v_invoices
FROM invoices i
WHERE i.sales_order_id = p_sales_order_id
AND i.status != 'void';

-- Calculate total billed
SELECT COALESCE(SUM(total), 0)
INTO v_billed_total
FROM invoices
WHERE sales_order_id = p_sales_order_id
AND status != 'void';

-- Build summary
v_summary := jsonb_build_object(
'sales_order_id', p_sales_order_id,
'proposal_total', v_proposal_total,
'change_orders', v_change_orders,
'change_orders_total', (
SELECT COALESCE(SUM((co->>'total_impact')::numeric), 0)
FROM jsonb_array_elements(v_change_orders) co
WHERE co->>'status' = 'approved'
),
'contract_total', v_proposal_total + (
SELECT COALESCE(SUM((co->>'total_impact')::numeric), 0)
FROM jsonb_array_elements(v_change_orders) co
WHERE co->>'status' = 'approved'
),
'invoices', v_invoices,
'billed_total', v_billed_total,
'remaining_balance', v_proposal_total + (
SELECT COALESCE(SUM((co->>'total_impact')::numeric), 0)
FROM jsonb_array_elements(v_change_orders) co
WHERE co->>'status' = 'approved'
) - v_billed_total,
'billing_progress_percent', CASE 
WHEN v_proposal_total + (
SELECT COALESCE(SUM((co->>'total_impact')::numeric), 0)
FROM jsonb_array_elements(v_change_orders) co
WHERE co->>'status' = 'approved'
) > 0 
THEN (v_billed_total / (v_proposal_total + (
SELECT COALESCE(SUM((co->>'total_impact')::numeric), 0)
FROM jsonb_array_elements(v_change_orders) co
WHERE co->>'status' = 'approved'
)) * 100)
ELSE 0
END
);

RETURN v_summary;
END;
$function$


