CREATE OR REPLACE FUNCTION public.get_company_api_key_presence()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
SELECT COALESCE(
(SELECT jsonb_build_object(
'openai', (openai_api_key IS NOT NULL AND openai_api_key <> ''),
'gemini', (gemini_api_key IS NOT NULL AND gemini_api_key <> ''),
'google_maps', (google_maps_api_key IS NOT NULL AND google_maps_api_key <> ''),
'taxjar', (taxjar_api_key IS NOT NULL AND taxjar_api_key <> ''),
'zip_tax', (zip_tax_api_key IS NOT NULL AND zip_tax_api_key <> ''),
'twilio', (twilio_auth_token IS NOT NULL AND twilio_auth_token <> '')
)
FROM public.company_settings LIMIT 1),
'{}'::jsonb);
$function$


CREATE OR REPLACE FUNCTION public.get_company_api_keys()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
result jsonb;
BEGIN
IF NOT EXISTS (
SELECT 1 FROM public.profiles p
WHERE p.id = auth.uid() AND (p.is_global_admin = true OR p.role = 'admin')
) THEN
RAISE EXCEPTION 'Not authorized';
END IF;

SELECT to_jsonb(t) INTO result
FROM (
SELECT id, google_maps_api_key, twilio_account_sid, twilio_auth_token,
twilio_phone_number, gemini_api_key, openai_api_key, zip_tax_api_key,
taxjar_api_key, stripe_invoice_secret_key, bill_com_api_key
FROM public.company_settings
LIMIT 1
) t;

RETURN COALESCE(result, '{}'::jsonb);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_contact_counts(p_view_filter text DEFAULT 'all'::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_base_filter text;
  v_result jsonb;
BEGIN
  SELECT organization_id INTO v_org_id FROM profiles WHERE id = auth.uid();
  IF v_org_id IS NULL THEN
    RETURN jsonb_build_object('total', 0, 'customers', 0, 'prospects', 0, 'leads', 0, 'on_fire', 0, 'hot', 0, 'warm', 0, 'cold', 0);
  END IF;
  IF p_view_filter = 'my' AND p_user_id IS NOT NULL THEN
    v_base_filter := format('organization_id = %L AND (created_by = %L OR assigned_to = %L)', v_org_id, p_user_id, p_user_id);
  ELSE
    v_base_filter := format('organization_id = %L', v_org_id);
  END IF;
  EXECUTE format($f$
    SELECT jsonb_build_object(
      'total', count(*),
      'customers', count(*) FILTER (WHERE contact_type NOT IN ('lead','prospect')),
      'prospects', count(*) FILTER (WHERE contact_type = 'prospect'),
      'leads', count(*) FILTER (WHERE contact_type = 'lead'),
      'on_fire', count(*) FILTER (WHERE contact_type IN ('lead','prospect') AND temperature = 'on_fire'),
      'hot', count(*) FILTER (WHERE contact_type IN ('lead','prospect') AND temperature = 'hot'),
      'warm', count(*) FILTER (WHERE contact_type IN ('lead','prospect') AND temperature = 'warm'),
      'cold', count(*) FILTER (WHERE contact_type IN ('lead','prospect') AND temperature = 'cold')
    )
    FROM contacts WHERE %s
  $f$, v_base_filter) INTO v_result;
  RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_contact_portal_access_level(p_contact_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_access_level text := 'no_access';
v_has_vip boolean := false;
v_has_test_tune boolean := false;
v_has_promotional boolean := false;
v_has_active_proposal boolean := false;
BEGIN
-- Check for active VIP subscription (active or trial)
SELECT EXISTS (
SELECT 1 
FROM recurring_subscriptions rs
JOIN recurring_plans rp ON rs.plan_id = rp.id
WHERE rs.contact_id = p_contact_id
AND rs.status IN ('active', 'trial')
AND rp.plan_type = 'vip'
LIMIT 1
) INTO v_has_vip;

IF v_has_vip THEN
RETURN 'full_portal';
END IF;

-- Check for promotional punchlist access grant
SELECT EXISTS (
SELECT 1 FROM punchlist_access_grants
WHERE contact_id = p_contact_id
AND access_type = 'promotional'
AND status = 'active'
AND (expiration_date IS NULL OR expiration_date >= CURRENT_DATE)
LIMIT 1
) INTO v_has_promotional;

IF v_has_promotional THEN
RETURN 'full_portal';
END IF;

-- Check for active Test & Tune access
SELECT EXISTS (
SELECT 1 FROM punchlist_access_grants
WHERE contact_id = p_contact_id
AND access_type = 'test_and_tune'
AND status = 'active'
AND (expiration_date IS NULL OR expiration_date >= CURRENT_DATE)
LIMIT 1
) INTO v_has_test_tune;

IF v_has_test_tune THEN
RETURN 'full_portal';
END IF;

-- Check for active proposal that grants portal access
SELECT EXISTS (
SELECT 1 FROM proposals
WHERE contact_id = p_contact_id
AND status IN ('sent', 'viewed', 'approved', 'approved_pending_action')
LIMIT 1
) INTO v_has_active_proposal;

IF v_has_active_proposal THEN
RETURN 'proposal_only';
END IF;

RETURN 'no_access';
END;
$function$


CREATE OR REPLACE FUNCTION public.get_contacts_with_balance(p_limit integer DEFAULT 50, p_search text DEFAULT ''::text, p_type_filter text DEFAULT 'all'::text, p_temperature_filter text DEFAULT 'all'::text, p_view_filter text DEFAULT 'all'::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_result jsonb;
BEGIN
SELECT organization_id INTO v_org_id
FROM profiles
WHERE id = auth.uid();

IF v_org_id IS NULL THEN
RETURN jsonb_build_object('contacts', '[]'::jsonb, 'total', 0);
END IF;

WITH filtered_contacts AS (
SELECT c.*,
count(*) OVER () AS matching_total
FROM contacts c
WHERE c.organization_id = v_org_id
AND (p_view_filter <> 'my' OR c.created_by = auth.uid() OR c.assigned_to = auth.uid())
AND (
p_type_filter = 'all'
OR (p_type_filter = 'lead' AND c.contact_type = 'lead')
OR (p_type_filter = 'prospect' AND c.contact_type = 'prospect')
OR (p_type_filter = 'customer' AND c.contact_type NOT IN ('lead', 'prospect'))
)
AND (
p_temperature_filter = 'all'
OR (
c.temperature = p_temperature_filter
AND (p_type_filter <> 'all' OR c.contact_type IN ('lead', 'prospect'))
)
)
AND (
COALESCE(trim(p_search), '') = ''
OR c.first_name ILIKE '%' || p_search || '%'
OR c.last_name ILIKE '%' || p_search || '%'
OR c.contact_name ILIKE '%' || p_search || '%'
OR c.company_name ILIKE '%' || p_search || '%'
OR c.email ILIKE '%' || p_search || '%'
OR c.phone ILIKE '%' || p_search || '%'
)
ORDER BY c.last_name ASC NULLS LAST, c.first_name ASC NULLS LAST, c.company_name ASC NULLS LAST
LIMIT GREATEST(0, LEAST(COALESCE(p_limit, 50), 200))
),
contact_rows AS (
SELECT fc.*,
COALESCE(b.balance_due, 0) AS balance_due,
COALESCE(p.first_name || ' ' || p.last_name, p.first_name, p.last_name, '') AS assigned_rep_name,
COALESCE(co.office_name, '') AS office_name,
COALESCE((
SELECT jsonb_agg(jsonb_build_object('id', ct.id, 'tag', ct.tag, 'color', ct.color))
FROM contact_tags ct
WHERE ct.contact_id = fc.id
), '[]'::jsonb) AS tags
FROM filtered_contacts fc
LEFT JOIN profiles p ON p.id = fc.assigned_to
LEFT JOIN company_offices co ON co.id = fc.office_id
LEFT JOIN (
SELECT i.contact_id, COALESCE(SUM(i.amount_due), 0) AS balance_due
FROM invoices i
WHERE i.status NOT IN ('voided', 'paid')
AND i.organization_id = v_org_id
GROUP BY i.contact_id
) b ON b.contact_id = fc.id
)
SELECT jsonb_build_object(
'contacts', COALESCE(jsonb_agg(jsonb_build_object(
'id', id,
'contact_name', contact_name,
'first_name', first_name,
'last_name', last_name,
'company_name', company_name,
'email', email,
'phone', phone,
'contact_type', contact_type,
'temperature', temperature,
'portal_access_enabled', portal_access_enabled,
'business_card_photo', business_card_photo,
'last_contact_date', last_contact_date,
'next_follow_up', next_follow_up,
'assigned_to', assigned_to,
'office_id', office_id,
'assigned_rep_name', assigned_rep_name,
'office_name', office_name,
'balance_due', balance_due,
'tags', tags
)), '[]'::jsonb),
'total', COALESCE(max(matching_total), 0)
)
INTO v_result
FROM contact_rows;

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_customer_billing_preference(p_contact_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_preference text;
BEGIN
-- Try to get the stored preference
SELECT billing_preference
INTO v_preference
FROM customer_billing_preferences
WHERE contact_id = p_contact_id;

IF v_preference IS NOT NULL THEN
RETURN v_preference;
END IF;

-- Fall back to company default
SELECT default_billing_preference
INTO v_preference
FROM company_settings
LIMIT 1;

RETURN COALESCE(v_preference, 'monthly');
END;
$function$


CREATE OR REPLACE FUNCTION public.get_customer_purchased_equipment(p_contact_id uuid)
 RETURNS TABLE(product_id uuid, product_name text, manufacturer text, model_number text, sku text, category text, quantity numeric, unit_price numeric, line_total numeric, proposal_id uuid, sales_order_id uuid, project_id uuid, purchase_date date, age_months integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
p.id AS product_id,
p.name AS product_name,
p.manufacturer,
p.model_number,
p.sku,
p.category,
pli.quantity,
pli.unit_price,
pli.line_total,
prop.id AS proposal_id,
so.id AS sales_order_id,
proj.id AS project_id,
COALESCE(
proj.actual_completion_date::date,
so.first_completion_date::date,
so.created_at::date
) AS purchase_date,
CASE
WHEN COALESCE(
proj.actual_completion_date::date,
so.first_completion_date::date,
so.created_at::date
) IS NOT NULL
THEN EXTRACT(YEAR FROM age(now(), COALESCE(
proj.actual_completion_date::date,
so.first_completion_date::date,
so.created_at::date
)))::integer * 12 + EXTRACT(MONTH FROM age(now(), COALESCE(
proj.actual_completion_date::date,
so.first_completion_date::date,
so.created_at::date
)))::integer
ELSE NULL
END AS age_months
FROM proposals prop
INNER JOIN proposal_line_items pli ON pli.proposal_id = prop.id
LEFT JOIN products p ON p.id = pli.product_id
LEFT JOIN sales_orders so ON so.proposal_id = prop.id
LEFT JOIN projects proj ON proj.sales_order_id = so.id
WHERE prop.contact_id = p_contact_id
AND pli.product_id IS NOT NULL
AND p.item_type = 'material'
AND pli.is_hidden = false
ORDER BY COALESCE(
proj.actual_completion_date::date,
so.first_completion_date::date,
so.created_at::date
) DESC NULLS LAST;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_default_company_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT id FROM company_settings LIMIT 1;
$function$


CREATE OR REPLACE FUNCTION public.get_effective_commission_rate(p_employee_id uuid, p_role_type text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_custom_rate numeric;
v_default_rate numeric;
v_settings record;
BEGIN
-- Get company settings
SELECT * INTO v_settings FROM company_commission_settings LIMIT 1;

-- Get employee custom rate if exists
SELECT 
CASE p_role_type
WHEN 'sales_projects' THEN custom_sales_projects_rate
WHEN 'design' THEN custom_design_rate
WHEN 'pm' THEN custom_pm_rate
WHEN 'service_sales' THEN custom_service_sales_rate
WHEN 'service_pm' THEN custom_service_pm_rate
END INTO v_custom_rate
FROM employee_commission_config
WHERE employee_id = p_employee_id
AND eligible_for_commissions = true;

-- Return custom rate if set, otherwise return default
IF v_custom_rate IS NOT NULL THEN
RETURN v_custom_rate;
END IF;

-- Return default rate
RETURN CASE p_role_type
WHEN 'sales_projects' THEN v_settings.default_sales_projects_rate
WHEN 'design' THEN v_settings.default_design_rate
WHEN 'pm' THEN v_settings.default_pm_rate
WHEN 'service_sales' THEN v_settings.default_service_sales_rate
WHEN 'service_pm' THEN v_settings.default_service_pm_rate
END;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_finance_dashboard_metrics(p_month_start date, p_month_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_result jsonb;
BEGIN
v_org_id := get_user_org_id();

SELECT jsonb_build_object(
'sales_invoiced', COALESCE(SUM(total) FILTER (
WHERE status NOT IN ('draft', 'void')
), 0),
'monthly_sales_invoiced', COALESCE(SUM(total) FILTER (
WHERE status NOT IN ('draft', 'void')
AND invoice_date >= p_month_start
AND invoice_date <= p_month_end
), 0),
'accounts_receivable', COALESCE(SUM(amount_due) FILTER (
WHERE status NOT IN ('draft', 'void')
), 0),
'paid_invoices', COUNT(*) FILTER (
WHERE status = 'paid'
),
'partial_invoices', COUNT(*) FILTER (
WHERE status = 'partial'
),
'overdue_invoices', COUNT(*) FILTER (
WHERE status = 'overdue'
OR (amount_due > 0 AND due_date IS NOT NULL AND due_date::text < p_month_start::text)
)
)
INTO v_result
FROM invoices
WHERE organization_id = v_org_id;

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_flow_events(p_filters jsonb DEFAULT '{}'::jsonb, p_before bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50)
 RETURNS SETOF jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 SELECT to_jsonb(e)||jsonb_build_object('viewed',v.event_id IS NOT NULL,
  'preview',CASE e.source_table
   WHEN 'messages' THEN (SELECT left(m.body,140) FROM public.messages m WHERE m.id=e.source_id)
   WHEN 'discussion_posts' THEN (SELECT left(d.content,140) FROM public.discussion_posts d WHERE d.id=e.source_id)
   WHEN 'task_comments' THEN (SELECT left(tc.content,140) FROM public.task_comments tc WHERE tc.id=e.source_id)
   ELSE NULL END)
 FROM public.flow_events e LEFT JOIN public.flow_event_views v ON v.event_id=e.id AND v.user_id=(SELECT auth.uid())
 WHERE (p_before IS NULL OR e.id<p_before)
 AND (nullif(p_filters->>'contact_id','') IS NULL OR e.contact_id=(p_filters->>'contact_id')::uuid)
 AND (nullif(p_filters->>'project_id','') IS NULL OR e.project_id=(p_filters->>'project_id')::uuid)
 AND (nullif(p_filters->>'work_order_id','') IS NULL OR e.work_order_id=(p_filters->>'work_order_id')::uuid)
 AND (nullif(p_filters->>'location_id','') IS NULL OR e.customer_location_id=(p_filters->>'location_id')::uuid)
 AND (nullif(p_filters->>'office_id','') IS NULL OR e.office_id=(p_filters->>'office_id')::uuid)
 AND (nullif(p_filters->>'actor_id','') IS NULL OR e.actor_id=(p_filters->>'actor_id')::uuid)
 AND (nullif(p_filters->>'category','') IS NULL OR e.category=p_filters->>'category')
 AND (nullif(p_filters->>'source_id','') IS NULL OR e.source_table='flow_updates' AND e.source_id=(p_filters->>'source_id')::uuid)
 AND (nullif(p_filters->>'kind','') IS NULL OR CASE p_filters->>'kind'
  WHEN 'messages' THEN e.source_table='messages'
  WHEN 'discussions' THEN e.source_table='discussion_posts'
  WHEN 'tasks' THEN e.source_table IN ('tasks','task_comments')
  WHEN 'updates' THEN e.category='update'
  WHEN 'activity' THEN e.source_table NOT IN ('messages','discussion_posts','tasks','task_comments') AND e.category<>'update'
  ELSE false END)
 AND (nullif(p_filters->>'since','') IS NULL OR e.created_at>=(p_filters->>'since')::timestamptz)
 AND (nullif(p_filters->>'until','') IS NULL OR e.created_at<(p_filters->>'until')::timestamptz)
 AND (NOT coalesce((p_filters->>'new_only')::boolean,false) OR v.event_id IS NULL)
 AND (nullif(trim(p_filters->>'search'),'') IS NULL OR
  position(lower(trim(p_filters->>'search')) IN lower(concat_ws(' ',e.customer_name,e.project_name,e.work_order_number,e.location_name,e.summary,e.actor_name)))>0)
 AND (NOT coalesce((p_filters->>'mentions_only')::boolean,false) OR (SELECT auth.uid())=ANY(e.mentioned_user_ids))
 AND (NOT coalesce((p_filters->>'my_work')::boolean,false) OR e.actor_id=(SELECT auth.uid())
  OR (SELECT auth.uid())=ANY(e.mentioned_user_ids)
  OR (e.source_table='discussion_posts' AND EXISTS (
    SELECT 1 FROM public.discussion_posts d WHERE d.id=e.source_id AND (SELECT auth.uid()) IN (d.user_id,d.assigned_to)))
  OR (e.source_table='messages' AND EXISTS (
   SELECT 1 FROM public.message_threads t WHERE t.id=e.thread_id AND t.organization_id=e.organization_id
    AND (t.created_by=(SELECT auth.uid()) OR t.assigned_sales_rep_id=(SELECT auth.uid())
     OR (t.context_type NOT IN ('project','work_order') AND EXISTS (SELECT 1 FROM public.contacts c WHERE c.id=t.contact_id AND c.assigned_to=(SELECT auth.uid())))
     OR EXISTS (SELECT 1 FROM public.projects p WHERE p.organization_id=t.organization_id
       AND (t.context_type='project' AND p.id=t.context_id OR t.context_type NOT IN ('project','work_order') AND p.contact_id=t.contact_id)
       AND (SELECT auth.uid()) IN (p.assigned_pm,p.salesperson_id,p.designer_id))
     OR EXISTS (SELECT 1 FROM public.work_orders w WHERE w.organization_id=t.organization_id
       AND (t.context_type='work_order' AND w.id=t.context_id OR t.context_type NOT IN ('project','work_order') AND w.contact_id=t.contact_id)
       AND (SELECT auth.uid()) IN (w.assigned_to,w.customer_sales_rep_id))
     OR EXISTS (SELECT 1 FROM public.profiles me WHERE me.id=(SELECT auth.uid())
       AND me.role='service_manager' AND t.context_type IN ('work_order','service_request')))))
  OR EXISTS (SELECT 1 FROM public.projects p WHERE p.id=e.project_id AND p.organization_id=e.organization_id AND (SELECT auth.uid()) IN (p.assigned_pm,p.salesperson_id,p.designer_id))
  OR EXISTS (SELECT 1 FROM public.work_orders w WHERE w.organization_id=e.organization_id AND (w.id=e.work_order_id OR (e.project_id IS NOT NULL AND w.project_id=e.project_id)) AND (SELECT auth.uid()) IN (w.assigned_to,w.customer_sales_rep_id))
  OR (e.project_id IS NULL AND e.work_order_id IS NULL AND EXISTS (SELECT 1 FROM public.contacts c WHERE c.id=e.contact_id AND c.organization_id=e.organization_id AND c.assigned_to=(SELECT auth.uid())))
 )
 ORDER BY e.id DESC LIMIT least(greatest(p_limit,1),100);
$function$


CREATE OR REPLACE FUNCTION public.get_gps_quality_report(p_technician_id uuid, p_start_date date, p_end_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result JSONB;
BEGIN
SELECT jsonb_build_object(
'total_points', COUNT(*),
'avg_accuracy', AVG(accuracy),
'min_accuracy', MIN(accuracy),
'max_accuracy', MAX(accuracy),
'high_accuracy_percent', (COUNT(*) FILTER (WHERE accuracy < 10) * 100.0 / NULLIF(COUNT(*), 0)),
'medium_accuracy_percent', (COUNT(*) FILTER (WHERE accuracy >= 10 AND accuracy <= 50) * 100.0 / NULLIF(COUNT(*), 0)),
'low_accuracy_percent', (COUNT(*) FILTER (WHERE accuracy > 50) * 100.0 / NULLIF(COUNT(*), 0)),
'avg_battery', AVG(battery_level),
'devices_used', jsonb_agg(DISTINCT device_model)
)
INTO v_result
FROM enhanced_gps_breadcrumbs
WHERE technician_id = p_technician_id
AND DATE(captured_at) BETWEEN p_start_date AND p_end_date;

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_latest_technician_locations()
 RETURNS TABLE(technician_id uuid, technician_name text, technician_role text, latitude real, longitude real, accuracy real, speed real, heading real, captured_at timestamp with time zone, battery_level real, device_model text, status text, clock_entry_id uuid, clock_in_time timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH latest_locations AS (
SELECT DISTINCT ON (egb.technician_id)
egb.technician_id,
egb.latitude,
egb.longitude,
egb.accuracy,
egb.speed,
egb.heading,
egb.captured_at,
egb.battery_level,
egb.device_model,
egb.daily_clock_entry_id
FROM enhanced_gps_breadcrumbs egb
INNER JOIN daily_clock_entries dce ON dce.id = egb.daily_clock_entry_id
WHERE dce.status = 'clocked_in'
AND dce.clock_out IS NULL
AND dce.entry_date = CURRENT_DATE
ORDER BY egb.technician_id, egb.captured_at DESC
)
SELECT
ll.technician_id,
COALESCE(p.full_name, p.email) as technician_name,
p.role as technician_role,
ll.latitude,
ll.longitude,
ll.accuracy,
ll.speed,
ll.heading,
ll.captured_at,
ll.battery_level,
ll.device_model,
dce.status,
dce.id as clock_entry_id,
dce.clock_in as clock_in_time
FROM latest_locations ll
INNER JOIN profiles p ON p.id = ll.technician_id
INNER JOIN daily_clock_entries dce ON dce.id = ll.daily_clock_entry_id
ORDER BY ll.captured_at DESC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_line_item_phase_count(p_line_item_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT COUNT(*)::integer
FROM proposal_line_item_labor_phases
