$function$


CREATE OR REPLACE FUNCTION public.get_line_item_total_labor_hours(p_line_item_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT COALESCE(SUM(hours), 0)
FROM proposal_line_item_labor_phases
WHERE line_item_id = p_line_item_id;
$function$


CREATE OR REPLACE FUNCTION public.get_my_sales_dashboard(p_date_reference date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_rep_id uuid := auth.uid();
v_result jsonb;
BEGIN
IF v_rep_id IS NULL THEN
RETURN jsonb_build_object('error', 'not_authenticated');
END IF;

-- Delegate to get_sales_rep_dashboard with target = self
SELECT * FROM get_sales_rep_dashboard(v_rep_id, p_date_reference) INTO v_result;
RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_next_order_number()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
v_next_num integer;
v_order_number text;
BEGIN
-- Get the highest existing order number (assumes format: SO-YYYY-NNNN)
SELECT COALESCE(MAX(CAST(SUBSTRING(order_number FROM '\\d+$') AS integer)), 0) + 1
INTO v_next_num
FROM sales_orders
WHERE order_number ~ '^SO-\\d{4}-\\d+$';

-- Generate new order number with current year
v_order_number := 'SO-' || TO_CHAR(CURRENT_DATE, 'YYYY') || '-' || LPAD(v_next_num::text, 4, '0');

RETURN v_order_number;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_next_project_number()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
v_next_num integer;
v_project_number text;
BEGIN
-- Get the highest existing project number (assumes format: PRJ-YYYY-NNNN)
SELECT COALESCE(MAX(CAST(SUBSTRING(project_number FROM '\\d+$') AS integer)), 0) + 1
INTO v_next_num
FROM projects
WHERE project_number ~ '^PRJ-\\d{4}-\\d+$';

-- Generate new project number with current year
v_project_number := 'PRJ-' || TO_CHAR(CURRENT_DATE, 'YYYY') || '-' || LPAD(v_next_num::text, 4, '0');

RETURN v_project_number;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_platform_pricing()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_pricing platform_pricing%ROWTYPE;
BEGIN
SELECT * INTO v_pricing
FROM platform_pricing
WHERE is_active = true
LIMIT 1;

IF NOT FOUND THEN
RETURN jsonb_build_object(
'base_price', 50,
'per_user_price', 10,
'included_users', 1,
'billing_interval', 'monthly'
);
END IF;

RETURN jsonb_build_object(
'id', v_pricing.id,
'base_price', v_pricing.base_price,
'per_user_price', v_pricing.per_user_price,
'included_users', v_pricing.included_users,
'billing_interval', v_pricing.billing_interval
);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_proposal_activity_summary(p_proposal_id uuid)
 RETURNS TABLE(total_views bigint, total_time_seconds bigint, last_viewed_at timestamp with time zone, unique_sessions bigint, unique_viewers bigint, unique_ips jsonb, device_breakdown jsonb, browser_breakdown jsonb, os_breakdown jsonb, activity_timeline jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH ip_counts AS (
SELECT 
ip_address,
COUNT(*) as view_count,
MAX(created_at) as last_seen,
MAX(metadata->>'deviceType') as device_type,
MAX(metadata->>'browser') as browser,
MAX(metadata->>'os') as os
FROM proposal_activity
WHERE proposal_id = p_proposal_id 
AND activity_type = 'viewed'
AND ip_address IS NOT NULL
AND ip_address != 'Unknown'
GROUP BY ip_address
),
device_stats AS (
SELECT 
metadata->>'deviceType' as device_type,
COUNT(*) as count
FROM proposal_activity
WHERE proposal_id = p_proposal_id 
AND activity_type = 'viewed'
AND metadata->>'deviceType' IS NOT NULL
GROUP BY metadata->>'deviceType'
),
browser_stats AS (
SELECT 
metadata->>'browser' as browser,
COUNT(*) as count
FROM proposal_activity
WHERE proposal_id = p_proposal_id 
AND activity_type = 'viewed'
AND metadata->>'browser' IS NOT NULL
GROUP BY metadata->>'browser'
),
os_stats AS (
SELECT 
metadata->>'os' as os,
COUNT(*) as count
FROM proposal_activity
WHERE proposal_id = p_proposal_id 
AND activity_type = 'viewed'
AND metadata->>'os' IS NOT NULL
GROUP BY metadata->>'os'
)
SELECT
COUNT(*) FILTER (WHERE activity_type = 'viewed') as total_views,
SUM(duration_seconds) FILTER (WHERE activity_type = 'time_spent') as total_time_seconds,
MAX(created_at) FILTER (WHERE activity_type = 'viewed') as last_viewed_at,
COUNT(DISTINCT user_agent) as unique_sessions,
(SELECT COUNT(*) FROM ip_counts) as unique_viewers,
COALESCE(
(SELECT jsonb_agg(
jsonb_build_object(
'ip', ip_address,
'views', view_count,
'lastSeen', last_seen,
'deviceType', device_type,
'browser', browser,
'os', os
) ORDER BY view_count DESC
) FROM ip_counts),
'[]'::jsonb
) as unique_ips,
COALESCE(
(SELECT jsonb_object_agg(device_type, count) FROM device_stats),
'{}'::jsonb
) as device_breakdown,
COALESCE(
(SELECT jsonb_object_agg(browser, count) FROM browser_stats),
'{}'::jsonb
) as browser_breakdown,
COALESCE(
(SELECT jsonb_object_agg(os, count) FROM os_stats),
'{}'::jsonb
) as os_breakdown,
COALESCE(
jsonb_agg(
jsonb_build_object(
'type', activity_type,
'created_at', created_at,
'duration', duration_seconds,
'ip_address', ip_address,
'deviceType', metadata->>'deviceType',
'browser', metadata->>'browser',
'os', metadata->>'os'
) ORDER BY created_at DESC
) FILTER (WHERE activity_type IN ('viewed', 'downloaded', 'accepted', 'declined')),
'[]'::jsonb
) as activity_timeline
FROM proposal_activity
WHERE proposal_id = p_proposal_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_proposal_payment_methods(p_proposal_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_methods text[];
BEGIN
-- Get payment methods from proposal settings (if set), otherwise from customer profile
SELECT
COALESCE(ps.payment_methods_allowed, c.payment_methods_allowed, ARRAY['payment', 'purchase_order']::text[])
INTO v_methods
FROM proposals p
LEFT JOIN proposal_settings ps ON ps.proposal_id = p.id
LEFT JOIN contacts c ON c.id = p.contact_id
WHERE p.id = p_proposal_id;

RETURN COALESCE(v_methods, ARRAY['payment', 'purchase_order']::text[]);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_proposal_sales_order_id(p_proposal_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sales_order_id uuid;
v_org_id uuid;
BEGIN
-- Ensure the caller belongs to the same org as the proposal
SELECT organization_id INTO v_org_id
FROM profiles
WHERE id = auth.uid();

SELECT sales_order_id INTO v_sales_order_id
FROM proposals
WHERE id = p_proposal_id
AND organization_id = v_org_id;

RETURN v_sales_order_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_proposal_unread_count(p_proposal_id uuid, p_sender_type text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN (
SELECT COUNT(*)
FROM proposal_messages
WHERE proposal_id = p_proposal_id
AND sender_type != p_sender_type
AND is_read = false
);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_punchlist_access_info(p_contact_id uuid)
 RETURNS TABLE(has_access boolean, access_type text, days_remaining integer, expiration_date date, subscription_plan_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid; v_contact uuid; v_role text;
BEGIN
 SELECT organization_id,contact_id,role INTO v_org,v_contact,v_role FROM profiles WHERE id=auth.uid() AND is_active;
 IF v_org IS NULL OR NOT EXISTS(SELECT 1 FROM contacts WHERE id=p_contact_id AND organization_id=v_org) OR
  (v_contact IS DISTINCT FROM p_contact_id AND (v_contact IS NOT NULL OR v_role IN ('customer','portal','client'))) THEN RAISE EXCEPTION 'Not authorized'; END IF;
 RETURN QUERY
 SELECT true,'vip_membership'::text,NULL::integer,NULL::date,rp.plan_name
 FROM recurring_subscriptions rs LEFT JOIN recurring_plans rp ON rp.id=rs.plan_id
 WHERE rs.contact_id=p_contact_id AND rs.organization_id=v_org AND rs.status='active' AND rp.plan_type='vip_plan'
 AND (rs.end_date IS NULL OR rs.end_date>=CURRENT_DATE) AND rs.next_billing_date>=CURRENT_DATE LIMIT 1;
 IF FOUND THEN RETURN; END IF;
 RETURN QUERY SELECT true,pag.access_type,
 CASE WHEN pag.expiration_date IS NULL THEN NULL ELSE pag.expiration_date-CURRENT_DATE END,pag.expiration_date,rp.plan_name
 FROM punchlist_access_grants pag LEFT JOIN recurring_subscriptions rs ON rs.id=pag.subscription_id LEFT JOIN recurring_plans rp ON rp.id=rs.plan_id
 WHERE pag.contact_id=p_contact_id AND pag.organization_id=v_org AND pag.status='active' AND (pag.expiration_date IS NULL OR pag.expiration_date>=CURRENT_DATE)
 AND (pag.access_type<>'vip_trial' OR (rs.status IN ('trial','active') AND rs.trial_source='vip_trial' AND rs.trial_end_date>=CURRENT_DATE))
 ORDER BY CASE pag.access_type WHEN 'vip_trial' THEN 0 WHEN 'test_and_tune' THEN 1 ELSE 2 END,pag.expiration_date DESC NULLS FIRST LIMIT 1;
END $function$


CREATE OR REPLACE FUNCTION public.get_recent_auto_clock_outs(days_ago integer DEFAULT 7)
 RETURNS TABLE(entry_id uuid, technician_id uuid, technician_name text, clock_in_at timestamp with time zone, clock_out_at timestamp with time zone, auto_clocked_out_at timestamp with time zone, points_deducted integer, clock_in_latitude numeric, clock_in_longitude numeric, clock_out_latitude numeric, clock_out_longitude numeric, clock_in_address text, clock_out_address text, clock_in_gps_accuracy real, clock_out_gps_accuracy real, clock_in_gps_capture_method text, clock_out_gps_capture_method text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT 
dce.id,
dce.technician_id,
p.full_name,
dce.clock_in,
dce.clock_out,
dce.auto_clocked_out_at,
dce.points_deducted,
dce.clock_in_latitude,
dce.clock_in_longitude,
dce.clock_out_latitude,
dce.clock_out_longitude,
dce.clock_in_address,
dce.clock_out_address,
dce.clock_in_gps_accuracy,
dce.clock_out_gps_accuracy,
dce.clock_in_gps_capture_method,
dce.clock_out_gps_capture_method
FROM daily_clock_entries dce
JOIN profiles p ON p.id = dce.technician_id
WHERE dce.auto_clocked_out = true
AND dce.auto_clocked_out_at >= now() - (days_ago || ' days')::interval
ORDER BY dce.auto_clocked_out_at DESC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_recently_used_products(p_company_id uuid, p_limit integer DEFAULT 10)
 RETURNS TABLE(product_id uuid, usage_count bigint, last_used timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
ili.product_id,
COUNT(*) as usage_count,
MAX(i.created_at) as last_used
FROM invoice_line_items ili
JOIN invoices i ON ili.invoice_id = i.id
WHERE ili.product_id IS NOT NULL
AND i.company_id = p_company_id
AND i.created_at >= NOW() - INTERVAL '90 days'
GROUP BY ili.product_id
ORDER BY MAX(i.created_at) DESC
LIMIT p_limit;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_root_proposal_id(p_proposal_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_parent_id uuid;
v_current_id uuid := p_proposal_id;
BEGIN
-- If this is not a revision, return itself
SELECT parent_proposal_id INTO v_parent_id FROM proposals WHERE id = v_current_id;

IF v_parent_id IS NULL THEN
RETURN v_current_id;
END IF;

-- Traverse up to find root
WHILE v_parent_id IS NOT NULL LOOP
v_current_id := v_parent_id;
SELECT parent_proposal_id INTO v_parent_id FROM proposals WHERE id = v_current_id;
END LOOP;

RETURN v_current_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_sales_goal_leaderboard(p_date_reference date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_id uuid := auth.uid();
v_caller_org uuid;
v_results jsonb := '[]'::jsonb;
v_row record;
v_rank int := 0;
v_quota numeric;
v_booked numeric;
v_attainment numeric;
v_display_name text;
v_is_current boolean;
v_prev_booked numeric;
v_trend text;
v_raw_start date;
v_years_elapsed int;
v_q_start date;
v_q_end date;
v_q_start_year int;
v_q_end_year int;
v_q_start_month int;
v_q_end_month int;
v_prev_q_start date;
v_prev_q_end date;
BEGIN
IF v_caller_id IS NULL THEN
RETURN jsonb_build_object('error', 'not_authenticated');
END IF;

v_caller_org := get_caller_org_id(v_caller_id);
IF v_caller_org IS NULL THEN
RETURN jsonb_build_object('error', 'no_organization');
END IF;

CREATE TEMP TABLE IF NOT EXISTS _leaderboard_temp (
rep_id uuid,
display_name text,
quota numeric,
booked numeric,
prev_booked numeric,
is_current boolean
);
DELETE FROM _leaderboard_temp;

FOR v_row IN
SELECT p.id, p.first_name, p.last_name, p.full_name,
COALESCE(p.current_annual_quota, 0) AS quota,
COALESCE(p.sales_rep_start_date, p.created_at::date) AS raw_start
FROM profiles p
WHERE p.organization_id = v_caller_org
AND p.can_create_proposals = true
LOOP
v_raw_start := COALESCE(v_row.raw_start, p_date_reference);
v_years_elapsed := GREATEST(0, EXTRACT(YEAR FROM AGE(p_date_reference, v_raw_start))::int);
v_q_start := (v_raw_start + (v_years_elapsed || ' years')::interval)::date;
v_q_end := (v_raw_start + ((v_years_elapsed + 1) || ' years')::interval - INTERVAL '1 day')::date;
v_prev_q_start := (v_raw_start + ((v_years_elapsed - 1) || ' years')::interval)::date;
v_prev_q_end := (v_raw_start + (v_years_elapsed || ' years')::interval - INTERVAL '1 day')::date;

v_q_start_year := EXTRACT(YEAR FROM v_q_start)::int;
v_q_end_year := EXTRACT(YEAR FROM v_q_end)::int;
v_q_start_month := EXTRACT(MONTH FROM v_q_start)::int;
v_q_end_month := EXTRACT(MONTH FROM v_q_end)::int;

v_booked := 0;
v_prev_booked := 0;

-- Full years within quota period from yearly_sales_performance
SELECT COALESCE(SUM(total_revenue), 0) INTO v_booked
FROM yearly_sales_performance
WHERE user_id = v_row.id AND year > v_q_start_year AND year < v_q_end_year;

-- Partial start year from monthly_stats
SELECT COALESCE(SUM(total_sales), 0) + v_booked INTO v_booked
FROM sales_monthly_stats
WHERE user_id = v_row.id AND year = v_q_start_year AND month >= v_q_start_month;

-- Full years from monthly_stats not in yearly
IF v_q_end_year > v_q_start_year + 1 THEN
SELECT COALESCE(SUM(sms.total_sales), 0) + v_booked INTO v_booked
FROM sales_monthly_stats sms
WHERE sms.user_id = v_row.id
AND sms.year > v_q_start_year AND sms.year < v_q_end_year
AND NOT EXISTS (
SELECT 1 FROM yearly_sales_performance ysp
WHERE ysp.user_id = v_row.id AND ysp.year = sms.year
);
END IF;

-- Partial end year
IF v_q_end_year != v_q_start_year THEN
SELECT COALESCE(SUM(total_sales), 0) + v_booked INTO v_booked
FROM sales_monthly_stats
WHERE user_id = v_row.id AND year = v_q_end_year AND month <= v_q_end_month;
END IF;

-- Sales orders fallback
SELECT COALESCE(SUM(contract_total), 0) + v_booked INTO v_booked
FROM sales_orders so
WHERE (CASE WHEN so.sales_rep_id IS NOT NULL THEN so.sales_rep_id ELSE so.created_by END) = v_row.id
AND COALESCE(so.booked_at, so.created_at) >= v_q_start::timestamptz
AND COALESCE(so.booked_at, so.created_at) <= v_q_end::timestamptz
AND so.status NOT IN ('cancelled', 'voided')
AND NOT EXISTS (
SELECT 1 FROM sales_monthly_stats sms3
WHERE sms3.user_id = v_row.id
AND sms3.year = EXTRACT(YEAR FROM COALESCE(so.booked_at, so.created_at))::int
AND sms3.month = EXTRACT(MONTH FROM COALESCE(so.booked_at, so.created_at))::int
);

-- Previous period
SELECT COALESCE(SUM(total_revenue), 0) INTO v_prev_booked
FROM yearly_sales_performance
WHERE user_id = v_row.id
AND year > EXTRACT(YEAR FROM v_prev_q_start)::int
AND year < EXTRACT(YEAR FROM v_prev_q_end)::int;

SELECT COALESCE(SUM(total_sales), 0) + v_prev_booked INTO v_prev_booked
FROM sales_monthly_stats
WHERE user_id = v_row.id
AND year = EXTRACT(YEAR FROM v_prev_q_start)::int
AND month >= EXTRACT(MONTH FROM v_prev_q_start)::int;

IF EXTRACT(YEAR FROM v_prev_q_end)::int != EXTRACT(YEAR FROM v_prev_q_start)::int THEN
SELECT COALESCE(SUM(total_sales), 0) + v_prev_booked INTO v_prev_booked
FROM sales_monthly_stats
WHERE user_id = v_row.id
AND year = EXTRACT(YEAR FROM v_prev_q_end)::int
AND month <= EXTRACT(MONTH FROM v_prev_q_end)::int;
END IF;

v_display_name := CASE
WHEN v_row.first_name IS NOT NULL AND v_row.last_name IS NOT NULL
THEN v_row.first_name || ' ' || LEFT(v_row.last_name, 1) || '.'
ELSE COALESCE(v_row.full_name, 'Unknown')
END;

INSERT INTO _leaderboard_temp (rep_id, display_name, quota, booked, prev_booked, is_current)
VALUES (v_row.id, v_display_name, v_row.quota, v_booked, v_prev_booked, v_row.id = v_caller_id);
END LOOP;

-- Build sorted output with ranks
FOR v_row IN
SELECT display_name, quota, booked, prev_booked, is_current
FROM _leaderboard_temp
ORDER BY booked DESC
LOOP
v_rank := v_rank + 1;
v_attainment := CASE WHEN v_row.quota > 0 THEN ROUND((v_row.booked / v_row.quota) * 100, 1) ELSE 0 END;
v_trend := CASE
WHEN v_row.prev_booked = 0 AND v_row.booked > 0 THEN 'up'
WHEN v_row.booked > v_row.prev_booked THEN 'up'
WHEN v_row.booked < v_row.prev_booked THEN 'down'
ELSE 'flat'
END;

v_results := v_results || jsonb_build_object(
'rank', v_rank,
'repDisplayName', v_row.display_name,
'attainmentPct', v_attainment,
'trend', v_trend,
'isCurrentUser', v_row.is_current
);
END LOOP;

DROP TABLE IF EXISTS _leaderboard_temp;

RETURN jsonb_build_object('leaderboard', v_results, 'currentUserId', v_caller_id);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_sales_rep_dashboard(p_target_rep_id uuid, p_date_reference date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_id uuid := auth.uid();
v_caller_org uuid;
v_target_org uuid;
v_profile record;
v_quota_info jsonb;
v_annual_quota numeric;
v_monthly_quota numeric;
v_raw_start_date date;
v_years_elapsed int;
v_quota_start_date date;
v_quota_end_date date;
v_quota_elapsed_pct numeric;
v_booked_sales numeric := 0;
v_booked_count int := 0;
v_prev_booked_sales numeric := 0;
v_prev_booked_count int := 0;
v_pipeline_total numeric := 0;
v_pipeline_count int := 0;
v_won_count int := 0;
v_lost_count int := 0;
v_close_rate numeric := 0;
v_prev_won_count int := 0;
v_prev_lost_count int := 0;
v_prev_close_rate numeric := 0;
v_monthly_trend jsonb := '[]'::jsonb;
v_avg_sale numeric := 0;
v_run_rate_90 numeric := 0;
v_month_start timestamptz;
v_row record;
v_current_year int;
v_current_month int;
v_prev_year int;
v_stats_total numeric;
v_stats_count int;
v_so_total numeric;
v_so_count int;
v_month_total numeric;
v_month_count int;
v_prev_year_total numeric;
v_ytd_total numeric := 0;
v_ytd_count int := 0;
v_all_time_total numeric := 0;
v_quota_start_year int;
v_quota_end_year int;
v_quota_start_month int;
v_quota_end_month int;
v_prev_quota_start_date date;
v_prev_quota_end_date date;
BEGIN
IF v_caller_id IS NULL THEN
RETURN jsonb_build_object('error', 'not_authenticated');
END IF;

IF p_target_rep_id != v_caller_id THEN
IF NOT is_manager_or_admin(v_caller_id) THEN
RETURN jsonb_build_object('error', 'unauthorized');
END IF;
v_caller_org := get_caller_org_id(v_caller_id);
SELECT organization_id INTO v_target_org FROM profiles WHERE id = p_target_rep_id;
IF v_target_org IS NULL OR v_target_org != v_caller_org THEN
RETURN jsonb_build_object('error', 'unauthorized');
END IF;
END IF;

SELECT id, first_name, last_name, full_name, organization_id,
current_annual_quota, monthly_sales_target, sales_rep_start_date, created_at
INTO v_profile
FROM profiles WHERE id = p_target_rep_id;

IF NOT FOUND THEN
RETURN jsonb_build_object('error', 'rep_not_found');
END IF;

SELECT * FROM calculate_sales_quota(p_target_rep_id, p_date_reference) INTO v_quota_info;
v_annual_quota := COALESCE((v_quota_info->>'current_annual_quota')::numeric, 0);
v_monthly_quota := COALESCE((v_quota_info->>'current_monthly_quota')::numeric, 0);

-- Compute the CURRENT anniversary year window (not year 1)
v_raw_start_date := COALESCE(v_profile.sales_rep_start_date, v_profile.created_at::date, p_date_reference);
v_years_elapsed := GREATEST(0, EXTRACT(YEAR FROM AGE(p_date_reference, v_raw_start_date))::int);
v_quota_start_date := (v_raw_start_date + (v_years_elapsed || ' years')::interval)::date;
v_quota_end_date := (v_raw_start_date + ((v_years_elapsed + 1) || ' years')::interval - INTERVAL '1 day')::date;

-- Previous period (same window, one year earlier)
v_prev_quota_start_date := (v_raw_start_date + ((v_years_elapsed - 1) || ' years')::interval)::date;
v_prev_quota_end_date := (v_raw_start_date + (v_years_elapsed || ' years')::interval - INTERVAL '1 day')::date;

IF v_quota_end_date > v_quota_start_date THEN
v_quota_elapsed_pct := LEAST(100, ROUND(
(EXTRACT(EPOCH FROM (p_date_reference::timestamp - v_quota_start_date::timestamp)) /
EXTRACT(EPOCH FROM (v_quota_end_date::timestamp - v_quota_start_date::timestamp)) * 100)::numeric, 1
));
ELSE
v_quota_elapsed_pct := 100;
END IF;

v_current_year := EXTRACT(YEAR FROM p_date_reference)::int;
v_current_month := EXTRACT(MONTH FROM p_date_reference)::int;
v_prev_year := v_current_year - 1;

v_quota_start_year := EXTRACT(YEAR FROM v_quota_start_date)::int;
v_quota_end_year := EXTRACT(YEAR FROM v_quota_end_date)::int;
v_quota_start_month := EXTRACT(MONTH FROM v_quota_start_date)::int;
v_quota_end_month := EXTRACT(MONTH FROM v_quota_end_date)::int;

-- ── Booked sales for current quota period ───────────────────────
-- Priority: yearly_sales_performance (full years) + sales_monthly_stats (partial years) + sales_orders (fallback)
-- Full years within the quota period from yearly_sales_performance
SELECT COALESCE(SUM(total_revenue), 0)
INTO v_stats_total
FROM yearly_sales_performance
WHERE user_id = p_target_rep_id
AND year > v_quota_start_year
AND year < v_quota_end_year;

-- Partial start year from monthly_stats
SELECT COALESCE(SUM(total_sales), 0), COALESCE(SUM(sales_order_count), 0)
INTO v_so_total, v_so_count
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id
AND year = v_quota_start_year
AND month >= v_quota_start_month;

v_stats_total := v_stats_total + v_so_total;
v_stats_count := v_so_count;

-- Full years between start and end from monthly_stats (if not in yearly)
IF v_quota_end_year > v_quota_start_year + 1 THEN
SELECT COALESCE(SUM(sms.total_sales), 0), COALESCE(SUM(sms.sales_order_count), 0)
INTO v_so_total, v_so_count
FROM sales_monthly_stats sms
WHERE sms.user_id = p_target_rep_id
AND sms.year > v_quota_start_year AND sms.year < v_quota_end_year
AND NOT EXISTS (
SELECT 1 FROM yearly_sales_performance ysp
WHERE ysp.user_id = p_target_rep_id AND ysp.year = sms.year
);
v_stats_total := v_stats_total + v_so_total;
v_stats_count := v_stats_count + v_so_count;
END IF;

-- Partial end year from monthly_stats
IF v_quota_end_year != v_quota_start_year THEN
SELECT COALESCE(SUM(total_sales), 0), COALESCE(SUM(sales_order_count), 0)
INTO v_so_total, v_so_count
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id
AND year = v_quota_end_year
AND month <= v_quota_end_month;
v_stats_total := v_stats_total + v_so_total;
v_stats_count := v_stats_count + v_so_count;
END IF;

-- Sales orders fallback (for months not covered by monthly_stats)
SELECT COALESCE(SUM(contract_total), 0), COUNT(*)
INTO v_so_total, v_so_count
FROM sales_orders
WHERE (CASE WHEN sales_rep_id IS NOT NULL THEN sales_rep_id ELSE created_by END) = p_target_rep_id
AND COALESCE(booked_at, created_at) >= v_quota_start_date::timestamptz
AND COALESCE(booked_at, created_at) <= v_quota_end_date::timestamptz
AND status NOT IN ('cancelled', 'voided')
AND NOT EXISTS (
SELECT 1 FROM sales_monthly_stats sms
WHERE sms.user_id = p_target_rep_id
AND sms.year = EXTRACT(YEAR FROM COALESCE(sales_orders.booked_at, sales_orders.created_at))::int
AND sms.month = EXTRACT(MONTH FROM COALESCE(sales_orders.booked_at, sales_orders.created_at))::int
);

v_booked_sales := COALESCE(v_stats_total, 0) + COALESCE(v_so_total, 0);
v_booked_count := COALESCE(v_stats_count, 0) + COALESCE(v_so_count, 0);

-- ── Previous period ─────────────────────────────────────────────
v_stats_total := 0;
v_stats_count := 0;

SELECT COALESCE(SUM(total_revenue), 0)
INTO v_stats_total
FROM yearly_sales_performance
WHERE user_id = p_target_rep_id
AND year > EXTRACT(YEAR FROM v_prev_quota_start_date)::int
AND year < EXTRACT(YEAR FROM v_prev_quota_end_date)::int;

SELECT COALESCE(SUM(total_sales), 0), COALESCE(SUM(sales_order_count), 0)
INTO v_so_total, v_so_count
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id
AND year = EXTRACT(YEAR FROM v_prev_quota_start_date)::int
AND month >= EXTRACT(MONTH FROM v_prev_quota_start_date)::int;
v_stats_total := v_stats_total + v_so_total;
v_stats_count := v_stats_count + v_so_count;

IF EXTRACT(YEAR FROM v_prev_quota_end_date)::int != EXTRACT(YEAR FROM v_prev_quota_start_date)::int THEN
SELECT COALESCE(SUM(total_sales), 0), COALESCE(SUM(sales_order_count), 0)
INTO v_so_total, v_so_count
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id
AND year = EXTRACT(YEAR FROM v_prev_quota_end_date)::int
AND month <= EXTRACT(MONTH FROM v_prev_quota_end_date)::int;
v_stats_total := v_stats_total + v_so_total;
v_stats_count := v_stats_count + v_so_count;
END IF;

SELECT COALESCE(SUM(contract_total), 0), COUNT(*)
INTO v_so_total, v_so_count
FROM sales_orders
WHERE (CASE WHEN sales_rep_id IS NOT NULL THEN sales_rep_id ELSE created_by END) = p_target_rep_id
AND COALESCE(booked_at, created_at) >= v_prev_quota_start_date::timestamptz
AND COALESCE(booked_at, created_at) <= v_prev_quota_end_date::timestamptz
AND status NOT IN ('cancelled', 'voided')
AND NOT EXISTS (
SELECT 1 FROM sales_monthly_stats sms
WHERE sms.user_id = p_target_rep_id
AND sms.year = EXTRACT(YEAR FROM COALESCE(sales_orders.booked_at, sales_orders.created_at))::int
AND sms.month = EXTRACT(MONTH FROM COALESCE(sales_orders.booked_at, sales_orders.created_at))::int
);

v_prev_booked_sales := COALESCE(v_stats_total, 0) + COALESCE(v_so_total, 0);
v_prev_booked_count := COALESCE(v_stats_count, 0) + COALESCE(v_so_count, 0);

v_avg_sale := CASE WHEN v_booked_count > 0 THEN v_booked_sales / v_booked_count ELSE 0 END;

-- ── All-time total ───────────────────────────────────────────────
SELECT COALESCE(SUM(total_revenue), 0) INTO v_all_time_total
FROM yearly_sales_performance
WHERE user_id = p_target_rep_id;

SELECT COALESCE(SUM(contract_total), 0)
INTO v_so_total
FROM sales_orders
WHERE (CASE WHEN sales_rep_id IS NOT NULL THEN sales_rep_id ELSE created_by END) = p_target_rep_id
AND status NOT IN ('cancelled', 'voided')
AND EXTRACT(YEAR FROM COALESCE(booked_at, created_at))::int NOT IN (
SELECT year FROM yearly_sales_performance WHERE user_id = p_target_rep_id
);
v_all_time_total := v_all_time_total + COALESCE(v_so_total, 0);

-- ── Pipeline ─────────────────────────────────────────────────────
SELECT COALESCE(SUM(total), 0), COUNT(*)
INTO v_pipeline_total, v_pipeline_count
FROM proposals
WHERE created_by = p_target_rep_id
AND status IN ('designing', 'ready_to_submit', 'sent', 'portal');

-- ── Close rate ───────────────────────────────────────────────────
SELECT COUNT(*) INTO v_won_count
FROM proposals
WHERE created_by = p_target_rep_id
AND status IN ('approved', 'approved_pending_action')
AND COALESCE(approved_at, created_at) >= v_quota_start_date::timestamptz
AND COALESCE(approved_at, created_at) <= v_quota_end_date::timestamptz;

SELECT COUNT(*) INTO v_lost_count
FROM proposals
WHERE created_by = p_target_rep_id
AND status IN ('declined', 'cancelled', 'expired')
AND COALESCE(
CASE WHEN status = 'declined' THEN declined_at END,
CASE WHEN status = 'expired' THEN valid_until::timestamptz END,
created_at
) >= v_quota_start_date::timestamptz
AND COALESCE(
CASE WHEN status = 'declined' THEN declined_at END,
CASE WHEN status = 'expired' THEN valid_until::timestamptz END,
created_at
) <= v_quota_end_date::timestamptz;

IF (v_won_count + v_lost_count) > 0 THEN
v_close_rate := ROUND((v_won_count::numeric / (v_won_count + v_lost_count)) * 100, 1);
END IF;

SELECT COUNT(*) INTO v_prev_won_count
FROM proposals
WHERE created_by = p_target_rep_id
AND status IN ('approved', 'approved_pending_action')
AND COALESCE(approved_at, created_at) >= v_prev_quota_start_date::timestamptz
AND COALESCE(approved_at, created_at) <= v_prev_quota_end_date::timestamptz;

SELECT COUNT(*) INTO v_prev_lost_count
FROM proposals
WHERE created_by = p_target_rep_id
AND status IN ('declined', 'cancelled', 'expired')
AND COALESCE(
CASE WHEN status = 'declined' THEN declined_at END,
CASE WHEN status = 'expired' THEN valid_until::timestamptz END,
created_at
) >= v_prev_quota_start_date::timestamptz
AND COALESCE(
CASE WHEN status = 'declined' THEN declined_at END,
CASE WHEN status = 'expired' THEN valid_until::timestamptz END,
created_at
) <= v_prev_quota_end_date::timestamptz;

IF (v_prev_won_count + v_prev_lost_count) > 0 THEN
v_prev_close_rate := ROUND((v_prev_won_count::numeric / (v_prev_won_count + v_prev_lost_count)) * 100, 1);
END IF;

-- ── Monthly trend (12 months) ────────────────────────────────────
v_month_start := date_trunc('month', p_date_reference::timestamptz);
FOR i IN 0..11 LOOP
v_month_total := 0;
v_month_count := 0;

SELECT COALESCE(SUM(total_sales), 0), COALESCE(SUM(sales_order_count), 0)
INTO v_stats_total, v_stats_count
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id
AND year = EXTRACT(YEAR FROM (v_month_start - (i || ' months')::interval))::int
AND month = EXTRACT(MONTH FROM (v_month_start - (i || ' months')::interval))::int;

IF COALESCE(v_stats_total, 0) > 0 THEN
v_month_total := v_stats_total;
v_month_count := v_stats_count;
ELSE
SELECT COALESCE(SUM(contract_total), 0), COUNT(*)
INTO v_so_total, v_so_count
FROM sales_orders
WHERE (CASE WHEN sales_rep_id IS NOT NULL THEN sales_rep_id ELSE created_by END) = p_target_rep_id
AND COALESCE(booked_at, created_at) >= (v_month_start - (i || ' months')::interval)
AND COALESCE(booked_at, created_at) < (v_month_start - ((i - 1) || ' months')::interval)
AND status NOT IN ('cancelled', 'voided');
v_month_total := v_so_total;
v_month_count := v_so_count;
END IF;

v_monthly_trend := v_monthly_trend || jsonb_build_object(
'month', to_char((v_month_start - (i || ' months')::interval)::date, 'YYYY-MM'),
'total', v_month_total,
'count', v_month_count
);
END LOOP;

-- ── 90-day run rate (annualized) ────────────────────────────────
SELECT COALESCE(SUM(total_sales), 0)
INTO v_stats_total
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id
AND year = v_current_year
AND month >= GREATEST(1, v_current_month - 2)
AND month <= v_current_month;

-- Add previous year months if we're in Jan/Feb
IF v_current_month <= 2 THEN
SELECT COALESCE(SUM(total_sales), 0)
INTO v_so_total
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id
AND year = v_current_year - 1
AND month >= 11 + v_current_month;
v_stats_total := v_stats_total + v_so_total;
END IF;

SELECT COALESCE(SUM(contract_total), 0)
INTO v_so_total
FROM sales_orders
WHERE (CASE WHEN sales_rep_id IS NOT NULL THEN sales_rep_id ELSE created_by END) = p_target_rep_id
AND COALESCE(booked_at, created_at) >= (p_date_reference::timestamptz - INTERVAL '90 days')
AND COALESCE(booked_at, created_at) <= p_date_reference::timestamptz
AND status NOT IN ('cancelled', 'voided')
AND NOT EXISTS (
SELECT 1 FROM sales_monthly_stats sms
WHERE sms.user_id = p_target_rep_id
AND sms.year = EXTRACT(YEAR FROM COALESCE(sales_orders.booked_at, sales_orders.created_at))::int
AND sms.month = EXTRACT(MONTH FROM COALESCE(sales_orders.booked_at, sales_orders.created_at))::int
);

v_run_rate_90 := COALESCE(v_stats_total, 0) + COALESCE(v_so_total, 0);
v_run_rate_90 := ROUND((v_run_rate_90 / 90.0) * 365, 2);

-- ── YTD total ────────────────────────────────────────────────────
SELECT COALESCE(SUM(total_sales), 0), COALESCE(SUM(sales_order_count), 0)
INTO v_ytd_total, v_ytd_count
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id
AND year = v_current_year
AND month <= v_current_month;

SELECT COALESCE(SUM(contract_total), 0), COUNT(*)
INTO v_so_total, v_so_count
FROM sales_orders
WHERE (CASE WHEN sales_rep_id IS NOT NULL THEN sales_rep_id ELSE created_by END) = p_target_rep_id
AND COALESCE(booked_at, created_at) >= make_timestamptz(v_current_year, 1, 1, 0, 0, 0)
AND COALESCE(booked_at, created_at) <= p_date_reference::timestamptz
AND status NOT IN ('cancelled', 'voided')
AND NOT EXISTS (
SELECT 1 FROM sales_monthly_stats sms
WHERE sms.user_id = p_target_rep_id
AND sms.year = EXTRACT(YEAR FROM COALESCE(sales_orders.booked_at, sales_orders.created_at))::int
AND sms.month = EXTRACT(MONTH FROM COALESCE(sales_orders.booked_at, sales_orders.created_at))::int
);

v_ytd_total := v_ytd_total + COALESCE(v_so_total, 0);
v_ytd_count := v_ytd_count + COALESCE(v_so_count, 0);

-- ── Previous year total ───────────────────────────────────────────
SELECT COALESCE(SUM(total_revenue), 0) INTO v_prev_year_total
FROM yearly_sales_performance
WHERE user_id = p_target_rep_id AND year = v_prev_year;

IF v_prev_year_total = 0 THEN
SELECT COALESCE(SUM(total_sales), 0) INTO v_prev_year_total
FROM sales_monthly_stats
WHERE user_id = p_target_rep_id AND year = v_prev_year;
END IF;

RETURN jsonb_build_object(
'repId', p_target_rep_id,
'repDisplayName', COALESCE(
CASE WHEN v_profile.first_name IS NOT NULL AND v_profile.last_name IS NOT NULL
THEN v_profile.first_name || ' ' || v_profile.last_name END,
v_profile.full_name,
'Unknown'
),
'quota', jsonb_build_object(
'annualQuota', v_annual_quota,
'monthlyQuota', v_monthly_quota,
'quotaStartDate', v_quota_start_date,
'quotaEndDate', v_quota_end_date,
'quotaElapsedPct', v_quota_elapsed_pct,
'hasQuota', v_annual_quota > 0
),
'bookedSales', jsonb_build_object(
'total', v_booked_sales,
'count', v_booked_count,
'avgSale', v_avg_sale,
'prevTotal', v_prev_booked_sales,
'prevCount', v_prev_booked_count
),
'pipeline', jsonb_build_object(
'total', v_pipeline_total,
'count', v_pipeline_count
),
'closeRate', jsonb_build_object(
'pct', v_close_rate,
'wonCount', v_won_count,
'lostCount', v_lost_count,
'prevPct', v_prev_close_rate,
'prevWonCount', v_prev_won_count,
'prevLostCount', v_prev_lost_count
),
'runRate90Day', v_run_rate_90,
'monthlyTrend', v_monthly_trend,
'ytdTotal', v_ytd_total,
'ytdCount', v_ytd_count,
'prevYearTotal', v_prev_year_total,
'allTimeTotal', v_all_time_total
);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_sales_team_dashboard(p_rep_ids uuid[], p_date_reference date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_caller_id uuid := auth.uid();
v_caller_org uuid;
v_rep_id uuid;
v_results jsonb := '[]'::jsonb;
v_single jsonb;
BEGIN
IF v_caller_id IS NULL THEN
RETURN jsonb_build_object('error', 'not_authenticated');
END IF;

IF NOT is_manager_or_admin(v_caller_id) THEN
RETURN jsonb_build_object('error', 'unauthorized');
END IF;

v_caller_org := get_caller_org_id(v_caller_id);

FOREACH v_rep_id IN ARRAY p_rep_ids LOOP
-- Verify rep is in same org
PERFORM 1 FROM profiles WHERE id = v_rep_id AND organization_id = v_caller_org;
IF NOT FOUND THEN
CONTINUE;
END IF;

SELECT * FROM get_sales_rep_dashboard(v_rep_id, p_date_reference) INTO v_single;
v_results := v_results || jsonb_build_array(v_single);
END LOOP;

RETURN jsonb_build_object('reps', v_results);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_session_logout_schedule()
 RETURNS TABLE(id uuid, enabled boolean, logout_time time without time zone, timezone text, label text, last_run_at timestamp with time zone, last_run_count integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT id, enabled, logout_time, timezone, label, last_run_at, last_run_count
FROM session_logout_schedule
LIMIT 1;
$function$


CREATE OR REPLACE FUNCTION public.get_tech_current_location(tech_id uuid)
 RETURNS TABLE(latitude numeric, longitude numeric, recorded_at timestamp with time zone, accuracy numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT 
tl.latitude,
tl.longitude,
tl.recorded_at,
tl.accuracy
FROM tech_locations tl
WHERE tl.technician_id = tech_id
ORDER BY tl.recorded_at DESC
