END;
$function$


CREATE OR REPLACE FUNCTION public.get_tech_efficiency_for_advisor(p_current_start date, p_current_end date, p_prior_start date, p_prior_end date)
 RETURNS TABLE(technician_id uuid, technician_name text, employment_type text, current_payroll_hours numeric, current_job_hours numeric, current_efficiency_pct numeric, current_days_worked integer, prior_payroll_hours numeric, prior_job_hours numeric, prior_efficiency_pct numeric, prior_days_worked integer, efficiency_change numeric, trend_direction text, current_miles_driven numeric, current_trips integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_business_days_current int;
v_business_days_prior   int;
BEGIN
SELECT COUNT(*)::int
INTO v_business_days_current
FROM generate_series(p_current_start, p_current_end, '1 day'::interval) AS d
WHERE EXTRACT(DOW FROM d) NOT IN (0, 6);

SELECT COUNT(*)::int
INTO v_business_days_prior
FROM generate_series(p_prior_start, p_prior_end, '1 day'::interval) AS d
WHERE EXTRACT(DOW FROM d) NOT IN (0, 6);

RETURN QUERY
WITH techs AS (
SELECT p.id, p.full_name, COALESCE(p.employment_type, 'hourly') AS emp_type
FROM profiles p
WHERE p.role IN ('tech', 'manager')
AND p.full_name IS NOT NULL
),

current_clock AS (
SELECT
d.technician_id,
SUM(COALESCE(d.total_hours, 0)) AS payroll_hrs,
COUNT(DISTINCT d.entry_date)::int AS days_clocked
FROM daily_clock_entries d
WHERE d.entry_date >= p_current_start
AND d.entry_date <= p_current_end
AND (d.status = 'clocked_out' OR d.payroll_hours_only = true)
GROUP BY d.technician_id
),

prior_clock AS (
SELECT
d.technician_id,
SUM(COALESCE(d.total_hours, 0)) AS payroll_hrs,
COUNT(DISTINCT d.entry_date)::int AS days_clocked
FROM daily_clock_entries d
WHERE d.entry_date >= p_prior_start
AND d.entry_date <= p_prior_end
AND (d.status = 'clocked_out' OR d.payroll_hours_only = true)
GROUP BY d.technician_id
),

current_jobs AS (
SELECT
te.technician_id,
SUM(COALESCE(te.total_hours, 0)) AS job_hrs,
COUNT(DISTINCT te.entry_date)::int AS days_with_jobs
FROM time_entries te
WHERE te.entry_date >= p_current_start
AND te.entry_date <= p_current_end
AND te.clock_out IS NOT NULL
GROUP BY te.technician_id
),

prior_jobs AS (
SELECT
te.technician_id,
SUM(COALESCE(te.total_hours, 0)) AS job_hrs,
COUNT(DISTINCT te.entry_date)::int AS days_with_jobs
FROM time_entries te
WHERE te.entry_date >= p_prior_start
AND te.entry_date <= p_prior_end
AND te.clock_out IS NOT NULL
GROUP BY te.technician_id
),

current_travel AS (
SELECT
tbr.technician_id,
SUM(COALESCE(tbr.total_distance_miles::numeric, 0)) AS miles,
COUNT(*)::int AS trips
FROM travel_bonus_requests tbr
WHERE tbr.created_at >= p_current_start
AND tbr.created_at < p_current_end + interval '1 day'
GROUP BY tbr.technician_id
),

combined AS (
SELECT
t.id        AS tech_id,
t.full_name AS tech_name,
t.emp_type,

CASE
WHEN t.emp_type IN ('salary', 'salary_no_clock')
THEN (v_business_days_current * 8)::numeric
ELSE COALESCE(cc.payroll_hrs, 0)
END AS c_payroll,

COALESCE(cj.job_hrs, 0) AS c_job,

CASE
WHEN t.emp_type IN ('salary', 'salary_no_clock')
THEN GREATEST(COALESCE(cj.days_with_jobs, 0), COALESCE(cc.days_clocked, 0))
ELSE GREATEST(
COALESCE(cc.days_clocked, 0),
CASE WHEN cc.days_clocked IS NULL THEN COALESCE(cj.days_with_jobs, 0) ELSE 0 END
)
END AS c_days,

CASE
WHEN t.emp_type IN ('salary', 'salary_no_clock')
THEN (v_business_days_prior * 8)::numeric
ELSE COALESCE(pc.payroll_hrs, 0)
END AS p_payroll,

COALESCE(pj.job_hrs, 0) AS p_job,

CASE
WHEN t.emp_type IN ('salary', 'salary_no_clock')
THEN GREATEST(COALESCE(pj.days_with_jobs, 0), COALESCE(pc.days_clocked, 0))
ELSE GREATEST(
COALESCE(pc.days_clocked, 0),
CASE WHEN pc.days_clocked IS NULL THEN COALESCE(pj.days_with_jobs, 0) ELSE 0 END
)
END AS p_days,

COALESCE(ct.miles, 0)   AS c_miles,
COALESCE(ct.trips, 0)   AS c_trips

FROM techs t
LEFT JOIN current_clock  cc ON cc.technician_id = t.id
LEFT JOIN current_jobs   cj ON cj.technician_id = t.id
LEFT JOIN prior_clock    pc ON pc.technician_id = t.id
LEFT JOIN prior_jobs     pj ON pj.technician_id = t.id
LEFT JOIN current_travel ct ON ct.technician_id = t.id
WHERE
cc.payroll_hrs IS NOT NULL OR cj.job_hrs IS NOT NULL
OR pc.payroll_hrs IS NOT NULL OR pj.job_hrs IS NOT NULL
)

SELECT
c.tech_id,
c.tech_name,
c.emp_type,

ROUND(c.c_payroll, 2) AS current_payroll_hours,
ROUND(c.c_job,     2) AS current_job_hours,
ROUND(CASE WHEN c.c_payroll > 0 THEN (c.c_job / c.c_payroll) * 100 ELSE 0 END, 1) AS current_efficiency_pct,
c.c_days::int         AS current_days_worked,

ROUND(c.p_payroll, 2) AS prior_payroll_hours,
ROUND(c.p_job,     2) AS prior_job_hours,
ROUND(CASE WHEN c.p_payroll > 0 THEN (c.p_job / c.p_payroll) * 100 ELSE 0 END, 1) AS prior_efficiency_pct,
c.p_days::int         AS prior_days_worked,

ROUND(
CASE WHEN c.c_payroll > 0 THEN (c.c_job / c.c_payroll) * 100 ELSE 0 END
- CASE WHEN c.p_payroll > 0 THEN (c.p_job / c.p_payroll) * 100 ELSE 0 END,
1
) AS efficiency_change,

CASE
WHEN (
CASE WHEN c.c_payroll > 0 THEN (c.c_job / c.c_payroll) * 100 ELSE 0 END
- CASE WHEN c.p_payroll > 0 THEN (c.p_job / c.p_payroll) * 100 ELSE 0 END
) > 3  THEN 'improving'
WHEN (
CASE WHEN c.c_payroll > 0 THEN (c.c_job / c.c_payroll) * 100 ELSE 0 END
- CASE WHEN c.p_payroll > 0 THEN (c.p_job / c.p_payroll) * 100 ELSE 0 END
) < -3 THEN 'declining'
ELSE 'stable'
END AS trend_direction,

ROUND(c.c_miles, 1) AS current_miles_driven,
c.c_trips::int      AS current_trips

FROM combined c
ORDER BY
CASE WHEN c.c_payroll > 0 THEN (c.c_job / c.c_payroll) * 100 ELSE 0 END DESC;

END;
$function$


CREATE OR REPLACE FUNCTION public.get_technician_route(p_clock_entry_id uuid)
 RETURNS TABLE(id text, latitude real, longitude real, altitude real, accuracy real, speed real, heading real, captured_at timestamp with time zone, capture_method text, battery_level real)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
egb.id,
egb.latitude,
egb.longitude,
egb.altitude,
egb.accuracy,
egb.speed,
egb.heading,
egb.captured_at,
egb.capture_method,
egb.battery_level
FROM enhanced_gps_breadcrumbs egb
WHERE egb.daily_clock_entry_id = p_clock_entry_id
ORDER BY egb.captured_at ASC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_tenant_billing_summary(p_org_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_sub tenant_subscriptions%ROWTYPE;
v_user_count integer;
v_org organizations%ROWTYPE;
BEGIN
IF p_org_id IS NOT NULL AND public.is_global_admin() THEN
v_org_id := p_org_id;
ELSE
SELECT organization_id INTO v_org_id FROM profiles WHERE id = auth.uid();
END IF;

SELECT * INTO v_org FROM organizations WHERE id = v_org_id;
SELECT * INTO v_sub FROM tenant_subscriptions WHERE organization_id = v_org_id;
SELECT count(*) INTO v_user_count FROM profiles WHERE organization_id = v_org_id AND is_active = true;

RETURN jsonb_build_object(
'organization_name', v_org.name,
'plan_type', v_org.plan_type,
'subscription_status', v_org.subscription_status,
'trial_ends_at', v_org.trial_ends_at,
'user_count', v_user_count,
'subscription', CASE WHEN v_sub.id IS NOT NULL THEN jsonb_build_object(
'id', v_sub.id,
'stripe_subscription_id', v_sub.stripe_subscription_id,
'current_user_count', v_sub.current_user_count,
'base_amount', v_sub.base_amount,
'per_user_amount', v_sub.per_user_amount,
'total_monthly_amount', v_sub.total_monthly_amount,
'discount_amount', v_sub.discount_amount,
'payment_status', v_sub.payment_status,
'current_period_start', v_sub.current_period_start,
'current_period_end', v_sub.current_period_end,
'cancel_at_period_end', v_sub.cancel_at_period_end
) ELSE NULL END
);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_test_tune_labor_totals(p_sales_order_id uuid)
 RETURNS TABLE(field_hours numeric, pm_hours numeric, non_performance_hours numeric, total_hours numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT 
COALESCE(SUM(CASE 
WHEN lc.counts_against_target = true AND lc.name = 'Field Labor' 
THEN wo.actual_hours 
ELSE 0 
END), 0) as field_hours,
COALESCE(SUM(CASE 
WHEN lc.name = 'PM Labor' 
THEN wo.actual_hours 
ELSE 0 
END), 0) as pm_hours,
COALESCE(SUM(CASE 
WHEN lc.name = 'Non-Performance Labor' 
THEN wo.actual_hours 
ELSE 0 
END), 0) as non_performance_hours,
COALESCE(SUM(wo.actual_hours), 0) as total_hours
FROM work_orders wo
LEFT JOIN labor_categories lc ON lc.id = wo.labor_category_id
WHERE wo.sales_order_id = p_sales_order_id
AND wo.status = 'completed';
END;
$function$


CREATE OR REPLACE FUNCTION public.get_test_tune_project_detail(project_sales_order_id uuid)
 RETURNS TABLE(id uuid, order_number text, contact_name text, contact_id uuid, contact_email text, contact_phone text, project_id uuid, project_title text, office_name text, office_id uuid, lead_tech_name text, lead_tech_id uuid, pm_name text, pm_id uuid, sales_rep_name text, sales_rep_id uuid, test_tune_start_date date, test_tune_end_date date, total_estimated_labor numeric, field_labor_target numeric, field_hours_used numeric, pm_hours_used numeric, non_performance_hours numeric, has_vip_membership boolean, portal_access_level text, punchlist_item_count integer, work_order_count integer, contract_total numeric, can_view_bonus_amounts boolean, can_view_pm_metrics boolean, can_view_admin_controls boolean, can_view_all_work_orders boolean, user_has_access boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
v_user_role text;
v_user_office_id uuid;
v_is_admin boolean;
v_is_manager boolean;
v_is_sales boolean;
v_is_tech boolean;
v_is_lead_tech boolean;
v_has_access boolean;
v_can_view_bonus boolean;
v_can_view_pm_metrics boolean;
v_can_view_admin_controls boolean;
v_can_view_all_wo boolean;
BEGIN
-- Get current user
v_user_id := auth.uid();

-- Get user role and office
SELECT role, default_office_id
INTO v_user_role, v_user_office_id
FROM profiles
WHERE id = v_user_id;

-- Determine role flags
v_is_admin := v_user_role IN ('admin', 'super_admin');
v_is_manager := v_user_role IN ('manager', 'sales_manager', 'service_manager');
v_is_sales := v_user_role IN ('sales', 'sales_rep', 'sales_manager');
v_is_tech := v_user_role IN ('tech', 'lead_tech', 'technician');

-- Check if user is lead tech on this project
v_is_lead_tech := EXISTS (
SELECT 1 FROM sales_orders WHERE id = project_sales_order_id AND lead_technician_id = v_user_id
);

-- Determine access based on role
v_has_access := CASE
WHEN v_is_admin THEN true
WHEN v_is_manager THEN EXISTS (
SELECT 1 FROM sales_orders WHERE id = project_sales_order_id AND office_id = v_user_office_id
)
WHEN v_is_sales THEN EXISTS (
SELECT 1 FROM sales_orders WHERE id = project_sales_order_id AND created_by = v_user_id
)
WHEN v_is_tech THEN (
-- Tech must be lead tech OR assigned to a work order on this project
v_is_lead_tech OR EXISTS (
SELECT 1 FROM work_orders
WHERE sales_order_id = project_sales_order_id
AND assigned_tech_id = v_user_id
)
)
ELSE false
END;

-- If no access, return empty result
IF NOT v_has_access THEN
RETURN;
END IF;

-- Set permission flags based on role
v_can_view_bonus := v_is_admin OR v_is_manager OR v_is_tech;
v_can_view_pm_metrics := v_is_admin OR v_is_manager;
v_can_view_admin_controls := v_is_admin;
v_can_view_all_wo := v_is_admin OR v_is_manager OR v_is_sales OR v_is_lead_tech;

RETURN QUERY
SELECT
so.id,
so.order_number,
c.full_name as contact_name,
so.contact_id,
c.email as contact_email,
c.phone as contact_phone,
p.id as project_id,
p.title as project_title,
COALESCE(co.office_name, 'No Office') as office_name,
so.office_id,
lt.full_name as lead_tech_name,
so.lead_technician_id as lead_tech_id,
pm.full_name as pm_name,
p.project_manager_id as pm_id,
sr.full_name as sales_rep_name,
so.created_by as sales_rep_id,
so.test_tune_start_date,
so.test_tune_end_date,
so.total_estimated_labor_hours as total_estimated_labor,
so.field_labor_target_hours as field_labor_target,
COALESCE(labor.field_hours, 0) as field_hours_used,
COALESCE(labor.pm_hours, 0) as pm_hours_used,
COALESCE(labor.non_performance_hours, 0) as non_performance_hours,
COALESCE(
(SELECT COUNT(*) > 0
FROM subscriptions sub
WHERE sub.contact_id = so.contact_id
AND sub.status IN ('active', 'trialing')
AND sub.plan_type = 'vip'
), false
) as has_vip_membership,
get_contact_portal_access_level(so.contact_id) as portal_access_level,
COALESCE(
(SELECT COUNT(*)::integer
FROM punchlist_tasks pt
WHERE pt.contact_id = so.contact_id
), 0
) as punchlist_item_count,
COALESCE(
(SELECT COUNT(*)::integer
FROM work_orders wo
WHERE wo.sales_order_id = so.id
), 0
) as work_order_count,
so.contract_total,
v_can_view_bonus as can_view_bonus_amounts,
v_can_view_pm_metrics as can_view_pm_metrics,
v_can_view_admin_controls as can_view_admin_controls,
v_can_view_all_wo as can_view_all_work_orders,
v_has_access as user_has_access
FROM sales_orders so
INNER JOIN contacts c ON c.id = so.contact_id
LEFT JOIN projects p ON p.sales_order_id = so.id
LEFT JOIN company_offices co ON co.id = so.office_id
LEFT JOIN profiles lt ON lt.id = so.lead_technician_id
LEFT JOIN profiles pm ON pm.id = p.project_manager_id
LEFT JOIN profiles sr ON sr.id = so.created_by
LEFT JOIN LATERAL (
SELECT
SUM(CASE
WHEN lpm.performance_category = 'Field Performance' THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as field_hours,
SUM(CASE
WHEN lpm.performance_category = 'PM Non-Performance' THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as pm_hours,
SUM(CASE
WHEN lpm.performance_category = 'Non-Performance' THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as non_performance_hours
FROM work_orders wo
LEFT JOIN labor_phases lp ON lp.id = wo.labor_phase_id
LEFT JOIN labor_phase_performance_mapping lpm ON lpm.labor_phase_id = lp.id
WHERE wo.sales_order_id = so.id
AND wo.status = 'completed'
) labor ON true
WHERE so.id = project_sales_order_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_test_tune_project_work_orders(project_sales_order_id uuid)
 RETURNS TABLE(id uuid, work_order_number text, title text, work_order_type text, status text, scheduled_date date, completed_date timestamp with time zone, estimated_hours numeric, actual_hours numeric, labor_category text, assigned_tech_name text, assigned_tech_id uuid, notes text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
v_user_role text;
v_user_office_id uuid;
v_is_admin boolean;
v_is_manager boolean;
v_is_sales boolean;
v_is_tech boolean;
v_is_lead_tech boolean;
v_show_all_work_orders boolean;
BEGIN
-- Get current user
v_user_id := auth.uid();

-- Get user role and office
SELECT role, default_office_id
INTO v_user_role, v_user_office_id
FROM profiles
WHERE id = v_user_id;

-- Determine role flags
v_is_admin := v_user_role IN ('admin', 'super_admin');
v_is_manager := v_user_role IN ('manager', 'sales_manager', 'service_manager');
v_is_sales := v_user_role IN ('sales', 'sales_rep', 'sales_manager');
v_is_tech := v_user_role IN ('tech', 'lead_tech', 'technician');

-- Check if user is lead tech on this project
v_is_lead_tech := EXISTS (
SELECT 1 FROM sales_orders WHERE id = project_sales_order_id AND lead_technician_id = v_user_id
);

-- Determine if we show all work orders or filter
v_show_all_work_orders := v_is_admin OR v_is_manager OR v_is_sales OR v_is_lead_tech;

RETURN QUERY
SELECT
wo.id,
wo.work_order_number,
wo.title,
wo.work_order_type,
wo.status,
wo.scheduled_date,
wo.completed_date,
wo.estimated_hours,
wo.actual_hours,
COALESCE(lp.name, 'Unknown') as labor_category,
t.full_name as assigned_tech_name,
wo.assigned_tech_id,
wo.notes,
wo.created_at
FROM work_orders wo
LEFT JOIN labor_phases lp ON lp.id = wo.labor_phase_id
LEFT JOIN profiles t ON t.id = wo.assigned_tech_id
WHERE wo.sales_order_id = project_sales_order_id
AND (v_show_all_work_orders OR wo.assigned_tech_id = v_user_id)
ORDER BY wo.created_at DESC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_test_tune_projects(include_expired boolean DEFAULT false)
 RETURNS TABLE(id uuid, order_number text, contact_name text, contact_id uuid, project_id uuid, project_title text, office_name text, lead_tech_name text, pm_name text, test_tune_start_date date, test_tune_end_date date, days_remaining integer, total_estimated_labor numeric, field_labor_target numeric, pm_allocation_hours numeric, field_performance_hours numeric, excluded_hours numeric, hours_remaining numeric, percentage_of_target numeric, status_indicator text, target_recalculated boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT 
so.id,
so.order_number,
c.full_name as contact_name,
so.contact_id,
p.id as project_id,
p.title as project_title,
COALESCE(co.office_name, 'No Office') as office_name,
lt.full_name as lead_tech_name,
pm.full_name as pm_name,
so.test_tune_start_date,
so.test_tune_end_date,
GREATEST(0, (so.test_tune_end_date - CURRENT_DATE)::integer) as days_remaining,
so.total_estimated_labor_hours as total_estimated_labor,
so.field_labor_target_hours as field_labor_target,
so.pm_labor_allocation_hours as pm_allocation_hours,
COALESCE(labor.field_hours, 0) as field_performance_hours,
COALESCE(labor.excluded_hours, 0) as excluded_hours,
so.field_labor_target_hours - COALESCE(labor.field_hours, 0) as hours_remaining,
CASE 
WHEN so.field_labor_target_hours > 0 
THEN ROUND((COALESCE(labor.field_hours, 0) / so.field_labor_target_hours * 100)::numeric, 1)
ELSE 0
END as percentage_of_target,
CASE 
WHEN COALESCE(labor.field_hours, 0) > so.field_labor_target_hours THEN 'over'
WHEN COALESCE(labor.field_hours, 0) / NULLIF(so.field_labor_target_hours, 0) > 0.75 THEN 'warning'
ELSE 'on_track'
END as status_indicator,
EXISTS (
SELECT 1 FROM test_tune_field_target_history
WHERE sales_order_id = so.id
) as target_recalculated
FROM sales_orders so
INNER JOIN contacts c ON c.id = so.contact_id
LEFT JOIN projects p ON p.sales_order_id = so.id
LEFT JOIN company_offices co ON co.id = so.office_id
LEFT JOIN profiles lt ON lt.id = so.lead_technician_id
LEFT JOIN profiles pm ON pm.id = p.project_manager_id
LEFT JOIN LATERAL (
SELECT 
SUM(CASE 
WHEN COALESCE(lppm.counts_against_target, true) = true 
THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as field_hours,
SUM(CASE 
WHEN COALESCE(lppm.counts_against_target, true) = false 
THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as excluded_hours
FROM work_orders wo
LEFT JOIN labor_phase_performance_mapping lppm ON lppm.labor_phase_id = wo.labor_phase_id
WHERE wo.sales_order_id = so.id
AND wo.status = 'completed'
) labor ON true
WHERE so.test_tune_status = 'active'
AND (
include_expired = true 
OR so.test_tune_end_date >= CURRENT_DATE
)
ORDER BY 
CASE 
WHEN so.test_tune_end_date >= CURRENT_DATE THEN 0
ELSE 1
END,
so.test_tune_end_date ASC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_test_tune_projects_for_user(p_user_id uuid, include_expired boolean DEFAULT false)
 RETURNS TABLE(id uuid, order_number text, contact_name text, contact_id uuid, project_id uuid, project_title text, office_name text, office_id uuid, lead_tech_name text, lead_tech_id uuid, pm_name text, pm_id uuid, sales_rep_name text, sales_rep_id uuid, test_tune_start_date date, test_tune_end_date date, days_remaining integer, total_estimated_labor numeric, field_labor_target numeric, pm_allocation_hours numeric, field_performance_hours numeric, excluded_hours numeric, hours_remaining numeric, percentage_of_target numeric, status_indicator text, target_recalculated boolean, user_can_view boolean, user_relationship text, sales_rep_eligible boolean, effective_labor_rate numeric, effective_rate_threshold numeric, elr_override_active boolean, labor_savings_pct numeric, bonus_tier_type text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_role text;
v_is_exec boolean;
v_default_office_id uuid;
v_global_threshold numeric;
v_bonus_tier_type text;
BEGIN
-- Get user's role, executive flag, and default office
SELECT p.role, COALESCE(p.can_view_executive_dashboard, false), p.default_office_id
INTO v_role, v_is_exec, v_default_office_id
FROM profiles p
WHERE p.id = p_user_id;

-- Get global threshold and tier type from settings
SELECT
COALESCE(min_effective_labor_rate, 100),
COALESCE(bonus_tier_type, 'flat_hours')
INTO v_global_threshold, v_bonus_tier_type
FROM test_tune_settings
LIMIT 1;

RETURN QUERY
SELECT
so.id,
so.order_number,
c.full_name as contact_name,
so.contact_id,
pr.id as project_id,
pr.title as project_title,
COALESCE(co.office_name, 'No Office') as office_name,
so.office_id,
lt.full_name as lead_tech_name,
so.lead_technician_id as lead_tech_id,
pm.full_name as pm_name,
pr.project_manager_id as pm_id,
sr.full_name as sales_rep_name,
so.sales_rep_id,
so.test_tune_start_date,
so.test_tune_end_date,
GREATEST(0, (so.test_tune_end_date - CURRENT_DATE)::integer) as days_remaining,
so.total_estimated_labor_hours as total_estimated_labor,
so.field_labor_target_hours as field_labor_target,
so.pm_labor_allocation_hours as pm_allocation_hours,
COALESCE(labor.field_hours, 0) as field_performance_hours,
COALESCE(labor.excluded_hours, 0) as excluded_hours,
so.field_labor_target_hours - COALESCE(labor.field_hours, 0) as hours_remaining,
CASE
WHEN so.field_labor_target_hours > 0
THEN ROUND((COALESCE(labor.field_hours, 0) / so.field_labor_target_hours * 100)::numeric, 1)
ELSE 0
END as percentage_of_target,
CASE
WHEN COALESCE(labor.field_hours, 0) > so.field_labor_target_hours THEN 'over'
WHEN COALESCE(labor.field_hours, 0) / NULLIF(so.field_labor_target_hours, 0) > 0.75 THEN 'warning'
ELSE 'on_track'
END as status_indicator,
EXISTS (
SELECT 1 FROM test_tune_field_target_history
WHERE sales_order_id = so.id
) as target_recalculated,

-- Role-based view permission
CASE
WHEN v_role IN ('admin', 'finance') OR v_is_exec THEN true
WHEN v_role = 'tech' THEN (
so.lead_technician_id = p_user_id OR
EXISTS (
SELECT 1 FROM work_orders wo
WHERE wo.sales_order_id = so.id AND wo.assigned_to = p_user_id
)
)
WHEN v_role IN ('manager', 'service_manager') THEN (
so.office_id = v_default_office_id OR pr.project_manager_id = p_user_id
)
WHEN v_role = 'sales' THEN so.sales_rep_id = p_user_id
ELSE false
END as user_can_view,

-- User relationship descriptor
CASE
WHEN v_role IN ('admin', 'finance') THEN 'admin'
WHEN v_is_exec THEN 'executive'
WHEN so.lead_technician_id = p_user_id THEN 'lead_tech'
WHEN EXISTS (
SELECT 1 FROM work_orders wo
WHERE wo.sales_order_id = so.id AND wo.assigned_to = p_user_id
) THEN 'assigned_tech'
WHEN pr.project_manager_id = p_user_id THEN 'project_manager'
WHEN so.sales_rep_id = p_user_id THEN 'sales_rep'
WHEN so.office_id = v_default_office_id THEN 'office_member'
ELSE 'none'
END as user_relationship,

-- ELR fields from bonus calculations (NULL if not yet evaluated)
bc.sales_rep_eligible,
bc.effective_labor_rate,
COALESCE(so.min_effective_labor_rate_override, v_global_threshold) as effective_rate_threshold,
(so.min_effective_labor_rate_override IS NOT NULL) as elr_override_active,

-- Savings percentage (from bonus calc if available, computed live otherwise)
COALESCE(
bc.labor_savings_pct,
CASE
WHEN so.total_estimated_labor_hours > 0
THEN ROUND(
((so.field_labor_target_hours - COALESCE(labor.field_hours, 0)) / so.total_estimated_labor_hours * 100)::numeric,
2
)
ELSE 0
END
) as labor_savings_pct,

v_bonus_tier_type as bonus_tier_type

FROM sales_orders so
INNER JOIN contacts c ON c.id = so.contact_id
LEFT JOIN projects pr ON pr.sales_order_id = so.id
LEFT JOIN company_offices co ON co.id = so.office_id
LEFT JOIN profiles lt ON lt.id = so.lead_technician_id
LEFT JOIN profiles pm ON pm.id = pr.project_manager_id
LEFT JOIN profiles sr ON sr.id = so.sales_rep_id
LEFT JOIN LATERAL (
SELECT
SUM(CASE
WHEN COALESCE(lppm.counts_against_target, true) = true
THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as field_hours,
SUM(CASE
WHEN COALESCE(lppm.counts_against_target, true) = false
THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as excluded_hours
FROM work_orders wo
LEFT JOIN labor_phase_performance_mapping lppm ON lppm.labor_phase_id = wo.labor_phase_id
WHERE wo.sales_order_id = so.id
AND wo.status = 'completed'
) labor ON true
LEFT JOIN LATERAL (
SELECT sales_rep_eligible, effective_labor_rate, labor_savings_pct
FROM test_tune_bonus_calculations
WHERE sales_order_id = so.id
ORDER BY updated_at DESC
LIMIT 1
) bc ON true
WHERE so.test_tune_status = 'active'
AND (include_expired = true OR so.test_tune_end_date >= CURRENT_DATE)
AND (
v_role IN ('admin', 'finance') OR v_is_exec OR
(v_role = 'tech' AND (
so.lead_technician_id = p_user_id OR
EXISTS (
SELECT 1 FROM work_orders wo
WHERE wo.sales_order_id = so.id AND wo.assigned_to = p_user_id
)
)) OR
(v_role IN ('manager', 'service_manager') AND (
so.office_id = v_default_office_id OR pr.project_manager_id = p_user_id
)) OR
(v_role = 'sales' AND so.sales_rep_id = p_user_id)
)
ORDER BY
CASE WHEN so.test_tune_end_date >= CURRENT_DATE THEN 0 ELSE 1 END,
so.test_tune_end_date ASC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_test_tune_projects_with_variance(p_user_id uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_include_expired boolean DEFAULT false)
 RETURNS TABLE(id uuid, order_number text, contact_name text, office_name text, sales_rep_name text, lead_tech_name text, pm_name text, field_labor_target numeric, field_performance_hours numeric, percentage_of_target numeric, hours_variance numeric, cost_variance numeric, status_indicator text, days_remaining integer, completion_date date, first_completion_hours numeric, post_completion_hours numeric, completion_attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_role text;
v_office_id uuid;
v_labor_rate numeric := 75.00;
BEGIN
-- Get user's role and office
SELECT role, office_id INTO v_user_role, v_office_id
FROM profiles
WHERE id = p_user_id;

RETURN QUERY
SELECT
so.id,
so.order_number,
c.full_name as contact_name,
COALESCE(co.office_name, 'No Office') as office_name,
sr.full_name as sales_rep_name,
lt.full_name as lead_tech_name,
pm.full_name as pm_name,
so.field_labor_target_hours as field_labor_target,
COALESCE(labor.field_hours, 0) as field_performance_hours,
CASE
WHEN so.field_labor_target_hours > 0
THEN (COALESCE(labor.field_hours, 0) / so.field_labor_target_hours * 100)
ELSE 0
END as percentage_of_target,
(so.field_labor_target_hours - COALESCE(labor.field_hours, 0)) as hours_variance,
((so.field_labor_target_hours - COALESCE(labor.field_hours, 0)) * v_labor_rate) as cost_variance,
CASE
WHEN COALESCE(labor.field_hours, 0) <= (so.field_labor_target_hours * 0.75) THEN 'on_track'
WHEN COALESCE(labor.field_hours, 0) <= so.field_labor_target_hours THEN 'warning'
ELSE 'over'
END as status_indicator,
GREATEST(0, (so.test_tune_end_date - CURRENT_DATE)::integer) as days_remaining,
so.test_tune_end_date as completion_date,
so.first_completion_hours,
COALESCE(labor.post_completion_hours, 0) as post_completion_hours,
so.completion_attempts
FROM sales_orders so
INNER JOIN contacts c ON c.id = so.contact_id
LEFT JOIN projects p ON p.sales_order_id = so.id
LEFT JOIN company_offices co ON co.id = so.office_id
LEFT JOIN profiles sr ON sr.id = so.created_by
LEFT JOIN profiles lt ON lt.id = so.lead_technician_id
LEFT JOIN profiles pm ON pm.id = p.project_manager_id
LEFT JOIN LATERAL (
SELECT
SUM(CASE WHEN lp.labor_phase = 'Field Labor' THEN COALESCE(wo.actual_hours, 0) ELSE 0 END) as field_hours,
SUM(CASE
WHEN so.first_completion_date IS NOT NULL
AND wo.completed_at > so.first_completion_date
AND lp.labor_phase = 'Field Labor'
THEN COALESCE(wo.actual_hours, 0)
ELSE 0
END) as post_completion_hours
FROM work_orders wo
LEFT JOIN labor_phases lp ON lp.id = wo.labor_phase_id
WHERE wo.sales_order_id = so.id AND wo.status = 'completed'
) labor ON true
WHERE so.test_tune_status = 'active'
AND (p_include_expired OR (so.test_tune_end_date - CURRENT_DATE) >= 0)
AND (p_start_date IS NULL OR so.test_tune_start_date >= p_start_date)
AND (p_end_date IS NULL OR so.test_tune_end_date <= p_end_date)
AND (
-- Admin sees all
v_user_role IN ('admin', 'super_admin')
-- Manager sees office projects
OR (v_user_role IN ('manager', 'service_manager') AND so.office_id = v_office_id)
-- Sales sees their sales
OR (v_user_role IN ('sales', 'sales_rep', 'sales_manager') AND so.created_by = p_user_id)
-- Tech sees their projects
OR (v_user_role IN ('tech', 'lead_tech') AND so.lead_technician_id = p_user_id)
-- PM sees their projects
OR (p.project_manager_id = p_user_id)
)
ORDER BY so.test_tune_end_date ASC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_test_tune_stats_for_user(p_user_id uuid)
 RETURNS TABLE(total_projects bigint, projects_on_track bigint, projects_at_risk bigint, projects_over_budget bigint, avg_efficiency_percentage numeric, total_labor_savings numeric, total_margin_drag numeric, estimated_bonus_pool numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
COUNT(*)::bigint as total_projects,
COUNT(*) FILTER (WHERE status_indicator = 'on_track')::bigint as projects_on_track,
COUNT(*) FILTER (WHERE status_indicator = 'warning')::bigint as projects_at_risk,
COUNT(*) FILTER (WHERE status_indicator = 'over')::bigint as projects_over_budget,
ROUND(AVG(percentage_of_target), 1) as avg_efficiency_percentage,
SUM(GREATEST(0, field_labor_target - field_performance_hours)) as total_labor_savings,
SUM(GREATEST(0, field_performance_hours - field_labor_target)) as total_margin_drag,
0::numeric as estimated_bonus_pool -- Will calculate separately based on settings
FROM get_test_tune_projects_for_user(p_user_id, false)
WHERE user_can_view = true;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_time_entry_project_id(p_time_entry_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_project_id uuid;
BEGIN
SELECT COALESCE(te.project_id, wo.project_id)
INTO v_project_id
FROM time_entries te
LEFT JOIN work_orders wo ON te.work_order_id = wo.id
WHERE te.id = p_time_entry_id;

RETURN v_project_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_top_performers(days integer DEFAULT 7)
 RETURNS TABLE(id uuid, full_name text, completions bigint, avg_quality numeric, photos_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
RETURN QUERY
SELECT
p.id,
p.full_name,
COUNT(DISTINCT jc.id) as completions,
ROUND(AVG(jc.quality_score)::numeric, 1) as avg_quality,
COUNT(DISTINCT jp.id) as photos_count
FROM profiles p
LEFT JOIN job_completions jc ON jc.technician_id = p.id
AND jc.completed_at >= NOW() - (days || ' days')::INTERVAL
LEFT JOIN job_photos jp ON jp.technician_id = p.id
AND jp.captured_at >= NOW() - (days || ' days')::INTERVAL
WHERE p.role IN ('technician', 'lead_technician')
AND EXISTS (
SELECT 1 FROM job_completions
WHERE technician_id = p.id
AND completed_at >= NOW() - (days || ' days')::INTERVAL
)
GROUP BY p.id, p.full_name
HAVING COUNT(DISTINCT jc.id) > 0
ORDER BY completions DESC, avg_quality DESC
LIMIT 10;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_upcoming_punchlist_customers()
 RETURNS TABLE(contact_id uuid, contact_name text, contact_email text, contact_phone text, project_id uuid, project_name text, project_number text, project_status text, target_completion_date date, days_until_completion integer, assigned_pm_name text, sales_order_id uuid, sales_order_number text, total_actual_hours numeric, total_estimated_hours numeric, progress_percent numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
BEGIN
SELECT organization_id INTO v_org_id
FROM profiles
WHERE id = auth.uid()
LIMIT 1;

RETURN QUERY
WITH work_order_hours AS (
SELECT
wo.project_id,
COALESCE(SUM(wo.actual_hours), 0)    AS actual_hrs,
COALESCE(SUM(wo.estimated_hours), 0) AS estimated_hrs
FROM work_orders wo
WHERE wo.project_id IS NOT NULL
GROUP BY wo.project_id
)
SELECT
c.id                                                          AS contact_id,
c.full_name                                                   AS contact_name,
c.email                                                       AS contact_email,
c.phone                                                       AS contact_phone,
p.id                                                          AS project_id,
p.name                                                        AS project_name,
p.project_number                                              AS project_number,
p.status                                                      AS project_status,
p.target_completion_date                                      AS target_completion_date,
CASE
WHEN p.target_completion_date IS NULL THEN NULL
ELSE (p.target_completion_date - CURRENT_DATE)::int
END                                                           AS days_until_completion,
pm.full_name                                                  AS assigned_pm_name,
so.id                                                         AS sales_order_id,
so.order_number                                               AS sales_order_number,
COALESCE(woh.actual_hrs, 0)                                   AS total_actual_hours,
COALESCE(woh.estimated_hrs, 0)                                AS total_estimated_hours,
CASE
WHEN COALESCE(woh.estimated_hrs, 0) = 0 THEN NULL
ELSE ROUND((COALESCE(woh.actual_hrs, 0) / woh.estimated_hrs) * 100, 1)
END                                                           AS progress_percent
FROM projects p
JOIN contacts c ON c.id = p.contact_id
LEFT JOIN profiles pm ON pm.id = p.assigned_pm
LEFT JOIN sales_orders so ON so.id = p.sales_order_id
LEFT JOIN work_order_hours woh ON woh.project_id = p.id
WHERE
-- Only in-progress projects
p.status IN ('planning', 'active')
-- Not yet substantially complete
AND p.substantial_completion_date IS NULL
-- 80% hours threshold: pass if no estimated hours OR >= 80% actual
AND (
COALESCE(woh.estimated_hrs, 0) = 0
OR COALESCE(woh.actual_hrs, 0) / NULLIF(woh.estimated_hrs, 0) >= 0.80
)
-- No active or suspended access grant already exists for this contact
AND NOT EXISTS (
SELECT 1 FROM punchlist_access_grants ag
WHERE ag.contact_id = p.contact_id
AND ag.status IN ('active', 'suspended')
)
-- No pending invite already queued for this contact
AND NOT EXISTS (
SELECT 1 FROM pending_punchlist_invites pi
WHERE pi.contact_id = p.contact_id
AND pi.status = 'pending'
)
-- Multi-tenant safety
AND c.organization_id = v_org_id
ORDER BY
CASE WHEN p.target_completion_date IS NULL THEN 1 ELSE 0 END,
p.target_completion_date ASC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_accessible_modules(p_user_id uuid)
 RETURNS TABLE(module_id uuid, module_key text, display_name text, department_id uuid, has_access boolean, access_source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH user_role AS (
SELECT role_id FROM profiles WHERE id = p_user_id
),
role_modules AS (
SELECT
dm.id as module_id,
dm.module_key,
dm.display_name,
dm.department_id,
COALESCE(rma.has_access, false) as has_access,
'role' as access_source
FROM department_modules dm
LEFT JOIN role_module_access rma ON rma.module_id = dm.id
CROSS JOIN user_role
WHERE rma.role_id = user_role.role_id
AND dm.is_active = true
),
override_modules AS (
SELECT
dm.id as module_id,
dm.module_key,
dm.display_name,
dm.department_id,
CASE
WHEN upo.override_type = 'grant' THEN true
WHEN upo.override_type = 'revoke' THEN false
END as has_access,
'override' as access_source
FROM user_permission_overrides upo
JOIN department_modules dm ON dm.id = upo.module_id
WHERE upo.user_id = p_user_id
AND dm.is_active = true
)
SELECT
COALESCE(om.module_id, rm.module_id) as module_id,
COALESCE(om.module_key, rm.module_key) as module_key,
COALESCE(om.display_name, rm.display_name) as display_name,
COALESCE(om.department_id, rm.department_id) as department_id,
COALESCE(om.has_access, rm.has_access, false) as has_access,
COALESCE(om.access_source, rm.access_source, 'none') as access_source
FROM role_modules rm
FULL OUTER JOIN override_modules om ON om.module_id = rm.module_id
WHERE COALESCE(om.has_access, rm.has_access, false) = true;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_calendars(user_id_param uuid)
 RETURNS TABLE(calendar_id uuid, calendar_name text, calendar_color text, is_default boolean, member_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
c.id as calendar_id,
c.name as calendar_name,
c.color as calendar_color,
COALESCE(cm.is_default, false) as is_default,
COUNT(DISTINCT cm2.user_id) as member_count
FROM calendars c
LEFT JOIN calendar_members cm ON cm.calendar_id = c.id AND cm.user_id = user_id_param
LEFT JOIN calendar_members cm2 ON cm2.calendar_id = c.id
WHERE c.is_active = true
AND (
c.created_by = user_id_param
OR EXISTS (
SELECT 1 FROM calendar_members
WHERE calendar_members.calendar_id = c.id
AND calendar_members.user_id = user_id_param
)
)
GROUP BY c.id, c.name, c.color, cm.is_default
ORDER BY cm.is_default DESC NULLS LAST, c.name;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_device_summary(p_user_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(device_type text, browser_name text, os_name text, session_count bigint, total_hours numeric, percentage numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH user_sessions_filtered AS (
SELECT
COALESCE(us.device_type, 'unknown') as device_type,
COALESCE(us.browser_name, 'unknown') as browser_name,
COALESCE(us.os_name, 'unknown') as os_name,
us.duration_seconds
FROM user_sessions us
WHERE us.user_id = p_user_id
AND us.session_start >= now() - (p_days || ' days')::interval
),
totals AS (
SELECT SUM(duration_seconds) as total_seconds FROM user_sessions_filtered
)
SELECT
usf.device_type,
usf.browser_name,
usf.os_name,
COUNT(*)::bigint as session_count,
ROUND((SUM(usf.duration_seconds) / 3600.0)::numeric, 2) as total_hours,
ROUND((SUM(usf.duration_seconds)::numeric / NULLIF(t.total_seconds, 0) * 100)::numeric, 1) as percentage
FROM user_sessions_filtered usf
CROSS JOIN totals t
GROUP BY usf.device_type, usf.browser_name, usf.os_name, t.total_seconds
ORDER BY SUM(usf.duration_seconds) DESC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_full_name(user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_name text;
BEGIN
SELECT full_name INTO user_name
FROM profiles
WHERE id = user_id;

RETURN user_name;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_location_summary(p_user_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(location_name text, ip_address text, color text, session_count bigint, total_hours numeric, percentage numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH user_sessions_filtered AS (
SELECT
us.ip_address,
COALESCE(ip.nickname, us.ip_address) as location_name,
COALESCE(ip.color, '#6B7280') as color,
us.duration_seconds
FROM user_sessions us
LEFT JOIN ip_nicknames ip ON us.ip_address = ip.ip_address
WHERE us.user_id = p_user_id
AND us.session_start >= now() - (p_days || ' days')::interval
AND us.ip_address IS NOT NULL
),
totals AS (
SELECT SUM(duration_seconds) as total_seconds FROM user_sessions_filtered
)
SELECT
usf.location_name,
usf.ip_address,
usf.color,
COUNT(*)::bigint as session_count,
ROUND((SUM(usf.duration_seconds) / 3600.0)::numeric, 2) as total_hours,
ROUND((SUM(usf.duration_seconds)::numeric / NULLIF(t.total_seconds, 0) * 100)::numeric, 1) as percentage
FROM user_sessions_filtered usf
CROSS JOIN totals t
GROUP BY usf.location_name, usf.ip_address, usf.color, t.total_seconds
ORDER BY SUM(usf.duration_seconds) DESC;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_module_access(p_user_id uuid, p_module_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_role_id uuid;
v_has_role_access boolean;
v_override_type text;
BEGIN
-- Get user's role
SELECT role_id INTO v_role_id
FROM profiles
WHERE id = p_user_id;

-- If no role assigned, no access
IF v_role_id IS NULL THEN
RETURN false;
END IF;

-- Check for user-specific override first
SELECT override_type INTO v_override_type
FROM user_permission_overrides
WHERE user_id = p_user_id
AND module_id = p_module_id;

-- If override exists, apply it
IF FOUND THEN
IF v_override_type = 'grant' THEN
RETURN true;
ELSIF v_override_type = 'revoke' THEN
RETURN false;
END IF;
END IF;

-- No override, check role-based access
SELECT has_access INTO v_has_role_access
FROM role_module_access
WHERE role_id = v_role_id
AND module_id = p_module_id;

-- Return role-based access (defaults to false if not found)
RETURN COALESCE(v_has_role_access, false);
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_org_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT organization_id FROM profiles WHERE id = auth.uid();
$function$


CREATE OR REPLACE FUNCTION public.get_user_points_balance(user_uuid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
balance integer;
BEGIN
SELECT COALESCE(SUM(points_amount), 0)
INTO balance
FROM points_transactions
WHERE user_id = user_uuid;

RETURN balance;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_proposal_visibility_scope(user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_role text;
visibility_scope text;
can_see_all boolean;
BEGIN
-- Get user's role and permissions
SELECT role, messaging_visibility_scope, can_see_all_proposals
INTO user_role, visibility_scope, can_see_all
FROM profiles
WHERE id = user_id;

-- Admins and managers with can_see_all_proposals see everything
IF user_role IN ('admin', 'manager') OR can_see_all THEN
RETURN 'company';
END IF;

-- Return the user's configured visibility scope
RETURN COALESCE(visibility_scope, 'own');
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_test_tune_permissions(p_user_id uuid)
 RETURNS TABLE(can_view_all_projects boolean, can_edit_bonuses boolean, can_override_bonuses boolean, can_approve_bonuses boolean, can_view_pm_metrics boolean, can_view_admin_controls boolean, can_view_bonus_amounts boolean, can_export_data boolean, user_role text, is_executive boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_role text;
v_is_exec boolean;
BEGIN
-- Get user's role and executive flag
SELECT role, COALESCE(can_view_executive_dashboard, false)
INTO v_role, v_is_exec
FROM profiles
WHERE id = p_user_id;

RETURN QUERY
SELECT
-- Can view all projects
v_role IN ('admin', 'finance') OR v_is_exec as can_view_all_projects,

-- Can edit bonuses (update amounts, statuses)
v_role IN ('admin', 'finance') as can_edit_bonuses,

-- Can override bonus calculations
v_role IN ('admin', 'finance') as can_override_bonuses,

-- Can approve/deny bonuses
v_role IN ('admin', 'finance') as can_approve_bonuses,

-- Can view PM performance metrics
v_role IN ('admin', 'finance', 'manager', 'service_manager') OR v_is_exec as can_view_pm_metrics,

-- Can view admin controls
v_role IN ('admin', 'finance') as can_view_admin_controls,

-- Can view bonus amounts (techs and PMs see their own, admins see all, sales don't see any)
v_role IN ('admin', 'finance', 'manager', 'service_manager', 'tech') as can_view_bonus_amounts,

-- Can export data
true as can_export_data,

-- Return role and executive flag
v_role as user_role,
v_is_exec as is_executive;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_user_visibility_scope()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_role text;
visibility text;
BEGIN
-- Get current user's role
SELECT role INTO user_role
FROM profiles
WHERE id = auth.uid();

-- Admins/managers always have all_offices
IF user_role IN ('admin', 'manager') THEN
RETURN 'all_offices';
END IF;

-- Get user's setting
SELECT COALESCE(visibility_scope, 'all_offices') INTO visibility
FROM user_visibility_settings
WHERE user_id = auth.uid();

RETURN COALESCE(visibility, 'all_offices');
END;
$function$


CREATE OR REPLACE FUNCTION public.get_users_needing_mileage_reminders()
 RETURNS TABLE(user_id uuid, vehicle_id uuid, vehicle_info text, last_entry_date date, days_since_last_entry integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH active_assignments AS (
SELECT 
va.user_id,
va.vehicle_id,
v.make || ' ' || v.model || ' (' || v.license_plate || ')' as vehicle_info
FROM vehicle_assignments va
JOIN vehicles v ON v.id = va.vehicle_id
WHERE va.is_active = true
AND v.status = 'active'
),
last_entries AS (
SELECT 
me.vehicle_id,
me.user_id,
MAX(me.entry_date) as last_entry_date
FROM mileage_entries me
GROUP BY me.vehicle_id, me.user_id
)
SELECT 
aa.user_id,
aa.vehicle_id,
aa.vehicle_info,
COALESCE(le.last_entry_date, (SELECT assigned_date FROM vehicle_assignments WHERE id = (
SELECT id FROM vehicle_assignments 
WHERE vehicle_id = aa.vehicle_id 
AND user_id = aa.user_id 
AND is_active = true 
LIMIT 1
))) as last_entry_date,
CURRENT_DATE - COALESCE(le.last_entry_date, (SELECT assigned_date FROM vehicle_assignments WHERE id = (
SELECT id FROM vehicle_assignments 
WHERE vehicle_id = aa.vehicle_id 
AND user_id = aa.user_id 
AND is_active = true 
LIMIT 1
))) as days_since_last_entry
FROM active_assignments aa
LEFT JOIN last_entries le ON le.vehicle_id = aa.vehicle_id AND le.user_id = aa.user_id
WHERE CURRENT_DATE - COALESCE(le.last_entry_date, (SELECT assigned_date FROM vehicle_assignments WHERE id = (
SELECT id FROM vehicle_assignments 
WHERE vehicle_id = aa.vehicle_id 
AND user_id = aa.user_id 
AND is_active = true 
LIMIT 1
))) >= 90;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_vehicle_statistics(p_vehicle_id uuid)
 RETURNS TABLE(total_entries integer, total_miles_recorded integer, average_miles_per_quarter numeric, last_entry_date date, last_odometer_reading integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
WITH entries AS (
SELECT 
COUNT(*) as entry_count,
MAX(odometer_reading) - MIN(odometer_reading) as miles_driven,
MAX(entry_date) as last_date,
MAX(odometer_reading) as last_reading
FROM mileage_entries
WHERE vehicle_id = p_vehicle_id
)
SELECT 
COALESCE(entry_count::integer, 0),
COALESCE(miles_driven::integer, 0),
CASE 
WHEN entry_count > 1 THEN 
ROUND(miles_driven::numeric / GREATEST(entry_count - 1, 1), 2)
ELSE 0
END as avg_per_quarter,
last_date,
last_reading::integer
FROM entries;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_work_order_group_summary(p_group_id uuid)
 RETURNS TABLE(work_order_count integer, total_estimated_hours numeric, total_actual_hours numeric, completion_status text, all_completed boolean, all_billable boolean, group_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT
COUNT(*)::int as work_order_count,
SUM(estimated_hours) as total_estimated_hours,
SUM(actual_hours) as total_actual_hours,
CASE
WHEN COUNT(*) = COUNT(*) FILTER (WHERE status = 'completed') THEN 'all_completed'
WHEN COUNT(*) FILTER (WHERE status = 'completed') > 0 THEN 'partially_completed'
ELSE 'not_started'
END as completion_status,
(COUNT(*) = COUNT(*) FILTER (WHERE status = 'completed')) as all_completed,
(COUNT(*) = COUNT(*) FILTER (WHERE is_billable = true)) as all_billable,
p_group_id as group_id
FROM work_orders
WHERE work_order_group_id = p_group_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.grant_customer_program(p_contact_id uuid, p_program text, p_project_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 90)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid; v_role text; v_start date; v_end date; v_id uuid; v_subscription uuid;
BEGIN
 SELECT organization_id,role INTO v_org,v_role FROM profiles WHERE id=auth.uid() AND is_active AND contact_id IS NULL;
 IF v_org IS NULL OR v_role NOT IN ('admin','manager','service_manager') THEN RAISE EXCEPTION 'Not authorized'; END IF;
 IF NOT EXISTS(SELECT 1 FROM contacts WHERE id=p_contact_id AND organization_id=v_org) THEN RAISE EXCEPTION 'Contact not found'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_contact_id::text,0));
 IF p_program='test_and_tune' THEN
  SELECT substantial_completion_date INTO v_start FROM projects WHERE id=p_project_id AND contact_id=p_contact_id AND organization_id=v_org;
  IF v_start IS NULL THEN RAISE EXCEPTION 'Select a project with a substantial completion date'; END IF;
  v_end=v_start+90;
  IF v_end<CURRENT_DATE THEN RAISE EXCEPTION 'The project Test & Tune period has ended'; END IF;
  IF EXISTS(SELECT 1 FROM punchlist_access_grants WHERE project_id=p_project_id AND access_type='test_and_tune') THEN RAISE EXCEPTION 'This project already has Test & Tune access. Use its existing grant'; END IF;
 ELSIF p_program='vip_trial' THEN
  IF p_days NOT BETWEEN 1 AND 365 THEN RAISE EXCEPTION 'Trial duration must be 1 to 365 days'; END IF;
  IF EXISTS(SELECT 1 FROM recurring_subscriptions rs LEFT JOIN recurring_plans rp ON rp.id=rs.plan_id WHERE rs.contact_id=p_contact_id AND rs.organization_id=v_org AND ((rs.status='active' AND rp.plan_type='vip_plan') OR (rs.status='trial' AND rs.trial_source='vip_trial' AND rs.trial_end_date>=CURRENT_DATE))) THEN RAISE EXCEPTION 'Customer already has VIP membership or a VIP trial'; END IF;
  v_start=CURRENT_DATE; v_end=v_start+p_days;
  INSERT INTO recurring_subscriptions(company_id,organization_id,contact_id,status,start_date,next_billing_date,trial_started_date,trial_end_date,trial_source,auto_invoice,auto_send,auto_renew,created_by,notes)
  VALUES(v_org,v_org,p_contact_id,'trial',v_start,v_end,v_start,v_end,'vip_trial',false,false,false,auth.uid(),'Explicit promotional VIP trial; no automatic billing') RETURNING id INTO v_subscription;
 ELSE RAISE EXCEPTION 'Unknown customer program'; END IF;
 INSERT INTO punchlist_access_grants(organization_id,contact_id,project_id,subscription_id,access_type,status,granted_date,expiration_date)
 VALUES(v_org,p_contact_id,CASE WHEN p_program='test_and_tune' THEN p_project_id END,v_subscription,p_program,'active',v_start,v_end) RETURNING id INTO v_id;
 RETURN v_id;
END $function$


CREATE OR REPLACE FUNCTION public.grant_punchlist_access_directly(p_contact_id uuid, p_days integer DEFAULT 90, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(access_grant_id uuid, is_renewal boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_existing_grant_id uuid;
v_is_renewal boolean := false;
v_contact_name text;
BEGIN
-- Verify contact exists
SELECT full_name INTO v_contact_name
FROM contacts
WHERE id = p_contact_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Contact not found';
END IF;

-- Check if contact already has an access grant (active or expired)
SELECT id INTO v_existing_grant_id
FROM punchlist_access_grants
WHERE contact_id = p_contact_id
LIMIT 1;

IF v_existing_grant_id IS NOT NULL THEN
-- Renew existing grant
v_is_renewal := true;

UPDATE punchlist_access_grants
SET
status = 'active',
granted_date = CURRENT_DATE,
expiration_date = CURRENT_DATE + (p_days || ' days')::interval,
notes = COALESCE(
p_notes,
'Access renewed directly by admin on ' || CURRENT_DATE::text
),
updated_at = now()
WHERE id = v_existing_grant_id;

ELSE
-- Create new grant
v_is_renewal := false;

INSERT INTO punchlist_access_grants (
contact_id,
access_type,
project_id,
granted_date,
expiration_date,
status,
notes
) VALUES (
p_contact_id,
'test_and_tune',
NULL,
CURRENT_DATE,
CURRENT_DATE + (p_days || ' days')::interval,
'active',
COALESCE(
p_notes,
'Access granted directly to ' || v_contact_name || ' by admin on ' || CURRENT_DATE::text
)
)
RETURNING id INTO v_existing_grant_id;
END IF;

RETURN QUERY SELECT v_existing_grant_id, v_is_renewal;
END;
$function$


CREATE OR REPLACE FUNCTION public.guard_employee_config_historical_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
-- SECURITY DEFINER functions run as postgres — allow them through.
IF current_user = 'postgres' THEN
RETURN NEW;
END IF;

-- Block direct changes to any historically meaningful field.
IF
NEW.compensation_type        IS DISTINCT FROM OLD.compensation_type
OR NEW.requires_daily_clock     IS DISTINCT FROM OLD.requires_daily_clock
OR NEW.requires_time_allocation IS DISTINCT FROM OLD.requires_time_allocation
OR NEW.payroll_time_basis       IS DISTINCT FROM OLD.payroll_time_basis
OR NEW.expected_weekly_hours    IS DISTINCT FROM OLD.expected_weekly_hours
OR NEW.standard_start_time      IS DISTINCT FROM OLD.standard_start_time
OR NEW.standard_end_time        IS DISTINCT FROM OLD.standard_end_time
OR NEW.work_days                IS DISTINCT FROM OLD.work_days
OR NEW.overtime_eligible        IS DISTINCT FROM OLD.overtime_eligible
OR NEW.pto_eligible             IS DISTINCT FROM OLD.pto_eligible
OR NEW.pay_schedule_id          IS DISTINCT FROM OLD.pay_schedule_id
OR NEW.effective_from           IS DISTINCT FROM OLD.effective_from
OR NEW.effective_to             IS DISTINCT FROM OLD.effective_to
THEN
RAISE EXCEPTION
'Direct modification of historically significant employee_payroll_configs fields is not permitted. Use the update_employee_and_config() RPC to create an effective-dated successor.';
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.guard_employment_classification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
-- SECURITY DEFINER functions run as postgres — allow them through.
IF current_user = 'postgres' THEN
RETURN NEW;
END IF;

-- Block any direct change to employment_classification.
IF NEW.employment_classification IS DISTINCT FROM OLD.employment_classification THEN
RAISE EXCEPTION
'Direct change to profiles.employment_classification is not permitted. Use the classify_as_employee(), classify_as_non_employee(), or update_employee_and_config() RPC.';
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.guard_finalization_tax_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_tax_status text;
v_is_finalizing boolean := false;
v_calc_result jsonb;
v_resolved_status text;
v_transaction_type text;
v_transaction_id uuid;
BEGIN
IF TG_TABLE_NAME = 'proposals' THEN
IF NEW.status IN ('sent', 'approved') AND COALESCE(OLD.status, '') NOT IN ('sent', 'approved') THEN
v_is_finalizing := true;
END IF;
v_transaction_type := 'proposal';
v_transaction_id := NEW.id;
ELSIF TG_TABLE_NAME = 'change_orders' THEN
IF NEW.status = 'approved' AND COALESCE(OLD.status, '') <> 'approved' THEN
v_is_finalizing := true;
END IF;
v_transaction_type := 'change_order';
v_transaction_id := NEW.id;
ELSIF TG_TABLE_NAME = 'invoices' THEN
IF NEW.status = 'submitted' AND COALESCE(OLD.status, '') <> 'submitted' THEN
v_is_finalizing := true;
END IF;
v_transaction_type := 'invoice';
v_transaction_id := NEW.id;
END IF;

IF NOT v_is_finalizing THEN
RETURN NEW;
END IF;

v_tax_status := NEW.tax_calculation_status;

IF v_tax_status IN ('ready', 'exempt', 'not_collecting') THEN
RETURN NEW;
END IF;

IF v_tax_status = 'review_required' THEN
BEGIN
v_calc_result := calculate_tax_context(v_transaction_type, v_transaction_id);
v_resolved_status := v_calc_result->>'tax_calculation_status';
IF COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0) = 0 THEN
NEW.tax_calculation_status := v_resolved_status;
NEW.tax_review_required := false;
NEW.tax_amount := 0;
RETURN NEW;
END IF;
EXCEPTION WHEN OTHERS THEN
RAISE EXCEPTION 'Cannot finalize %: tax calculation requires review. Please resolve tax review issues before finalizing.', TG_TABLE_NAME
USING ERRCODE = 'check_violation';
END;
RAISE EXCEPTION 'Cannot finalize %: tax calculation requires review. Please resolve tax review issues before finalizing.', TG_TABLE_NAME
USING ERRCODE = 'check_violation';
END IF;

IF v_tax_status IS NULL OR v_tax_status NOT IN ('ready', 'exempt', 'not_collecting', 'review_required') THEN
BEGIN
v_calc_result := calculate_tax_context(v_transaction_type, v_transaction_id);
v_resolved_status := v_calc_result->>'tax_calculation_status';
EXCEPTION WHEN OTHERS THEN
RAISE EXCEPTION 'Cannot finalize %: tax calculation could not be resolved. Please run tax calculation and resolve any issues before finalizing.', TG_TABLE_NAME
USING ERRCODE = 'check_violation';
END;

IF v_resolved_status IN ('ready', 'exempt', 'not_collecting') THEN
NEW.tax_calculation_status := v_resolved_status;
NEW.tax_review_required := false;
NEW.tax_amount := COALESCE((v_calc_result->>'tax_amount')::numeric, 0);
RETURN NEW;
ELSIF v_resolved_status = 'review_required' THEN
IF COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0) = 0 THEN
NEW.tax_calculation_status := v_resolved_status;
NEW.tax_review_required := false;
NEW.tax_amount := 0;
RETURN NEW;
END IF;
RAISE EXCEPTION 'Cannot finalize %: tax calculation requires review. Please resolve tax review issues before finalizing.', TG_TABLE_NAME
USING ERRCODE = 'check_violation';
ELSE
RAISE EXCEPTION 'Cannot finalize %: tax calculation returned an unrecognized status. Please run tax calculation and resolve any issues before finalizing.', TG_TABLE_NAME
USING ERRCODE = 'check_violation';
END IF;
END IF;

RAISE EXCEPTION 'Cannot finalize %: tax calculation status must be resolved before finalizing.', TG_TABLE_NAME
USING ERRCODE = 'check_violation';
END;
$function$


CREATE OR REPLACE FUNCTION public.guard_lost_review_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE actor_role text; actor_org uuid;
BEGIN
 NEW.can_send_lost_opportunity_reviews := coalesce(NEW.can_send_lost_opportunity_reviews,NEW.role IN ('sales','sales_v2','sales_manager','admin','manager','owner'));
 NEW.can_view_lost_opportunity_submissions := coalesce(NEW.can_view_lost_opportunity_submissions,NEW.role='admin');
 IF current_user IN ('authenticated','anon') AND ((TG_OP='INSERT' AND (NEW.can_view_lost_opportunity_submissions OR NEW.notify_lost_opportunity_submissions)) OR (TG_OP='UPDATE' AND
 (NEW.can_send_lost_opportunity_reviews IS DISTINCT FROM OLD.can_send_lost_opportunity_reviews OR NEW.can_view_lost_opportunity_submissions IS DISTINCT FROM OLD.can_view_lost_opportunity_submissions OR NEW.notify_lost_opportunity_submissions IS DISTINCT FROM OLD.notify_lost_opportunity_submissions))) THEN
  SELECT role,organization_id INTO actor_role,actor_org FROM profiles WHERE id=auth.uid();
  IF actor_role IS DISTINCT FROM 'admin' OR actor_org IS DISTINCT FROM NEW.organization_id OR (TG_OP='UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id) THEN
   RAISE EXCEPTION 'Only an administrator in this company can change Lost Opportunity permissions';
  END IF;
 END IF;
 RETURN NEW;
END $function$


CREATE OR REPLACE FUNCTION public.guard_pay_period_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
-- SECURITY DEFINER functions run as postgres — allow them through.
IF current_user = 'postgres' THEN
RETURN NEW;
END IF;

-- Block any direct transition to or from 'payroll_approved'.
IF OLD.status = 'payroll_approved' OR NEW.status = 'payroll_approved' THEN
IF OLD.status IS DISTINCT FROM NEW.status THEN
RAISE EXCEPTION
'Direct status transition % → % on pay_periods is not permitted. Use the approve_payroll_period() or reopen_pay_period() RPC.',
COALESCE(OLD.status, '<null>'),
COALESCE(NEW.status, '<null>');
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.guard_work_order_option()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND OLD.system_key IS NOT NULL THEN RAISE EXCEPTION 'Built-in options can be deactivated, not deleted'; END IF;
 IF TG_OP='UPDATE' AND (NEW.organization_id<>OLD.organization_id OR NEW.kind<>OLD.kind OR NEW.system_key IS DISTINCT FROM OLD.system_key OR NEW.behavior<>OLD.behavior) THEN
  RAISE EXCEPTION 'Option identity and behavior are immutable. Create another option instead';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$


CREATE OR REPLACE FUNCTION public.handle_deposit_billing_action(p_proposal_id uuid, p_send_notification boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal proposals%ROWTYPE;
v_invoice_id uuid;
v_sales_order_id uuid;
v_project_id uuid;
v_project_number text;
v_result jsonb;
BEGIN
-- Get proposal details
SELECT * INTO v_proposal FROM proposals WHERE id = p_proposal_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Proposal not found';
END IF;

-- Verify proposal is in correct status
IF v_proposal.status NOT IN ('approved', 'approved_pending_action') THEN
RAISE EXCEPTION 'Proposal must be approved before billing action';
END IF;

-- Verify deposit is required
IF NOT v_proposal.require_deposit THEN
RAISE EXCEPTION 'This proposal does not require a deposit';
END IF;

-- Create or update sales order with pending_deposit status
IF v_proposal.sales_order_id IS NULL THEN
-- Create new sales order
INSERT INTO sales_orders (
company_id,
proposal_id,
contact_id,
order_number,
status,
contract_total,
created_by
) VALUES (
v_proposal.company_id,
v_proposal.id,
v_proposal.contact_id,
REPLACE(v_proposal.proposal_number, 'PRO-', 'SO-'),
'pending_deposit',
v_proposal.total,
auth.uid()
)
RETURNING id INTO v_sales_order_id;

-- Update proposal with sales_order_id
UPDATE proposals SET sales_order_id = v_sales_order_id WHERE id = p_proposal_id;
ELSE
-- Update existing sales order
UPDATE sales_orders
SET status = 'pending_deposit'
WHERE id = v_proposal.sales_order_id
RETURNING id INTO v_sales_order_id;
END IF;

-- Create project if it doesn't exist
IF NOT EXISTS (SELECT 1 FROM projects WHERE sales_order_id = v_sales_order_id) THEN
-- Generate project number
v_project_number := get_next_project_number();

-- Create project with pending_deposit status
INSERT INTO projects (
company_id,
sales_order_id,
contact_id,
project_number,
name,
status,
assigned_pm,
job_site_address,
notes,
created_by
) VALUES (
v_proposal.company_id,
v_sales_order_id,
v_proposal.contact_id,
v_project_number,
v_proposal.title,
'planning', -- Project in planning until deposit is paid
v_proposal.created_by, -- Default PM is proposal creator
CASE
WHEN v_proposal.jobsite_location IS NOT NULL
THEN v_proposal.jobsite_location
ELSE NULL
END,
'Project created from approved proposal ' || v_proposal.proposal_number || '. Awaiting deposit payment.',
auth.uid()
)
RETURNING id INTO v_project_id;

RAISE NOTICE 'Created Project % for Proposal %', v_project_number, v_proposal.proposal_number;
END IF;

-- Create deposit invoice if it doesn't exist
IF v_proposal.deposit_invoice_id IS NULL THEN
-- Generate invoice number
DECLARE
v_invoice_number text;
v_max_number integer;
BEGIN
SELECT COALESCE(MAX(
CASE
WHEN invoice_number ~ '^\\d+$' THEN invoice_number::integer
ELSE 0
END
), 0) INTO v_max_number
FROM invoices
WHERE company_id = v_proposal.company_id;

v_invoice_number := LPAD((v_max_number + 1)::text, 5, '0');

-- Create invoice
INSERT INTO invoices (
company_id,
proposal_id,
contact_id,
invoice_number,
invoice_type,
status,
subtotal,
tax_amount,
total,
amount_paid,
amount_due,
created_by
) VALUES (
v_proposal.company_id,
v_proposal.id,
v_proposal.contact_id,
v_invoice_number,
'deposit',
'sent',
v_proposal.deposit_amount_due,
0,
v_proposal.deposit_amount_due,
0,
v_proposal.deposit_amount_due,
auth.uid()
)
RETURNING id INTO v_invoice_id;

-- Add line item
INSERT INTO invoice_line_items (
company_id,
invoice_id,
description,
quantity,
unit_price,
total
) VALUES (
v_proposal.company_id,
v_invoice_id,
'Deposit for Proposal ' || v_proposal.proposal_number,
1,
v_proposal.deposit_amount_due,
v_proposal.deposit_amount_due
);

-- Update proposal
UPDATE proposals
SET
deposit_invoice_id = v_invoice_id,
deposit_request_sent = true,
deposit_request_sent_at = now()
WHERE id = p_proposal_id;
END;
ELSE
v_invoice_id := v_proposal.deposit_invoice_id;

-- Update existing invoice to 'sent' if it was draft
UPDATE invoices
SET status = 'sent'
WHERE id = v_invoice_id AND status = 'draft';
END IF;

-- Update proposal with billing action
UPDATE proposals
SET
status = 'approved',
billing_action_taken = true,
billing_action_type = 'deposit_invoice',
billing_action_at = now(),
billing_action_by = auth.uid()
WHERE id = p_proposal_id;

-- Record notification if requested (but don't send - that's done by frontend/edge function)
IF p_send_notification THEN
PERFORM record_proposal_notification(
p_proposal_id,
'deposit_invoice_sent',
(SELECT email FROM contacts WHERE id = v_proposal.contact_id),
(SELECT full_name FROM contacts WHERE id = v_proposal.contact_id),
'email',
jsonb_build_object(
'invoice_id', v_invoice_id,
'sales_order_id', v_sales_order_id,
'project_id', v_project_id,
'amount', v_proposal.deposit_amount_due
)
);
END IF;

-- Return result
v_result := jsonb_build_object(
'success', true,
'invoice_id', v_invoice_id,
'sales_order_id', v_sales_order_id,
'project_id', v_project_id,
'notification_recorded', p_send_notification
);

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_deposit_billing_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal proposals%ROWTYPE;
v_invoice_id uuid;
v_sales_order_id uuid;
v_project_id uuid;
v_project_number text;
v_result jsonb;
BEGIN
-- Get proposal details
SELECT * INTO v_proposal FROM proposals WHERE id = p_proposal_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Proposal not found';
END IF;

-- Verify proposal is in correct status
IF v_proposal.status NOT IN ('approved', 'approved_pending_action') THEN
RAISE EXCEPTION 'Proposal must be approved before billing action';
END IF;

-- Verify deposit is required
IF NOT v_proposal.require_deposit THEN
RAISE EXCEPTION 'This proposal does not require a deposit';
END IF;

-- Create or update sales order with pending_deposit status
IF v_proposal.sales_order_id IS NULL THEN
-- Create new sales order
INSERT INTO sales_orders (
company_id,
proposal_id,
contact_id,
order_number,
status,
contract_total,
created_by
) VALUES (
v_proposal.company_id,
v_proposal.id,
v_proposal.contact_id,
REPLACE(v_proposal.proposal_number, 'PRO-', 'SO-'),
'pending_deposit',
v_proposal.total,
auth.uid()
)
RETURNING id INTO v_sales_order_id;

-- Update proposal with sales_order_id
UPDATE proposals SET sales_order_id = v_sales_order_id WHERE id = p_proposal_id;
ELSE
-- Update existing sales order
UPDATE sales_orders
SET status = 'pending_deposit'
WHERE id = v_proposal.sales_order_id
RETURNING id INTO v_sales_order_id;
END IF;

-- Create project if it doesn't exist
IF NOT EXISTS (SELECT 1 FROM projects WHERE sales_order_id = v_sales_order_id) THEN
-- Generate project number
v_project_number := get_next_project_number();

-- Create project with pending_deposit status
INSERT INTO projects (
company_id,
sales_order_id,
contact_id,
project_number,
name,
status,
assigned_pm,
job_site_address,
notes,
created_by
) VALUES (
v_proposal.company_id,
v_sales_order_id,
v_proposal.contact_id,
v_project_number,
v_proposal.title,
'planning', -- Project in planning until deposit is paid
v_proposal.created_by, -- Default PM is proposal creator
CASE
WHEN v_proposal.jobsite_location IS NOT NULL
THEN v_proposal.jobsite_location
ELSE NULL
END,
'Project created from approved proposal ' || v_proposal.proposal_number || '. Awaiting deposit payment.',
auth.uid()
)
RETURNING id INTO v_project_id;

RAISE NOTICE 'Created Project % for Proposal %', v_project_number, v_proposal.proposal_number;
END IF;

-- Create deposit invoice if it doesn't exist
IF v_proposal.deposit_invoice_id IS NULL THEN
-- Generate invoice number
DECLARE
v_invoice_number text;
v_max_number integer;
BEGIN
SELECT COALESCE(MAX(
CASE
WHEN invoice_number ~ '^\\d+$' THEN invoice_number::integer
ELSE 0
END
), 0) INTO v_max_number
FROM invoices
WHERE company_id = v_proposal.company_id;

v_invoice_number := LPAD((v_max_number + 1)::text, 5, '0');

-- Create invoice
INSERT INTO invoices (
company_id,
proposal_id,
contact_id,
invoice_number,
invoice_type,
status,
subtotal,
tax_amount,
total,
amount_paid,
amount_due,
created_by
) VALUES (
v_proposal.company_id,
v_proposal.id,
v_proposal.contact_id,
v_invoice_number,
'deposit',
'submitted',
v_proposal.deposit_amount_due,
0,
v_proposal.deposit_amount_due,
0,
v_proposal.deposit_amount_due,
auth.uid()
)
RETURNING id INTO v_invoice_id;

-- Add line item
INSERT INTO invoice_line_items (
company_id,
invoice_id,
description,
quantity,
unit_price,
total
) VALUES (
v_proposal.company_id,
v_invoice_id,
'Deposit for Proposal ' || v_proposal.proposal_number,
1,
v_proposal.deposit_amount_due,
v_proposal.deposit_amount_due
);

-- Update proposal
UPDATE proposals
SET
deposit_invoice_id = v_invoice_id,
deposit_request_sent = true,
deposit_request_sent_at = now()
WHERE id = p_proposal_id;
END;
ELSE
v_invoice_id := v_proposal.deposit_invoice_id;

-- Update existing invoice to 'submitted' if it was draft
UPDATE invoices
SET status = 'submitted'
WHERE id = v_invoice_id AND status = 'draft';
END IF;

-- Update proposal with billing action
UPDATE proposals
SET
status = 'approved',
billing_action_taken = true,
billing_action_type = 'deposit_invoice',
billing_action_at = now(),
billing_action_by = auth.uid()
WHERE id = p_proposal_id;

-- Record notification if requested (but don't send - that's done by frontend/edge function)
IF p_send_notification THEN
PERFORM record_proposal_notification(
p_proposal_id,
'deposit_invoice_sent',
(SELECT email FROM contacts WHERE id = v_proposal.contact_id),
(SELECT full_name FROM contacts WHERE id = v_proposal.contact_id),
'email',
jsonb_build_object(
'invoice_id', v_invoice_id,
'sales_order_id', v_sales_order_id,
'project_id', v_project_id,
'amount', v_proposal.deposit_amount_due
)
);
END IF;

-- Return result
v_result := jsonb_build_object(
'success', true,
'invoice_id', v_invoice_id,
'sales_order_id', v_sales_order_id,
'project_id', v_project_id,
'notification_recorded', p_send_notification
);

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_deposit_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invoice RECORD;
v_proposal_id uuid;
v_sales_order_id uuid;
BEGIN
SELECT id, amount_due, status
INTO v_invoice
FROM invoices
WHERE id = NEW.invoice_id;

IF v_invoice.amount_due <= 0 AND v_invoice.status = 'paid' THEN
SELECT id INTO v_proposal_id
FROM proposals
WHERE deposit_invoice_id = NEW.invoice_id
AND deposit_paid = false
LIMIT 1;

IF v_proposal_id IS NOT NULL THEN
UPDATE proposals
SET 
deposit_paid = true,
deposit_payment_date = now()
WHERE id = v_proposal_id;

SELECT id INTO v_sales_order_id
FROM sales_orders
WHERE proposal_id = v_proposal_id
AND status = 'pending_deposit';

IF v_sales_order_id IS NOT NULL THEN
UPDATE sales_orders
SET status = 'planning'
WHERE id = v_sales_order_id;
END IF;

BEGIN
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id
)
SELECT 
p.created_by,
'deposit_paid',
'Deposit Payment Received',
'Deposit payment received for proposal #' || p.proposal_number,
p.id
FROM proposals p
WHERE p.id = v_proposal_id;
EXCEPTION
WHEN OTHERS THEN
RAISE WARNING 'Failed to create deposit_paid notification: %', SQLERRM;
END;
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_deposit_payment_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal_id uuid;
v_sales_order_id uuid;
v_proposal_number text;
v_sales_rep_id uuid;
BEGIN
-- Only process when deposit invoice status changes to 'paid'
IF NEW.invoice_type = 'deposit'
AND NEW.status = 'paid'
AND OLD.status != 'paid'
AND NEW.proposal_id IS NOT NULL
THEN
-- Get proposal and sales order info
SELECT 
p.id,
p.sales_order_id,
p.proposal_number,
COALESCE(p.assigned_to, p.created_by)
INTO 
v_proposal_id,
v_sales_order_id,
v_proposal_number,
v_sales_rep_id
FROM proposals p
WHERE p.id = NEW.proposal_id;

-- Update proposal deposit_paid flag
UPDATE proposals
SET deposit_paid = true,
deposit_payment_date = CURRENT_DATE
WHERE id = v_proposal_id;

-- Update sales order status from pending_deposit to planning
IF v_sales_order_id IS NOT NULL THEN
UPDATE sales_orders
SET status = 'planning',
notes = COALESCE(notes, '') || E'\
Deposit paid on ' || CURRENT_DATE::text
WHERE id = v_sales_order_id
AND status = 'pending_deposit';
END IF;

-- Notify sales rep that deposit was paid
BEGIN
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id
) VALUES (
v_sales_rep_id,
'deposit_invoice_paid',
'Deposit Payment Received',
'Deposit payment received for proposal ' || v_proposal_number || '. Sales order moved to Planning and is ready for scheduling.',
v_proposal_id
);
EXCEPTION
WHEN OTHERS THEN
RAISE WARNING 'Failed to create deposit paid notification: %', SQLERRM;
END;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_invoice_paid_deposit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal_id uuid;
v_sales_order_id uuid;
BEGIN
-- Only proceed if status changed to paid and it wasn't paid before
IF NEW.status = 'paid' AND (OLD.status IS NULL OR OLD.status != 'paid') THEN
-- Check if this invoice is a deposit invoice for a proposal
SELECT id INTO v_proposal_id
FROM proposals
WHERE deposit_invoice_id = NEW.id
AND deposit_paid = false
LIMIT 1;

IF v_proposal_id IS NOT NULL THEN
-- Update proposal deposit status
UPDATE proposals
SET 
deposit_paid = true,
deposit_payment_date = now()
WHERE id = v_proposal_id;

-- Update sales order status from pending_deposit to planning
SELECT id INTO v_sales_order_id
FROM sales_orders
WHERE proposal_id = v_proposal_id
AND status = 'pending_deposit';

IF v_sales_order_id IS NOT NULL THEN
UPDATE sales_orders
SET status = 'planning'
WHERE id = v_sales_order_id;
END IF;

-- Update project status to approved (from pending_deposit)
UPDATE projects
SET status = 'approved'
WHERE sales_order_id = v_sales_order_id
AND status = 'pending_deposit';

-- Create notification for proposal creator
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id
)
SELECT 
p.created_by,
'deposit_paid',
'Deposit Payment Received',
'Deposit payment received for proposal #' || p.proposal_number || '. Project is now approved and ready for production.',
p.id
FROM proposals p
WHERE p.id = v_proposal_id;
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_mileage_entry_submission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_vehicle_info text;
BEGIN
-- Get vehicle information
SELECT make || ' ' || model || ' (' || license_plate || ')'
INTO v_vehicle_info
FROM vehicles
WHERE id = NEW.vehicle_id;

-- Mark existing reminders as completed
UPDATE mileage_reminders
SET status = 'completed',
entry_submitted_at = now()
WHERE user_id = NEW.user_id
AND vehicle_id = NEW.vehicle_id
AND status IN ('pending', 'sent', 'overdue');

-- DISMISS/DELETE mileage reminder notifications for this user/vehicle
DELETE FROM notifications
WHERE user_id = NEW.user_id
AND type = 'mileage_reminder'
AND reference_id = NEW.vehicle_id::text
AND reference_type = 'vehicle'
AND read_at IS NULL;

-- Create next reminder
PERFORM create_next_mileage_reminder(NEW.user_id, NEW.vehicle_id);

-- Create notification for admins
INSERT INTO notifications (user_id, type, title, body, reference_id, reference_type)
SELECT
p.id,
'system',
'Mileage Entry Submitted',
(SELECT full_name FROM profiles WHERE id = NEW.user_id) || ' submitted mileage for ' || v_vehicle_info,
NEW.id::text,
'mileage_entry'
FROM profiles p
WHERE p.role IN ('admin', 'manager');

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_username text;
v_role text;
v_full_name text;
v_email text;
v_org_id uuid;
v_employment_type text;
v_requires_daily_clock boolean;
BEGIN
-- Skip profile creation for portal users (customers accessing the customer portal)
IF (NEW.raw_user_meta_data->>'is_portal_user')::boolean = true THEN
RETURN NEW;
END IF;

v_email := NEW.email;
v_full_name := COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(v_email, '@', 1));
v_username := COALESCE(
NEW.raw_user_meta_data->>'username',
lower(regexp_replace(split_part(v_email, '@', 1), '[^a-zA-Z0-9]', '', 'g'))
);
v_role := COALESCE(NEW.raw_user_meta_data->>'role', 'sales');
v_org_id := (NEW.raw_user_meta_data->>'organization_id')::uuid;

IF v_org_id IS NULL THEN
SELECT id INTO v_org_id FROM organizations LIMIT 1;
END IF;

IF v_role = 'tech' THEN
v_employment_type := 'hourly';
v_requires_daily_clock := true;
ELSIF v_role IN ('admin', 'finance', 'manager') THEN
v_employment_type := 'salary_no_clock';
v_requires_daily_clock := false;
ELSE
v_employment_type := 'salary';
v_requires_daily_clock := false;
END IF;

BEGIN
INSERT INTO profiles (id, email, full_name, username, role, organization_id, employment_type, requires_daily_clock)
VALUES (NEW.id, v_email, v_full_name, v_username, v_role, v_org_id, v_employment_type, v_requires_daily_clock);
EXCEPTION WHEN unique_violation THEN
v_username := v_username || '_' || substr(NEW.id::text, 1, 4);
INSERT INTO profiles (id, email, full_name, username, role, organization_id, employment_type, requires_daily_clock)
VALUES (NEW.id, v_email, v_full_name, v_username, v_role, v_org_id, v_employment_type, v_requires_daily_clock);
END;

BEGIN
INSERT INTO user_starred_modules (user_id, module_id, sort_order)
SELECT NEW.id, dsm.module_id, dsm.sort_order
FROM default_starred_modules dsm
WHERE dsm.role = v_role
ON CONFLICT DO NOTHING;
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Failed to populate default starred modules for user %: %', NEW.id, SQLERRM;
END;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_no_deposit_action(p_proposal_id uuid, p_send_notification boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal proposals%ROWTYPE;
v_sales_order_id uuid;
v_project_id uuid;
v_project_number text;
v_result jsonb;
BEGIN
-- Get proposal details
SELECT * INTO v_proposal FROM proposals WHERE id = p_proposal_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Proposal not found';
END IF;

-- Verify proposal is approved
IF v_proposal.status NOT IN ('approved', 'approved_pending_action') THEN
RAISE EXCEPTION 'Proposal must be approved';
END IF;

-- Create or update sales order with planning status
IF v_proposal.sales_order_id IS NULL THEN
INSERT INTO sales_orders (
company_id,
proposal_id,
contact_id,
order_number,
status,
contract_total,
created_by
) VALUES (
v_proposal.company_id,
v_proposal.id,
v_proposal.contact_id,
REPLACE(v_proposal.proposal_number, 'PRO-', 'SO-'),
'planning',
v_proposal.total,
auth.uid()
)
RETURNING id INTO v_sales_order_id;

UPDATE proposals SET sales_order_id = v_sales_order_id WHERE id = p_proposal_id;
ELSE
UPDATE sales_orders
SET status = 'planning'
WHERE id = v_proposal.sales_order_id
RETURNING id INTO v_sales_order_id;
END IF;

-- Create project if it doesn't exist (ready to work since no deposit required)
IF NOT EXISTS (SELECT 1 FROM projects WHERE sales_order_id = v_sales_order_id) THEN
-- Generate project number
v_project_number := get_next_project_number();

-- Create project with approved status (ready to work)
INSERT INTO projects (
company_id,
sales_order_id,
contact_id,
project_number,
name,
status,
assigned_pm,
job_site_address,
notes,
created_by
) VALUES (
v_proposal.company_id,
v_sales_order_id,
v_proposal.contact_id,
v_project_number,
v_proposal.title,
'planning', -- Ready to schedule work
v_proposal.created_by, -- Default PM is proposal creator
CASE
WHEN v_proposal.jobsite_location IS NOT NULL
THEN v_proposal.jobsite_location
ELSE NULL
END,
'Project created from approved proposal ' || v_proposal.proposal_number || '. No deposit required. Ready to schedule.',
auth.uid()
)
RETURNING id INTO v_project_id;

RAISE NOTICE 'Created Project % for Proposal %', v_project_number, v_proposal.proposal_number;
END IF;

-- Update proposal
UPDATE proposals
SET
status = 'approved',
billing_action_taken = true,
billing_action_type = 'no_deposit_required',
billing_action_at = now(),
billing_action_by = auth.uid()
WHERE id = p_proposal_id;

-- Record notification if requested
IF p_send_notification THEN
PERFORM record_proposal_notification(
p_proposal_id,
'approval_confirmation',
(SELECT email FROM contacts WHERE id = v_proposal.contact_id),
(SELECT full_name FROM contacts WHERE id = v_proposal.contact_id),
'email',
jsonb_build_object(
'sales_order_id', v_sales_order_id,
'project_id', v_project_id
)
);
END IF;

v_result := jsonb_build_object(
'success', true,
'sales_order_id', v_sales_order_id,
'project_id', v_project_id,
'notification_recorded', p_send_notification
);

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_po_acceptance_action(p_proposal_id uuid, p_po_number text, p_po_file_url text DEFAULT NULL::text, p_send_notification boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal proposals%ROWTYPE;
v_sales_order_id uuid;
v_project_id uuid;
v_project_number text;
v_result jsonb;
BEGIN
-- Get proposal details
SELECT * INTO v_proposal FROM proposals WHERE id = p_proposal_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Proposal not found';
END IF;

-- Verify proposal is in correct status
IF v_proposal.status NOT IN ('approved', 'approved_pending_action') THEN
RAISE EXCEPTION 'Proposal must be approved before PO action';
END IF;

-- Verify PO is allowed as acceptance method
IF NOT ('purchase_order' = ANY(v_proposal.acceptance_methods)) THEN
RAISE EXCEPTION 'Purchase Order is not an allowed acceptance method for this proposal';
END IF;

-- Verify deposit is NOT required (PO only valid when no deposit)
IF v_proposal.require_deposit THEN
RAISE EXCEPTION 'Cannot use Purchase Order when deposit is required';
END IF;

-- Update proposal with PO details
UPDATE proposals
SET
status = 'approved',
accepted_via_method = 'purchase_order',
purchase_order_number = p_po_number,
purchase_order_file_url = p_po_file_url,
billing_action_taken = true,
billing_action_type = 'purchase_order',
billing_action_at = now(),
billing_action_by = auth.uid()
WHERE id = p_proposal_id;

-- Create or update sales order with planning status (ready to schedule)
IF v_proposal.sales_order_id IS NULL THEN
INSERT INTO sales_orders (
company_id,
proposal_id,
contact_id,
order_number,
status,
contract_total,
payment_terms,
created_by
) VALUES (
v_proposal.company_id,
v_proposal.id,
v_proposal.contact_id,
REPLACE(v_proposal.proposal_number, 'PRO-', 'SO-'),
'planning',
v_proposal.total,
'Net 30',
auth.uid()
)
RETURNING id INTO v_sales_order_id;

UPDATE proposals SET sales_order_id = v_sales_order_id WHERE id = p_proposal_id;
ELSE
UPDATE sales_orders
SET
status = 'planning',
payment_terms = 'Net 30'
WHERE id = v_proposal.sales_order_id
RETURNING id INTO v_sales_order_id;
END IF;

-- Create project if it doesn't exist (ready to work since PO received)
IF NOT EXISTS (SELECT 1 FROM projects WHERE sales_order_id = v_sales_order_id) THEN
-- Generate project number
v_project_number := get_next_project_number();

-- Create project with approved status (ready to work)
INSERT INTO projects (
company_id,
sales_order_id,
contact_id,
project_number,
name,
status,
assigned_pm,
job_site_address,
notes,
created_by
) VALUES (
v_proposal.company_id,
v_sales_order_id,
v_proposal.contact_id,
v_project_number,
v_proposal.title,
'planning', -- Ready to schedule work
v_proposal.created_by, -- Default PM is proposal creator
CASE
WHEN v_proposal.jobsite_location IS NOT NULL
THEN v_proposal.jobsite_location
ELSE NULL
END,
'Project created from approved proposal ' || v_proposal.proposal_number || '. PO# ' || p_po_number || ' received. Ready to schedule.',
auth.uid()
)
RETURNING id INTO v_project_id;

RAISE NOTICE 'Created Project % for Proposal % with PO %', v_project_number, v_proposal.proposal_number, p_po_number;
END IF;

-- Record notification if requested
IF p_send_notification THEN
PERFORM record_proposal_notification(
p_proposal_id,
'po_confirmation',
(SELECT email FROM contacts WHERE id = v_proposal.contact_id),
(SELECT full_name FROM contacts WHERE id = v_proposal.contact_id),
'email',
jsonb_build_object(
'sales_order_id', v_sales_order_id,
'project_id', v_project_id,
'po_number', p_po_number
)
);
END IF;

-- Return result
v_result := jsonb_build_object(
'success', true,
'sales_order_id', v_sales_order_id,
'project_id', v_project_id,
'po_number', p_po_number,
'notification_recorded', p_send_notification
);

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_proposal_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sales_order_id       uuid;
v_project_id           uuid;
v_order_number         text;
v_project_number       text;
v_invoice_id           uuid;
v_invoice_number       text;
v_deposit_amount       numeric;
v_require_deposit      boolean;
v_accepted_via_method  text;
v_customer_name        text;
v_sales_order_status   text;
BEGIN
IF NEW.status = 'approved'
AND OLD.status != 'approved'
AND NEW.sales_order_id IS NULL
AND NEW.billing_action_taken = false
THEN

SELECT COALESCE(full_name, contact_name, email, 'Customer')
INTO v_customer_name
FROM contacts WHERE id = NEW.contact_id;

v_require_deposit     := COALESCE(NEW.require_deposit, true);
v_deposit_amount      := COALESCE(NEW.deposit_amount_due, 0);
v_accepted_via_method := NEW.accepted_via_method;

IF v_accepted_via_method IS NULL THEN
v_accepted_via_method   := 'verbal';
NEW.accepted_via_method := 'verbal';
END IF;

IF NEW.approval_completed_at IS NULL THEN
NEW.approval_completed_at := now();
END IF;

v_order_number   := generate_sales_order_number(NEW.proposal_number);
v_project_number := generate_project_number(v_order_number);

IF v_accepted_via_method = 'purchase_order' THEN
v_sales_order_status    := 'planning';
NEW.billing_action_type := 'purchase_order';
IF NEW.purchase_order_number IS NULL OR NEW.purchase_order_number = '' THEN
RAISE EXCEPTION 'Purchase Order number is required for PO acceptance';
END IF;

ELSIF NOT v_require_deposit THEN
v_sales_order_status    := 'planning';
NEW.billing_action_type := 'no_deposit_required';

ELSIF NEW.deposit_paid THEN
v_sales_order_status    := 'planning';
NEW.billing_action_type := 'deposit_invoice';

IF v_deposit_amount > 0 THEN
v_invoice_number := generate_invoice_number();
INSERT INTO invoices (
company_id, proposal_id, contact_id, invoice_number,
invoice_type, invoice_date, due_date, source_type,
subtotal, tax_amount, tax_rate, tax_environment, tax_project_type,
total, amount_due, status, payment_terms, notes, created_by
) VALUES (
NEW.company_id, NEW.id, NEW.contact_id, v_invoice_number,
'deposit', CURRENT_DATE, CURRENT_DATE, 'deposit',
v_deposit_amount, 0,
COALESCE(NEW.tax_rate, 0),
COALESCE(NEW.tax_environment, 'residential'),
COALESCE(NEW.tax_project_type, 'general_installation_repair'),
v_deposit_amount, 0, 'paid', 'Paid',
'Deposit payment received for ' || v_customer_name,
NEW.approved_by
) RETURNING id INTO v_invoice_id;

INSERT INTO invoice_line_items (invoice_id, description, quantity, unit_price, amount, is_taxable)
VALUES (v_invoice_id, 'Deposit for Proposal ' || NEW.proposal_number, 1, v_deposit_amount, v_deposit_amount, false);

INSERT INTO invoice_payments (
company_id, invoice_id, proposal_id, payment_date, amount,
payment_method, reference_number, notes, created_by
) VALUES (
NEW.company_id, v_invoice_id, NEW.id,
COALESCE(NEW.deposit_payment_date, CURRENT_DATE),
v_deposit_amount, 'other',
'Deposit - Proposal ' || NEW.proposal_number,
'Deposit payment recorded at approval', NEW.approved_by
);
NEW.deposit_invoice_id := v_invoice_id;
END IF;

ELSE
v_sales_order_status        := 'pending_deposit';
NEW.billing_action_type     := 'deposit_invoice';
NEW.deposit_request_sent    := true;
NEW.deposit_request_sent_at := now();

IF v_deposit_amount > 0 THEN
v_invoice_number := generate_invoice_number();
INSERT INTO invoices (
company_id, proposal_id, contact_id, invoice_number,
invoice_type, invoice_date, due_date, source_type,
subtotal, tax_amount, tax_rate, tax_environment, tax_project_type,
total, amount_due, status, payment_terms, notes, created_by
) VALUES (
NEW.company_id, NEW.id, NEW.contact_id, v_invoice_number,
'deposit', CURRENT_DATE, CURRENT_DATE, 'deposit',
v_deposit_amount, 0,
COALESCE(NEW.tax_rate, 0),
COALESCE(NEW.tax_environment, 'residential'),
COALESCE(NEW.tax_project_type, 'general_installation_repair'),
v_deposit_amount, v_deposit_amount, 'submitted', 'Due upon receipt',
'Deposit invoice for ' || v_customer_name, NEW.approved_by
) RETURNING id INTO v_invoice_id;

INSERT INTO invoice_line_items (invoice_id, description, quantity, unit_price, amount, is_taxable)
VALUES (v_invoice_id, 'Deposit for Proposal ' || NEW.proposal_number, 1, v_deposit_amount, v_deposit_amount, false);

NEW.deposit_invoice_id := v_invoice_id;
END IF;
END IF;

-- Create Sales Order
INSERT INTO sales_orders (
company_id, proposal_id, contact_id, order_number, status,
contract_total, payment_terms, notes, created_by
) VALUES (
NEW.company_id, NEW.id, NEW.contact_id, v_order_number,
v_sales_order_status, NEW.total, COALESCE(NEW.payment_terms, 'Net 30'),
CASE
WHEN v_accepted_via_method = 'purchase_order'
THEN 'Converted from proposal ' || NEW.proposal_number || ' - PO: ' || NEW.purchase_order_number
WHEN NEW.deposit_paid
THEN 'Converted from proposal ' || NEW.proposal_number || ' - Deposit received'
WHEN v_require_deposit AND NOT NEW.deposit_paid
THEN 'Converted from proposal ' || NEW.proposal_number || ' - Pending deposit payment'
ELSE 'Converted from proposal ' || NEW.proposal_number
END,
NEW.approved_by
) RETURNING id INTO v_sales_order_id;

NEW.sales_order_id := v_sales_order_id;

IF v_invoice_id IS NOT NULL THEN
UPDATE invoices SET sales_order_id = v_sales_order_id WHERE id = v_invoice_id;
END IF;

-- Create Project
INSERT INTO projects (
company_id,
organization_id,
sales_order_id,
contact_id,
project_number,
name,
status,
created_by
) VALUES (
NEW.company_id,
NEW.organization_id,
v_sales_order_id,
NEW.contact_id,
v_project_number,
COALESCE(NEW.title, 'Project for ' || NEW.proposal_number),
'planning',
NEW.approved_by
) RETURNING id INTO v_project_id;

UPDATE sales_orders SET project_id = v_project_id WHERE id = v_sales_order_id;

-- Notify sales rep
IF NEW.approved_by IS DISTINCT FROM NEW.created_by THEN
BEGIN
INSERT INTO notifications (user_id, type, title, message, related_id)
VALUES (
COALESCE(NEW.assigned_to, NEW.created_by),
'proposal_approved',
'Customer Approved Proposal',
v_customer_name || ' approved proposal ' || NEW.proposal_number || '. ' ||
CASE
WHEN v_accepted_via_method = 'purchase_order'
THEN 'Sales order and project created with PO #' || NEW.purchase_order_number || '.'
WHEN NEW.deposit_paid
THEN 'Deposit received. Sales order and project ready for scheduling.'
WHEN v_require_deposit AND NOT NEW.deposit_paid
THEN 'Deposit invoice created. Project created and pending deposit.'
ELSE 'Sales order and project created, ready for scheduling.'
END,
NEW.id
);
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Failed to create notification: %', SQLERRM;
END;
END IF;

NEW.billing_action_taken := true;
NEW.billing_action_at    := now();
NEW.billing_action_by    := NEW.approved_by;

END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_proposal_reactivation_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal record;
v_task_id uuid;
v_contact_name text;
v_company_id uuid;
BEGIN
-- Get proposal details
SELECT 
p.*,
c.full_name as customer_name,
c.contact_name as customer_contact_name,
COALESCE(pr.company_id, (SELECT company_id FROM profiles LIMIT 1)) as company_id
INTO v_proposal
FROM proposals p
JOIN contacts c ON c.id = p.contact_id
LEFT JOIN profiles pr ON pr.id = p.created_by
WHERE p.id = NEW.proposal_id;

-- Determine contact name
v_contact_name := COALESCE(v_proposal.customer_name, v_proposal.customer_contact_name, 'Customer');
v_company_id := v_proposal.company_id;

-- Create task for sales rep (assigned to proposal owner or general sales)
INSERT INTO tasks (
title,
description,
status,
priority,
assigned_to,
contact_id,
due_date,
company_id
) VALUES (
'Review & Reactivate Proposal ' || v_proposal.proposal_number,
'Customer ' || v_contact_name || ' has requested reactivation of proposal ' || 
v_proposal.proposal_number || '. Please review pricing, update if needed, and reactivate.',
'pending',
'high',
COALESCE(v_proposal.created_by, v_proposal.sales_rep_id),
NEW.contact_id,
CURRENT_DATE + INTERVAL '1 day',
v_company_id
) RETURNING id INTO v_task_id;

-- Update reactivation request with task ID and sales rep
UPDATE proposal_reactivation_requests
SET 
task_id = v_task_id,
sales_rep_id = COALESCE(v_proposal.created_by, v_proposal.sales_rep_id)
WHERE id = NEW.id;

-- Create notification for sales rep
INSERT INTO notifications (
user_id,
title,
message,
type,
related_id,
action_url
) VALUES (
COALESCE(v_proposal.created_by, v_proposal.sales_rep_id),
'Proposal Reactivation Request',
v_contact_name || ' has requested reactivation of proposal ' || v_proposal.proposal_number,
'proposal_reactivation',
NEW.proposal_id,
'/proposals?id=' || NEW.proposal_id
);

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_service_request_cancellation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.status='cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN
    UPDATE public.punchlist_tasks SET status='draft',service_request_id=NULL,
      requested_at=NULL,updated_at=now()
    WHERE service_request_id=NEW.id AND status='requested';
  END IF;
  RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_service_request_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Only process when moving from 'in_progress' to 'completed'
IF OLD.status = 'in_progress' AND NEW.status = 'completed' THEN
-- Create notification for the customer
IF NEW.contact_id IS NOT NULL THEN
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id
)
SELECT
auth.uid(),
'service_completed',
'Service Request Completed',
'Service request #' || NEW.id || ' has been completed',
NEW.id
WHERE EXISTS (SELECT 1 FROM contacts WHERE id = NEW.contact_id);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.handle_unified_proposal_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sales_order_id      uuid;
v_order_number        text;
v_invoice_id          uuid;
v_invoice_number      text;
v_deposit_amount      numeric;
v_require_deposit     boolean;
v_accepted_via_method text;
v_customer_name       text;
v_sales_order_status  text;
v_project_id          uuid;
v_project_number      text;
BEGIN
IF NEW.status = 'approved'
AND OLD.status != 'approved'
AND NEW.sales_order_id IS NULL
AND (NEW.billing_action_taken = false OR NEW.sales_order_id IS NULL)
THEN

BEGIN

SELECT COALESCE(full_name, contact_name, email, 'Customer')
INTO v_customer_name
FROM contacts
WHERE id = NEW.contact_id;

v_require_deposit     := COALESCE(NEW.require_deposit, true);
v_deposit_amount      := COALESCE(NEW.deposit_amount_due, 0);
v_accepted_via_method := COALESCE(NEW.accepted_via_method, 'verbal');

IF NEW.accepted_via_method IS NULL THEN
NEW.accepted_via_method := 'verbal';
END IF;

IF NEW.approval_completed_at IS NULL THEN
NEW.approval_completed_at := now();
END IF;

v_order_number := generate_sales_order_number(NEW.proposal_number);

IF v_accepted_via_method = 'purchase_order' THEN
v_sales_order_status    := 'planning';
NEW.billing_action_type := 'purchase_order';

IF NEW.purchase_order_number IS NULL OR NEW.purchase_order_number = '' THEN
RAISE EXCEPTION 'Purchase Order number is required for PO acceptance';
END IF;

ELSIF NOT v_require_deposit THEN
v_sales_order_status    := 'planning';
NEW.billing_action_type := 'no_deposit_required';

ELSIF NEW.deposit_paid THEN
v_sales_order_status    := 'planning';
NEW.billing_action_type := 'deposit_invoice';

IF v_deposit_amount > 0 THEN
v_invoice_number := generate_invoice_number();

INSERT INTO invoices (
company_id, organization_id,
proposal_id, contact_id,
invoice_number, invoice_type,
invoice_date, due_date, source_type,
subtotal, tax_amount, tax_rate,
tax_environment, tax_project_type,
total, amount_due, status, payment_terms, notes, created_by
) VALUES (
NEW.company_id, NEW.organization_id,
NEW.id, NEW.contact_id,
v_invoice_number, 'deposit',
CURRENT_DATE, CURRENT_DATE, 'deposit',
v_deposit_amount, 0, COALESCE(NEW.tax_rate, 0),
COALESCE(NEW.tax_environment, 'residential'),
COALESCE(NEW.tax_project_type, 'general_installation_repair'),
v_deposit_amount, 0, 'paid', 'Paid',
'Deposit payment received for ' || v_customer_name,
NEW.approved_by
) RETURNING id INTO v_invoice_id;

INSERT INTO invoice_line_items (
invoice_id, organization_id,
description, quantity, unit_price, amount, is_taxable
) VALUES (
v_invoice_id, NEW.organization_id,
'Deposit for Proposal ' || NEW.proposal_number,
1, v_deposit_amount, v_deposit_amount, false
);

INSERT INTO invoice_payments (
company_id, invoice_id, proposal_id,
payment_date, amount, payment_method, reference_number, notes, created_by
) VALUES (
NEW.company_id, v_invoice_id, NEW.id,
COALESCE(NEW.deposit_payment_date, CURRENT_DATE),
v_deposit_amount, 'other',
'Deposit - Proposal ' || NEW.proposal_number,
'Deposit payment recorded at approval',
NEW.approved_by
);

NEW.deposit_invoice_id := v_invoice_id;
END IF;

ELSE
v_sales_order_status        := 'pending_deposit';
NEW.billing_action_type     := 'deposit_invoice';
NEW.deposit_request_sent    := true;
NEW.deposit_request_sent_at := now();

IF v_deposit_amount > 0 THEN
v_invoice_number := generate_invoice_number();

INSERT INTO invoices (
company_id, organization_id,
proposal_id, contact_id,
invoice_number, invoice_type,
invoice_date, due_date, source_type,
subtotal, tax_amount, tax_rate,
tax_environment, tax_project_type,
total, amount_due, status, payment_terms, notes, created_by
) VALUES (
NEW.company_id, NEW.organization_id,
NEW.id, NEW.contact_id,
v_invoice_number, 'deposit',
CURRENT_DATE, CURRENT_DATE, 'deposit',
v_deposit_amount, 0, COALESCE(NEW.tax_rate, 0),
COALESCE(NEW.tax_environment, 'residential'),
COALESCE(NEW.tax_project_type, 'general_installation_repair'),
v_deposit_amount, v_deposit_amount, 'submitted', 'Due upon receipt',
'Deposit invoice for ' || v_customer_name,
NEW.approved_by
) RETURNING id INTO v_invoice_id;

INSERT INTO invoice_line_items (
invoice_id, organization_id,
description, quantity, unit_price, amount, is_taxable
) VALUES (
v_invoice_id, NEW.organization_id,
'Deposit for Proposal ' || NEW.proposal_number,
1, v_deposit_amount, v_deposit_amount, false
);

NEW.deposit_invoice_id := v_invoice_id;
END IF;
END IF;

-- Create Sales Order (copy portal_template_override_id from proposal's report_template_id)
INSERT INTO sales_orders (
company_id, organization_id,
proposal_id, contact_id,
order_number, status,
contract_total, payment_terms, notes, created_by,
portal_template_override_id
) VALUES (
NEW.company_id, NEW.organization_id,
NEW.id, NEW.contact_id,
v_order_number, v_sales_order_status,
NEW.total,
COALESCE(NEW.payment_terms, 'Net 30'),
CASE
WHEN v_accepted_via_method = 'purchase_order' THEN
'Converted from proposal ' || NEW.proposal_number || ' - PO: ' || NEW.purchase_order_number
WHEN NEW.deposit_paid THEN
'Converted from proposal ' || NEW.proposal_number || ' - Deposit received'
WHEN v_require_deposit AND NOT NEW.deposit_paid THEN
'Converted from proposal ' || NEW.proposal_number || ' - Pending deposit payment'
ELSE
'Converted from proposal ' || NEW.proposal_number
END,
NEW.approved_by,
NEW.report_template_id
) RETURNING id INTO v_sales_order_id;

NEW.sales_order_id := v_sales_order_id;

-- Link deposit invoice to sales order
IF v_invoice_id IS NOT NULL THEN
UPDATE invoices SET sales_order_id = v_sales_order_id WHERE id = v_invoice_id;
END IF;

-- Create Project linked to this sales order
BEGIN
v_project_number := get_next_project_number();

INSERT INTO projects (
company_id, organization_id,
sales_order_id, contact_id,
project_number, name,
status, assigned_pm,
job_site_address, notes, created_by,
salesperson_id
) VALUES (
NEW.company_id, NEW.organization_id,
v_sales_order_id, NEW.contact_id,
v_project_number,
COALESCE(NEW.title, 'Project for ' || v_customer_name),
'planning',
NEW.created_by,
NEW.jobsite_location,
'Project created from approved proposal ' || NEW.proposal_number,
NEW.approved_by,
NEW.created_by
) RETURNING id INTO v_project_id;

UPDATE sales_orders SET project_id = v_project_id WHERE id = v_sales_order_id;

IF v_invoice_id IS NOT NULL THEN
UPDATE invoices SET project_id = v_project_id WHERE id = v_invoice_id;
END IF;

EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Failed to create project for proposal %: %', NEW.proposal_number, SQLERRM;
END;

NEW.billing_action_taken := true;
NEW.billing_action_at    := now();
NEW.billing_action_by    := NEW.approved_by;

IF NEW.approved_by IS DISTINCT FROM NEW.created_by THEN
BEGIN
INSERT INTO notifications (user_id, type, title, message, related_id)
VALUES (
NEW.created_by,
'proposal_approved',
'Customer Approved Proposal',
v_customer_name || ' approved proposal ' || NEW.proposal_number || '. ' ||
CASE
WHEN v_accepted_via_method = 'purchase_order' THEN
'Sales order created with PO #' || NEW.purchase_order_number || ' and is ready for scheduling.'
WHEN NEW.deposit_paid THEN
'Deposit received. Sales order created and ready for scheduling.'
WHEN v_require_deposit AND NOT NEW.deposit_paid THEN
'Deposit invoice created and sent. Sales order pending deposit payment.'
ELSE
'Sales order created and ready for scheduling.'
END,
NEW.id
);
EXCEPTION WHEN OTHERS THEN
RAISE WARNING 'Failed to create notification: %', SQLERRM;
END;
END IF;

EXCEPTION WHEN OTHERS THEN
RAISE EXCEPTION 'Proposal approval failed while creating sales order: %', SQLERRM;
END;

END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.http(request http_request)
 RETURNS http_response
 LANGUAGE c
AS '$libdir/http', $function$http_request$function$


CREATE OR REPLACE FUNCTION public.http_delete(uri character varying)
 RETURNS http_response
 LANGUAGE sql
AS $function$ SELECT public.http(('DELETE', $1, NULL, NULL, NULL)::public.http_request) $function$


CREATE OR REPLACE FUNCTION public.http_delete(uri character varying, content character varying, content_type character varying)
 RETURNS http_response
 LANGUAGE sql
AS $function$ SELECT public.http(('DELETE', $1, NULL, $3, $2)::public.http_request) $function$


CREATE OR REPLACE FUNCTION public.http_get(uri character varying, data jsonb)
 RETURNS http_response
 LANGUAGE sql
AS $function$
        SELECT public.http(('GET', $1 || '?' || public.urlencode($2), NULL, NULL, NULL)::public.http_request)
    $function$


CREATE OR REPLACE FUNCTION public.http_get(uri character varying)
 RETURNS http_response
 LANGUAGE sql
AS $function$ SELECT public.http(('GET', $1, NULL, NULL, NULL)::public.http_request) $function$


CREATE OR REPLACE FUNCTION public.http_head(uri character varying)
 RETURNS http_response
 LANGUAGE sql
AS $function$ SELECT public.http(('HEAD', $1, NULL, NULL, NULL)::public.http_request) $function$


CREATE OR REPLACE FUNCTION public.http_header(field character varying, value character varying)
 RETURNS http_header
 LANGUAGE sql
AS $function$ SELECT $1, $2 $function$


CREATE OR REPLACE FUNCTION public.http_list_curlopt()
 RETURNS TABLE(curlopt text, value text)
 LANGUAGE c
AS '$libdir/http', $function$http_list_curlopt$function$


CREATE OR REPLACE FUNCTION public.http_patch(uri character varying, content character varying, content_type character varying)
 RETURNS http_response
 LANGUAGE sql
AS $function$ SELECT public.http(('PATCH', $1, NULL, $3, $2)::public.http_request) $function$


CREATE OR REPLACE FUNCTION public.http_post(uri character varying, data jsonb)
 RETURNS http_response
 LANGUAGE sql
AS $function$
        SELECT public.http(('POST', $1, NULL, 'application/x-www-form-urlencoded', public.urlencode($2))::public.http_request)
    $function$


CREATE OR REPLACE FUNCTION public.http_post(uri character varying, content character varying, content_type character varying)
 RETURNS http_response
 LANGUAGE sql
AS $function$ SELECT public.http(('POST', $1, NULL, $3, $2)::public.http_request) $function$


CREATE OR REPLACE FUNCTION public.http_put(uri character varying, content character varying, content_type character varying)
 RETURNS http_response
 LANGUAGE sql
AS $function$ SELECT public.http(('PUT', $1, NULL, $3, $2)::public.http_request) $function$


CREATE OR REPLACE FUNCTION public.http_reset_curlopt()
 RETURNS boolean
 LANGUAGE c
AS '$libdir/http', $function$http_reset_curlopt$function$


CREATE OR REPLACE FUNCTION public.http_set_curlopt(curlopt character varying, value character varying)
 RETURNS boolean
 LANGUAGE c
AS '$libdir/http', $function$http_set_curlopt$function$


CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM profiles 
WHERE id = auth.uid() 
AND role = 'admin'
);
$function$


CREATE OR REPLACE FUNCTION public.is_admin_bypass_rls()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM profiles
WHERE id = auth.uid()
AND role = 'admin'
);
$function$


CREATE OR REPLACE FUNCTION public.is_at_home_location(p_latitude numeric, p_longitude numeric, p_home_latitude numeric, p_home_longitude numeric, p_radius_meters integer DEFAULT 100)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
v_distance_meters decimal;
BEGIN
IF p_latitude IS NULL OR p_longitude IS NULL OR
p_home_latitude IS NULL OR p_home_longitude IS NULL THEN
RETURN false;
END IF;

v_distance_meters := 6371000 * 2 * ASIN(SQRT(
POWER(SIN(RADIANS(p_home_latitude - p_latitude) / 2), 2) +
COS(RADIANS(p_latitude)) * COS(RADIANS(p_home_latitude)) *
POWER(SIN(RADIANS(p_home_longitude - p_longitude) / 2), 2)
));

RETURN v_distance_meters <= p_radius_meters;
END;
$function$


CREATE OR REPLACE FUNCTION public.is_contact_ready_for_qb_sync(p_contact_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
v_contact record;
v_ready boolean := false;
BEGIN
SELECT
contact_name,
email,
phone,
street_address,
city,
zip_code
INTO v_contact
FROM contacts
WHERE id = p_contact_id;

-- Contact is ready if it has name and at least email or phone
IF v_contact.contact_name IS NOT NULL AND v_contact.contact_name != '' AND
(
(v_contact.email IS NOT NULL AND v_contact.email != '') OR
(v_contact.phone IS NOT NULL AND v_contact.phone != '')
) THEN
v_ready := true;
END IF;

RETURN v_ready;
END;
$function$


CREATE OR REPLACE FUNCTION public.is_equipment_warranty_eligible(p_product_id uuid, p_contact_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_purchase_date date;
BEGIN
SELECT purchase_date
INTO v_purchase_date
FROM get_customer_purchased_equipment(p_contact_id)
WHERE product_id = p_product_id
ORDER BY purchase_date DESC NULLS LAST
LIMIT 1;

-- If no purchase date found, not eligible (conservative default)
IF v_purchase_date IS NULL THEN
RETURN false;
END IF;

-- Eligible if purchase date is less than 15 months ago
RETURN v_purchase_date > (now() - interval '15 months')::date;
END;
$function$


