CREATE OR REPLACE FUNCTION public.is_working_today(tech_id uuid, check_date date)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
day_name text;
tech_work_days text[];
BEGIN
-- Get day of week name in lowercase
day_name := lower(to_char(check_date, 'Day'));
day_name := trim(day_name);

-- Get technician's work days
SELECT work_days INTO tech_work_days
FROM profiles
WHERE id = tech_id;

-- Check if today is a work day
RETURN day_name = ANY(tech_work_days);
END;
$function$


CREATE OR REPLACE FUNCTION public.link_work_orders(p_work_order_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_group_id uuid;
v_existing_group_id uuid;
v_wo_id uuid;
BEGIN
-- Check if any of the work orders already has a group_id
SELECT work_order_group_id INTO v_existing_group_id
FROM work_orders
WHERE id = ANY(p_work_order_ids)
AND work_order_group_id IS NOT NULL
LIMIT 1;

-- Use existing group_id or create a new one
v_group_id := COALESCE(v_existing_group_id, gen_random_uuid());

-- Update all work orders to use this group_id
UPDATE work_orders
SET work_order_group_id = v_group_id
WHERE id = ANY(p_work_order_ids);

RETURN v_group_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.lock_pay_period(p_pay_period_id uuid, p_locked_by uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
v_org_id uuid;
v_snapshot jsonb;
v_count int;
BEGIN
SELECT organization_id INTO v_org_id
FROM pay_periods
WHERE id = p_pay_period_id;

IF NOT FOUND THEN
RETURN json_build_object('error', 'pay period not found');
END IF;

-- Build immutable snapshot of all segments
SELECT jsonb_agg(to_jsonb(pts.*)) INTO v_snapshot
FROM payroll_time_segments pts
WHERE pts.pay_period_id = p_pay_period_id
AND pts.organization_id = v_org_id;

-- Create lock record
INSERT INTO pay_period_time_locks (organization_id, pay_period_id, locked_by, lock_scope, snapshot_data)
VALUES (v_org_id, p_pay_period_id, p_locked_by, 'period', COALESCE(v_snapshot, '[]'::jsonb));

-- Mark all segments as locked
-- We need to bypass the immutability trigger for this one operation
-- by using a direct approach: set is_locked in a way the trigger allows
-- The trigger only blocks updates WHERE OLD.is_locked = true; since these
-- segments currently have is_locked = false, the update will succeed.
UPDATE payroll_time_segments
SET is_locked = true,
locked_at = now()
WHERE pay_period_id = p_pay_period_id
AND organization_id = v_org_id
AND is_locked = false;

GET DIAGNOSTICS v_count = ROW_COUNT;

-- Update pay period status
UPDATE pay_periods
SET status = 'locked',
locked_at = now(),
locked_by = p_locked_by
WHERE id = p_pay_period_id;

RETURN json_build_object('locked_segments', v_count, 'snapshot_created', true);
END;
$function$


CREATE OR REPLACE FUNCTION public.lock_proposal(proposal_id_param uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
BEGIN
v_user_id := auth.uid();

IF v_user_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
END IF;

UPDATE public.proposals
SET
is_locked = true,
locked_at = now(),
locked_by = v_user_id,
updated_at = now()
WHERE id = proposal_id_param;

RETURN jsonb_build_object(
'success', true,
'message', 'Proposal locked successfully'
);
END;
$function$


CREATE OR REPLACE FUNCTION public.log_bonus_calculation_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF (TG_OP = 'INSERT') THEN
INSERT INTO test_tune_bonus_history (bonus_calculation_id, changed_by, change_type, new_values)
VALUES (NEW.id, auth.uid(), 'calculated', to_jsonb(NEW));
ELSIF (TG_OP = 'UPDATE') THEN
IF (OLD.status != NEW.status) THEN
INSERT INTO test_tune_bonus_history (bonus_calculation_id, changed_by, change_type, old_values, new_values, reason)
VALUES (NEW.id, auth.uid(), NEW.status, 
jsonb_build_object('status', OLD.status, 'total_bonus_amount', OLD.total_bonus_amount),
jsonb_build_object('status', NEW.status, 'total_bonus_amount', NEW.total_bonus_amount),
NEW.notes);
ELSE
INSERT INTO test_tune_bonus_history (bonus_calculation_id, changed_by, change_type, old_values, new_values)
VALUES (NEW.id, auth.uid(), 'adjusted', to_jsonb(OLD), to_jsonb(NEW));
END IF;
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.log_change_order_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_action text;
v_description text;
v_snapshot jsonb;
v_org_id uuid;
BEGIN
IF TG_OP = 'DELETE' THEN
RETURN OLD;
END IF;

IF TG_OP = 'INSERT' THEN
v_action := 'created';
v_description := 'Change order created';
v_snapshot := to_jsonb(NEW);
v_org_id := NEW.organization_id;
ELSIF TG_OP = 'UPDATE' THEN
IF NEW.status != OLD.status THEN
v_action := 'status_changed';
v_description := 'Status changed from ' || OLD.status || ' to ' || NEW.status;
ELSE
v_action := 'modified';
v_description := 'Change order modified';
END IF;
v_snapshot := to_jsonb(OLD);
v_org_id := NEW.organization_id;
END IF;

BEGIN
INSERT INTO change_order_history (
change_order_id,
action,
performed_by,
description,
snapshot,
organization_id,
created_at
) VALUES (
NEW.id,
v_action,
auth.uid(),
v_description,
v_snapshot,
v_org_id,
now()
);
EXCEPTION WHEN OTHERS THEN
-- History logging failure must never block the change order operation
NULL;
END;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.log_parts_usage_from_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.status = 'installed' AND OLD.status != 'installed' AND NEW.installed_at IS NOT NULL THEN
INSERT INTO parts_usage_log (
parts_request_id,
work_order_id,
technician_id,
part_name,
quantity_used,
unit_cost,
total_cost,
source,
used_at
) VALUES (
NEW.id,
NEW.work_order_id,
NEW.technician_id,
NEW.part_name,
NEW.quantity,
COALESCE(NEW.actual_cost, NEW.estimated_cost, 0) / NEW.quantity,
COALESCE(NEW.actual_cost, NEW.estimated_cost, 0),
'parts_request',
NEW.installed_at
);
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.log_project_task_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_changed_by uuid;
v_old_values jsonb;
v_new_values jsonb;
v_change_type text;
BEGIN
v_org_id := NEW.organization_id;
v_changed_by := auth.uid();

IF (TG_OP = 'INSERT') THEN
v_change_type := 'created';
v_new_values := jsonb_build_object(
'title', NEW.title,
'description', NEW.description,
'source', NEW.source,
'visibility', NEW.visibility,
'assigned_to', NEW.assigned_to,
'labor_phase_id', NEW.labor_phase_id,
'estimated_hours', NEW.estimated_hours,
'status', NEW.status
);

INSERT INTO task_history (task_id, changed_by, change_type, old_values, new_values, organization_id)
VALUES (NEW.id, v_changed_by, v_change_type, NULL, v_new_values, v_org_id);

ELSIF (TG_OP = 'UPDATE') THEN
-- Build old/new values only for tracked columns that actually changed
v_old_values := '{}'::jsonb;
v_new_values := '{}'::jsonb;

IF OLD.title IS DISTINCT FROM NEW.title THEN
v_old_values := v_old_values || jsonb_build_object('title', OLD.title);
v_new_values := v_new_values || jsonb_build_object('title', NEW.title);
END IF;
IF OLD.description IS DISTINCT FROM NEW.description THEN
v_old_values := v_old_values || jsonb_build_object('description', OLD.description);
v_new_values := v_new_values || jsonb_build_object('description', NEW.description);
END IF;
IF OLD.status IS DISTINCT FROM NEW.status THEN
v_old_values := v_old_values || jsonb_build_object('status', OLD.status);
v_new_values := v_new_values || jsonb_build_object('status', NEW.status);
END IF;
IF OLD.visibility IS DISTINCT FROM NEW.visibility THEN
v_old_values := v_old_values || jsonb_build_object('visibility', OLD.visibility);
v_new_values := v_new_values || jsonb_build_object('visibility', NEW.visibility);
END IF;
IF OLD.assigned_to IS DISTINCT FROM NEW.assigned_to THEN
v_old_values := v_old_values || jsonb_build_object('assigned_to', OLD.assigned_to);
v_new_values := v_new_values || jsonb_build_object('assigned_to', NEW.assigned_to);
END IF;
IF OLD.labor_phase_id IS DISTINCT FROM NEW.labor_phase_id THEN
v_old_values := v_old_values || jsonb_build_object('labor_phase_id', OLD.labor_phase_id);
v_new_values := v_new_values || jsonb_build_object('labor_phase_id', NEW.labor_phase_id);
END IF;
IF OLD.estimated_hours IS DISTINCT FROM NEW.estimated_hours THEN
v_old_values := v_old_values || jsonb_build_object('estimated_hours', OLD.estimated_hours);
v_new_values := v_new_values || jsonb_build_object('estimated_hours', NEW.estimated_hours);
END IF;

-- Only insert a history row if something actually changed
IF v_new_values <> '{}'::jsonb THEN
v_change_type := 'updated';

INSERT INTO task_history (task_id, changed_by, change_type, old_values, new_values, organization_id)
VALUES (NEW.id, v_changed_by, v_change_type, v_old_values, v_new_values, v_org_id);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.log_punchlist_task_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF (TG_OP = 'INSERT') THEN
INSERT INTO punchlist_task_history (task_id, changed_by, change_type, new_values, organization_id)
VALUES (NEW.id, auth.uid(), 'created', to_jsonb(NEW), NEW.organization_id);
ELSIF (TG_OP = 'UPDATE') THEN
IF (OLD.status != NEW.status) THEN
INSERT INTO punchlist_task_history (task_id, changed_by, change_type, old_values, new_values, organization_id)
VALUES (NEW.id, auth.uid(), 'status_changed',
jsonb_build_object('status', OLD.status),
jsonb_build_object('status', NEW.status),
NEW.organization_id);
ELSE
INSERT INTO punchlist_task_history (task_id, changed_by, change_type, old_values, new_values, organization_id)
VALUES (NEW.id, auth.uid(), 'updated', to_jsonb(OLD), to_jsonb(NEW), NEW.organization_id);
END IF;

IF (NEW.status = 'completed' AND OLD.status != 'completed') THEN
UPDATE punchlist_tasks SET completed_at = now() WHERE id = NEW.id;
END IF;
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.log_sms(p_contact_id uuid, p_appointment_id uuid, p_to_phone text, p_message text, p_status text DEFAULT 'sent'::text, p_external_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_log_id UUID;
BEGIN
INSERT INTO sms_logs (contact_id, appointment_id, to_phone, message, status, external_message_id, error)
VALUES (p_contact_id, p_appointment_id, p_to_phone, p_message, p_status, p_external_id, p_error) RETURNING id INTO v_log_id;
IF p_appointment_id IS NOT NULL THEN PERFORM mark_reminder_sent(p_appointment_id, p_status, p_error); END IF;
RETURN v_log_id;
END;
$function$


