CREATE OR REPLACE FUNCTION public.mark_proposal_activity_viewed(p_proposal_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_organization_id uuid;
v_user_id uuid;
BEGIN
-- Use provided user_id or get from auth context
v_user_id := COALESCE(p_user_id, auth.uid());

-- Return early if no user (not authenticated)
IF v_user_id IS NULL THEN
RETURN;
END IF;

-- Get organization_id from proposal
SELECT organization_id INTO v_organization_id
FROM proposals
WHERE id = p_proposal_id;

-- Return if proposal not found
IF v_organization_id IS NULL THEN
RETURN;
END IF;

-- Upsert the view record
INSERT INTO proposal_activity_views (proposal_id, user_id, organization_id, last_viewed_at)
VALUES (p_proposal_id, v_user_id, v_organization_id, now())
ON CONFLICT (proposal_id, user_id)
DO UPDATE SET
last_viewed_at = now(),
updated_at = now();
END;
$function$


CREATE OR REPLACE FUNCTION public.mark_punchlist_task_completed(p_task_id uuid, p_completed_by uuid DEFAULT NULL::uuid, p_completed_by_customer boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF p_completed_by IS NOT NULL AND p_completed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Completion identity cannot be reassigned' USING ERRCODE='42501';
  END IF;
  PERFORM public.update_punchlist_item(p_task_id,'complete');
END;
$function$


CREATE OR REPLACE FUNCTION public.mark_punchlist_task_completed(p_task_id uuid, p_completed_by uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  PERFORM public.mark_punchlist_task_completed(p_task_id,p_completed_by,false);
END;
$function$


CREATE OR REPLACE FUNCTION public.mark_reminder_sent(p_appointment_id uuid, p_status text DEFAULT 'sent'::text, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
UPDATE appointments SET reminder_sent_at = now(), reminder_status = p_status WHERE id = p_appointment_id;
RETURN FOUND;
END;
