CREATE OR REPLACE FUNCTION public.mark_settings_section_reviewed(proposal_id_input uuid, section_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_column_name text;
v_sql text;
BEGIN
-- Validate section name and map to column
v_column_name := CASE section_name
WHEN 'details' THEN 'details_reviewed_at'
WHEN 'scope' THEN 'scope_reviewed_at'
WHEN 'contract' THEN 'contract_reviewed_at'
WHEN 'billing' THEN 'billing_reviewed_at'
WHEN 'tax' THEN 'tax_reviewed_at'
WHEN 'fees' THEN 'fees_reviewed_at'
ELSE NULL
END;

IF v_column_name IS NULL THEN
RAISE EXCEPTION 'Invalid section name: %', section_name;
END IF;

-- Update the specific column
v_sql := format(
'UPDATE proposal_settings SET %I = now(), updated_at = now() WHERE proposal_id = $1',
v_column_name
);

EXECUTE v_sql USING proposal_id_input;
END;
$function$


CREATE OR REPLACE FUNCTION public.mark_tax_review_required(p_transaction_type text, p_transaction_id uuid, p_failure_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_exists boolean := false;
v_org_id uuid;
v_calc_result jsonb;
v_snapshot_id uuid;
v_existing_reasons jsonb;
v_new_reason jsonb;
v_final_status text;
BEGIN
-- ── 1. Validate transaction exists ────────────────────────────────────
IF p_transaction_type = 'proposal' THEN
SELECT organization_id INTO v_org_id FROM proposals WHERE id = p_transaction_id;
v_exists := v_org_id IS NOT NULL;
ELSIF p_transaction_type = 'change_order' THEN
SELECT co.organization_id INTO v_org_id FROM change_orders co WHERE co.id = p_transaction_id;
v_exists := v_org_id IS NOT NULL;
ELSIF p_transaction_type = 'invoice' THEN
SELECT organization_id INTO v_org_id FROM invoices WHERE id = p_transaction_id;
v_exists := v_org_id IS NOT NULL;
ELSE
RETURN jsonb_build_object('error', 'Unknown transaction type: ' || p_transaction_type);
END IF;

IF NOT v_exists THEN
RETURN jsonb_build_object('error', 'Transaction not found: ' || p_transaction_type || ' ' || p_transaction_id);
END IF;

-- ── 2. Get the MJV calculation context FIRST ──────────────────────────
-- calculate_tax may set the status to 'ready', but we will override
-- it with the failure mutation below.
v_calc_result := calculate_tax(p_transaction_type, p_transaction_id);

-- ── 3. Build the TaxJar failure review reason ─────────────────────────
v_new_reason := jsonb_build_object(
'layer', 'taxjar',
'reason', p_failure_reason
);

-- Merge with existing review reasons from calculate_tax
v_existing_reasons := v_calc_result->'review_reasons';
IF v_existing_reasons IS NULL THEN
v_existing_reasons := '[]'::jsonb;
END IF;
v_existing_reasons := v_existing_reasons || jsonb_build_array(v_new_reason);

-- ── 4. Upsert the tax snapshot with failure context ───────────────────
SELECT id INTO v_snapshot_id
FROM tax_snapshots
WHERE transaction_type = p_transaction_type
AND transaction_id = p_transaction_id
ORDER BY calculated_at DESC
LIMIT 1;

IF v_snapshot_id IS NOT NULL THEN
UPDATE tax_snapshots SET
tax_calculation_status = 'review_required',
taxability_results = v_calc_result->'taxability_results',
origin_address = v_calc_result->'origin_result',
destination_address = v_calc_result->'destination_result',
collection_status = v_calc_result->>'collection_status',
exemption_reference = v_calc_result->>'exemption_reference',
taxable_subtotal = COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0),
sales_tax = 0,
calculated_at = now()
WHERE id = v_snapshot_id;
ELSE
INSERT INTO tax_snapshots (
organization_id,
transaction_type,
transaction_id,
state,
tax_calculation_status,
taxability_results,
origin_method,
origin_address,
destination_address,
collection_status,
nexus_result,
exemption_reference,
taxable_subtotal,
sales_tax,
calculated_at
) VALUES (
v_org_id,
p_transaction_type,
p_transaction_id,
COALESCE(v_calc_result->'destination_result'->>'state', ''),
'review_required',
v_calc_result->'taxability_results',
v_calc_result->'origin_result'->>'origin_method',
v_calc_result->'origin_result',
v_calc_result->'destination_result',
v_calc_result->>'collection_status',
v_calc_result->>'collection_status',
v_calc_result->>'exemption_reference',
COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0),
0,
now()
)
ON CONFLICT DO NOTHING
RETURNING id INTO v_snapshot_id;

IF v_snapshot_id IS NOT NULL THEN
IF p_transaction_type = 'proposal' THEN
UPDATE proposals SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'change_order' THEN
UPDATE change_orders SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'invoice' THEN
UPDATE invoices SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
END IF;
END IF;
END IF;

-- ── 5. Perform the failure mutation LAST ──────────────────────────────
-- This happens after calculate_tax so the stored status is always
-- review_required when the function returns.
IF p_transaction_type = 'proposal' THEN
UPDATE proposals SET
tax_calculation_status = 'review_required',
tax_review_required = true,
tax_amount = 0
WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'change_order' THEN
UPDATE change_orders SET
tax_calculation_status = 'review_required',
tax_review_required = true,
tax_amount = 0
WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'invoice' THEN
UPDATE invoices SET
tax_calculation_status = 'review_required',
tax_review_required = true,
tax_amount = 0
WHERE id = p_transaction_id;
END IF;

-- ── 6. Verify the transaction row still contains review_required ──────
IF p_transaction_type = 'proposal' THEN
SELECT tax_calculation_status INTO v_final_status FROM proposals WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'change_order' THEN
SELECT tax_calculation_status INTO v_final_status FROM change_orders WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'invoice' THEN
SELECT tax_calculation_status INTO v_final_status FROM invoices WHERE id = p_transaction_id;
END IF;

-- ── 7. Return the failure result ───────────────────────────────────────
RETURN jsonb_build_object(
'tax_calculation_status', v_final_status,
'taxability_results', v_calc_result->'taxability_results',
'origin_result', v_calc_result->'origin_result',
'collection_status', v_calc_result->>'collection_status',
'destination_result', v_calc_result->'destination_result',
'tax_amount', 0,
'taxable_subtotal', COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0),
'review_reasons', v_existing_reasons,
'exemption_reference', v_calc_result->>'exemption_reference',
'taxjar_error', p_failure_reason,
'source', 'taxjar_failure'
);
END;
$function$


CREATE OR REPLACE FUNCTION public.midnight_session_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sessions_closed integer;
v_result jsonb;
BEGIN
-- Close all active sessions where last activity was more than 5 minutes ago
WITH closed_sessions AS (
UPDATE user_sessions
SET
is_active = false,
session_end = now()
WHERE is_active = true
AND last_activity < now() - INTERVAL '5 minutes'
RETURNING id
)
SELECT COUNT(*) INTO v_sessions_closed
FROM closed_sessions;

-- Build result
v_result := jsonb_build_object(
'success', true,
'sessions_closed', v_sessions_closed,
'cleanup_time', now(),
'message', format('Closed %s inactive sessions at midnight', v_sessions_closed)
);

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.monitor_invoice_payment_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal record;
v_sales_order_id uuid;
v_sales_rep_id uuid;
BEGIN
IF NEW.status = 'paid' AND (OLD.status IS NULL OR OLD.status != 'paid') THEN
IF NEW.proposal_id IS NOT NULL THEN
SELECT 
p.id as proposal_id,
p.proposal_number,
p.sales_order_id,
p.created_by as sales_rep_id,
so.order_number,
so.status as sales_order_status
INTO v_proposal
FROM proposals p
LEFT JOIN sales_orders so ON so.id = p.sales_order_id
WHERE p.id = NEW.proposal_id;

IF FOUND AND v_proposal.sales_order_id IS NOT NULL THEN
v_sales_order_id := v_proposal.sales_order_id;
v_sales_rep_id := v_proposal.sales_rep_id;

IF v_proposal.sales_order_status = 'pending_deposit' THEN
UPDATE sales_orders
SET 
status = 'planning',
notes = COALESCE(notes, '') || E'\
' || 'Deposit payment received on ' || to_char(now(), 'YYYY-MM-DD HH24:MI'),
updated_at = now()
WHERE id = v_sales_order_id;

BEGIN
INSERT INTO notifications (
company_id,
user_id,
type,
title,
message,
related_type,
related_id,
created_at
) VALUES (
NEW.company_id,
v_sales_rep_id,
'deposit_received',
'Deposit Payment Received',
'Deposit payment received for proposal ' || v_proposal.proposal_number || '. Sales Order ' || v_proposal.order_number || ' is now ready for planning.',
'sales_order',
v_sales_order_id,
now()
);
EXCEPTION
WHEN OTHERS THEN
RAISE WARNING 'Failed to create deposit notification: %', SQLERRM;
END;
END IF;
END IF;
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.normalize_test_tune_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_start date;
BEGIN
 IF NEW.access_type='test_and_tune' THEN
  SELECT substantial_completion_date INTO v_start FROM projects WHERE id=NEW.project_id AND contact_id=NEW.contact_id AND organization_id=NEW.organization_id;
  IF v_start IS NULL THEN RAISE EXCEPTION 'Test & Tune requires a substantially completed project'; END IF;
  IF v_start+90<CURRENT_DATE THEN RAISE EXCEPTION 'The project Test & Tune period has ended'; END IF;
  NEW.granted_date=v_start; NEW.expiration_date=v_start+90;
 END IF;
 RETURN NEW;
END $function$


CREATE OR REPLACE FUNCTION public.notify_admins_of_vip_signup()
