CREATE OR REPLACE FUNCTION public.notify_approvers_of_time_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_approver_ids uuid[];
v_approver_id  uuid;
v_tech_name    text;
v_session_type text;
v_hours        numeric;
v_title        text;
v_body         text;
BEGIN
-- Only fire on new pending_approval inserts
IF NEW.status <> 'pending_approval' THEN
RETURN NEW;
END IF;

-- Get approver list from company_settings
SELECT time_request_approver_ids
INTO v_approver_ids
FROM company_settings
LIMIT 1;

IF v_approver_ids IS NULL OR array_length(v_approver_ids, 1) IS NULL THEN
RETURN NEW;
END IF;

-- Resolve tech's display name
SELECT COALESCE(full_name, email, 'A technician')
INTO v_tech_name
FROM profiles
WHERE id = NEW.assigned_to;

v_session_type := CASE NEW.session_type
WHEN 'shop_time'  THEN 'Shop Time'
WHEN 'training'   THEN 'Training Time'
ELSE initcap(replace(NEW.session_type, '_', ' '))
END;

v_hours := COALESCE(NEW.predetermined_hours, 0);

v_title := v_tech_name || ' requested ' || v_session_type;
v_body  := v_session_type || ' request for ' ||
v_hours::text || ' hour(s)' ||
CASE WHEN NEW.request_reason IS NOT NULL AND NEW.request_reason <> ''
THEN ': ' || NEW.request_reason
ELSE ''
END;

-- Insert one notification per approver
FOREACH v_approver_id IN ARRAY v_approver_ids
LOOP
INSERT INTO notifications (user_id, type, title, body, related_id, is_read)
VALUES (
v_approver_id,
'internal_time_request_submitted',
v_title,
v_body,
NEW.id,
false
);
END LOOP;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_bug_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
recipient RECORD;
BEGIN
-- Send notifications to all configured recipients
FOR recipient IN
SELECT
bns.user_id,
bns.send_email,
bns.send_site_notification,
p.full_name,
p.email
FROM bug_notification_settings bns
JOIN profiles p ON p.id = bns.user_id
LOOP
-- Send site notification if enabled
IF recipient.send_site_notification THEN
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id
) VALUES (
recipient.user_id,
'bug_report',
'New Bug Report',
'A new bug has been reported: ' || LEFT(NEW.description, 100),
NEW.id
);
END IF;

-- Email notifications will be handled by the application layer
-- when send_email is true
END LOOP;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_creator_service_request_kicked_back()
