CREATE OR REPLACE FUNCTION public.notify_on_customer_question()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
thread_proposal_id uuid;
sales_rep_id uuid;
proposal_number text;
customer_name text;
org_id uuid;
BEGIN
-- Only process customer messages
IF NEW.author_type != 'customer' OR NEW.is_internal = true THEN
RETURN NEW;
END IF;

-- Get proposal context
SELECT proposal_id, assigned_sales_rep_id
INTO thread_proposal_id, sales_rep_id
FROM message_threads
WHERE id = NEW.thread_id;

-- Only notify if this is a proposal-related message
IF thread_proposal_id IS NOT NULL AND sales_rep_id IS NOT NULL THEN
-- Get proposal number, customer name, and organization_id
SELECT p.proposal_number, c.full_name, p.organization_id
INTO proposal_number, customer_name, org_id
FROM proposals p
LEFT JOIN contacts c ON p.contact_id = c.id
WHERE p.id = thread_proposal_id;

-- Create notification for sales rep
INSERT INTO notifications (user_id, organization_id, type, title, message, related_id)
VALUES (
sales_rep_id,
org_id,
'customer_question',
'New Customer Question',
customer_name || ' asked a question about proposal ' || COALESCE(proposal_number, 'N/A'),
thread_proposal_id
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_paparazzi_requester()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_requester_id uuid;
v_customer_name text;
v_project_name text;
BEGIN
-- Only proceed if status changed to completed
IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
-- Get requester info
SELECT requested_by, customer_name INTO v_requester_id, v_customer_name
FROM paparazzi_requests
WHERE id = NEW.id;

-- Get project name if exists
IF NEW.project_id IS NOT NULL THEN
SELECT name INTO v_project_name
FROM projects
WHERE id = NEW.project_id;
END IF;

-- Create notification
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id,
organization_id
) VALUES (
v_requester_id,
'paparazzi_photos_uploaded',
'Photos Uploaded',
'Photos have been uploaded for ' || v_customer_name || 
CASE WHEN v_project_name IS NOT NULL THEN ' - ' || v_project_name ELSE '' END,
NEW.id,
NEW.organization_id
);

-- Set completed_at if not already set
IF NEW.completed_at IS NULL THEN
NEW.completed_at = now();
END IF;
END IF;

RETURN NEW;
END;
$function$


