CREATE OR REPLACE FUNCTION public.notify_rep_of_proposal_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal_title text;
v_proposal_owner uuid;
v_proposal_number text;
BEGIN
-- Only create notification for customer messages
IF NEW.sender_type = 'customer' THEN
-- Get proposal details
SELECT title, created_by, proposal_number
INTO v_proposal_title, v_proposal_owner, v_proposal_number
FROM proposals
WHERE id = NEW.proposal_id;

-- Create notification for the proposal owner (sales rep)
IF v_proposal_owner IS NOT NULL THEN
INSERT INTO notifications (
user_id,
title,
body,
type,
related_id,
is_read,
created_at
) VALUES (
v_proposal_owner,
'New Customer Message',
'Customer sent a message on proposal: ' || COALESCE(v_proposal_title, v_proposal_number),
'proposal_message',
NEW.proposal_id,
false,
now()
);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_sales_rep_of_approval(p_proposal_id uuid, p_customer_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_proposal proposals%ROWTYPE;
v_assigned_to uuid;
v_message text;
BEGIN
-- Get proposal details
SELECT * INTO v_proposal FROM proposals WHERE id = p_proposal_id;

-- Get assigned sales rep (owner or created_by)
v_assigned_to := COALESCE(v_proposal.assigned_to, v_proposal.created_by);

IF v_assigned_to IS NULL THEN
RETURN; -- No one to notify
END IF;

-- Build notification message based on deposit requirement
IF v_proposal.require_deposit THEN
IF v_proposal.accepted_via_method = 'verbal' THEN
v_message := p_customer_name || ' approved proposal ' || v_proposal.proposal_number ||
'. A deposit invoice has been created and sent to the customer. Sales order is pending deposit payment.';
ELSE
v_message := p_customer_name || ' approved proposal ' || v_proposal.proposal_number ||
' with purchase order #' || COALESCE(v_proposal.purchase_order_number, 'N/A') ||
'. Sales order has been created and is ready for scheduling.';
END IF;
ELSE
v_message := p_customer_name || ' approved proposal ' || v_proposal.proposal_number ||
'. Sales order has been created and is ready for scheduling.';
END IF;

-- Create notification for the sales rep
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id,
created_at
) VALUES (
v_assigned_to,
'proposal_approved',
'Customer Approved Proposal',
v_message,
p_proposal_id,
now()
);

EXCEPTION
WHEN OTHERS THEN
-- Log error but don't fail the transaction
RAISE WARNING 'Failed to notify sales rep: %', SQLERRM;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_service_managers_new_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_punchlist boolean := NEW.source_type='punchlist' OR NEW.notes ILIKE '%Created from customer punchlist portal%';
BEGIN
  INSERT INTO public.notifications (user_id,organization_id,title,body,type,related_id,is_read,created_at)
  SELECT p.id,NEW.organization_id,
    CASE WHEN v_punchlist THEN 'New Punchlist Service Request' ELSE 'New Service Request' END,
    CASE WHEN v_punchlist THEN 'Customer ' || NEW.customer_name || ' requested service for punchlist items'
         ELSE 'Service request from ' || NEW.customer_name || ': ' || left(NEW.job_description,100) END,
    CASE WHEN v_punchlist THEN 'punchlist_service_request' ELSE 'service_request_created' END,
    coalesce(NEW.work_order_id,NEW.id),false,now()
  FROM public.profiles p WHERE p.organization_id=NEW.organization_id AND p.role='service_manager' AND p.is_active;
  RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_task_assigned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_customer_name text;
v_body text;
BEGIN
-- Look up customer name from contact if linked
IF NEW.contact_id IS NOT NULL THEN
SELECT COALESCE(full_name, company_name)
INTO v_customer_name
FROM contacts
WHERE id = NEW.contact_id;
END IF;

-- Build body with customer name if available
IF v_customer_name IS NOT NULL AND v_customer_name <> '' THEN
v_body := NEW.title || ' — ' || v_customer_name;
ELSE
v_body := NEW.title;
END IF;

-- On INSERT: Notify if task is assigned to someone
IF TG_OP = 'INSERT' AND NEW.assigned_to IS NOT NULL THEN
INSERT INTO notifications (
user_id,
title,
body,
type,
is_read,
related_id,
created_at
) VALUES (
NEW.assigned_to,
'Task Assigned to You',
v_body,
'task_assigned',
false,
NEW.id,
now()
);
END IF;

-- On UPDATE: Notify if assignment changed and is now assigned to someone
IF TG_OP = 'UPDATE' AND
(OLD.assigned_to IS DISTINCT FROM NEW.assigned_to) AND
NEW.assigned_to IS NOT NULL THEN
INSERT INTO notifications (
user_id,
title,
body,
type,
is_read,
related_id,
created_at
) VALUES (
NEW.assigned_to,
'Task Assigned to You',
v_body,
'task_assigned',
false,
NEW.id,
now()
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_task_status_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Only notify if status actually changed
IF OLD.status != NEW.status THEN
-- Notify the assignee if there is one, otherwise notify the creator
INSERT INTO notifications (
user_id,
title,
body,
type,
is_read,
related_id,
created_at
) VALUES (
COALESCE(NEW.assigned_to, NEW.user_id),
'Task Status Updated',
NEW.title || ' - Status changed to: ' || NEW.status,
'task',
false,
NEW.id,
now()
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_tech_of_time_request_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_approver_name text;
v_session_type  text;
v_hours         numeric;
v_title         text;
v_body          text;
v_notif_type    text;
BEGIN
-- Fire when status transitions from pending_approval to completed (approved) or denied
IF OLD.status <> 'pending_approval' THEN
RETURN NEW;
END IF;
IF NEW.status NOT IN ('completed', 'denied') THEN
RETURN NEW;
END IF;

-- Resolve approver name
SELECT COALESCE(full_name, email, 'A manager')
INTO v_approver_name
FROM profiles
WHERE id = NEW.approved_by;

v_session_type := CASE NEW.session_type
WHEN 'shop_time'  THEN 'Shop Time'
WHEN 'training'   THEN 'Training Time'
ELSE initcap(replace(NEW.session_type, '_', ' '))
END;

v_hours := COALESCE(NEW.predetermined_hours, 0);

IF NEW.status = 'completed' THEN
v_notif_type := 'internal_time_request_approved';
v_title      := v_session_type || ' request approved';
v_body       := v_approver_name || ' approved your ' || v_session_type || ' request. ' ||
v_hours::text || 'h have been added to your payroll for ' ||
to_char(NEW.session_date::date, 'Mon DD') || '.';
ELSE
v_notif_type := 'internal_time_request_denied';
v_title      := v_session_type || ' request declined';
v_body       := v_approver_name || ' declined your ' || v_session_type || ' request.' ||
CASE WHEN NEW.denial_reason IS NOT NULL AND NEW.denial_reason <> ''
THEN ' Reason: ' || NEW.denial_reason
ELSE ''
END;
END IF;

INSERT INTO notifications (user_id, type, title, body, related_id, is_read)
VALUES (
NEW.assigned_to,
v_notif_type,
v_title,
v_body,
NEW.id,
false
);

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_time_adjustment_requested()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Notify admins and finance that a new request needs review
INSERT INTO notifications (
user_id,
type,
title,
message,
related_id
)
SELECT 
p.id,
'time_adjustment_requested',
'Time Adjustment Request',
(SELECT full_name FROM profiles WHERE id = NEW.technician_id) || ' has requested a time adjustment',
NEW.id::text
FROM profiles p
WHERE p.role IN ('admin', 'finance');

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_time_adjustment_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
-- Only send notification when status changes from pending to approved/denied
IF OLD.status = 'pending' AND NEW.status IN ('approved', 'denied') THEN
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id
) VALUES (
NEW.technician_id,
'time_adjustment',
CASE
WHEN NEW.status = 'approved' THEN 'Time Adjustment Request Approved'
ELSE 'Time Adjustment Request Denied'
END,
CASE
WHEN NEW.status = 'approved' THEN 'Your time adjustment request has been approved by admin.'
ELSE 'Your time adjustment request has been denied. Reason: ' || COALESCE(NEW.admin_notes, 'No reason provided.')
END,
NEW.id
);
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_watchers_of_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
watcher_record record;
task_title text;
commenter_name text;
BEGIN
-- Get task title and commenter name
SELECT t.title, p.full_name
INTO task_title, commenter_name
FROM tasks t, profiles p
WHERE t.id = NEW.task_id
AND p.id = NEW.user_id;

-- Notify all watchers except the commenter
FOR watcher_record IN
SELECT user_id
FROM task_watchers
WHERE task_id = NEW.task_id
AND user_id != NEW.user_id
LOOP
INSERT INTO task_notifications (
task_id,
user_id,
notification_type,
message,
created_by
)
VALUES (
NEW.task_id,
watcher_record.user_id,
'comment',
commenter_name || ' commented on task: ' || task_title,
NEW.user_id
);
END LOOP;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.notify_work_order_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.assigned_to IS NOT NULL AND (TG_OP = 'INSERT' OR OLD.assigned_to IS DISTINCT FROM NEW.assigned_to) THEN
INSERT INTO notifications (
user_id,
title,
body,
type,
related_id,
organization_id,
is_read,
created_at
)
VALUES (
NEW.assigned_to,
'New Work Order Assigned',
'Work Order ' || NEW.work_order_number || ' has been assigned to you. ' || COALESCE(NEW.title, ''),
'work_order_assignment',
NEW.id,
NEW.organization_id,
false,
now()
);
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.persist_taxjar_result(p_transaction_type text, p_transaction_id uuid, p_taxjar_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_exists boolean := false;
v_org_id uuid;
v_calc_result jsonb;
v_snapshot_id uuid;
v_amount_to_collect numeric;
v_rate numeric;
v_tax_source text;
v_freight_taxable boolean;
v_breakdown jsonb;
v_state_rate numeric := 0;
v_county_rate numeric := 0;
v_city_rate numeric := 0;
v_district_rate numeric := 0;
v_combined_rate numeric := 0;
v_jurisdiction_name text;
BEGIN
-- ── Validate transaction exists ────────────────────────────────────
IF p_transaction_type = 'proposal' THEN
SELECT organization_id INTO v_org_id FROM proposals WHERE id = p_transaction_id;
v_exists := v_org_id IS NOT NULL;
ELSIF p_transaction_type = 'change_order' THEN
SELECT co.organization_id INTO v_org_id FROM change_orders co WHERE co.id = p_transaction_id;
v_exists := v_org_id IS NOT NULL;
ELSIF p_transaction_type = 'invoice' THEN
SELECT organization_id INTO v_org_id FROM invoices WHERE id = p_transaction_id;
v_exists := v_org_id IS NOT NULL;
ELSE
RETURN jsonb_build_object('error', 'Unknown transaction type: ' || p_transaction_type);
END IF;

IF NOT v_exists THEN
RETURN jsonb_build_object('error', 'Transaction not found: ' || p_transaction_type || ' ' || p_transaction_id);
END IF;

-- ── Extract TaxJar result fields ───────────────────────────────────
v_amount_to_collect := COALESCE((p_taxjar_result->>'amount_to_collect')::numeric, 0);
v_rate := COALESCE((p_taxjar_result->>'rate')::numeric, 0);
v_tax_source := p_taxjar_result->>'tax_source';
v_freight_taxable := COALESCE((p_taxjar_result->>'freight_taxable')::boolean, false);
v_breakdown := p_taxjar_result->'breakdown';

-- Extract rate components from breakdown if available
IF v_breakdown IS NOT NULL THEN
v_state_rate := COALESCE((v_breakdown->'state'->>'state_rate')::numeric, 0);
v_county_rate := COALESCE((v_breakdown->'county'->>'county_rate')::numeric, 0);
v_city_rate := COALESCE((v_breakdown->'city'->>'city_rate')::numeric, 0);
v_district_rate := COALESCE((v_breakdown->'special'->>'special_rate')::numeric, 0);
v_combined_rate := v_rate;
-- Build jurisdiction name from breakdown
SELECT COALESCE(string_agg(COALESCE(part, ''), ', '), '') INTO v_jurisdiction_name
FROM (
SELECT v_breakdown->'state'->>'state_abbrev' AS part
UNION ALL
SELECT v_breakdown->'county'->>'county_name'
UNION ALL
SELECT v_breakdown->'city'->>'city_name'
) parts
WHERE part IS NOT NULL AND part <> '';
ELSE
v_combined_rate := v_rate;
END IF;

-- ── Update the transaction record with authoritative TaxJar values ─
IF p_transaction_type = 'proposal' THEN
UPDATE proposals SET
tax_amount = v_amount_to_collect,
tax_rate = v_rate,
tax_calculation_status = 'ready',
tax_review_required = false
WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'change_order' THEN
UPDATE change_orders SET
tax_amount = v_amount_to_collect,
tax_rate = v_rate,
tax_calculation_status = 'ready',
tax_review_required = false
WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'invoice' THEN
UPDATE invoices SET
tax_amount = v_amount_to_collect,
tax_rate = v_rate,
tax_calculation_status = 'ready',
tax_review_required = false
WHERE id = p_transaction_id;
END IF;

-- ── Get the full MJV calculation context for the snapshot ──────────
v_calc_result := calculate_tax(p_transaction_type, p_transaction_id);

-- ── Upsert the tax snapshot ────────────────────────────────────────
-- Check if a snapshot already exists for this transaction
SELECT id INTO v_snapshot_id
FROM tax_snapshots
WHERE transaction_type = p_transaction_type
AND transaction_id = p_transaction_id
ORDER BY calculated_at DESC
LIMIT 1;

IF v_snapshot_id IS NOT NULL THEN
-- Update existing snapshot with TaxJar results
UPDATE tax_snapshots SET
tax_calculation_status = 'ready',
sales_tax = v_amount_to_collect,
combined_rate = v_combined_rate,
state_rate = v_state_rate,
county_rate = v_county_rate,
city_rate = v_city_rate,
district_rate = v_district_rate,
tax_source = v_tax_source,
freight_taxable = v_freight_taxable,
jurisdiction_breakdown = v_breakdown,
taxjar_verified_at = now(),
taxability_results = v_calc_result->'taxability_results',
origin_address = v_calc_result->'origin_result',
destination_address = v_calc_result->'destination_result',
collection_status = v_calc_result->>'collection_status',
exemption_reference = v_calc_result->>'exemption_reference',
taxable_subtotal = COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0),
calculated_at = now()
WHERE id = v_snapshot_id;
ELSE
-- Insert new snapshot with TaxJar results
INSERT INTO tax_snapshots (
organization_id,
transaction_type,
transaction_id,
state,
environment,
project_type,
tax_calculation_status,
taxability_results,
origin_method,
origin_address,
destination_address,
collection_status,
nexus_result,
exemption_reference,
taxable_subtotal,
sales_tax,
combined_rate,
state_rate,
county_rate,
city_rate,
district_rate,
tax_source,
freight_taxable,
jurisdiction_breakdown,
taxjar_verified_at,
calculated_at
) VALUES (
v_org_id,
p_transaction_type,
p_transaction_id,
COALESCE(v_calc_result->'destination_result'->>'state', ''),
NULL,
NULL,
'ready',
v_calc_result->'taxability_results',
v_calc_result->'origin_result'->>'origin_method',
v_calc_result->'origin_result',
v_calc_result->'destination_result',
v_calc_result->>'collection_status',
v_calc_result->>'collection_status',
v_calc_result->>'exemption_reference',
COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0),
v_amount_to_collect,
v_combined_rate,
v_state_rate,
v_county_rate,
v_city_rate,
v_district_rate,
v_tax_source,
v_freight_taxable,
v_breakdown,
now(),
now()
)
ON CONFLICT DO NOTHING
RETURNING id INTO v_snapshot_id;

-- Link the snapshot to the transaction
IF v_snapshot_id IS NOT NULL THEN
IF p_transaction_type = 'proposal' THEN
UPDATE proposals SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'change_order' THEN
UPDATE change_orders SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'invoice' THEN
UPDATE invoices SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
END IF;
END IF;
END IF;

-- ── Return the completed result ───────────────────────────────────
RETURN jsonb_build_object(
'tax_calculation_status', 'ready',
'taxability_results', v_calc_result->'taxability_results',
'origin_result', v_calc_result->'origin_result',
'collection_status', v_calc_result->>'collection_status',
'destination_result', v_calc_result->'destination_result',
'tax_amount', v_amount_to_collect,
'taxable_subtotal', COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0),
'tax_rate', v_rate,
'tax_source', v_tax_source,
'freight_taxable', v_freight_taxable,
'jurisdiction_breakdown', v_breakdown,
'review_reasons', v_calc_result->'review_reasons',
'exemption_reference', v_calc_result->>'exemption_reference',
'taxjar_verified_at', to_jsonb(now()),
'source', 'taxjar'
);
END;
$function$


CREATE OR REPLACE FUNCTION public.populate_default_starred_modules(p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Clear any existing starred modules for this user (in case of role change)
DELETE FROM user_starred_modules WHERE user_id = p_user_id;

-- Populate with default starred modules for the role
INSERT INTO user_starred_modules (user_id, module_id)
SELECT p_user_id, module_id
FROM default_starred_modules
WHERE role = p_role
ON CONFLICT (user_id, module_id) DO NOTHING;
END;
$function$


CREATE OR REPLACE FUNCTION public.prevent_line_item_changes_on_submitted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invoice_status text;
v_inv_id uuid;
BEGIN
v_inv_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END;

SELECT status INTO v_invoice_status
FROM invoices WHERE id = v_inv_id;

IF v_invoice_status IS NOT NULL AND v_invoice_status <> 'draft' THEN
RAISE EXCEPTION 'Cannot % line items on a submitted invoice. Line items are locked after submission.',
TG_OP
USING ERRCODE = 'check_violation';
END IF;

RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$


CREATE OR REPLACE FUNCTION public.prevent_locked_segment_modification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
v_reopen_period_id text;
v_reopen_authorized text;
BEGIN
IF TG_OP = 'DELETE' THEN
IF OLD.is_locked = true THEN
RAISE EXCEPTION 'Cannot delete locked payroll time segment %. Use the correction workflow instead.', OLD.id;
END IF;
RETURN OLD;
END IF;

IF OLD.is_locked = true THEN
v_reopen_period_id := current_setting('app.reopen_pay_period_id', true);
v_reopen_authorized := current_setting('app.reopen_authorized', true);

IF current_user = 'postgres'
AND v_reopen_authorized = 'true'
AND v_reopen_period_id IS NOT NULL
AND v_reopen_period_id = OLD.pay_period_id::text
AND NEW.is_locked = false
THEN
RETURN NEW;
END IF;

RAISE EXCEPTION 'Cannot modify locked payroll time segment %. Use the correction workflow instead.', OLD.id;
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.prevent_non_draft_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF OLD.status <> 'draft' THEN
RAISE EXCEPTION 'Cannot delete a submitted invoice. Only draft invoices can be deleted. Void the invoice instead.'
USING ERRCODE = 'check_violation';
END IF;
RETURN OLD;
END;
$function$


CREATE OR REPLACE FUNCTION public.prevent_post_submit_field_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF COALESCE(OLD.status, 'draft') <> 'draft' AND NEW.status = OLD.status THEN
IF NEW.contact_id IS DISTINCT FROM OLD.contact_id THEN
RAISE EXCEPTION 'Cannot modify customer on a submitted invoice. Void and recreate if needed.'
USING ERRCODE = 'check_violation';
END IF;
IF NEW.subtotal IS DISTINCT FROM OLD.subtotal
OR NEW.tax_amount IS DISTINCT FROM OLD.tax_amount
OR NEW.total IS DISTINCT FROM OLD.total
OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number
OR NEW.invoice_date IS DISTINCT FROM OLD.invoice_date
OR NEW.due_date IS DISTINCT FROM OLD.due_date
OR NEW.tax_environment IS DISTINCT FROM OLD.tax_environment
OR NEW.tax_project_type IS DISTINCT FROM OLD.tax_project_type
OR NEW.tax_rate IS DISTINCT FROM OLD.tax_rate
OR NEW.tax_jurisdiction_id IS DISTINCT FROM OLD.tax_jurisdiction_id
OR NEW.billing_name IS DISTINCT FROM OLD.billing_name
OR NEW.billing_address_line1 IS DISTINCT FROM OLD.billing_address_line1
OR NEW.billing_address_line2 IS DISTINCT FROM OLD.billing_address_line2
OR NEW.billing_city IS DISTINCT FROM OLD.billing_city
OR NEW.billing_state IS DISTINCT FROM OLD.billing_state
OR NEW.billing_zip IS DISTINCT FROM OLD.billing_zip
OR NEW.jobsite_address IS DISTINCT FROM OLD.jobsite_address
OR NEW.jobsite_city IS DISTINCT FROM OLD.jobsite_city
OR NEW.jobsite_state IS DISTINCT FROM OLD.jobsite_state
OR NEW.jobsite_zip IS DISTINCT FROM OLD.jobsite_zip
THEN
RAISE EXCEPTION 'Cannot modify accounting fields on a submitted invoice. Fields are locked after submission.'
USING ERRCODE = 'check_violation';
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.process_stock_adjustment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_adjustment_rec RECORD;
v_current_qty numeric;
BEGIN
-- Get adjustment details
SELECT warehouse_id INTO v_adjustment_rec
FROM stock_adjustments
WHERE id = NEW.adjustment_id;

-- Get current quantity
SELECT quantity_on_hand INTO v_current_qty
FROM product_inventory
WHERE product_id = NEW.product_id
AND warehouse_id = v_adjustment_rec.warehouse_id;

-- Update inventory
INSERT INTO product_inventory (product_id, warehouse_id, quantity_on_hand, updated_at)
VALUES (NEW.product_id, v_adjustment_rec.warehouse_id, NEW.quantity_after, now())
ON CONFLICT (product_id, warehouse_id)
DO UPDATE SET
quantity_on_hand = NEW.quantity_after,
last_counted_at = now(),
updated_at = now();

-- Create stock movement
INSERT INTO stock_movements (
product_id,
warehouse_id,
movement_type,
quantity,
quantity_before,
quantity_after,
reference_type,
reference_id,
notes,
created_by
) VALUES (
NEW.product_id,
v_adjustment_rec.warehouse_id,
'adjustment',
NEW.quantity_after - NEW.quantity_before,
NEW.quantity_before,
NEW.quantity_after,
'stock_adjustment',
NEW.adjustment_id,
NEW.notes,
auth.uid()
);

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.process_stock_transfer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_transfer_rec RECORD;
v_qty_change numeric;
v_current_qty_from numeric;
v_current_qty_to numeric;
BEGIN
IF TG_OP = 'INSERT' AND NEW.quantity_received = 0 THEN
-- On insert, deduct from source warehouse
SELECT from_warehouse_id, to_warehouse_id INTO v_transfer_rec
FROM stock_transfers
WHERE id = NEW.transfer_id;

-- Get current quantity at source
SELECT quantity_on_hand INTO v_current_qty_from
FROM product_inventory
WHERE product_id = NEW.product_id
AND warehouse_id = v_transfer_rec.from_warehouse_id;

-- Deduct from source warehouse
UPDATE product_inventory
SET
quantity_on_hand = quantity_on_hand - NEW.quantity,
updated_at = now()
WHERE product_id = NEW.product_id
AND warehouse_id = v_transfer_rec.from_warehouse_id;

-- Create stock movement for transfer out
INSERT INTO stock_movements (
product_id,
warehouse_id,
movement_type,
quantity,
quantity_before,
quantity_after,
reference_type,
reference_id,
notes,
created_by
) VALUES (
NEW.product_id,
v_transfer_rec.from_warehouse_id,
'transfer_out',
-NEW.quantity,
COALESCE(v_current_qty_from, 0),
COALESCE(v_current_qty_from, 0) - NEW.quantity,
'stock_transfer',
NEW.transfer_id,
'Transfer out',
auth.uid()
);
ELSIF TG_OP = 'UPDATE' AND NEW.quantity_received > OLD.quantity_received THEN
-- On update, add to destination warehouse
SELECT to_warehouse_id INTO v_transfer_rec
FROM stock_transfers
WHERE id = NEW.transfer_id;

v_qty_change := NEW.quantity_received - OLD.quantity_received;

-- Get current quantity at destination
SELECT quantity_on_hand INTO v_current_qty_to
FROM product_inventory
WHERE product_id = NEW.product_id
AND warehouse_id = v_transfer_rec.to_warehouse_id;

-- Add to destination warehouse
INSERT INTO product_inventory (product_id, warehouse_id, quantity_on_hand, updated_at)
VALUES (NEW.product_id, v_transfer_rec.to_warehouse_id, v_qty_change, now())
ON CONFLICT (product_id, warehouse_id)
DO UPDATE SET
quantity_on_hand = product_inventory.quantity_on_hand + v_qty_change,
updated_at = now();

-- Create stock movement for transfer in
INSERT INTO stock_movements (
product_id,
warehouse_id,
movement_type,
quantity,
quantity_before,
quantity_after,
reference_type,
reference_id,
notes,
created_by
) VALUES (
NEW.product_id,
v_transfer_rec.to_warehouse_id,
'transfer_in',
v_qty_change,
COALESCE(v_current_qty_to, 0),
COALESCE(v_current_qty_to, 0) + v_qty_change,
'stock_transfer',
NEW.transfer_id,
'Transfer in',
auth.uid()
);

-- Update transfer status
PERFORM update_transfer_status(NEW.transfer_id);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.process_subscription_cancellation(p_subscription_id uuid, p_reason_category text, p_reason_details text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_subscription record;
v_effective_date date;
v_will_continue_billing boolean;
v_cancellation_id uuid;
v_company_id uuid;
BEGIN
-- Get subscription details
SELECT * INTO v_subscription
FROM recurring_subscriptions
WHERE id = p_subscription_id
AND status = 'active';

IF NOT FOUND THEN
RETURN json_build_object(
'success', false,
'error', 'Subscription not found or already cancelled'
);
END IF;

-- Get company_id
SELECT company_id INTO v_company_id
FROM recurring_subscriptions
WHERE id = p_subscription_id;

-- Determine effective date
IF v_subscription.end_date IS NOT NULL THEN
-- Has contract end date - cancel on that date
v_effective_date := v_subscription.end_date;
v_will_continue_billing := true;
ELSE
-- No contract end date - cancel immediately at end of current billing period
v_effective_date := v_subscription.next_billing_date;
v_will_continue_billing := false;
END IF;

-- Create cancellation record
INSERT INTO subscription_cancellations (
company_id,
subscription_id,
cancelled_by_user_id,
effective_date,
reason_category,
reason_details,
will_continue_billing
) VALUES (
v_company_id,
p_subscription_id,
auth.uid(),
v_effective_date,
p_reason_category,
p_reason_details,
v_will_continue_billing
)
RETURNING id INTO v_cancellation_id;

-- Update subscription
UPDATE recurring_subscriptions
SET
cancellation_requested = true,
cancellation_id = v_cancellation_id,
updated_at = now()
WHERE id = p_subscription_id;

RETURN json_build_object(
'success', true,
'cancellation_id', v_cancellation_id,
'effective_date', v_effective_date,
'will_continue_billing', v_will_continue_billing
);
END;
$function$


CREATE OR REPLACE FUNCTION public.process_task_comment_mentions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
mentioned_username text;
mentioned_user_id uuid;
task_title text;
BEGIN
-- Get task title for notification
SELECT title INTO task_title FROM tasks WHERE id = NEW.task_id;

-- Extract all @mentions from the comment
FOR mentioned_username IN
SELECT DISTINCT regexp_matches[1]
FROM regexp_matches(NEW.content, '@([a-zA-Z0-9_]+)', 'g') AS regexp_matches
LOOP
-- Find user by username
SELECT id INTO mentioned_user_id
FROM profiles
WHERE username = mentioned_username
AND is_active = true;

IF mentioned_user_id IS NOT NULL THEN
-- Create mention record
INSERT INTO task_mentions (task_id, comment_id, mentioned_user_id, mentioning_user_id)
VALUES (NEW.task_id, NEW.id, mentioned_user_id, NEW.user_id);

-- Add mentioned user as watcher
INSERT INTO task_watchers (task_id, user_id)
VALUES (NEW.task_id, mentioned_user_id)
ON CONFLICT (task_id, user_id) DO NOTHING;

-- Create notification
INSERT INTO task_notifications (
task_id,
user_id,
notification_type,
message,
created_by
)
VALUES (
NEW.task_id,
mentioned_user_id,
'mention',
'mentioned you in a comment on task: ' || task_title,
NEW.user_id
);
END IF;
END LOOP;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.promote_revision_to_live(revision_id_param uuid, send_notification boolean DEFAULT false, notification_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_revision proposals%ROWTYPE;
v_old_live_id uuid;
v_user_id uuid;
v_contact_email text;
v_proposal_number text;
BEGIN
v_user_id := auth.uid();

IF v_user_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
END IF;

SELECT * INTO v_revision FROM public.proposals WHERE id = revision_id_param;

IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Revision not found');
END IF;

SELECT id INTO v_old_live_id
FROM public.proposals
WHERE parent_proposal_id = COALESCE(v_revision.parent_proposal_id, v_revision.id)
AND is_active_revision = true
AND id != revision_id_param;

IF v_old_live_id IS NOT NULL THEN
UPDATE public.proposals
SET
is_active_revision = false,
is_portal_visible = false,
is_locked = false,
locked_at = NULL,
locked_by = NULL,
updated_at = now()
WHERE id = v_old_live_id;
END IF;

UPDATE public.proposals
SET
is_active_revision = true,
is_portal_visible = true,
status = CASE
WHEN status = 'designing' THEN 'ready_to_submit'
ELSE status
END,
updated_at = now()
WHERE id = revision_id_param;

IF send_notification THEN
SELECT c.email, p.proposal_number
INTO v_contact_email, v_proposal_number
FROM public.proposals p
JOIN public.contacts c ON c.id = p.contact_id
WHERE p.id = revision_id_param;

BEGIN
INSERT INTO public.notifications (
user_id,
type,
title,
message,
related_id
) VALUES (
v_user_id,
'proposal_updated',
'Proposal Updated',
COALESCE(notification_message, 'Your proposal has been updated. Please review the changes.'),
revision_id_param
);
EXCEPTION
WHEN OTHERS THEN
RAISE WARNING 'Failed to create revision notification: %', SQLERRM;
END;
END IF;

RETURN jsonb_build_object(
'success', true,
'message', 'Revision promoted to Live successfully',
'old_live_id', v_old_live_id,
'new_live_id', revision_id_param
);
END;
$function$


CREATE OR REPLACE FUNCTION public.protect_profile_privilege_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
-- Service role, cron jobs and SECURITY DEFINER internals have no auth.uid(): leave them alone.
IF auth.uid() IS NULL THEN
RETURN NEW;
END IF;

IF public.caller_is_admin_profile() THEN
RETURN NEW;
END IF;

NEW.role                        := OLD.role;
NEW.role_id                     := OLD.role_id;
NEW.is_global_admin             := OLD.is_global_admin;
NEW.organization_id             := OLD.organization_id;
NEW.is_active                   := OLD.is_active;
NEW.employment_type             := OLD.employment_type;
NEW.requires_daily_clock        := OLD.requires_daily_clock;
NEW.monthly_sales_target        := OLD.monthly_sales_target;
NEW.can_view_team_pulse         := OLD.can_view_team_pulse;
NEW.can_access_recur            := OLD.can_access_recur;
NEW.can_send_portal_invites     := OLD.can_send_portal_invites;
NEW.can_see_all_proposals       := OLD.can_see_all_proposals;
NEW.can_view_all_tasks          := OLD.can_view_all_tasks;
NEW.can_view_all_pipeline       := OLD.can_view_all_pipeline;
NEW.can_edit_contact_assignments:= OLD.can_edit_contact_assignments;
NEW.can_edit_products           := OLD.can_edit_products;
NEW.can_see_all_review_requests := OLD.can_see_all_review_requests;
NEW.can_edit_contacts           := OLD.can_edit_contacts;
NEW.can_view_prospects          := OLD.can_view_prospects;
NEW.can_view_executive_dashboard:= OLD.can_view_executive_dashboard;
NEW.can_delete_invoices         := OLD.can_delete_invoices;
NEW.can_create_work_orders      := OLD.can_create_work_orders;
NEW.can_create_proposals        := OLD.can_create_proposals;
NEW.can_create_purchase_orders  := OLD.can_create_purchase_orders;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.queue_punchlist_invite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Check if substantial_completion_date was just set
IF (NEW.substantial_completion_date IS NOT NULL 
AND (OLD.substantial_completion_date IS NULL OR OLD.substantial_completion_date != NEW.substantial_completion_date)) THEN

-- Only queue if:
-- 1. No existing pending invite for this contact
-- 2. No active access grant for this contact
-- 3. Contact doesn't already have VIP membership with punchlist access
IF NOT EXISTS (
SELECT 1 FROM pending_punchlist_invites 
WHERE contact_id = NEW.contact_id 
AND status = 'pending'
) AND NOT EXISTS (
SELECT 1 FROM punchlist_access_grants
WHERE contact_id = NEW.contact_id
AND status = 'active'
AND (expiration_date IS NULL OR expiration_date >= CURRENT_DATE)
) THEN

-- Create pending invite for staff review
INSERT INTO pending_punchlist_invites (
contact_id,
project_id,
status,
notes
) VALUES (
NEW.contact_id,
NEW.id,
'pending',
'Auto-queued on project substantial completion: ' || NEW.name
);
END IF;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.recalculate_all_sales_quotas()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_count integer := 0;
r record;
BEGIN
FOR r IN
SELECT id FROM profiles
WHERE is_active = true
AND role IN ('sales','admin','manager','sales_manager')
LOOP
PERFORM recalculate_sales_quota_for_user(r.id);
v_count := v_count + 1;
END LOOP;
RETURN v_count;
END;
$function$


CREATE OR REPLACE FUNCTION public.recalculate_field_target_on_change_order_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_sales_order_id uuid;
v_added_labor_hours numeric(10, 2);
v_previous_total numeric(10, 2);
v_previous_field_target numeric(10, 2);
v_previous_pm_allocation numeric(10, 2);
v_new_total numeric(10, 2);
v_new_field_target numeric(10, 2);
v_new_pm_allocation numeric(10, 2);
BEGIN
-- Only proceed if status changed to 'approved'
IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
-- Get the sales order ID
v_sales_order_id := NEW.sales_order_id;

-- Skip if no sales order linked
IF v_sales_order_id IS NULL THEN
RETURN NEW;
END IF;

-- Calculate total labor hours from this change order
SELECT COALESCE(SUM(labor_hours), 0)
INTO v_added_labor_hours
FROM change_order_line_items
WHERE change_order_id = NEW.id
AND labor_hours IS NOT NULL;

-- Skip if no labor hours added
IF v_added_labor_hours = 0 THEN
RETURN NEW;
END IF;

-- Get current values from sales order
SELECT 
COALESCE(total_estimated_labor_hours, 0),
COALESCE(field_labor_target_hours, 0),
COALESCE(pm_labor_allocation_hours, 0)
INTO 
v_previous_total,
v_previous_field_target,
v_previous_pm_allocation
FROM sales_orders
WHERE id = v_sales_order_id;

-- Calculate new values
v_new_total := v_previous_total + v_added_labor_hours;
v_new_pm_allocation := v_new_total * 0.05;  -- 5% for PM
v_new_field_target := v_new_total * 0.95;   -- 95% for field target

-- Update sales order
UPDATE sales_orders
SET
total_estimated_labor_hours = v_new_total,
pm_labor_allocation_hours = v_new_pm_allocation,
field_labor_target_hours = v_new_field_target,
updated_at = now()
WHERE id = v_sales_order_id;

-- Log to history
INSERT INTO test_tune_field_target_history (
sales_order_id,
change_order_id,
change_order_number,
previous_total_labor_hours,
previous_field_target_hours,
previous_pm_allocation_hours,
added_labor_hours,
new_total_labor_hours,
new_field_target_hours,
new_pm_allocation_hours,
recalculated_by
) VALUES (
v_sales_order_id,
NEW.id,
NEW.change_order_number,
v_previous_total,
v_previous_field_target,
v_previous_pm_allocation,
v_added_labor_hours,
v_new_total,
v_new_field_target,
v_new_pm_allocation,
auth.uid()
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.recalculate_sales_quota_for_user(p_user_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_quota numeric;
BEGIN
v_result := calculate_sales_quota(p_user_id, CURRENT_DATE);
v_quota := (v_result->>'current_annual_quota')::numeric;

UPDATE profiles
SET current_annual_quota = v_quota,
quota_last_calculated_at = now()
WHERE id = p_user_id;

RETURN v_quota;
END;
$function$


CREATE OR REPLACE FUNCTION public.reconcile_allocation(p_pay_period_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_start date;
v_end date;
v_emp_record record;
v_config record;
v_day date;
v_available_hours numeric;
v_allocated_hours numeric;
v_unallocated_hours numeric;
v_overallocated_hours numeric;
v_flagged int := 0;
v_checked int := 0;
BEGIN
SELECT organization_id, period_start_date, period_end_date
INTO v_org_id, v_start, v_end
FROM pay_periods
WHERE id = p_pay_period_id;

IF NOT FOUND THEN
RETURN json_build_object('error', 'pay period not found');
END IF;

DELETE FROM payroll_reconciliation_flags
WHERE pay_period_id = p_pay_period_id
AND reconciliation_type = 'allocation';

FOR v_emp_record IN
SELECT DISTINCT e.id AS emp_id, e.user_id
FROM payroll_time_segments pts
JOIN employees e ON e.user_id = pts.employee_id
WHERE pts.pay_period_id = p_pay_period_id
AND pts.organization_id = v_org_id
LOOP
FOR v_day IN SELECT generate_series(v_start, v_end, '1 day'::interval)::date LOOP
SELECT * INTO v_config
FROM employee_payroll_configs
WHERE employee_id = v_emp_record.emp_id
AND effective_from <= v_day
AND (effective_to IS NULL OR effective_to >= v_day)
ORDER BY effective_from DESC
LIMIT 1;

CONTINUE WHEN v_config IS NULL OR v_config.requires_time_allocation = false;

v_checked := v_checked + 1;

v_available_hours := NULL;
IF v_config.requires_daily_clock = true THEN
SELECT COALESCE(SUM(COALESCE(total_hours, 0)), 0)
INTO v_available_hours
FROM daily_clock_entries
WHERE technician_id = v_emp_record.user_id
AND entry_date = v_day
AND organization_id = v_org_id
AND status = 'clocked_out';
END IF;

SELECT COALESCE(SUM(COALESCE(total_hours, 0)), 0)
INTO v_allocated_hours
FROM time_entries
WHERE technician_id = v_emp_record.user_id
AND entry_date = v_day
AND organization_id = v_org_id
AND status = 'approved';

SELECT COALESCE(SUM(COALESCE(predetermined_hours, 0)), 0)
INTO v_overallocated_hours
FROM internal_time_sessions
WHERE assigned_to = v_emp_record.user_id
AND session_date = v_day
AND organization_id = v_org_id
AND status = 'approved';

v_allocated_hours := v_allocated_hours + v_overallocated_hours;
v_overallocated_hours := 0;

IF v_available_hours IS NOT NULL THEN
v_unallocated_hours := v_available_hours - v_allocated_hours;
IF v_unallocated_hours < 0 THEN
v_overallocated_hours := ABS(v_unallocated_hours);
v_unallocated_hours := 0;
END IF;
ELSE
v_unallocated_hours := NULL;
END IF;

IF (v_unallocated_hours IS NOT NULL AND v_unallocated_hours > 0.01)
OR v_overallocated_hours > 0.01 THEN
INSERT INTO payroll_reconciliation_flags (
organization_id, pay_period_id, employee_id, segment_date,
daily_clock_hours, segment_hours, variance_hours, needs_review,
resolution_status, reconciliation_type
)
VALUES (
v_org_id, p_pay_period_id, v_emp_record.user_id, v_day,
COALESCE(v_available_hours, 0), v_allocated_hours,
COALESCE(v_unallocated_hours, 0) + v_overallocated_hours, true,
'unresolved', 'allocation'
)
ON CONFLICT (pay_period_id, employee_id, segment_date) DO NOTHING;

v_flagged := v_flagged + 1;
END IF;
END LOOP;
END LOOP;

RETURN json_build_object(
'total_days_checked', v_checked,
'flagged_days', v_flagged
);
END;
$function$


CREATE OR REPLACE FUNCTION public.reconcile_attendance(p_pay_period_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_start date;
v_end date;
v_emp_record record;
v_config record;
v_day date;
v_clock_count int;
v_clock_hours numeric;
v_expected_hours numeric;
v_variance numeric;
v_flagged int := 0;
v_checked int := 0;
v_day_name text;
v_is_work_day boolean;
BEGIN
SELECT organization_id, period_start_date, period_end_date
INTO v_org_id, v_start, v_end
FROM pay_periods
WHERE id = p_pay_period_id;

IF NOT FOUND THEN
RETURN json_build_object('error', 'pay period not found');
END IF;

DELETE FROM payroll_reconciliation_flags
WHERE pay_period_id = p_pay_period_id
AND reconciliation_type = 'attendance';

-- Map segment employee_id (profiles.id) to employees via user_id
FOR v_emp_record IN
SELECT DISTINCT e.id AS emp_id, e.user_id
FROM payroll_time_segments pts
JOIN employees e ON e.user_id = pts.employee_id
WHERE pts.pay_period_id = p_pay_period_id
AND pts.organization_id = v_org_id
LOOP
FOR v_day IN SELECT generate_series(v_start, v_end, '1 day'::interval)::date LOOP
SELECT * INTO v_config
FROM employee_payroll_configs
WHERE employee_id = v_emp_record.emp_id
AND effective_from <= v_day
AND (effective_to IS NULL OR effective_to >= v_day)
ORDER BY effective_from DESC
LIMIT 1;

CONTINUE WHEN v_config IS NULL OR v_config.requires_daily_clock = false;

v_day_name := btrim(to_char(v_day, 'day'));
v_is_work_day := v_config.work_days IS NULL OR v_day_name = ANY(v_config.work_days);

SELECT COUNT(*), COALESCE(SUM(COALESCE(total_hours, 0)), 0)
INTO v_clock_count, v_clock_hours
FROM daily_clock_entries
WHERE technician_id = v_emp_record.user_id
AND entry_date = v_day
AND organization_id = v_org_id
AND status = 'clocked_out';

v_checked := v_checked + 1;

v_expected_hours := 0;
IF v_is_work_day AND v_config.standard_start_time IS NOT NULL AND v_config.standard_end_time IS NOT NULL THEN
v_expected_hours := EXTRACT(EPOCH FROM (v_config.standard_end_time - v_config.standard_start_time)) / 3600;
END IF;

IF v_is_work_day AND v_clock_count = 0 THEN
INSERT INTO payroll_reconciliation_flags (
organization_id, pay_period_id, employee_id, segment_date,
daily_clock_hours, segment_hours, variance_hours, needs_review,
resolution_status, reconciliation_type
)
VALUES (
v_org_id, p_pay_period_id, v_emp_record.user_id, v_day,
0, 0, v_expected_hours, true,
'unresolved', 'attendance'
)
ON CONFLICT (pay_period_id, employee_id, segment_date) DO NOTHING;

v_flagged := v_flagged + 1;
ELSIF v_is_work_day AND v_clock_hours > 0 AND v_expected_hours > 0 AND v_clock_hours < (v_expected_hours * 0.5) THEN
v_variance := v_expected_hours - v_clock_hours;
INSERT INTO payroll_reconciliation_flags (
organization_id, pay_period_id, employee_id, segment_date,
daily_clock_hours, segment_hours, variance_hours, needs_review,
resolution_status, reconciliation_type
)
VALUES (
v_org_id, p_pay_period_id, v_emp_record.user_id, v_day,
v_clock_hours, 0, v_variance, true,
'unresolved', 'attendance'
)
ON CONFLICT (pay_period_id, employee_id, segment_date) DO NOTHING;

v_flagged := v_flagged + 1;
END IF;
END LOOP;
END LOOP;

RETURN json_build_object(
'total_days_checked', v_checked,
'flagged_days', v_flagged
);
END;
$function$


CREATE OR REPLACE FUNCTION public.reconcile_payroll_segments(p_pay_period_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid;
v_start date;
v_end date;
v_days_checked int := 0;
v_flagged int := 0;
v_total_variance numeric := 0;
v_daily_hours numeric;
v_seg_hours numeric;
v_variance numeric;
v_emp_id uuid;
v_day date;
v_config record;
v_emp_record record;
v_source_hours numeric;
v_excluded_hours numeric;
v_exclusion_reason text;
v_allocation_hours numeric;
v_user_id uuid;
BEGIN
SELECT organization_id, period_start_date, period_end_date
INTO v_org_id, v_start, v_end
FROM pay_periods
WHERE id = p_pay_period_id;

IF NOT FOUND THEN
RETURN json_build_object('error', 'pay period not found');
END IF;

-- Delete existing payroll-type reconciliation flags for this period
DELETE FROM payroll_reconciliation_flags
WHERE pay_period_id = p_pay_period_id
AND reconciliation_type = 'payroll';

-- Get all employees (profiles.id) with segments in this period
-- Map to employees table via user_id
FOR v_emp_record IN
SELECT DISTINCT pts.employee_id AS profile_id, e.id AS emp_id, e.user_id
FROM payroll_time_segments pts
JOIN employees e ON e.user_id = pts.employee_id
WHERE pts.pay_period_id = p_pay_period_id
AND pts.organization_id = v_org_id
LOOP
FOR v_day IN SELECT DISTINCT segment_date FROM payroll_time_segments WHERE pay_period_id = p_pay_period_id AND employee_id = v_emp_record.profile_id ORDER BY segment_date LOOP
-- Resolve effective config for this date
SELECT * INTO v_config
FROM employee_payroll_configs
WHERE employee_id = v_emp_record.emp_id
AND effective_from <= v_day
AND (effective_to IS NULL OR effective_to >= v_day)
ORDER BY effective_from DESC
LIMIT 1;

v_days_checked := v_days_checked + 1;
v_excluded_hours := 0;
v_exclusion_reason := NULL;

-- Sum payroll segment hours for this employee/day
SELECT COALESCE(SUM(COALESCE(total_hours, 0)), 0)
INTO v_seg_hours
FROM payroll_time_segments
WHERE employee_id = v_emp_record.profile_id
AND segment_date = v_day
AND pay_period_id = p_pay_period_id
AND organization_id = v_org_id;

-- Determine source hours based on payroll_time_basis
IF v_config IS NULL THEN
v_source_hours := 0;
v_exclusion_reason := 'No effective payroll configuration found';
ELSIF v_config.payroll_time_basis = 'salary' THEN
v_source_hours := 0;
IF v_seg_hours > 0 THEN
v_excluded_hours := v_seg_hours;
v_exclusion_reason := 'Salary employee should not have hourly segments';
END IF;
ELSIF v_config.payroll_time_basis = 'daily_clock' THEN
SELECT COALESCE(SUM(COALESCE(total_hours, 0)), 0)
INTO v_source_hours
FROM daily_clock_entries
WHERE technician_id = v_emp_record.user_id
AND entry_date = v_day
AND organization_id = v_org_id
AND status = 'clocked_out';
ELSIF v_config.payroll_time_basis = 'work_allocation' THEN
SELECT COALESCE(SUM(COALESCE(total_hours, 0)), 0)
INTO v_source_hours
FROM time_entries
WHERE technician_id = v_emp_record.user_id
AND entry_date = v_day
AND organization_id = v_org_id
AND status = 'approved';

SELECT COALESCE(SUM(COALESCE(predetermined_hours, 0)), 0)
INTO v_allocation_hours
FROM internal_time_sessions
WHERE assigned_to = v_emp_record.user_id
AND session_date = v_day
AND organization_id = v_org_id
AND status = 'approved';

v_source_hours := v_source_hours + v_allocation_hours;
ELSE
v_source_hours := 0;
END IF;

v_variance := v_source_hours - v_seg_hours;

-- Upsert reconciliation flag (payroll type)
INSERT INTO payroll_reconciliation_flags (
organization_id, pay_period_id, employee_id, segment_date,
daily_clock_hours, segment_hours, variance_hours, needs_review,
resolution_status, excluded_hours, exclusion_reason, reconciliation_type
)
VALUES (
v_org_id, p_pay_period_id, v_emp_record.profile_id, v_day,
v_source_hours, v_seg_hours, v_variance,
ABS(v_variance) > 0.01 OR v_excluded_hours > 0,
'unresolved',
v_excluded_hours,
v_exclusion_reason,
'payroll'
)
ON CONFLICT (pay_period_id, employee_id, segment_date)
DO UPDATE SET
daily_clock_hours = EXCLUDED.daily_clock_hours,
segment_hours = EXCLUDED.segment_hours,
variance_hours = EXCLUDED.variance_hours,
needs_review = EXCLUDED.needs_review,
excluded_hours = EXCLUDED.excluded_hours,
exclusion_reason = EXCLUDED.exclusion_reason,
resolution_status = CASE
WHEN payroll_reconciliation_flags.resolution_status = 'resolved'
AND EXCLUDED.needs_review = true
THEN 'unresolved'
ELSE payroll_reconciliation_flags.resolution_status
END
WHERE payroll_reconciliation_flags.resolution_status != 'ignored';

IF ABS(v_variance) > 0.01 OR v_excluded_hours > 0 THEN
v_flagged := v_flagged + 1;
v_total_variance := v_total_variance + ABS(v_variance);
END IF;
END LOOP;
END LOOP;

RETURN json_build_object(
'total_days_checked', v_days_checked,
'flagged_days', v_flagged,
'total_variance_hours', v_total_variance
);
END;
$function$


CREATE OR REPLACE FUNCTION public.record_invoice_open(p_invoice_id uuid, p_user_agent text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_contact_id uuid;
v_org_id uuid;
BEGIN
SELECT p.contact_id, p.organization_id
INTO v_contact_id, v_org_id
FROM profiles p
WHERE p.id = auth.uid()
LIMIT 1;

IF v_org_id IS NULL THEN
RETURN;
END IF;

INSERT INTO invoice_opens (invoice_id, contact_id, organization_id, user_agent)
VALUES (p_invoice_id, v_contact_id, v_org_id, p_user_agent);
END;
$function$


CREATE OR REPLACE FUNCTION public.record_invoice_open(p_invoice_id uuid, p_user_agent text DEFAULT NULL::text, p_event_type text DEFAULT 'viewed'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_contact_id uuid;
v_org_id uuid;
BEGIN
SELECT p.contact_id, p.organization_id
INTO v_contact_id, v_org_id
FROM profiles p
WHERE p.id = auth.uid()
LIMIT 1;

IF v_org_id IS NULL THEN
RETURN;
END IF;

INSERT INTO invoice_opens (invoice_id, contact_id, organization_id, user_agent, event_type)
VALUES (p_invoice_id, v_contact_id, v_org_id, p_user_agent, p_event_type);
END;
$function$


CREATE OR REPLACE FUNCTION public.record_proposal_notification(p_proposal_id uuid, p_notification_type text, p_recipient_email text, p_recipient_name text DEFAULT NULL::text, p_method text DEFAULT 'email'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_notification_id uuid;
v_company_id uuid;
BEGIN
-- Get company_id from proposal
SELECT company_id INTO v_company_id
FROM proposals
WHERE id = p_proposal_id;

-- Insert notification record
INSERT INTO proposal_notifications (
company_id,
proposal_id,
notification_type,
sent_by,
recipient_email,
recipient_name,
method,
metadata
) VALUES (
v_company_id,
p_proposal_id,
p_notification_type,
auth.uid(),
p_recipient_email,
p_recipient_name,
p_method,
p_metadata
)
RETURNING id INTO v_notification_id;

-- Update proposal customer_notified fields
UPDATE proposals
SET
customer_notified = true,
customer_notified_at = now()
WHERE id = p_proposal_id;

RETURN v_notification_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.record_scheduled_logout_run(sessions_closed integer)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
UPDATE session_logout_schedule
SET
last_run_at = now(),
last_run_count = sessions_closed,
updated_at = now()
WHERE id = (SELECT id FROM session_logout_schedule LIMIT 1);
$function$


CREATE OR REPLACE FUNCTION public.refresh_contact_portal_access_cache(p_contact_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_access_level text;
BEGIN
v_access_level := get_contact_portal_access_level(p_contact_id);

