END;
$function$


CREATE OR REPLACE FUNCTION public.refresh_payroll_time(p_pay_period_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_org_id uuid; v_start date; v_end date; v_status text;
v_seg_result json; v_assign_result json; v_segments_count int := 0;
v_jur_high int := 0; v_jur_medium int := 0; v_jur_low int := 0; v_jur_unassigned int := 0;
v_approvals_created int := 0; v_recon_result json; v_refreshed_at timestamptz := now();
v_seg_id uuid; v_jur_result json;
BEGIN
SELECT organization_id, period_start_date, period_end_date, status INTO v_org_id, v_start, v_end, v_status FROM pay_periods WHERE id = p_pay_period_id;
IF NOT FOUND THEN RETURN json_build_object('error', 'pay period not found'); END IF;
IF v_status IN ('payroll_approved', 'submitted', 'processed', 'locked') THEN RETURN json_build_object('error', 'Cannot refresh payroll time for a period with status: ' || v_status); END IF;

DELETE FROM payroll_time_segments pts
WHERE pts.organization_id = v_org_id
AND pts.pay_period_id = p_pay_period_id
AND pts.is_locked = false
AND (
(pts.source_table = 'daily_clock_entries' AND NOT EXISTS (SELECT 1 FROM daily_clock_entries d WHERE d.id = pts.source_record_id))
OR (pts.source_table = 'time_entries' AND NOT EXISTS (SELECT 1 FROM time_entries t WHERE t.id = pts.source_record_id))
OR (pts.source_table = 'internal_time_sessions' AND NOT EXISTS (SELECT 1 FROM internal_time_sessions s WHERE s.id = pts.source_record_id))
);

v_seg_result := regenerate_payroll_segments(v_org_id, v_start, v_end);
v_segments_count := COALESCE((v_seg_result->>'inserted_or_updated')::int, 0);
v_assign_result := assign_segments_to_pay_period(p_pay_period_id);

FOR v_seg_id IN SELECT id FROM payroll_time_segments WHERE pay_period_id = p_pay_period_id AND organization_id = v_org_id AND is_locked = false AND work_jurisdiction_source != 'manual_override' LOOP
v_jur_result := determine_segment_jurisdiction(v_seg_id);
UPDATE payroll_time_segments SET work_jurisdiction_state = (v_jur_result->>'jurisdiction_state')::text, work_jurisdiction_source = (v_jur_result->>'jurisdiction_source')::text, work_jurisdiction_confidence = (v_jur_result->>'confidence')::text, gps_validated = (v_jur_result->>'gps_validated')::boolean WHERE id = v_seg_id;
IF (v_jur_result->>'confidence') = 'high' THEN v_jur_high := v_jur_high + 1;
ELSIF (v_jur_result->>'confidence') = 'medium' THEN v_jur_medium := v_jur_medium + 1;
ELSIF (v_jur_result->>'confidence') = 'low' THEN v_jur_low := v_jur_low + 1;
ELSIF (v_jur_result->>'confidence') = 'unassigned' THEN v_jur_unassigned := v_jur_unassigned + 1; END IF;
END LOOP;

INSERT INTO payroll_approvals (organization_id, pay_period_id, employee_id, approval_status)
SELECT v_org_id, p_pay_period_id, pts.employee_id, 'pending'
FROM (SELECT DISTINCT employee_id FROM payroll_time_segments WHERE pay_period_id = p_pay_period_id AND organization_id = v_org_id) pts
ON CONFLICT (pay_period_id, employee_id) DO NOTHING;
GET DIAGNOSTICS v_approvals_created = ROW_COUNT;

v_recon_result := reconcile_payroll_segments(p_pay_period_id);
UPDATE pay_periods SET last_refresh_at = v_refreshed_at, last_segment_count = v_segments_count WHERE id = p_pay_period_id;

RETURN json_build_object(
'segments_created_or_updated', v_segments_count,
'segments_assigned', COALESCE((v_assign_result->>'assigned')::int, 0),
'jurisdiction_high', v_jur_high,
'jurisdiction_medium', v_jur_medium,
'jurisdiction_low', v_jur_low,
'jurisdiction_unassigned', v_jur_unassigned,
'approvals_created', v_approvals_created,
'reconciliation_flags', COALESCE((v_recon_result->>'flagged_days')::int, 0),
'reconciliation_total_variance', COALESCE((v_recon_result->>'total_variance_hours')::numeric, 0),
'refreshed_at', v_refreshed_at
);
END;
$function$


CREATE OR REPLACE FUNCTION public.refresh_portal_access_on_proposal_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF TG_OP = 'DELETE' THEN
PERFORM refresh_contact_portal_access_cache(OLD.contact_id);
RETURN OLD;
ELSE
PERFORM refresh_contact_portal_access_cache(NEW.contact_id);
RETURN NEW;
END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.refresh_portal_access_on_subscription_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF TG_OP = 'DELETE' THEN
PERFORM refresh_contact_portal_access_cache(OLD.contact_id);
RETURN OLD;
ELSE
PERFORM refresh_contact_portal_access_cache(NEW.contact_id);
RETURN NEW;
END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.refresh_sales_monthly_stats(p_user_id uuid, p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
rec RECORD;
BEGIN
FOR rec IN
SELECT
EXTRACT(YEAR FROM so.created_at)::int AS yr,
EXTRACT(MONTH FROM so.created_at)::int AS mo,
COALESCE(SUM(so.contract_total), 0) AS total_sales,
COUNT(so.id) AS order_count
FROM sales_orders so
WHERE so.created_by = p_user_id
AND so.organization_id = p_org_id
AND so.status NOT IN ('cancelled', 'void')
GROUP BY yr, mo
LOOP
INSERT INTO sales_monthly_stats (organization_id, user_id, year, month, total_sales, sales_order_count, updated_at)
VALUES (p_org_id, p_user_id, rec.yr, rec.mo, rec.total_sales, rec.order_count, now())
ON CONFLICT (organization_id, user_id, year, month)
DO UPDATE SET
total_sales = EXCLUDED.total_sales,
sales_order_count = EXCLUDED.sales_order_count,
updated_at = now();
END LOOP;

FOR rec IN
SELECT
EXTRACT(YEAR FROM p.created_at)::int AS yr,
EXTRACT(MONTH FROM p.created_at)::int AS mo,
COUNT(*) FILTER (WHERE p.status IN ('sent', 'viewed', 'portal', 'approved', 'accepted')) AS sent_count,
COUNT(*) FILTER (WHERE p.status IN ('approved', 'accepted')) AS approved_count
FROM proposals p
WHERE p.created_by = p_user_id
AND p.organization_id = p_org_id
GROUP BY yr, mo
LOOP
INSERT INTO sales_monthly_stats (organization_id, user_id, year, month, proposals_sent, proposals_approved, updated_at)
VALUES (p_org_id, p_user_id, rec.yr, rec.mo, rec.sent_count, rec.approved_count, now())
ON CONFLICT (organization_id, user_id, year, month)
DO UPDATE SET
proposals_sent = EXCLUDED.proposals_sent,
proposals_approved = EXCLUDED.proposals_approved,
updated_at = now();
END LOOP;
END;
$function$


CREATE OR REPLACE FUNCTION public.regenerate_payroll_segments(p_organization_id uuid, p_start_date date, p_end_date date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_inserted int := 0;
v_updated int := 0;
v_skipped_locked int := 0;
v_pto_segments int := 0;
v_emp_record record;
v_config record;
v_seg_date date;
v_clock_hours numeric;
v_pto_hours numeric;
v_pto_is_paid boolean;
v_seg_key text;
v_existing_count int;
BEGIN
FOR v_emp_record IN
SELECT DISTINCT e.id AS emp_id, e.user_id
FROM employees e
WHERE e.organization_id = p_organization_id
LOOP
FOR v_seg_date IN SELECT generate_series(p_start_date, p_end_date, '1 day'::interval)::date LOOP
SELECT * INTO v_config
FROM employee_payroll_configs
WHERE employee_id = v_emp_record.emp_id
AND effective_from <= v_seg_date
AND (effective_to IS NULL OR effective_to >= v_seg_date)
ORDER BY effective_from DESC
LIMIT 1;

CONTINUE WHEN v_config IS NULL;

IF v_config.payroll_time_basis = 'daily_clock' THEN
INSERT INTO payroll_time_segments (
organization_id, employee_id, segment_date, start_time, end_time,
total_hours, break_minutes, time_type, source_table, source_record_id,
segment_key, segment_sequence, daily_clock_entry_id,
physical_work_location_state, gps_validated
)
SELECT
p_organization_id,
v_emp_record.user_id,
dce.entry_date,
dce.clock_in,
dce.clock_out,
COALESCE(dce.total_hours, 0),
COALESCE(dce.break_minutes, 0),
'job',
'daily_clock_entries',
dce.id,
'daily_clock:' || dce.id::text || ':0',
0,
dce.id,
dce.clock_out_address,
true
FROM daily_clock_entries dce
WHERE dce.technician_id = v_emp_record.user_id
AND dce.entry_date = v_seg_date
AND dce.organization_id = p_organization_id
AND dce.status = 'clocked_out'
ON CONFLICT (organization_id, segment_key)
DO UPDATE SET
start_time = EXCLUDED.start_time,
end_time = EXCLUDED.end_time,
total_hours = EXCLUDED.total_hours,
break_minutes = EXCLUDED.break_minutes,
daily_clock_entry_id = EXCLUDED.daily_clock_entry_id
WHERE payroll_time_segments.is_locked = false;

GET DIAGNOSTICS v_inserted = ROW_COUNT;
v_updated := v_updated + v_inserted;
v_inserted := 0;

IF v_config.pto_eligible THEN
SELECT
COALESCE(SUM(pr.total_hours), 0),
COALESCE(BOOL_OR(pp.is_paid), false)
INTO v_pto_hours, v_pto_is_paid
FROM pto_requests pr
JOIN pto_policies pp ON pr.policy_id = pp.id
WHERE pr.employee_id = v_emp_record.user_id
AND pr.organization_id = p_organization_id
AND pr.status = 'approved'
AND pr.start_date <= v_seg_date
AND pr.end_date >= v_seg_date
AND pp.is_paid = true;

IF v_pto_hours > 0 AND v_pto_is_paid THEN
v_seg_key := 'pto:' || v_emp_record.user_id::text || ':' || v_seg_date::text;
INSERT INTO payroll_time_segments (
organization_id, employee_id, segment_date, start_time, end_time,
total_hours, time_type, source_table, source_record_id,
segment_key, segment_sequence
)
VALUES (
p_organization_id,
v_emp_record.user_id,
v_seg_date,
v_seg_date::timestamp,
v_seg_date::timestamp + interval '1 day',
v_pto_hours,
'pto',
'pto_requests',
NULL,
v_seg_key,
0
)
ON CONFLICT (organization_id, segment_key)
DO UPDATE SET
total_hours = EXCLUDED.total_hours
WHERE payroll_time_segments.is_locked = false;

v_pto_segments := v_pto_segments + 1;
END IF;
END IF;

ELSIF v_config.payroll_time_basis = 'work_allocation' THEN
INSERT INTO payroll_time_segments (
organization_id, employee_id, segment_date, start_time, end_time,
total_hours, break_minutes, time_type, source_table, source_record_id,
segment_key, segment_sequence, work_order_id, project_id,
labor_phase_id, overtime_hours, physical_work_location_state,
physical_work_lat, physical_work_lng, gps_validated
)
SELECT
te.organization_id,
v_emp_record.user_id,
te.entry_date,
te.clock_in,
te.clock_out,
te.total_hours,
COALESCE(te.break_minutes, 0),
CASE
WHEN te.entry_type = 'work_order' THEN 'job'
WHEN te.entry_type = 'project' THEN 'job'
WHEN te.entry_type = 'training' THEN 'training'
ELSE 'job'
END,
'time_entries',
te.id,
'time_entries:' || te.id::text || ':0',
0,
te.work_order_id,
te.project_id,
te.labor_phase_id,
te.overtime_hours,
te.physical_work_location_state,
NULL,
NULL,
te.gps_validated
FROM time_entries te
WHERE te.technician_id = v_emp_record.user_id
AND te.entry_date = v_seg_date
AND te.organization_id = p_organization_id
AND te.status = 'approved'
ON CONFLICT (organization_id, segment_key)
DO UPDATE SET
start_time = EXCLUDED.start_time,
end_time = EXCLUDED.end_time,
total_hours = EXCLUDED.total_hours,
break_minutes = EXCLUDED.break_minutes,
overtime_hours = EXCLUDED.overtime_hours,
physical_work_location_state = EXCLUDED.physical_work_location_state,
gps_validated = EXCLUDED.gps_validated,
work_order_id = EXCLUDED.work_order_id,
project_id = EXCLUDED.project_id,
labor_phase_id = EXCLUDED.labor_phase_id
WHERE payroll_time_segments.is_locked = false;

GET DIAGNOSTICS v_inserted = ROW_COUNT;
v_updated := v_updated + v_inserted;
v_inserted := 0;

INSERT INTO payroll_time_segments (
organization_id, employee_id, segment_date, start_time, end_time,
total_hours, time_type, source_table, source_record_id,
segment_key, segment_sequence
)
SELECT
its.organization_id,
v_emp_record.user_id,
its.session_date,
(its.session_date::timestamp + its.start_time) AT TIME ZONE 'UTC',
CASE WHEN its.end_time IS NOT NULL
THEN (its.session_date::timestamp + its.end_time) AT TIME ZONE 'UTC'
ELSE NULL
END,
its.predetermined_hours,
CASE WHEN its.session_type = 'shop_time' THEN 'shop_admin' ELSE its.session_type END,
'internal_time_sessions',
its.id,
'internal_time_sessions:' || its.id::text || ':0',
0
FROM internal_time_sessions its
WHERE its.assigned_to = v_emp_record.user_id
AND its.session_date = v_seg_date
AND its.organization_id = p_organization_id
AND its.status = 'approved'
ON CONFLICT (organization_id, segment_key)
DO UPDATE SET
start_time = EXCLUDED.start_time,
end_time = EXCLUDED.end_time,
total_hours = EXCLUDED.total_hours,
time_type = EXCLUDED.time_type
WHERE payroll_time_segments.is_locked = false;

GET DIAGNOSTICS v_inserted = ROW_COUNT;
v_updated := v_updated + v_inserted;
v_inserted := 0;

IF v_config.pto_eligible THEN
SELECT
COALESCE(SUM(pr.total_hours), 0),
COALESCE(BOOL_OR(pp.is_paid), false)
INTO v_pto_hours, v_pto_is_paid
FROM pto_requests pr
JOIN pto_policies pp ON pr.policy_id = pp.id
WHERE pr.employee_id = v_emp_record.user_id
AND pr.organization_id = p_organization_id
AND pr.status = 'approved'
AND pr.start_date <= v_seg_date
AND pr.end_date >= v_seg_date
AND pp.is_paid = true;

IF v_pto_hours > 0 AND v_pto_is_paid THEN
v_seg_key := 'pto:' || v_emp_record.user_id::text || ':' || v_seg_date::text;
INSERT INTO payroll_time_segments (
organization_id, employee_id, segment_date, start_time, end_time,
total_hours, time_type, source_table, source_record_id,
segment_key, segment_sequence
)
VALUES (
p_organization_id,
v_emp_record.user_id,
v_seg_date,
v_seg_date::timestamp,
v_seg_date::timestamp + interval '1 day',
v_pto_hours,
'pto',
'pto_requests',
NULL,
v_seg_key,
0
)
ON CONFLICT (organization_id, segment_key)
DO UPDATE SET
total_hours = EXCLUDED.total_hours
WHERE payroll_time_segments.is_locked = false;

v_pto_segments := v_pto_segments + 1;
END IF;
END IF;

ELSIF v_config.payroll_time_basis = 'salary' THEN
NULL;
END IF;
END LOOP;
END LOOP;

RETURN json_build_object(
'inserted_or_updated', v_updated,
'pto_segments', v_pto_segments,
'skipped_locked', v_skipped_locked
);
END;
$function$


CREATE OR REPLACE FUNCTION public.reject_change_order(p_change_order_id uuid, p_rejection_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Restore hidden proposal line items that were removed in this CO
UPDATE proposal_line_items pli
SET is_hidden = false
WHERE pli.id IN (
SELECT coli.proposal_line_item_id
FROM change_order_line_items coli
WHERE coli.change_order_id = p_change_order_id
AND coli.action_type = 'remove'
AND coli.proposal_line_item_id IS NOT NULL
);

-- Mark the change order as rejected
UPDATE change_orders
SET status           = 'rejected',
rejection_reason = p_rejection_reason,
is_active        = false,
updated_at       = now()
WHERE id = p_change_order_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.renew_proposal(proposal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE proposals
SET 
expires_at = NOW() + INTERVAL '30 days',
last_renewed_at = NOW(),
renewal_count = COALESCE(renewal_count, 0) + 1,
status = CASE 
WHEN status = 'expired' THEN 'sent'
ELSE status
END
WHERE id = proposal_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.renew_punchlist_access(p_access_grant_id uuid, p_days integer DEFAULT 90)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_grant record;
BEGIN
-- Get the access grant
SELECT * INTO v_grant
FROM punchlist_access_grants
WHERE id = p_access_grant_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Access grant not found';
END IF;

-- Renew the access
UPDATE punchlist_access_grants
SET 
status = 'active',
granted_date = CURRENT_DATE,
expiration_date = CURRENT_DATE + (p_days || ' days')::interval,
updated_at = now()
WHERE id = p_access_grant_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.reopen_pay_period(p_pay_period_id uuid, p_reopened_by uuid, p_reopen_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org_id uuid; v_status text; v_caller_org_id uuid;
BEGIN
IF p_reopened_by IS NULL OR p_reopened_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Unauthorized reopen actor'; END IF;
SELECT organization_id, status INTO v_org_id, v_status FROM pay_periods WHERE id=p_pay_period_id;
IF NOT FOUND THEN RETURN json_build_object('error','pay period not found'); END IF;
SELECT organization_id INTO v_caller_org_id FROM profiles WHERE id=auth.uid();
IF NOT FOUND OR v_caller_org_id IS DISTINCT FROM v_org_id THEN RAISE EXCEPTION 'Unauthorized: caller does not belong to this organization'; END IF;
IF NOT EXISTS (SELECT 1 FROM profiles WHERE id=auth.uid() AND organization_id=v_org_id AND role IN ('admin','manager','office_manager','production_manager','service_manager')) THEN RAISE EXCEPTION 'Unauthorized: caller is not authorized to reopen payroll'; END IF;
IF v_status != 'payroll_approved' THEN RETURN json_build_object('error','Only payroll_approved periods can be reopened'); END IF;
IF p_reopen_reason IS NULL OR btrim(p_reopen_reason)='' THEN RAISE EXCEPTION 'A non-empty reopen reason is required'; END IF;
PERFORM set_config('app.reopen_authorized','true',true);
PERFORM set_config('app.reopen_pay_period_id',p_pay_period_id::text,true);
UPDATE pay_periods SET status='needs_review', payroll_approved_at=NULL, payroll_approved_by=NULL, reopened_by=auth.uid(), reopened_at=now(), reopen_reason=p_reopen_reason, updated_at=now() WHERE id=p_pay_period_id;
UPDATE payroll_time_segments SET is_locked=false, locked_at=NULL, payroll_approval_status='pending', payroll_approved_by=NULL, payroll_approved_at=NULL WHERE pay_period_id=p_pay_period_id AND organization_id=v_org_id;
RETURN json_build_object('success',true,'message','Pay period reopened to needs_review');
END;
$function$


CREATE OR REPLACE FUNCTION public.reopen_project_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_project_task_id uuid;
v_reopen_enabled boolean;
v_has_other_completions boolean;
BEGIN
-- Get the project_task_id (either from OLD or from work_order_tasks)
v_project_task_id := OLD.project_task_id;

-- If not directly set, try to get from work_order_tasks
IF v_project_task_id IS NULL AND OLD.work_order_task_id IS NOT NULL THEN
SELECT project_task_id INTO v_project_task_id
FROM work_order_tasks
WHERE id = OLD.work_order_task_id;
END IF;

-- Exit if no project task is linked
IF v_project_task_id IS NULL THEN
RETURN OLD;
END IF;

-- Check if reopen on delete is enabled
SELECT COALESCE(auto_completion_reopen_on_delete, true)
INTO v_reopen_enabled
FROM company_settings
LIMIT 1;

IF NOT v_reopen_enabled THEN
RETURN OLD;
END IF;

-- Check if there are any other completions for this project task
SELECT EXISTS(
SELECT 1 
FROM work_order_task_completions 
WHERE project_task_id = v_project_task_id
AND id != OLD.id
) INTO v_has_other_completions;

-- Only check work_order_tasks if no direct completions found
IF NOT v_has_other_completions THEN
SELECT EXISTS(
SELECT 1 
FROM work_order_task_completions wotc
JOIN work_order_tasks wot ON wot.id = wotc.work_order_task_id
WHERE wot.project_task_id = v_project_task_id
AND wotc.id != OLD.id
) INTO v_has_other_completions;
END IF;

-- If no other completions exist, reopen the project task
IF NOT v_has_other_completions THEN
UPDATE project_tasks
SET 
status = 'open',
completed_at = NULL,
is_auto_completed = false,
auto_completed_by = NULL
WHERE 
id = v_project_task_id 
AND is_auto_completed = true;
END IF;

RETURN OLD;
END;
$function$


CREATE OR REPLACE FUNCTION public.request_punchlist_service(p_task_ids uuid[], p_contact_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_contact public.contacts%ROWTYPE;
  v_ids uuid[];
  v_count int;
  v_request_id uuid;
  v_existing uuid[];
  v_description text;
BEGIN
  SELECT * INTO v_contact FROM public.contacts WHERE id=p_contact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contact not found'; END IF;
  PERFORM private.punchlist_customer_access(p_contact_id,v_contact.organization_id);
  -- Serialize requests and item mutations for this customer, including concurrent retries.
  PERFORM 1 FROM public.contacts WHERE id=p_contact_id FOR UPDATE;
  SELECT array_agg(DISTINCT x ORDER BY x) INTO v_ids FROM unnest(p_task_ids) x WHERE x IS NOT NULL;
  IF coalesce(cardinality(v_ids),0)=0 THEN RAISE EXCEPTION 'Select at least one item'; END IF;
  SELECT count(*) INTO v_count FROM public.punchlist_tasks
  WHERE id=ANY(v_ids) AND contact_id=p_contact_id AND organization_id=v_contact.organization_id;
  IF v_count <> cardinality(v_ids) THEN RAISE EXCEPTION 'Invalid punchlist selection' USING ERRCODE='42501'; END IF;
  -- Exact retries return the existing open request, without extra requests or notifications.
  IF NOT EXISTS (SELECT 1 FROM public.punchlist_tasks WHERE id=ANY(v_ids)
                 AND (status <> 'requested' OR service_request_id IS NULL)) THEN
    SELECT array_agg(DISTINCT service_request_id) INTO v_existing FROM public.punchlist_tasks WHERE id=ANY(v_ids);
    IF cardinality(v_existing)=1 AND EXISTS (SELECT 1 FROM public.service_requests
        WHERE id=v_existing[1] AND status='open') THEN
      RETURN v_existing[1];
    END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM public.punchlist_tasks WHERE id=ANY(v_ids)
             AND (status <> 'draft' OR service_request_id IS NOT NULL OR work_order_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'Some selected items have already been requested. Refresh your list.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.punchlist_tasks WHERE id=ANY(v_ids)
             AND coalesce(nullif(btrim(details),''),nullif(btrim(title),'')) IS NULL) THEN
    RAISE EXCEPTION 'Describe what needs attention before requesting service';
  END IF;
  SELECT string_agg('- ' || coalesce(nullif(btrim(details),''),title), E'\
' ORDER BY priority_order,created_at,id)
  INTO v_description FROM public.punchlist_tasks WHERE id=ANY(v_ids);
  INSERT INTO public.service_requests (
    organization_id,contact_id,customer_name,customer_phone,customer_email,
    job_location_address,job_location_city,job_location_state,job_location_zip,
    job_description,billable_type,billable_by,priority,notes,status,source_type,created_by
  ) VALUES (
    v_contact.organization_id,p_contact_id,coalesce(v_contact.full_name,v_contact.company_name,'Customer'),
    v_contact.phone,v_contact.email,coalesce(v_contact.street_address,'Address on file'),
    v_contact.city,v_contact.state,v_contact.zip_code,
    'Punchlist Service Request' || E'\
\
' || v_description || coalesce(E'\
\
Notes: ' || nullif(btrim(p_notes),''),''),
    'warranty','admin','normal','Created from customer punchlist portal','open','punchlist',
    (SELECT id FROM public.profiles WHERE id=auth.uid())
  ) RETURNING id INTO v_request_id;
  UPDATE public.punchlist_tasks SET status='requested',service_request_id=v_request_id,
    requested_at=now(),updated_at=now() WHERE id=ANY(v_ids);
  RETURN v_request_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.reschedule_appointment_secure(p_appointment_id uuid, p_new_date text, p_new_start_time text, p_new_end_time text, p_new_tech_id text DEFAULT NULL::text, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
caller_uid UUID := auth.uid();
caller_role TEXT;
current_tech TEXT;
conflict_count INT := 0;
BEGIN
SELECT role INTO caller_role FROM profiles WHERE id = caller_uid;
IF caller_role IS NULL OR caller_role NOT IN ('admin', 'manager', 'service_manager') THEN
RETURN jsonb_build_object('success', false, 'error', 'Permission denied: insufficient role for scheduling');
END IF;

SELECT assigned_technician INTO current_tech
FROM appointments WHERE id = p_appointment_id;

IF current_tech IS NULL AND NOT EXISTS (SELECT 1 FROM appointments WHERE id = p_appointment_id) THEN
RETURN jsonb_build_object('success', false, 'error', 'Appointment not found');
END IF;

-- Conflict check
IF NOT p_force THEN
SELECT count(*) INTO conflict_count
FROM (
SELECT 1 FROM appointments a
WHERE a.appointment_date = p_new_date
AND a.assigned_technician = COALESCE(p_new_tech_id, current_tech)
AND a.status <> 'cancelled'
AND a.id <> p_appointment_id
AND to_minutes(a.start_time) < to_minutes(p_new_end_time)
AND to_minutes(a.end_time) > to_minutes(p_new_start_time)
UNION ALL
SELECT 1 FROM work_orders w
WHERE w.scheduled_date = p_new_date
AND w.assigned_to = COALESCE(p_new_tech_id, current_tech)
AND w.status NOT IN ('completed', 'cancelled', 'archived')
AND to_minutes(COALESCE(w.scheduled_start_time, '08:00')) < to_minutes(p_new_end_time)
AND to_minutes(COALESCE(w.scheduled_end_time, '17:00')) > to_minutes(p_new_start_time)
) AS conflicts;

IF conflict_count > 0 THEN
RETURN jsonb_build_object('success', false, 'conflict', jsonb_build_object('hasConflict', true));
END IF;
END IF;

PERFORM set_config('app.bypass_scheduling_guard', 'true', false);

UPDATE appointments
SET appointment_date = p_new_date,
start_time = p_new_start_time,
end_time = p_new_end_time,
assigned_technician = CASE
WHEN p_new_tech_id IS NOT NULL AND p_new_tech_id <> '' THEN p_new_tech_id::UUID
WHEN p_new_tech_id = '' THEN NULL
ELSE assigned_technician
END
WHERE id = p_appointment_id;

PERFORM set_config('app.bypass_scheduling_guard', 'false', false);

RETURN jsonb_build_object('success', true);
END;
$function$


CREATE OR REPLACE FUNCTION public.reschedule_work_order_secure(p_work_order_id uuid, p_new_date text, p_new_start_time text, p_new_end_time text, p_new_tech_id text DEFAULT NULL::text, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
caller_uid UUID := auth.uid();
caller_role TEXT;
current_status TEXT;
current_tech TEXT;
conflict_count INT := 0;
conflict_data JSONB;
BEGIN
-- Verify caller role
SELECT role INTO caller_role FROM profiles WHERE id = caller_uid;
IF caller_role IS NULL OR caller_role NOT IN ('admin', 'manager', 'service_manager') THEN
RETURN jsonb_build_object('success', false, 'error', 'Permission denied: insufficient role for scheduling');
END IF;

-- Get current status and technician
SELECT status, assigned_to INTO current_status, current_tech
FROM work_orders WHERE id = p_work_order_id;

IF current_status IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Work order not found');
END IF;

-- Server-side conflict check (unless force)
IF NOT p_force THEN
SELECT count(*) INTO conflict_count
FROM (
SELECT 1 FROM appointments a
WHERE a.appointment_date = p_new_date
AND a.assigned_technician = COALESCE(p_new_tech_id, current_tech)
AND a.status <> 'cancelled'
AND a.id <> p_work_order_id
AND to_minutes(a.start_time) < to_minutes(p_new_end_time)
AND to_minutes(a.end_time) > to_minutes(p_new_start_time)
UNION ALL
SELECT 1 FROM work_orders w
WHERE w.scheduled_date = p_new_date
AND w.assigned_to = COALESCE(p_new_tech_id, current_tech)
AND w.status NOT IN ('completed', 'cancelled', 'archived')
AND w.id <> p_work_order_id
AND to_minutes(COALESCE(w.scheduled_start_time, '08:00')) < to_minutes(p_new_end_time)
AND to_minutes(COALESCE(w.scheduled_end_time, '17:00')) > to_minutes(p_new_start_time)
) AS conflicts;

IF conflict_count > 0 THEN
RETURN jsonb_build_object('success', false, 'conflict', jsonb_build_object('hasConflict', true));
END IF;
END IF;

-- Determine status transition
-- Only transition if current status is 'pending' and a technician is being assigned
-- Never downgrade in_progress, completed, cancelled, etc.
DECLARE
new_status TEXT := current_status;
BEGIN
IF p_new_tech_id IS NOT NULL AND p_new_tech_id <> '' THEN
-- Assigning to a technician
IF current_status = 'pending' THEN
new_status := 'scheduled';
END IF;
ELSE
-- Unassigning: only transition if currently assigned/scheduled
IF current_status IN ('assigned', 'scheduled') THEN
new_status := 'pending';
END IF;
END IF;
END;

-- Perform the update with bypass guard
PERFORM set_config('app.bypass_scheduling_guard', 'true', false);

UPDATE work_orders
SET scheduled_date = p_new_date,
scheduled_start_time = p_new_start_time,
scheduled_end_time = p_new_end_time,
assigned_to = CASE
WHEN p_new_tech_id IS NOT NULL AND p_new_tech_id <> '' THEN p_new_tech_id::UUID
WHEN p_new_tech_id = '' THEN NULL
ELSE assigned_to
END,
status = new_status
WHERE id = p_work_order_id;

PERFORM set_config('app.bypass_scheduling_guard', 'false', false);

RETURN jsonb_build_object('success', true, 'new_status', new_status);
END;
$function$


CREATE OR REPLACE FUNCTION public.reserve_pto_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE pto_balances
SET 
pending_hours = pending_hours + NEW.total_hours,
updated_at = now()
WHERE employee_id = NEW.employee_id
AND policy_id = NEW.policy_id;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.resolve_tax_destination(p_state text, p_org_id uuid, p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_nexus_status text;
BEGIN
IF p_state IS NULL OR p_org_id IS NULL THEN
RETURN jsonb_build_object(
'review_required', true,
'review_reason', 'Missing state or organization for tax destination',
'collection_status', 'review_required',
'nexus_status', 'unknown'
);
END IF;

-- Check dealer_nexus_states for this org + state (current rows only)
SELECT nexus_status INTO v_nexus_status
FROM dealer_nexus_states
WHERE organization_id = p_org_id
AND state = p_state
AND COALESCE(is_current, true) = true
ORDER BY updated_at DESC NULLS LAST
LIMIT 1;

-- No row found: missing configuration is UNKNOWN, not "no nexus"
IF v_nexus_status IS NULL THEN
RETURN jsonb_build_object(
'review_required', true,
'review_reason', 'No nexus configuration found for destination state ' || p_state || '. Configure nexus status for this state before collecting tax.',
'collection_status', 'review_required',
'nexus_status', 'unknown'
);
END IF;

-- Map actual CHECK constraint values: yes / no / unknown
IF v_nexus_status = 'yes' THEN
RETURN jsonb_build_object(
'review_required', false,
'review_reason', null,
'collection_status', 'collecting',
'nexus_status', 'yes'
);
ELSIF v_nexus_status = 'no' THEN
RETURN jsonb_build_object(
'review_required', false,
'review_reason', null,
'collection_status', 'not_collecting',
'nexus_status', 'no'
);
ELSIF v_nexus_status = 'unknown' THEN
RETURN jsonb_build_object(
'review_required', true,
'review_reason', 'Nexus status is unknown for destination state ' || p_state || '. Determine nexus before collecting or waiving tax.',
'collection_status', 'review_required',
'nexus_status', 'unknown'
);
ELSE
-- Unexpected value — treat as unknown for safety
RETURN jsonb_build_object(
'review_required', true,
'review_reason', 'Unrecognized nexus status "' || COALESCE(v_nexus_status, '(null)') || '" for destination state ' || p_state || '.',
'collection_status', 'review_required',
'nexus_status', 'unknown'
);
END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.resolve_tax_exemption(p_contact_id uuid, p_state text, p_environment text, p_project_type text)
 RETURNS TABLE(exemption_reference text, is_exempt boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_contact_exempt boolean := false;
v_cert_number text;
BEGIN
IF p_contact_id IS NULL THEN
RETURN QUERY SELECT NULL::text, false;
RETURN;
END IF;

-- Step 1: contact must be flagged as tax exempt
SELECT is_tax_exempt INTO v_contact_exempt
FROM contacts
WHERE id = p_contact_id;

IF NOT COALESCE(v_contact_exempt, false) THEN
RETURN QUERY SELECT NULL::text, false;
RETURN;
END IF;

-- Step 2: a valid, active, unexpired certificate must exist
-- Matches the existing getApplicableTaxRate() pattern in taxCalculations.ts:
--   contact_id match, is_active = true, expiration check
-- No issuing_state filter: the existing MJV architecture has no
-- applicability-by-transaction-state model for certificates.
SELECT certificate_number INTO v_cert_number
FROM tax_exemption_certificates
WHERE contact_id = p_contact_id
AND COALESCE(is_active, true) = true
AND (expiration_date IS NULL OR expiration_date >= CURRENT_DATE)
ORDER BY
CASE WHEN expiration_date IS NULL THEN 1 ELSE 0 END DESC,
expiration_date ASC
LIMIT 1;

IF v_cert_number IS NOT NULL THEN
RETURN QUERY SELECT v_cert_number, true;
ELSE
-- Flagged exempt but no valid certificate — do NOT grant exemption
RETURN QUERY SELECT NULL::text, false;
END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.resolve_tax_origin_address(p_organization_id uuid, p_office_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_origin_method text;
v_office_id uuid;
v_street text;
v_city text;
v_state text;
v_zip text;
v_review_required boolean := false;
v_review_reason text;
v_office_name text;
BEGIN
-- Read the dealer's tax origin method
SELECT cs.tax_origin_method INTO v_origin_method
FROM company_settings cs
WHERE cs.organization_id = p_organization_id;

-- Default to corporate if not set
v_origin_method := COALESCE(v_origin_method, 'corporate');

IF v_origin_method = 'corporate' THEN
SELECT id, address_line1, city, state, zip, office_name
INTO v_office_id, v_street, v_city, v_state, v_zip, v_office_name
FROM company_offices
WHERE organization_id = p_organization_id
AND is_headquarters = true
LIMIT 1;

IF v_office_id IS NULL THEN
RETURN jsonb_build_object(
'origin_method', 'corporate',
'office_id', NULL::uuid,
'street', NULL, 'city', NULL, 'state', NULL, 'zip', NULL,
'review_required', true,
'review_reason', 'No headquarters office found. Set an office as headquarters or switch to Assigned Office Address mode.'
);
END IF;

ELSIF v_origin_method = 'assigned_office' THEN
IF p_office_id IS NULL THEN
RETURN jsonb_build_object(
'origin_method', 'assigned_office',
'office_id', NULL::uuid,
'street', NULL, 'city', NULL, 'state', NULL, 'zip', NULL,
'review_required', true,
'review_reason', 'No office assigned to this transaction. Assign an office or switch to Corporate Address mode.'
);
END IF;

SELECT id, address_line1, city, state, zip, office_name
INTO v_office_id, v_street, v_city, v_state, v_zip, v_office_name
FROM company_offices
WHERE id = p_office_id
AND organization_id = p_organization_id;

IF v_office_id IS NULL THEN
RETURN jsonb_build_object(
'origin_method', 'assigned_office',
'office_id', p_office_id,
'street', NULL, 'city', NULL, 'state', NULL, 'zip', NULL,
'review_required', true,
'review_reason', 'Assigned office not found. The office may have been deleted.'
);
END IF;
END IF;

-- Validate address completeness
IF COALESCE(v_street, '') = '' OR COALESCE(v_city, '') = ''
OR COALESCE(v_state, '') = '' OR COALESCE(v_zip, '') = '' THEN
v_review_required := true;
v_review_reason := 'Origin address incomplete for office "' || COALESCE(v_office_name, '(unknown)') || '". Missing: ';
IF COALESCE(v_street, '') = '' THEN v_review_reason := v_review_reason || 'street, '; END IF;
IF COALESCE(v_city, '') = '' THEN v_review_reason := v_review_reason || 'city, '; END IF;
IF COALESCE(v_state, '') = '' THEN v_review_reason := v_review_reason || 'state, '; END IF;
IF COALESCE(v_zip, '') = '' THEN v_review_reason := v_review_reason || 'zip, '; END IF;
v_review_reason := rtrim(v_review_reason, ', ') || '.';
END IF;

RETURN jsonb_build_object(
'origin_method', v_origin_method,
'office_id', v_office_id,
'street', v_street,
'city', v_city,
'state', v_state,
'zip', v_zip,
'review_required', v_review_required,
'review_reason', v_review_reason
);
END;
$function$


CREATE OR REPLACE FUNCTION public.resolve_tax_rule(p_state text, p_organization_id uuid, p_environment text DEFAULT NULL::text, p_project_type text DEFAULT NULL::text, p_classification_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_candidate_score int;
v_row record;

-- Master result (resolved independently)
v_master_rule_id uuid;
v_master_taxability_status text;
v_master_explanation text;
v_master_rule_version int;
v_master_score int := -1;

-- Dealer result (resolved independently)
v_dealer_rule_id uuid;
v_dealer_taxability_status text;
v_dealer_explanation text;
v_dealer_rule_version int;
v_dealer_score int := -1;
BEGIN
-- ── 1. Resolve best matching master rule ────────────────────────────
FOR v_row IN
SELECT m.id, m.taxability_status, m.explanation, m.rule_version,
m.qualifier_environment, m.qualifier_project_type, m.qualifier_separately_stated
FROM master_state_tax_rules m
JOIN master_classifications mc ON mc.id = m.classification_id
WHERE m.state = p_state
AND mc.code = p_classification_code
AND m.is_active = true
AND m.effective_from <= CURRENT_DATE
AND (m.effective_through IS NULL OR m.effective_through >= CURRENT_DATE)
AND (m.qualifier_environment IS NULL OR m.qualifier_environment = p_environment)
AND (m.qualifier_project_type IS NULL OR m.qualifier_project_type = p_project_type)
LOOP
v_candidate_score := 0;
IF v_row.qualifier_environment IS NOT NULL THEN
v_candidate_score := v_candidate_score + 1;
END IF;
IF v_row.qualifier_project_type IS NOT NULL THEN
v_candidate_score := v_candidate_score + 1;
END IF;
IF v_row.qualifier_separately_stated IS NOT NULL THEN
v_candidate_score := v_candidate_score + 1;
END IF;

IF v_candidate_score > v_master_score
OR (v_candidate_score = v_master_score AND v_row.rule_version > COALESCE(v_master_rule_version, 0))
THEN
v_master_score := v_candidate_score;
v_master_rule_id := v_row.id;
v_master_taxability_status := v_row.taxability_status;
v_master_explanation := v_row.explanation;
v_master_rule_version := v_row.rule_version;
END IF;
END LOOP;

-- ── 2. Independently resolve best matching dealer-specific rule ──────
FOR v_row IN
SELECT s.id, s.taxability_status, s.explanation, s.rule_version,
s.environment AS qual_env, s.project_type AS qual_pt
FROM state_tax_rules_matrix s
JOIN tax_classifications tc ON tc.id = s.tax_classification_id
WHERE s.organization_id = p_organization_id
AND s.state = p_state
AND tc.code = p_classification_code
AND s.is_active = true
AND s.effective_from <= CURRENT_DATE
AND (s.effective_through IS NULL OR s.effective_through >= CURRENT_DATE)
AND (s.environment IS NULL OR s.environment = p_environment OR s.environment = 'both')
AND (s.project_type IS NULL OR s.project_type = p_project_type)
LOOP
v_candidate_score := 0;
IF v_row.qual_env IS NOT NULL AND v_row.qual_env <> 'both' THEN
v_candidate_score := v_candidate_score + 1;
END IF;
IF v_row.qual_pt IS NOT NULL THEN
v_candidate_score := v_candidate_score + 1;
END IF;

IF v_candidate_score > v_dealer_score
OR (v_candidate_score = v_dealer_score AND v_row.rule_version > COALESCE(v_dealer_rule_version, 0))
THEN
v_dealer_score := v_candidate_score;
v_dealer_rule_id := v_row.id;
v_dealer_taxability_status := v_row.taxability_status;
v_dealer_explanation := v_row.explanation;
v_dealer_rule_version := v_row.rule_version;
END IF;
END LOOP;

-- ── 3. Dealer override takes precedence when it exists ──────────────
IF v_dealer_rule_id IS NOT NULL THEN
RETURN jsonb_build_object(
'taxability_status', v_dealer_taxability_status,
'explanation', v_dealer_explanation,
'rule_id', v_dealer_rule_id,
'rule_version', v_dealer_rule_version,
'source', 'dealer_override'
);
ELSIF v_master_rule_id IS NOT NULL THEN
RETURN jsonb_build_object(
'taxability_status', v_master_taxability_status,
'explanation', v_master_explanation,
'rule_id', v_master_rule_id,
'rule_version', v_master_rule_version,
'source', 'master'
);
ELSE
-- ── 4. Neither exists: return needs_review ─────────────────────────
RETURN jsonb_build_object(
'taxability_status', 'needs_review',
'explanation', 'No tax rule found for state ' || COALESCE(p_state, '(null)') ||
', classification ' || COALESCE(p_classification_code, '(null)') ||
', environment ' || COALESCE(p_environment, '(any)') ||
', project type ' || COALESCE(p_project_type, '(any)') ||
'. Manual review required.',
'rule_id', NULL::uuid,
'rule_version', NULL::integer,
'source', NULL::text
);
END IF;
END;
$function$


CREATE OR REPLACE FUNCTION public.resolve_work_order_options()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v public.work_order_options;
BEGIN
 -- Automatic workflow transitions retain canonical behavior and discard stale custom labels.
 IF TG_OP='UPDATE' THEN
  IF NEW.type<>OLD.type AND NEW.work_order_type_id IS NOT DISTINCT FROM OLD.work_order_type_id THEN NEW.work_order_type_id=NULL; END IF;
  IF NEW.status<>OLD.status AND NEW.work_order_status_id IS NOT DISTINCT FROM OLD.work_order_status_id THEN NEW.work_order_status_id=NULL; END IF;
 END IF;
 IF NEW.work_order_type_id IS NOT NULL THEN
  SELECT * INTO v FROM work_order_options WHERE id=NEW.work_order_type_id AND organization_id=NEW.company_id AND kind='type';
  IF NOT FOUND THEN RAISE EXCEPTION 'Invalid work order type'; END IF;
  IF NOT v.is_active AND (TG_OP='INSERT' OR NEW.work_order_type_id IS DISTINCT FROM OLD.work_order_type_id) THEN RAISE EXCEPTION 'Work order type is inactive'; END IF;
  NEW.type=v.behavior;
  IF v.behavior='vip_program' AND NOT EXISTS(SELECT 1 FROM recurring_subscriptions rs JOIN recurring_plans rp ON rp.id=rs.plan_id WHERE rs.id=NEW.recurring_subscription_id AND rs.contact_id=NEW.contact_id AND rs.organization_id=NEW.company_id AND rs.status='active' AND rp.plan_type='vip_plan') THEN RAISE EXCEPTION 'VIP maintenance requires the customer’s active VIP plan'; END IF;
  IF v.system_key='test_and_tune' AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND organization_id=NEW.company_id AND substantial_completion_date IS NOT NULL AND CURRENT_DATE BETWEEN substantial_completion_date AND substantial_completion_date+90) AND (TG_OP='INSERT' OR NEW.work_order_type_id IS DISTINCT FROM OLD.work_order_type_id) THEN RAISE EXCEPTION 'Test & Tune requires a project in its 90-day period'; END IF;
 END IF;
 IF NEW.work_order_status_id IS NOT NULL THEN
  SELECT * INTO v FROM work_order_options WHERE id=NEW.work_order_status_id AND organization_id=NEW.company_id AND kind='status';
  IF NOT FOUND THEN RAISE EXCEPTION 'Invalid work order status'; END IF;
  IF NOT v.is_active AND (TG_OP='INSERT' OR NEW.work_order_status_id IS DISTINCT FROM OLD.work_order_status_id) THEN RAISE EXCEPTION 'Work order status is inactive'; END IF;
  NEW.status=v.behavior;
 END IF;
 RETURN NEW;
END $function$


CREATE OR REPLACE FUNCTION public.restore_portal_version(portal_version_id_param uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
v_pv public.proposal_portal_versions%ROWTYPE;
v_proposal_snap jsonb;
v_rooms_snap jsonb;
v_room jsonb;
v_room_data jsonb;
v_line_items jsonb;
v_li jsonb;
v_proposal_id uuid;
v_new_room_id uuid;
BEGIN
v_user_id := auth.uid();
IF v_user_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
END IF;

SELECT * INTO v_pv FROM public.proposal_portal_versions WHERE id = portal_version_id_param;
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Portal version not found');
END IF;

v_proposal_id := v_pv.proposal_id;
v_proposal_snap := v_pv.snapshot_data -> 'proposal';
v_rooms_snap := v_pv.snapshot_data -> 'rooms';

-- Hide from portal and unlock so rep can review/edit
UPDATE public.proposals SET
title              = (v_proposal_snap ->> 'title'),
status             = 'sent',
is_portal_visible  = false,
is_locked          = false,
locked_at          = NULL,
locked_by          = NULL,
notes              = (v_proposal_snap ->> 'notes'),
scope_of_work      = (v_proposal_snap ->> 'scope_of_work'),
updated_at         = now()
WHERE id = v_proposal_id;

-- Delete existing rooms + line items (CASCADE deletes line_items)
DELETE FROM public.proposal_rooms WHERE proposal_id = v_proposal_id;

-- Re-insert rooms and line items from snapshot
IF v_rooms_snap IS NOT NULL AND jsonb_array_length(v_rooms_snap) > 0 THEN
FOR v_room IN SELECT * FROM jsonb_array_elements(v_rooms_snap)
LOOP
v_room_data := v_room -> 'room';
v_line_items := v_room -> 'line_items';

v_new_room_id := gen_random_uuid();

INSERT INTO public.proposal_rooms (
id, proposal_id, name, sort_order, created_at, updated_at
) VALUES (
v_new_room_id,
v_proposal_id,
v_room_data ->> 'name',
(v_room_data ->> 'sort_order')::integer,
now(),
now()
);

IF v_line_items IS NOT NULL AND jsonb_array_length(v_line_items) > 0 THEN
FOR v_li IN SELECT * FROM jsonb_array_elements(v_line_items)
LOOP
INSERT INTO public.proposal_line_items (
id,
room_id,
proposal_id,
product_id,
description,
quantity,
unit_price,
line_total,
sort_order,
taxable,
item_type,
notes,
install_notes,
tech_notes,
is_hidden,
parent_line_item_id,
labor_phase_id,
created_at,
updated_at
) VALUES (
gen_random_uuid(),
v_new_room_id,
v_proposal_id,
NULLIF(v_li ->> 'product_id', '')::uuid,
v_li ->> 'description',
(v_li ->> 'quantity')::numeric,
(v_li ->> 'unit_price')::numeric,
(v_li ->> 'line_total')::numeric,
(v_li ->> 'sort_order')::integer,
(v_li ->> 'taxable')::boolean,
v_li ->> 'item_type',
v_li ->> 'notes',
v_li ->> 'install_notes',
v_li ->> 'tech_notes',
COALESCE((v_li ->> 'is_hidden')::boolean, false),
NULL,
NULLIF(v_li ->> 'labor_phase_id', '')::uuid,
now(),
now()
);
END LOOP;
END IF;
END LOOP;
END IF;

-- Log in activity feed
INSERT INTO public.activity_feed (
user_id, activity_type, entity_type, entity_id, description
) VALUES (
v_user_id,
'portal_version_restored',
'proposal',
v_proposal_id,
format('Restored portal version %s', v_pv.portal_version_number)
);

RETURN jsonb_build_object(
'success', true,
'proposal_id', v_proposal_id,
'restored_version', v_pv.portal_version_number,
'message', format('Portal version %s restored. Review and re-submit when ready.', v_pv.portal_version_number)
);
END;
$function$


CREATE OR REPLACE FUNCTION public.revert_proposal_from_snapshot(p_proposal_id uuid, p_snapshot jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_room jsonb;
v_item jsonb;
v_room_id uuid;
v_snapshot_room_ids uuid[];
v_snapshot_item_ids uuid[];
BEGIN
-- Collect all room and item IDs from the snapshot
SELECT array_agg((r->>'id')::uuid)
INTO v_snapshot_room_ids
FROM jsonb_array_elements(p_snapshot->'rooms') r;

-- Delete any rooms that don't exist in the snapshot (added by the CO)
DELETE FROM proposal_rooms
WHERE proposal_id = p_proposal_id
AND (v_snapshot_room_ids IS NULL OR id != ALL(v_snapshot_room_ids));

-- Restore each room from the snapshot
FOR v_room IN SELECT * FROM jsonb_array_elements(p_snapshot->'rooms')
LOOP
v_room_id := (v_room->>'id')::uuid;

-- Upsert the room
INSERT INTO proposal_rooms (id, proposal_id, name, description, sort_order)
VALUES (
v_room_id,
p_proposal_id,
v_room->>'name',
v_room->>'description',
COALESCE((v_room->>'sort_order')::integer, 0)
)
ON CONFLICT (id) DO UPDATE SET
name = EXCLUDED.name,
description = EXCLUDED.description,
sort_order = EXCLUDED.sort_order;

-- Collect snapshot item IDs for this room
SELECT array_agg((li->>'id')::uuid)
INTO v_snapshot_item_ids
FROM jsonb_array_elements(v_room->'line_items') li;

-- Delete items in this room that are NOT in the snapshot (were added by the CO)
DELETE FROM proposal_line_items
WHERE room_id = v_room_id
AND proposal_id = p_proposal_id
AND (v_snapshot_item_ids IS NULL OR id != ALL(v_snapshot_item_ids));

-- Restore each line item from the snapshot
FOR v_item IN SELECT * FROM jsonb_array_elements(v_room->'line_items')
LOOP
INSERT INTO proposal_line_items (
id, proposal_id, room_id, product_id, description,
quantity, unit, unit_price, cost, line_total,
item_type, labor_hours, labor_rate, labor_total,
is_taxable, is_hidden, sort_order, parent_item_id,
labor_phase_id, class_id, display_mode, show_task_notes, task_notes
) VALUES (
(v_item->>'id')::uuid,
p_proposal_id,
v_room_id,
CASE WHEN v_item->>'product_id' = 'null' OR v_item->>'product_id' IS NULL THEN NULL ELSE (v_item->>'product_id')::uuid END,
COALESCE(v_item->>'description', ''),
COALESCE((v_item->>'quantity')::numeric, 1),
COALESCE(v_item->>'unit', 'each'),
COALESCE((v_item->>'unit_price')::numeric, 0),
CASE WHEN v_item->>'cost' = 'null' OR v_item->>'cost' IS NULL THEN NULL ELSE (v_item->>'cost')::numeric END,
COALESCE((v_item->>'line_total')::numeric, 0),
v_item->>'item_type',
CASE WHEN v_item->>'labor_hours' = 'null' OR v_item->>'labor_hours' IS NULL THEN NULL ELSE (v_item->>'labor_hours')::numeric END,
CASE WHEN v_item->>'labor_rate' = 'null' OR v_item->>'labor_rate' IS NULL THEN NULL ELSE (v_item->>'labor_rate')::numeric END,
CASE WHEN v_item->>'labor_total' = 'null' OR v_item->>'labor_total' IS NULL THEN NULL ELSE (v_item->>'labor_total')::numeric END,
COALESCE((v_item->>'is_taxable')::boolean, true),
false, -- Always restore items as visible (not hidden)
COALESCE((v_item->>'sort_order')::integer, 0),
CASE WHEN v_item->>'parent_item_id' = 'null' OR v_item->>'parent_item_id' IS NULL THEN NULL ELSE (v_item->>'parent_item_id')::uuid END,
CASE WHEN v_item->>'labor_phase_id' = 'null' OR v_item->>'labor_phase_id' IS NULL THEN NULL ELSE (v_item->>'labor_phase_id')::uuid END,
CASE WHEN v_item->>'class_id' = 'null' OR v_item->>'class_id' IS NULL THEN NULL ELSE (v_item->>'class_id')::uuid END,
COALESCE(v_item->>'display_mode', 'itemized'),
COALESCE((v_item->>'show_task_notes')::boolean, false),
v_item->>'task_notes'
)
ON CONFLICT (id) DO UPDATE SET
description = EXCLUDED.description,
quantity = EXCLUDED.quantity,
unit = EXCLUDED.unit,
unit_price = EXCLUDED.unit_price,
cost = EXCLUDED.cost,
line_total = EXCLUDED.line_total,
item_type = EXCLUDED.item_type,
labor_hours = EXCLUDED.labor_hours,
labor_rate = EXCLUDED.labor_rate,
labor_total = EXCLUDED.labor_total,
is_taxable = EXCLUDED.is_taxable,
is_hidden = false,
sort_order = EXCLUDED.sort_order,
parent_item_id = EXCLUDED.parent_item_id,
labor_phase_id = EXCLUDED.labor_phase_id,
class_id = EXCLUDED.class_id,
display_mode = EXCLUDED.display_mode,
show_task_notes = EXCLUDED.show_task_notes,
task_notes = EXCLUDED.task_notes;
END LOOP;
END LOOP;
END;
$function$


CREATE OR REPLACE FUNCTION public.rollback_time_entry_import(p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_deleted_count integer;
v_import_record record;
BEGIN
-- Get the import record
SELECT * INTO v_import_record
FROM time_entry_import_history
WHERE batch_id = p_batch_id
AND status = 'completed';

IF NOT FOUND THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Import batch not found or already rolled back'
);
END IF;

-- Check permission (must be admin or original importer)
IF v_import_record.imported_by != auth.uid() THEN
IF NOT EXISTS (
SELECT 1 FROM profiles
WHERE id = auth.uid()
AND role = 'admin'
) THEN
RETURN jsonb_build_object(
'success', false,
'error', 'Permission denied'
);
END IF;
END IF;

-- Delete time entries from this batch
DELETE FROM time_entries
WHERE import_batch_id = p_batch_id;

GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

-- Update import history
UPDATE time_entry_import_history
SET 
status = 'rolled_back',
rollback_at = now(),
rollback_by = auth.uid()
WHERE batch_id = p_batch_id;

RETURN jsonb_build_object(
'success', true,
'deleted_count', v_deleted_count
);
END;
$function$


CREATE OR REPLACE FUNCTION public.rollover_incomplete_occurrences()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_occurrence RECORD;
BEGIN
FOR v_occurrence IN
SELECT * FROM scheduled_connection_occurrences
WHERE scheduled_date < CURRENT_DATE
AND is_completed = false
AND is_skipped = false
AND rollover_count < 7 -- Max 7 days of rollover
LOOP
-- Update the occurrence to today
UPDATE scheduled_connection_occurrences
SET
scheduled_date = CURRENT_DATE,
is_rolled_over = true,
rollover_count = rollover_count + 1,
original_scheduled_date = COALESCE(original_scheduled_date, scheduled_date),
updated_at = now()
WHERE id = v_occurrence.id;
END LOOP;

-- Mark old occurrences as missed if rolled over too many times
UPDATE scheduled_connection_occurrences
SET
is_skipped = true,
skipped_reason = 'Automatically marked as missed after 7 days',
skipped_at = now()
WHERE scheduled_date < CURRENT_DATE - 7
AND is_completed = false
AND is_skipped = false;
END;
$function$


CREATE OR REPLACE FUNCTION public.save_portal_version_snapshot(proposal_id_param uuid, notes_param text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
v_proposal proposals%ROWTYPE;
v_next_version integer;
v_snapshot jsonb;
v_version_id uuid;
v_org_id uuid;
BEGIN
v_user_id := auth.uid();
IF v_user_id IS NULL THEN
RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
END IF;

SELECT * INTO v_proposal FROM public.proposals WHERE id = proposal_id_param;
IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Proposal not found');
END IF;

-- Determine org
v_org_id := v_proposal.organization_id;

-- Next portal version number
SELECT COALESCE(MAX(portal_version_number), 0) + 1
INTO v_next_version
FROM public.proposal_portal_versions
WHERE proposal_id = proposal_id_param;

-- Build full snapshot
SELECT jsonb_build_object(
'proposal', row_to_json(p.*),
'rooms', (
SELECT jsonb_agg(
jsonb_build_object(
'room', row_to_json(r.*),
'line_items', (
SELECT jsonb_agg(row_to_json(li.*) ORDER BY li.sort_order)
FROM public.proposal_line_items li
WHERE li.room_id = r.id
)
) ORDER BY r.sort_order
)
FROM public.proposal_rooms r
WHERE r.proposal_id = p.id
)
)
INTO v_snapshot
FROM public.proposals p
WHERE p.id = proposal_id_param;

-- Insert the portal version record
INSERT INTO public.proposal_portal_versions (
proposal_id,
portal_version_number,
snapshot_data,
submitted_by,
submitted_at,
title,
total,
notes,
organization_id
) VALUES (
proposal_id_param,
v_next_version,
v_snapshot,
v_user_id,
now(),
v_proposal.title,
v_proposal.grand_total,
notes_param,
v_org_id
)
RETURNING id INTO v_version_id;

-- Update current_portal_version on the proposal
UPDATE public.proposals
SET current_portal_version = v_next_version,
updated_at = now()
WHERE id = proposal_id_param;

RETURN jsonb_build_object(
'success', true,
'version_id', v_version_id,
'portal_version_number', v_next_version
);
END;
$function$


CREATE OR REPLACE FUNCTION public.search_flow_targets(p_search text DEFAULT ''::text, p_contact uuid DEFAULT NULL::uuid)
 RETURNS SETOF jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 WITH matches AS (
  (SELECT 'contact'::text AS kind,c.id,
    coalesce(nullif(c.full_name,''),nullif(c.contact_name,''),nullif(c.company_name,''),'Customer') AS label
   FROM public.contacts c WHERE c.organization_id=(SELECT public.get_user_org_id()) AND public.flow_has_module_access('contacts')
   AND (p_contact IS NULL OR c.id=p_contact)
   AND position(lower(trim(p_search)) IN lower(concat_ws(' ',c.full_name,c.contact_name,c.company_name)))>0
   ORDER BY c.updated_at DESC NULLS LAST LIMIT 8)
  UNION ALL
  (SELECT 'project',p.id,concat_ws(' · ',p.project_number,p.name)
   FROM public.projects p WHERE p.organization_id=(SELECT public.get_user_org_id()) AND public.flow_has_module_access('projects')
   AND (p_contact IS NULL OR p.contact_id=p_contact)
   AND position(lower(trim(p_search)) IN lower(concat_ws(' ',p.project_number,p.name)))>0
   ORDER BY p.created_at DESC LIMIT 8)
  UNION ALL
  (SELECT 'work_order',w.id,concat_ws(' · ',w.work_order_number,w.title)
   FROM public.work_orders w WHERE w.organization_id=(SELECT public.get_user_org_id()) AND public.flow_has_module_access('work_orders')
   AND (p_contact IS NULL OR w.contact_id=p_contact)
   AND position(lower(trim(p_search)) IN lower(concat_ws(' ',w.work_order_number,w.title)))>0
   ORDER BY w.created_at DESC LIMIT 8)
 ) SELECT to_jsonb(matches) FROM matches;
$function$


CREATE OR REPLACE FUNCTION public.seed_proposal_tasks_for_line_item(p_line_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_line_item  record;
v_default    record;
v_sort_order integer := 0;
v_has_labor  boolean := false;
BEGIN
SELECT * INTO v_line_item
FROM proposal_line_items
WHERE id = p_line_item_id;

IF NOT FOUND THEN
RETURN;
END IF;

IF v_line_item.tasks_seeded_at IS NOT NULL THEN
RETURN;
END IF;

IF v_line_item.product_id IS NOT NULL THEN
FOR v_default IN
SELECT id, title, description, labor_phase_id, sort_order
FROM catalog_item_default_tasks
WHERE product_id = v_line_item.product_id
ORDER BY sort_order
LOOP
INSERT INTO proposal_tasks (
proposal_id, line_item_id, source_default_task_id,
title, description, labor_phase_id, sort_order,
organization_id
) VALUES (
v_line_item.proposal_id, p_line_item_id, v_default.id,
v_default.title, v_default.description, v_default.labor_phase_id,
v_default.sort_order, v_line_item.organization_id
);
v_sort_order := v_sort_order + 1;
END LOOP;
END IF;

IF v_sort_order > 0 THEN
UPDATE proposal_line_items
SET tasks_seeded_at = now()
WHERE id = p_line_item_id;
RETURN;
END IF;

v_has_labor := false;

IF v_line_item.labor_hours IS NOT NULL AND v_line_item.labor_hours > 0 THEN
v_has_labor := true;
ELSIF v_line_item.programming_labor_hours IS NOT NULL AND v_line_item.programming_labor_hours > 0 THEN
v_has_labor := true;
ELSIF EXISTS (
SELECT 1 FROM proposal_line_item_labor_phases
WHERE line_item_id = p_line_item_id
) THEN
v_has_labor := true;
END IF;

IF v_has_labor THEN
INSERT INTO proposal_tasks (
proposal_id, line_item_id, source_default_task_id,
title, description, labor_phase_id, sort_order,
organization_id
) VALUES (
v_line_item.proposal_id, p_line_item_id, NULL,
v_line_item.description, NULL, NULL, 0,
v_line_item.organization_id
);

UPDATE proposal_line_items
SET tasks_seeded_at = now()
WHERE id = p_line_item_id;
END IF;
END;
$function$


