CREATE OR REPLACE FUNCTION public.send_po_request_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_contact_email text;
v_contact_name text;
v_sales_rep_email text;
v_sales_rep_name text;
BEGIN
-- Only trigger when po_pending becomes true
IF NEW.po_pending = true AND (OLD.po_pending IS NULL OR OLD.po_pending = false) THEN

-- Get contact info
SELECT email, COALESCE(full_name, contact_name, email)
INTO v_contact_email, v_contact_name
FROM contacts
WHERE id = NEW.contact_id;

-- Get sales rep info
SELECT 
au.email,
COALESCE(p.first_name || ' ' || p.last_name, p.full_name, au.email)
INTO v_sales_rep_email, v_sales_rep_name
FROM auth.users au
LEFT JOIN profiles p ON p.id = au.id
WHERE au.id = NEW.created_by;

-- Send notification to customer (they can provide PO via portal)
IF v_contact_email IS NOT NULL THEN
BEGIN
-- Create a notification record for tracking
INSERT INTO proposal_notifications (
proposal_id,
contact_id,
notification_type,
recipient_email,
subject,
sent_at
) VALUES (
NEW.id,
NEW.contact_id,
'po_request',
v_contact_email,
'Purchase Order Number Needed - Proposal ' || NEW.proposal_number,
now()
);
EXCEPTION
WHEN OTHERS THEN
RAISE WARNING 'Failed to create PO request notification: %', SQLERRM;
END;
END IF;

END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.send_punchlist_invite(p_invite_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v pending_punchlist_invites; v_id uuid;
BEGIN
 SELECT * INTO v FROM pending_punchlist_invites WHERE id=p_invite_id AND status='pending' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Invite unavailable'; END IF;
 v_id=grant_customer_program(v.contact_id,'test_and_tune',v.project_id,90);
 DELETE FROM pending_punchlist_invites WHERE id=p_invite_id;
 RETURN v_id;
END $function$


CREATE OR REPLACE FUNCTION public.send_scheduled_connection_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_schedule_record RECORD;
v_rollover_count INT;
BEGIN
-- Get schedule details
SELECT 
sc.*,
c.full_name as contact_name
INTO v_schedule_record
FROM scheduled_connections sc
LEFT JOIN contacts c ON c.id = sc.contact_id
WHERE sc.id = NEW.scheduled_connection_id;

-- Determine notification type based on rollover count
IF NEW.rollover_count = 0 THEN
-- New occurrence - send reminder
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id,
created_at
)
VALUES (
v_schedule_record.created_by,
'scheduled_connection_reminder',
'Scheduled Connection Due Today',
format('Your scheduled %s with %s is due today', 
v_schedule_record.connection_type,
COALESCE(v_schedule_record.contact_name, v_schedule_record.prospect_name)
),
NEW.id,
NOW()
);
ELSIF NEW.rollover_count = 1 THEN
-- First rollover
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id,
created_at
)
VALUES (
v_schedule_record.created_by,
'scheduled_connection_rollover',
'Connection Rolled Over',
format('Your scheduled %s with %s was not completed yesterday and has been rolled over to today',
v_schedule_record.connection_type,
COALESCE(v_schedule_record.contact_name, v_schedule_record.prospect_name)
),
NEW.id,
NOW()
);
ELSIF NEW.rollover_count >= 2 THEN
-- Multiple rollovers - overdue
INSERT INTO notifications (
user_id,
type,
title,
body,
related_id,
created_at
)
VALUES (
v_schedule_record.created_by,
'scheduled_connection_overdue',
'Connection Overdue',
format('Your scheduled %s with %s is %s days overdue. This has been rolled over %s times.',
v_schedule_record.connection_type,
COALESCE(v_schedule_record.contact_name, v_schedule_record.prospect_name),
NEW.rollover_count,
NEW.rollover_count
),
NEW.id,
NOW()
);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.set_active_revision(p_proposal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_root_proposal_id uuid;
BEGIN
-- Get root proposal
v_root_proposal_id := get_root_proposal_id(p_proposal_id);

-- Set all revisions to inactive
UPDATE proposals
SET is_active_revision = false
WHERE (id = v_root_proposal_id OR parent_proposal_id = v_root_proposal_id);

-- Set specified revision to active
UPDATE proposals
SET is_active_revision = true
WHERE id = p_proposal_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.set_adjustment_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.adjustment_number IS NULL OR NEW.adjustment_number = '' THEN
NEW.adjustment_number := generate_adjustment_number();
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.set_contact_user_names()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF TG_OP = 'INSERT' AND NEW.created_by IS NOT NULL THEN
NEW.created_by_name := get_user_full_name(NEW.created_by);
END IF;

IF NEW.assigned_to IS NOT NULL AND (TG_OP = 'INSERT' OR OLD.assigned_to IS DISTINCT FROM NEW.assigned_to) THEN
NEW.assigned_to_name := get_user_full_name(NEW.assigned_to);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.set_default_descriptions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
-- Copy description to sales_description if sales_description is empty
IF NEW.sales_description IS NULL AND NEW.description IS NOT NULL THEN
NEW.sales_description := NEW.description;
END IF;

-- Copy sales_description to purchase_description if purchase_description is empty
IF NEW.purchase_description IS NULL AND NEW.sales_description IS NOT NULL THEN
NEW.purchase_description := NEW.sales_description;
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.set_default_team_pulse_permission()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
IF NEW.role IN ('admin', 'manager') THEN
NEW.can_view_team_pulse := COALESCE(NEW.can_view_team_pulse, true);
ELSE
NEW.can_view_team_pulse := COALESCE(NEW.can_view_team_pulse, false);
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.set_global_admin_status(target_user_id uuid, is_admin boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Check if caller is global admin
IF NOT public.is_global_admin() THEN
RAISE EXCEPTION 'Only global admins can modify global admin status';
END IF;

-- Update target user
UPDATE profiles
SET is_global_admin = is_admin,
updated_at = now()
WHERE id = target_user_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.set_invoice_user_names()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF TG_OP = 'INSERT' AND NEW.created_by IS NOT NULL THEN
NEW.created_by_name := get_user_full_name(NEW.created_by);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.set_job_elr_override(p_sales_order_id uuid, p_override_rate numeric, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_old_override numeric;
v_org_id uuid;
v_role text;
BEGIN
-- Check permission
SELECT role INTO v_role FROM profiles WHERE id = auth.uid();
IF v_role NOT IN ('admin', 'super_admin', 'finance', 'sales_manager') THEN
RAISE EXCEPTION 'Only administrators can set per-job ELR overrides';
END IF;

-- Get current state
SELECT min_effective_labor_rate_override, organization_id
INTO v_old_override, v_org_id
FROM sales_orders
WHERE id = p_sales_order_id;

-- Update
UPDATE sales_orders
SET
min_effective_labor_rate_override = p_override_rate,
min_effective_labor_rate_override_reason = p_reason,
updated_at = now()
WHERE id = p_sales_order_id;

-- Audit log
INSERT INTO test_tune_elr_override_log (
organization_id,
sales_order_id,
changed_by,
old_override,
new_override,
reason
) VALUES (
v_org_id,
p_sales_order_id,
auth.uid(),
v_old_override,
p_override_rate,
p_reason
);
END;
$function$


