CREATE OR REPLACE FUNCTION public.set_organization_plan(org_id uuid, new_plan_type text, new_plan_tier text DEFAULT NULL::text, new_max_users integer DEFAULT NULL::integer, new_trial_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Check if caller is global admin
IF NOT public.is_global_admin() THEN
RAISE EXCEPTION 'Only global admins can modify organization plans';
END IF;

-- Validate plan type
IF new_plan_type NOT IN ('trial', 'free', 'paid') THEN
RAISE EXCEPTION 'Invalid plan type. Must be trial, free, or paid';
END IF;

-- Update organization
UPDATE organizations
SET 
plan_type = new_plan_type,
plan_tier = COALESCE(new_plan_tier, plan_tier),
max_users = COALESCE(new_max_users, max_users),
trial_ends_at = new_trial_ends_at,
updated_at = now()
WHERE id = org_id;
END;
$function$


