CREATE OR REPLACE FUNCTION public.should_create_deposit_invoice(p_accepted_via_method text, p_require_deposit boolean, p_deposit_paid boolean, p_deposit_request_sent boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
-- Purchase Order: Never create invoice at approval
IF p_accepted_via_method = 'purchase_order' THEN
RETURN false;
END IF;

-- No deposit required: No invoice needed
IF NOT p_require_deposit THEN
RETURN false;
END IF;

-- Payment method: Always create invoice (marked as paid)
IF p_accepted_via_method = 'payment' THEN
RETURN true;
END IF;

-- Verbal with deposit received: Create invoice (marked as paid)
IF p_accepted_via_method = 'verbal' AND p_deposit_paid THEN
RETURN true;
END IF;

-- Verbal with deposit request sent: Create invoice (marked as sent)
IF p_accepted_via_method = 'verbal' AND p_deposit_request_sent THEN
RETURN true;
END IF;

-- Default: No invoice
RETURN false;
END;
$function$


CREATE OR REPLACE FUNCTION public.stamp_message_proposal_portal_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_proposal_id uuid;
  v_version integer;
BEGIN
  IF NEW.portal_version_number IS NOT NULL THEN RETURN NEW; END IF;
  SELECT mt.proposal_id INTO v_proposal_id FROM public.message_threads mt WHERE mt.id = NEW.thread_id;
  IF v_proposal_id IS NOT NULL THEN
    SELECT COALESCE(p.current_portal_version, 0) INTO v_version FROM public.proposals p WHERE p.id = v_proposal_id;
    NEW.portal_version_number := NULLIF(v_version, 0);
  END IF;
  RETURN NEW;
END;
$function$


