BEGIN
  IF NEW.portal_version_number IS NOT NULL OR NEW.proposal_id IS NULL THEN RETURN NEW; END IF;
  SELECT COALESCE(p.current_portal_version, 0) INTO v_version FROM public.proposals p WHERE p.id = NEW.proposal_id;
  NEW.portal_version_number := NULLIF(v_version, 0);
