CREATE OR REPLACE FUNCTION public.start_user_session(p_user_id uuid, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_device_type text DEFAULT NULL::text, p_browser_name text DEFAULT NULL::text, p_browser_version text DEFAULT NULL::text, p_os_name text DEFAULT NULL::text, p_os_version text DEFAULT NULL::text, p_device_model text DEFAULT NULL::text, p_device_vendor text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_session_id uuid;
v_existing_id uuid;
v_org_id uuid;
BEGIN
-- Auto-resolve organization_id from profile when not provided
IF p_organization_id IS NULL THEN
SELECT organization_id INTO v_org_id
FROM profiles
WHERE id = p_user_id;
ELSE
v_org_id := p_organization_id;
END IF;

-- Check for any existing active session on the same device fingerprint (no time window)
SELECT id INTO v_existing_id
FROM user_sessions
WHERE user_id = p_user_id
AND is_active = true
AND COALESCE(device_type, '')  = COALESCE(p_device_type, '')
AND COALESCE(browser_name, '') = COALESCE(p_browser_name, '')
AND COALESCE(os_name, '')      = COALESCE(p_os_name, '')
ORDER BY last_activity DESC
LIMIT 1;

IF v_existing_id IS NOT NULL THEN
-- Update last_activity on the existing session instead of creating a duplicate
UPDATE user_sessions
SET last_activity = now()
WHERE id = v_existing_id;
RETURN v_existing_id;
END IF;

-- No existing active session for this device — create a new one
INSERT INTO user_sessions (
user_id,
session_start,
last_activity,
ip_address,
user_agent,
is_active,
device_type,
browser_name,
browser_version,
os_name,
os_version,
device_model,
device_vendor,
organization_id
) VALUES (
p_user_id,
now(),
now(),
p_ip_address,
p_user_agent,
true,
p_device_type,
p_browser_name,
p_browser_version,
p_os_name,
p_os_version,
p_device_model,
p_device_vendor,
v_org_id
)
RETURNING id INTO v_session_id;

RETURN v_session_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.submit_invoice(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invoice RECORD;
v_line_items RECORD;
v_calc_result jsonb;
v_tax_amount numeric;
v_subtotal numeric;
v_total numeric;
v_portal_enabled boolean;
v_portal_visible boolean;
v_errors text[] := ARRAY[]::text[];
v_has_positive_amount boolean;
v_taxable_subtotal numeric;
v_assigned_number text;
BEGIN
SELECT * INTO v_invoice
FROM invoices
WHERE id = p_invoice_id
FOR UPDATE;

IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'errors', ARRAY['Invoice not found']);
END IF;

IF v_invoice.status <> 'draft' THEN
RETURN jsonb_build_object('success', false, 'errors', ARRAY['Invoice must be in draft status to submit']);
END IF;

IF v_invoice.contact_id IS NULL THEN
v_errors := array_append(v_errors, 'Customer is required');
END IF;

IF v_invoice.invoice_date IS NULL THEN
v_errors := array_append(v_errors, 'Invoice date is required');
END IF;
IF v_invoice.due_date IS NULL THEN
v_errors := array_append(v_errors, 'Due date is required');
END IF;

IF NOT EXISTS (SELECT 1 FROM invoice_line_items WHERE invoice_id = p_invoice_id) THEN
v_errors := array_append(v_errors, 'At least one line item is required');
ELSE
FOR v_line_items IN
SELECT description, amount, quantity, tax_classification_id, item_type
FROM invoice_line_items WHERE invoice_id = p_invoice_id
LOOP
IF v_line_items.description IS NULL OR v_line_items.description = '' THEN
v_errors := array_append(v_errors, 'All line items must have a description');
END IF;
IF v_line_items.quantity <= 0 THEN
v_errors := array_append(v_errors, 'Line item ''' || COALESCE(v_line_items.description, 'unnamed') || ''' must have a positive quantity');
END IF;
END LOOP;
END IF;

IF array_length(v_errors, 1) IS NOT NULL THEN
RETURN jsonb_build_object('success', false, 'errors', to_jsonb(v_errors));
END IF;

BEGIN
v_calc_result := calculate_tax_context('invoice', p_invoice_id);
v_tax_amount := COALESCE((v_calc_result->>'tax_amount')::numeric, 0);
v_taxable_subtotal := COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0);
EXCEPTION WHEN OTHERS THEN
v_tax_amount := 0;
v_taxable_subtotal := 0;
END;

IF v_calc_result->>'tax_calculation_status' = 'review_required' AND v_taxable_subtotal > 0 THEN
RETURN jsonb_build_object(
'success', false,
'errors', ARRAY['Tax calculation requires review. Please resolve tax configuration before submitting this invoice.']
);
END IF;

SELECT COALESCE(SUM(amount), 0) INTO v_subtotal
FROM invoice_line_items WHERE invoice_id = p_invoice_id;

v_total := v_subtotal + v_tax_amount;

SELECT COALESCE(portal_invoices_enabled, false) INTO v_portal_enabled
FROM company_settings
WHERE organization_id = v_invoice.organization_id
LIMIT 1;

IF v_total - COALESCE(v_invoice.amount_paid, 0) > 0 AND v_portal_enabled THEN
v_portal_visible := true;
ELSE
v_portal_visible := false;
END IF;

UPDATE invoices
SET
status = 'submitted',
subtotal = v_subtotal,
tax_amount = v_tax_amount,
total = v_total,
amount_due = v_total - COALESCE(amount_paid, 0),
portal_visible = v_portal_visible,
tax_calculation_status = COALESCE(v_calc_result->>'tax_calculation_status', 'ready'),
tax_review_required = (v_calc_result->>'tax_calculation_status' = 'review_required'),
updated_at = now()
WHERE id = p_invoice_id;

SELECT invoice_number INTO v_assigned_number FROM invoices WHERE id = p_invoice_id;

RETURN jsonb_build_object(
'success', true,
'invoice_number', v_assigned_number,
'portal_visible', v_portal_visible
);
END;
$function$


CREATE OR REPLACE FUNCTION public.submit_security_onboarding(p_token text, p_full_name text, p_email text, p_phone text, p_address_line1 text, p_city text, p_state text, p_zip_code text, p_signature text, p_customer_ip text, p_payment_method text, p_payment_token text, p_last_four text, p_emergency_contacts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_contract RECORD;
v_contact_id uuid;
v_org_id uuid;
v_ec jsonb;
v_first_name text;
v_last_name text;
v_space_pos int;
v_token_uuid uuid;
BEGIN
-- Safely cast token text to uuid
BEGIN
v_token_uuid := p_token::uuid;
EXCEPTION WHEN invalid_text_representation THEN
RETURN jsonb_build_object('success', false, 'error', 'Invalid or expired invitation link');
END;

-- Validate token and get contract
SELECT id, contact_id, organization_id, magic_link_expires_at, status
INTO v_contract
FROM security_contracts
WHERE magic_link_token = v_token_uuid
AND magic_link_expires_at > now();

IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'error', 'Invalid or expired invitation link');
END IF;

IF v_contract.status NOT IN ('pending_customer', 'customer_completed') THEN
RETURN jsonb_build_object('success', false, 'error', 'This agreement has already been processed');
END IF;

v_contact_id := v_contract.contact_id;
v_org_id := v_contract.organization_id;

-- Split full_name into first/last (split on first space)
IF p_full_name IS NOT NULL AND p_full_name <> '' THEN
v_space_pos := position(' ' IN trim(p_full_name));
IF v_space_pos > 0 THEN
v_first_name := trim(substring(p_full_name FROM 1 FOR v_space_pos - 1));
v_last_name  := trim(substring(p_full_name FROM v_space_pos + 1));
ELSE
v_first_name := trim(p_full_name);
v_last_name  := NULL;
END IF;
END IF;

-- Update contact information if contact exists
IF v_contact_id IS NOT NULL THEN
UPDATE contacts SET
first_name   = COALESCE(v_first_name, first_name),
last_name    = COALESCE(v_last_name, last_name),
contact_name = COALESCE(p_full_name, contact_name),
email        = COALESCE(p_email, email),
phone        = COALESCE(p_phone, phone),
street_address = COALESCE(p_address_line1, street_address),
city     = COALESCE(p_city, city),
state    = COALESCE(p_state, state),
zip_code = COALESCE(p_zip_code, zip_code),
updated_at = now()
WHERE id = v_contact_id;
END IF;

-- Update security contract
UPDATE security_contracts SET
status = 'pending_approval',
customer_completed_at = now(),
customer_signature = p_signature,
customer_signature_date = now(),
customer_ip_address = p_customer_ip,
payment_method = p_payment_method,
payment_token = p_payment_token,
last_four = p_last_four,
updated_at = now()
WHERE id = v_contract.id;

-- Insert emergency contacts
IF p_emergency_contacts IS NOT NULL AND jsonb_array_length(p_emergency_contacts) > 0 THEN
FOR v_ec IN SELECT * FROM jsonb_array_elements(p_emergency_contacts)
LOOP
INSERT INTO security_contract_emergency_contacts (
contract_id,
organization_id,
contact_name,
phone_number,
password_codeword,
can_authorize_entry,
priority_order
) VALUES (
v_contract.id,
v_org_id,
v_ec->>'name',
v_ec->>'phone',
v_ec->>'password',
COALESCE((v_ec->>'canAuthorize')::boolean, false),
COALESCE((v_ec->>'priority_order')::integer, 1)
);
END LOOP;
END IF;

RETURN jsonb_build_object('success', true);
END;
$function$


CREATE OR REPLACE FUNCTION public.sync_account_credit_remaining()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
NEW.amount_remaining := GREATEST(0, NEW.amount - NEW.amount_applied);
NEW.updated_at := now();
IF NEW.amount_remaining <= 0 AND NEW.status = 'open' THEN
NEW.status := 'fully_applied';
END IF;
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.sync_is_prospect_flag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- is_prospect is ONLY true for contact_type = 'prospect'
-- leads and customers (person/business) all have is_prospect = false
NEW.is_prospect := (NEW.contact_type = 'prospect');
RETURN NEW;
END;
$function$


