CREATE OR REPLACE FUNCTION public.sync_vip_appointment_to_work_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_scheduled_datetime timestamptz;
BEGIN
-- Only proceed if appointment has linked work order
IF NOT EXISTS (
SELECT 1 FROM work_orders
WHERE appointment_id = NEW.id
) THEN
RETURN NEW;
END IF;

-- Combine appointment date and start time
v_scheduled_datetime := (NEW.appointment_date || ' ' || NEW.start_time)::timestamptz;

-- Update the linked work order with appointment changes
UPDATE work_orders
SET
description = COALESCE(NEW.description, NEW.title || ' - VIP Program Visit'),
scheduled_date = v_scheduled_datetime,
assigned_to = NEW.assigned_technician,
status = CASE
WHEN NEW.status = 'completed' THEN 'completed'
WHEN NEW.status = 'cancelled' THEN 'cancelled'
WHEN NEW.status = 'in_progress' THEN 'in_progress'
ELSE status
END,
updated_at = NOW()
WHERE appointment_id = NEW.id
AND type = 'vip_program'
AND status NOT IN ('completed', 'cancelled');

RETURN NEW;
END;
$function$


