CREATE OR REPLACE FUNCTION public.to_minutes(t text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
h INT;
m INT;
BEGIN
IF t IS NULL THEN RETURN 0; END IF;
h := split_part(t, ':', 1)::INT;
m := split_part(t, ':', 2)::INT;
RETURN h * 60 + m;
END;
$function$


CREATE OR REPLACE FUNCTION public.toggle_punchlist_access_suspension(p_access_grant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_current_status text;
v_new_status text;
BEGIN
SELECT status INTO v_current_status
FROM punchlist_access_grants
WHERE id = p_access_grant_id;

IF NOT FOUND THEN
RAISE EXCEPTION 'Access grant not found';
END IF;

IF v_current_status NOT IN ('active', 'suspended') THEN
RAISE EXCEPTION 'Only active or suspended grants can be toggled (current status: %)', v_current_status;
END IF;

IF v_current_status = 'active' THEN
v_new_status := 'suspended';
UPDATE punchlist_access_grants
SET
status = 'suspended',
suspended_at = now(),
suspended_by = auth.uid(),
updated_at = now()
WHERE id = p_access_grant_id;
ELSE
v_new_status := 'active';
UPDATE punchlist_access_grants
SET
status = 'active',
suspended_at = NULL,
suspended_by = NULL,
updated_at = now()
WHERE id = p_access_grant_id;
END IF;

RETURN v_new_status;
END;
$function$


