CREATE OR REPLACE FUNCTION public.update_change_order_billing_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_change_order record;
v_total_billed numeric;
v_change_order_total numeric;
BEGIN
-- Loop through all change orders linked to this invoice
FOR v_change_order IN
SELECT DISTINCT co.id, co.new_contract_total - co.original_contract_amount as total_impact
FROM change_orders co
JOIN invoice_change_order_links icol ON co.id = icol.change_order_id
WHERE icol.invoice_id = NEW.id
LOOP
-- Calculate total billed for this change order
SELECT COALESCE(SUM(amount_billed), 0)
INTO v_total_billed
FROM invoice_change_order_links
WHERE change_order_id = v_change_order.id;

v_change_order_total := v_change_order.total_impact;

-- Update change order billing status
UPDATE change_orders
SET 
amount_billed = v_total_billed,
billing_status = CASE
WHEN v_total_billed = 0 THEN 'unbilled'
WHEN v_total_billed >= v_change_order_total THEN 'fully_billed'
ELSE 'partially_billed'
END
WHERE id = v_change_order.id;
END LOOP;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.update_co_billing_status_on_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_change_order record;
v_total_billed numeric;
v_change_order_total numeric;
BEGIN
FOR v_change_order IN
SELECT DISTINCT co.id,
ABS(co.new_contract_total - co.original_contract_amount) AS total_impact
FROM change_orders co
JOIN invoice_change_order_links icol ON co.id = icol.change_order_id
WHERE icol.invoice_id = NEW.id
LOOP
SELECT COALESCE(SUM(ABS(amount_billed)), 0)
INTO v_total_billed
FROM invoice_change_order_links
WHERE change_order_id = v_change_order.id;

v_change_order_total := v_change_order.total_impact;

UPDATE change_orders
SET
amount_billed = v_total_billed,
billing_status = CASE
WHEN v_total_billed = 0 THEN 'unbilled'
WHEN v_change_order_total > 0 AND v_total_billed >= v_change_order_total THEN 'fully_billed'
ELSE 'partially_billed'
END
WHERE id = v_change_order.id;
END LOOP;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.update_commission_on_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invoice record;
v_percentage_collected numeric;
v_commission record;
BEGIN
-- Get invoice_id from the payment
IF TG_OP = 'DELETE' THEN
SELECT * INTO v_invoice FROM invoices WHERE id = OLD.invoice_id;
ELSE
SELECT * INTO v_invoice FROM invoices WHERE id = NEW.invoice_id;
END IF;

-- Skip if invoice has no total (avoid division by zero)
IF v_invoice.total <= 0 THEN
RETURN COALESCE(NEW, OLD);
END IF;

-- Calculate percentage collected
v_percentage_collected := LEAST(v_invoice.amount_paid / v_invoice.total, 1.0);

-- Update all commission records for this invoice
FOR v_commission IN 
SELECT * FROM commission_records WHERE invoice_id = v_invoice.id
LOOP
UPDATE commission_records
SET
amount_collected = v_invoice.amount_paid,
amount_earned = total_potential_commission * v_percentage_collected,
status = CASE
WHEN v_invoice.amount_paid = 0 THEN 'pending'
WHEN v_invoice.amount_paid >= v_invoice.total THEN 'ready_to_pay'
ELSE 'accruing'
END,
updated_at = now()
WHERE id = v_commission.id;
END LOOP;

RETURN COALESCE(NEW, OLD);
END;
$function$


