CREATE OR REPLACE FUNCTION public.update_employee_and_config(p_user_id uuid, p_hire_date date, p_employee_number text DEFAULT NULL::text, p_employment_status text DEFAULT 'active'::text, p_termination_date date DEFAULT NULL::date, p_compensation_type text DEFAULT 'hourly'::text, p_requires_daily_clock boolean DEFAULT true, p_requires_time_allocation boolean DEFAULT false, p_payroll_time_basis text DEFAULT 'daily_clock'::text, p_expected_weekly_hours numeric DEFAULT 40, p_standard_start_time text DEFAULT '08:00'::text, p_standard_end_time text DEFAULT '17:00'::text, p_work_days text[] DEFAULT ARRAY['monday'::text, 'tuesday'::text, 'wednesday'::text, 'thursday'::text, 'friday'::text], p_overtime_eligible boolean DEFAULT false, p_pto_eligible boolean DEFAULT false, p_pay_schedule_id uuid DEFAULT NULL::uuid, p_effective_date date DEFAULT NULL::date, p_reviewed_by uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org_id uuid; v_emp_id uuid; v_current_config record; v_config_changed boolean := false; v_eff_date date; v_new_start time; v_new_end time; v_new_work_days text[];
BEGIN
IF p_reviewed_by IS NULL OR p_reviewed_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Unauthorized employee update actor'; END IF;
SELECT p.organization_id, e.id INTO v_org_id, v_emp_id FROM profiles p JOIN employees e ON e.user_id = p.id AND e.organization_id = p.organization_id WHERE p.id = p_user_id;
IF NOT FOUND THEN RAISE EXCEPTION 'Employee record not found for user %', p_user_id; END IF;
IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND organization_id = v_org_id AND role IN ('admin','manager','office_manager','production_manager','service_manager')) THEN RAISE EXCEPTION 'Unauthorized: caller cannot update employees'; END IF;
UPDATE employees SET employment_status = p_employment_status, hire_date = p_hire_date, termination_date = p_termination_date, employee_number = p_employee_number, updated_at = now() WHERE id = v_emp_id;
SELECT * INTO v_current_config FROM employee_payroll_configs WHERE employee_id = v_emp_id AND effective_to IS NULL LIMIT 1;
v_new_start := CASE WHEN p_requires_daily_clock THEN p_standard_start_time::time ELSE NULL END;
v_new_end := CASE WHEN p_requires_daily_clock THEN p_standard_end_time::time ELSE NULL END;
v_new_work_days := CASE WHEN array_length(p_work_days, 1) > 0 THEN p_work_days ELSE NULL END;
IF v_current_config IS NULL THEN v_config_changed := true; ELSE v_config_changed := v_current_config.compensation_type IS DISTINCT FROM p_compensation_type OR v_current_config.requires_daily_clock IS DISTINCT FROM p_requires_daily_clock OR v_current_config.requires_time_allocation IS DISTINCT FROM p_requires_time_allocation OR v_current_config.payroll_time_basis IS DISTINCT FROM p_payroll_time_basis OR COALESCE(v_current_config.expected_weekly_hours, -1) IS DISTINCT FROM COALESCE(p_expected_weekly_hours, -1) OR COALESCE(v_current_config.standard_start_time, '00:00'::time) IS DISTINCT FROM COALESCE(v_new_start, '00:00'::time) OR COALESCE(v_current_config.standard_end_time, '00:00'::time) IS DISTINCT FROM COALESCE(v_new_end, '00:00'::time) OR COALESCE(array_to_string(v_current_config.work_days, ','), '') IS DISTINCT FROM COALESCE(array_to_string(v_new_work_days, ','), '') OR v_current_config.overtime_eligible IS DISTINCT FROM p_overtime_eligible OR v_current_config.pto_eligible IS DISTINCT FROM p_pto_eligible OR v_current_config.pay_schedule_id IS DISTINCT FROM p_pay_schedule_id; END IF;
IF v_config_changed THEN
v_eff_date := COALESCE(p_effective_date, CURRENT_DATE);
IF v_current_config IS NOT NULL THEN UPDATE employee_payroll_configs SET effective_to = v_eff_date - 1 WHERE id = v_current_config.id; END IF;
INSERT INTO employee_payroll_configs (organization_id, employee_id, effective_from, effective_to, compensation_type, requires_daily_clock, requires_time_allocation, payroll_time_basis, expected_weekly_hours, standard_start_time, standard_end_time, work_days, overtime_eligible, pto_eligible, pay_schedule_id, reviewed_at, reviewed_by) VALUES (v_org_id, v_emp_id, v_eff_date, NULL, p_compensation_type, p_requires_daily_clock, p_requires_time_allocation, p_payroll_time_basis, p_expected_weekly_hours, v_new_start, v_new_end, v_new_work_days, p_overtime_eligible, p_pto_eligible, p_pay_schedule_id, now(), auth.uid());
END IF;
UPDATE profiles SET employment_classification = 'employee', employment_classification_reviewed_at = now(), employment_classification_reviewed_by = auth.uid() WHERE id = p_user_id;
RETURN json_build_object('success', true, 'employee_id', v_emp_id, 'config_changed', v_config_changed);
END;
$function$


