CREATE OR REPLACE FUNCTION public.update_inventory_on_po_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_warehouse_id uuid;
v_qty_change numeric;
v_current_qty numeric;
BEGIN
-- Get warehouse_id from purchase order
SELECT warehouse_id INTO v_warehouse_id
FROM purchase_orders
WHERE id = NEW.po_id;

-- Calculate quantity change
v_qty_change := NEW.quantity_received - COALESCE(OLD.quantity_received, 0);

IF v_qty_change != 0 THEN
-- Get current quantity
SELECT quantity_on_hand INTO v_current_qty
FROM product_inventory
WHERE product_id = NEW.product_id
AND warehouse_id = v_warehouse_id;

-- Update or insert inventory record
INSERT INTO product_inventory (product_id, warehouse_id, quantity_on_hand, updated_at)
VALUES (NEW.product_id, v_warehouse_id, v_qty_change, now())
ON CONFLICT (product_id, warehouse_id)
DO UPDATE SET
quantity_on_hand = product_inventory.quantity_on_hand + v_qty_change,
updated_at = now();

-- Create stock movement record
INSERT INTO stock_movements (
product_id,
warehouse_id,
movement_type,
quantity,
quantity_before,
quantity_after,
reference_type,
reference_id,
notes,
created_by
) VALUES (
NEW.product_id,
v_warehouse_id,
'purchase',
v_qty_change,
COALESCE(v_current_qty, 0),
COALESCE(v_current_qty, 0) + v_qty_change,
'purchase_order',
NEW.po_id,
'Received from PO',
auth.uid()
);

-- Update PO status
PERFORM update_po_status(NEW.po_id);
END IF;

RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.update_invoice_payment_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invoice_id uuid;
v_total numeric;
v_paid numeric;
BEGIN
IF TG_OP = 'DELETE' THEN
v_invoice_id := OLD.invoice_id;
ELSE
v_invoice_id := NEW.invoice_id;
END IF;

SELECT COALESCE(SUM(amount), 0) INTO v_paid
FROM payments WHERE invoice_id = v_invoice_id;

SELECT total INTO v_total FROM invoices WHERE id = v_invoice_id;

UPDATE invoices
SET
amount_paid = v_paid,
amount_due = v_total - v_paid,
status = CASE
WHEN v_paid = 0 THEN 'submitted'
WHEN v_paid >= v_total THEN 'paid'
WHEN v_paid > 0 AND v_paid < v_total THEN 'partial'
ELSE status
END,
updated_at = now()
WHERE id = v_invoice_id;

RETURN COALESCE(NEW, OLD);
END;
$function$


