CREATE OR REPLACE FUNCTION public.update_labor_phase_mapping(p_labor_phase_id uuid, p_counts_against_target boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_old_value boolean;
v_admin_id uuid;
BEGIN
-- Get current user
v_admin_id := auth.uid();

-- Verify admin role
IF NOT EXISTS (
SELECT 1 FROM profiles
WHERE id = v_admin_id
AND role IN ('admin', 'owner')
) THEN
RAISE EXCEPTION 'Only admins can update labor phase mappings';
END IF;

-- Get old value if exists
SELECT counts_against_target INTO v_old_value
FROM labor_phase_performance_mapping
WHERE labor_phase_id = p_labor_phase_id;

-- Insert or update mapping
INSERT INTO labor_phase_performance_mapping (labor_phase_id, counts_against_target, updated_at)
VALUES (p_labor_phase_id, p_counts_against_target, now())
ON CONFLICT (labor_phase_id)
DO UPDATE SET
counts_against_target = p_counts_against_target,
updated_at = now();

-- Create audit record
INSERT INTO labor_phase_mapping_audit (
labor_phase_id,
admin_id,
old_value,
new_value,
reason
) VALUES (
p_labor_phase_id,
v_admin_id,
v_old_value,
p_counts_against_target,
p_reason
);
END;
$function$


