CREATE OR REPLACE FUNCTION public.update_platform_pricing(p_base_price numeric, p_per_user_price numeric, p_included_users integer DEFAULT 1, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_new_id uuid;
BEGIN
IF NOT public.is_global_admin() THEN
RAISE EXCEPTION 'Only global admins can update platform pricing';
END IF;

IF p_base_price < 0 OR p_per_user_price < 0 THEN
RAISE EXCEPTION 'Prices cannot be negative';
END IF;

UPDATE platform_pricing SET is_active = false WHERE is_active = true;

INSERT INTO platform_pricing (base_price, per_user_price, included_users, billing_interval, is_active, created_by)
VALUES (p_base_price, p_per_user_price, p_included_users, 'monthly', true, auth.uid())
RETURNING id INTO v_new_id;

INSERT INTO platform_pricing_history (pricing_id, base_price, per_user_price, included_users, changed_by, notes)
VALUES (v_new_id, p_base_price, p_per_user_price, p_included_users, auth.uid(), p_notes);

RETURN jsonb_build_object('success', true, 'pricing_id', v_new_id);
END;
$function$


CREATE OR REPLACE FUNCTION public.update_po_status(po_id_param uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
v_total_ordered numeric;
v_total_received numeric;
v_new_status text;
BEGIN
SELECT
SUM(quantity_ordered),
SUM(quantity_received)
INTO v_total_ordered, v_total_received
FROM purchase_order_items
WHERE po_id = po_id_param;

IF v_total_received = 0 THEN
v_new_status := 'sent';
ELSIF v_total_received >= v_total_ordered THEN
v_new_status := 'received';
ELSE
v_new_status := 'partial';
END IF;

UPDATE purchase_orders
SET
status = v_new_status,
received_date = CASE WHEN v_new_status = 'received' THEN CURRENT_DATE ELSE received_date END,
updated_at = now()
WHERE id = po_id_param
AND status != 'cancelled';
END;
$function$


