CREATE OR REPLACE FUNCTION public.update_proposal_activity_duration(p_activity_id uuid, p_duration_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_allowed boolean := false;
BEGIN
  IF p_activity_id IS NULL OR p_duration_seconds IS NULL OR p_duration_seconds < 0 THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM proposal_activity pa
    JOIN proposals p ON p.id = pa.proposal_id
    JOIN profiles pr ON pr.contact_id = p.contact_id
    WHERE pa.id = p_activity_id
      AND pa.activity_type = 'viewed'
      AND pr.id = auth.uid()
  ) INTO v_allowed;

  IF NOT v_allowed THEN
    RETURN false;
  END IF;

  UPDATE proposal_activity
  SET duration_seconds = GREATEST(COALESCE(duration_seconds, 0), p_duration_seconds)
  WHERE id = p_activity_id;

  RETURN FOUND;
END;
$function$


CREATE OR REPLACE FUNCTION public.update_proposal_items_hash()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
new_hash text;
proposal_id_to_update uuid;
BEGIN
-- Determine which proposal_id to update
IF TG_OP = 'DELETE' THEN
proposal_id_to_update := OLD.proposal_id;
ELSE
proposal_id_to_update := NEW.proposal_id;
END IF;

-- Calculate new hash
new_hash := calculate_proposal_items_hash(proposal_id_to_update);

-- Update proposal_settings with new hash
UPDATE proposal_settings
SET proposal_items_hash = new_hash
WHERE proposal_id = proposal_id_to_update;

RETURN COALESCE(NEW, OLD);
END;
$function$


