CREATE OR REPLACE FUNCTION public.update_pto_balance_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.status = 'approved' AND OLD.status = 'pending' THEN
UPDATE pto_balances
SET 
current_balance_hours = current_balance_hours - NEW.total_hours,
pending_hours = pending_hours - NEW.total_hours,
used_hours_ytd = used_hours_ytd + NEW.total_hours,
updated_at = now()
WHERE employee_id = NEW.employee_id
AND policy_id = NEW.policy_id;
ELSIF NEW.status = 'denied' AND OLD.status = 'pending' THEN
UPDATE pto_balances
SET 
pending_hours = pending_hours - NEW.total_hours,
updated_at = now()
WHERE employee_id = NEW.employee_id
AND policy_id = NEW.policy_id;
END IF;

RETURN NEW;
END;
$function$


