CREATE OR REPLACE FUNCTION public.user_can_view_record(target_office_id uuid, target_created_by uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
current_user_id uuid;
current_user_role text;
user_visibility text;
user_primary_office uuid;
BEGIN
current_user_id := auth.uid();

SELECT role, primary_office_id INTO current_user_role, user_primary_office
FROM profiles
WHERE id = current_user_id;

-- Admins and managers can see everything
IF current_user_role IN ('admin', 'manager', 'project_manager') THEN
RETURN true;
END IF;

-- Portal users can't use this function (they have separate policies)
IF current_user_role = 'portal_user' THEN
RETURN false;
END IF;

-- For staff users (sales, bd, technician), check visibility settings
SELECT COALESCE(visibility_scope, 'all_offices') INTO user_visibility
FROM user_visibility_settings
WHERE user_id = current_user_id;

IF user_visibility IS NULL THEN
user_visibility := 'all_offices';
END IF;

CASE user_visibility
WHEN 'own_only' THEN
RETURN target_created_by = current_user_id OR target_created_by IS NULL;

WHEN 'office_only' THEN
IF user_primary_office IS NULL THEN
RETURN target_created_by = current_user_id OR target_created_by IS NULL;
END IF;
RETURN target_office_id = user_primary_office 
OR target_created_by = current_user_id 
OR (target_office_id IS NULL AND target_created_by IS NULL);

WHEN 'selected_offices' THEN
RETURN EXISTS (
SELECT 1 FROM user_offices
WHERE user_id = current_user_id
AND office_id = target_office_id
) OR target_created_by = current_user_id 
OR (target_office_id IS NULL AND target_created_by IS NULL);

WHEN 'all_offices' THEN
RETURN true;

ELSE
RETURN true;
END CASE;
END;
$function$


CREATE OR REPLACE FUNCTION public.user_has_module_access(p_user_id uuid, p_module_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_module_id uuid;
v_department_id uuid;
v_has_dept_access boolean;
v_has_module_access boolean;
v_user_role text;
BEGIN
SELECT role INTO v_user_role FROM profiles WHERE id = p_user_id;

IF v_user_role = 'admin' THEN RETURN true; END IF;

SELECT dm.id, dm.department_id INTO v_module_id, v_department_id
FROM department_modules dm WHERE dm.module_key = p_module_key AND dm.is_enabled = true;

IF v_module_id IS NULL THEN RETURN false; END IF;

SELECT COALESCE(has_access, true) INTO v_has_dept_access
FROM department_access WHERE user_id = p_user_id AND department_id = v_department_id;

IF v_has_dept_access = false THEN RETURN false; END IF;

SELECT COALESCE(has_access, true) INTO v_has_module_access
FROM module_access WHERE user_id = p_user_id AND module_id = v_module_id;

RETURN COALESCE(v_has_module_access, true);
END;
$function$


CREATE OR REPLACE FUNCTION public.validate_discount_code(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_code discount_codes%ROWTYPE;
BEGIN
SELECT * INTO v_code
FROM discount_codes
WHERE UPPER(code) = UPPER(p_code)
AND is_active = true
AND valid_from <= now()
AND (valid_until IS NULL OR valid_until > now());

IF NOT FOUND THEN
RETURN jsonb_build_object('valid', false, 'error', 'Invalid or expired discount code');
END IF;

IF v_code.max_redemptions IS NOT NULL AND v_code.times_redeemed >= v_code.max_redemptions THEN
RETURN jsonb_build_object('valid', false, 'error', 'This discount code has reached its maximum usage');
END IF;

RETURN jsonb_build_object(
'valid', true,
'id', v_code.id,
'code', v_code.code,
'discount_type', v_code.discount_type,
'discount_value', v_code.discount_value,
'duration_type', v_code.duration_type,
'duration_months', v_code.duration_months,
'description', v_code.description
);
END;
$function$


CREATE OR REPLACE FUNCTION public.validate_invoice_amount(p_sales_order_id uuid, p_new_invoice_amount numeric, p_exclude_invoice_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_result jsonb;
v_contract_total numeric := 0;
v_billed_total numeric := 0;
v_remaining_balance numeric := 0;
v_proposal_total numeric := 0;
v_change_orders_total numeric := 0;
BEGIN
-- Get proposal total from sales order
SELECT COALESCE(p.total, 0)
INTO v_proposal_total
FROM sales_orders so
LEFT JOIN proposals p ON so.proposal_id = p.id
WHERE so.id = p_sales_order_id;

-- Get approved change orders total
SELECT COALESCE(SUM(new_contract_total - original_contract_amount), 0)
INTO v_change_orders_total
FROM change_orders
WHERE sales_order_id = p_sales_order_id
AND approval_status = 'approved';

-- Calculate total contract value
v_contract_total := v_proposal_total + v_change_orders_total;

-- Get total already billed (excluding the invoice being validated if editing)
SELECT COALESCE(SUM(total), 0)
INTO v_billed_total
FROM invoices
WHERE sales_order_id = p_sales_order_id
AND status != 'void'
AND (p_exclude_invoice_id IS NULL OR id != p_exclude_invoice_id);

-- Calculate remaining balance
v_remaining_balance := v_contract_total - v_billed_total;

-- Build result object
v_result := jsonb_build_object(
'valid', v_remaining_balance >= p_new_invoice_amount,
'contract_total', v_contract_total,
'proposal_total', v_proposal_total,
'change_orders_total', v_change_orders_total,
'billed_total', v_billed_total,
'remaining_balance', v_remaining_balance,
'requested_amount', p_new_invoice_amount,
'would_exceed_by', CASE 
WHEN p_new_invoice_amount > v_remaining_balance 
THEN p_new_invoice_amount - v_remaining_balance 
ELSE 0 
END
);

RETURN v_result;
END;
$function$


CREATE OR REPLACE FUNCTION public.void_invoice(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_invoice RECORD;
BEGIN
SELECT * INTO v_invoice
FROM invoices
WHERE id = p_invoice_id
FOR UPDATE;

IF NOT FOUND THEN
RETURN jsonb_build_object('success', false, 'errors', ARRAY['Invoice not found']);
END IF;

IF v_invoice.status NOT IN ('submitted', 'partial', 'paid', 'overdue') THEN
RETURN jsonb_build_object('success', false, 'errors', ARRAY['Only submitted, partial, paid, or overdue invoices can be voided']);
END IF;

UPDATE invoices
SET
status = 'void',
portal_visible = false,
qbo_void_pending = (v_invoice.qbo_invoice_id IS NOT NULL),
updated_at = now()
WHERE id = p_invoice_id;

RETURN jsonb_build_object(
'success', true,
'invoice_number', v_invoice.invoice_number,
'qbo_void_pending', v_invoice.qbo_invoice_id IS NOT NULL
);
END;
$function$


CREATE OR REPLACE FUNCTION public.write_tax_snapshot(p_transaction_type text, p_transaction_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_calc_result jsonb;
v_snapshot_id uuid;
v_org_id uuid;
v_contact_id uuid;
v_state text;
v_environment text;
v_project_type text;
v_tax_rate numeric;
v_material_amount numeric;
v_labor_amount numeric;
v_taxable_subtotal numeric;
v_tax_amount numeric;
v_origin_result jsonb;
v_destination_result jsonb;
v_exemption_ref text;
v_nexus_status text;
BEGIN
IF p_transaction_type = 'proposal' THEN
SELECT organization_id, contact_id, tax_environment, tax_project_type, tax_rate,
jobsite_state, tax_amount, parts_total, labor_total
INTO v_org_id, v_contact_id, v_environment, v_project_type, v_tax_rate,
v_state, v_tax_amount, v_material_amount, v_labor_amount
FROM proposals WHERE id = p_transaction_id;
v_taxable_subtotal := v_material_amount + v_labor_amount;

ELSIF p_transaction_type = 'change_order' THEN
SELECT co.organization_id, co.tax_environment, co.tax_project_type, co.tax_rate,
co.tax_amount, co.subtotal_after_modifiers
INTO v_org_id, v_environment, v_project_type, v_tax_rate,
v_tax_amount, v_taxable_subtotal
FROM change_orders co WHERE co.id = p_transaction_id;

SELECT p.contact_id, p.jobsite_state
INTO v_contact_id, v_state
FROM proposals p JOIN change_orders co ON co.proposal_id = p.id
WHERE co.id = p_transaction_id;

ELSIF p_transaction_type = 'invoice' THEN
-- Read tax context directly from the invoices table (authoritative for finalized invoices)
SELECT organization_id, contact_id, tax_amount, total,
tax_environment, tax_project_type, tax_rate,
jobsite_state
INTO v_org_id, v_contact_id, v_tax_amount, v_taxable_subtotal,
v_environment, v_project_type, v_tax_rate,
v_state
FROM invoices WHERE id = p_transaction_id;

-- If invoice's own tax context fields are NULL, fall back to proposal JOIN (backward compat)
IF v_environment IS NULL AND v_state IS NULL THEN
SELECT p.tax_environment, p.tax_project_type, p.tax_rate, p.jobsite_state
INTO v_environment, v_project_type, v_tax_rate, v_state
FROM proposals p
JOIN invoices inv ON inv.proposal_id = p.id
WHERE inv.id = p_transaction_id LIMIT 1;
END IF;

ELSE
RETURN NULL;
END IF;

-- Run the orchestrator
v_calc_result := calculate_tax(p_transaction_type, p_transaction_id);

-- Extract results
v_origin_result := v_calc_result->'origin_result';
v_destination_result := v_calc_result->'destination_result';
v_exemption_ref := v_calc_result->>'exemption_reference';
v_nexus_status := v_calc_result->>'collection_status';

-- Insert the snapshot
INSERT INTO tax_snapshots (
organization_id,
transaction_type,
transaction_id,
contact_id,
state,
environment,
project_type,
tax_calculation_status,
taxability_results,
origin_method,
origin_office_id,
origin_address,
destination_address,
collection_status,
nexus_result,
exemption_reference,
taxable_subtotal,
sales_tax,
calculated_at
) VALUES (
v_org_id,
p_transaction_type,
p_transaction_id,
v_contact_id,
v_state,
v_environment,
v_project_type,
v_calc_result->>'tax_calculation_status',
v_calc_result->'taxability_results',
v_origin_result->>'origin_method',
(v_origin_result->>'office_id')::uuid,
v_origin_result,
v_destination_result,
v_calc_result->>'collection_status',
v_nexus_status,
v_exemption_ref,
COALESCE((v_calc_result->>'taxable_subtotal')::numeric, 0),
COALESCE((v_calc_result->>'tax_amount')::numeric, 0),
now()
) RETURNING id INTO v_snapshot_id;

-- Update the transaction's snapshot FK
IF p_transaction_type = 'proposal' THEN
UPDATE proposals SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'change_order' THEN
UPDATE change_orders SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
ELSIF p_transaction_type = 'invoice' THEN
UPDATE invoices SET tax_snapshot_id = v_snapshot_id WHERE id = p_transaction_id;
END IF;

RETURN v_snapshot_id;
END;
$function$


CREATE OR REPLACE FUNCTION public.write_tax_snapshot_on_co_approved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
PERFORM write_tax_snapshot('change_order', NEW.id);
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.write_tax_snapshot_on_invoice_finalized()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
-- Idempotency: skip if invoice already has a tax snapshot
IF NEW.tax_snapshot_id IS NOT NULL THEN
RETURN NEW;
END IF;

PERFORM write_tax_snapshot('invoice', NEW.id);
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.write_tax_snapshot_on_proposal_approved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
PERFORM write_tax_snapshot('proposal', NEW.id);
RETURN NEW;
END;
$function$


CREATE OR REPLACE FUNCTION public.write_tax_snapshot_on_proposal_sent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
PERFORM write_tax_snapshot('proposal', NEW.id);
RETURN NEW;
END;
$function$



