CREATE POLICY "Portal users can view their appointments" ON public.appointments FOR SELECT TO authenticated USING ((contact_id IN ( SELECT contacts.id
   FROM contacts
  WHERE (contacts.portal_user_id = auth_uid()))));
CREATE POLICY "appointments_delete_same_org" ON public.appointments FOR DELETE TO authenticated USING ((organization_id = get_user_org_id()));
