-- ============================================================================
-- RLS POLICIES (STORAGE SCHEMA)
-- ============================================================================

CREATE POLICY "Allow anonymous uploads during signup" ON storage.objects FOR INSERT TO anon WITH CHECK ((bucket_id = 'organization_logos'::text));
CREATE POLICY "Allow authenticated deletes contract sigs" ON storage.objects FOR DELETE TO authenticated USING (((bucket_id = 'security-contract-signatures'::text) AND ((storage.foldername(name))[1] IN ( SELECT (security_contracts.id)::text AS id
   FROM security_contracts
  WHERE ((security_contracts.created_by_user_id = auth.uid()) OR (EXISTS ( SELECT 1
           FROM profiles
          WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'finance'::text]))))))))));
CREATE POLICY "Allow authenticated uploads" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'organization_logos'::text));
CREATE POLICY "Allow authenticated uploads contract sigs" ON storage.objects FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'security-contract-signatures'::text));
CREATE POLICY "Allow organization admins to delete logos" ON storage.objects FOR DELETE TO authenticated USING (((bucket_id = 'organization_logos'::text) AND ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'owner'::text]))))) OR is_global_admin())));
CREATE POLICY "Allow organization admins to update logos" ON storage.objects FOR UPDATE TO authenticated USING (((bucket_id = 'organization_logos'::text) AND ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'owner'::text]))))) OR is_global_admin())));
CREATE POLICY "Anyone can view attachments" ON storage.objects FOR SELECT USING ((bucket_id = 'attachments'::text));
CREATE POLICY "Anyone can view purchase orders" ON storage.objects FOR SELECT TO anon, authenticated USING ((bucket_id = 'purchase-orders'::text));
CREATE POLICY "Authenticated users can delete product images" ON storage.objects FOR DELETE TO authenticated USING ((bucket_id = 'product-images'::text));
CREATE POLICY "Authenticated users can update product images" ON storage.objects FOR UPDATE TO authenticated USING ((bucket_id = 'product-images'::text));
