CREATE POLICY "Customers can upload to own task folders" ON storage.objects FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'punchlist-photos'::text) AND ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text, 'production_manager'::text, 'technician'::text, 'office'::text]))))) OR (EXISTS ( SELECT 1
   FROM (punchlist_tasks pt
     JOIN punchlist_access_grants pag ON ((pag.contact_id = pt.contact_id)))
  WHERE (((pt.id)::text = (string_to_array(objects.name, '/'::text))[1]) AND (pag.contact_id IN ( SELECT profiles.contact_id
           FROM profiles
          WHERE (profiles.id = auth.uid()))) AND (pag.status = 'active'::text) AND ((pag.expiration_date IS NULL) OR (pag.expiration_date >= CURRENT_DATE))))))));
